INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87227, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "咨询是有不懂的事，去问懂的人，请他给出主意。", "primary_collocate": null, "pronunciation": "zī xún", "ipa": "tsɨ˥ ɕyn˧˥", "syllable_count": 2, "sentences": [{"text": "我不懂法律，想去咨询一位律师。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子以前，他咨询了很多朋友。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子总是生病，妈妈去咨询医生。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以咨询一下老师，他一定知道。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学做菜，所以咨询过一位厨师。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事太难，我要向专家咨询。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他遇到难题，就去咨询老教授。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想换工作，先咨询了一位前辈。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不用自己想，去咨询懂行的人吧。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想养小狗，就咨询了养狗的邻居。", "target_word": "咨询", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "咨询了", "label": "体标"}, {"form": "咨询过", "label": "体标"}, {"form": "咨询咨询", "label": "重叠"}, {"form": "咨询师", "label": "复合"}, {"form": "諮詢", "label": "繁体"}], "register": "中性", "sense_fingerprint": "遇到不懂的事，向懂行的人请教并请他出主意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1493551b-beb8-436c-890d-5f7aa674fb8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87227, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "教", "is_correct": false, "explanation": "语义：说“我不懂法律”，却想去教律师法律，前后矛盾。"}, {"text": "咨询", "is_correct": true, "explanation": "咨询：向懂法律的人请教，与“不懂法律”的语境相符。"}, {"text": "反驳", "is_correct": false, "explanation": "语义：不懂法律就无法反驳律师的意见。"}, {"text": "考", "is_correct": false, "explanation": "语义：“考”是参加考试，“一位律师”不能作考试对象，且与“不懂法律”的语境不符。"}], "explanations": {"教": "语义：说“我不懂法律”，却想去教律师法律，前后矛盾。", "咨询": "咨询：向懂法律的人请教，与“不懂法律”的语境相符。", "反驳": "语义：不懂法律就无法反驳律师的意见。", "考": "语义：“考”是参加考试，“一位律师”不能作考试对象，且与“不懂法律”的语境不符。"}, "sentence_index": 0, "correct_answer": "咨询"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在车站咨询了一把伞。", "explanation": "这里应该用〈借〉。咨询是请懂行的人出主意，借伞要用借。"}, {"text": "他在纸上咨询了一幅画。", "explanation": "这里应该用〈画〉。咨询是请懂行的人出主意，画画要用画。"}, {"text": "他在超市咨询了两瓶牛奶。", "explanation": "这里应该用〈买〉。咨询是请懂行的人出主意，买东西要用买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87227, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "咨询", "is_correct": true, "explanation": "咨询：遇到难题去请教老教授，符合求助的语境。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：遇到难题却去嘲笑老教授，与“就去”求助的语境相悖。"}, {"text": "驳斥", "is_correct": false, "explanation": "语义：遇到难题就去驳斥老教授，与求助请教的语境不符。"}, {"text": "训斥", "is_correct": false, "explanation": "语义：遇到难题就去训斥老教授，逻辑不通。"}], "explanations": {"咨询": "咨询：遇到难题去请教老教授，符合求助的语境。", "嘲笑": "语义：遇到难题却去嘲笑老教授，与“就去”求助的语境相悖。", "驳斥": "语义：遇到难题就去驳斥老教授，与求助请教的语境不符。", "训斥": "语义：遇到难题就去训斥老教授，逻辑不通。"}, "sentence_index": 6, "correct_answer": "咨询"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我向餐厅咨询了一桌菜。", "explanation": "这里应该用〈订〉。咨询是请懂行的人出主意，预订菜品要用订。"}, {"text": "警察咨询了那个小偷。", "explanation": "这里应该用〈抓〉。咨询是请懂行的人出主意，抓捕嫌疑人要用抓。"}, {"text": "他向领导咨询了假。", "explanation": "这里应该用〈请〉（请假）。咨询是请对方出主意，请领导准假要用请假。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想把专家咨询一下意见。", "corrected_sentence": "我想向专家咨询一下意见。", "error_description": "错误在介词：咨询专家应用“向”，“把”字句不能这样用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他咨询了过一位律师。", "corrected_sentence": "他咨询过一位律师。", "error_description": "错误在“了”和“过”同时出现：“咨询过”表示曾经有过的经历，不能再加“了”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
