INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87229, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87229, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "信誉是大家觉得你说话算数，很可靠。", "primary_collocate": null, "pronunciation": "xìn yù", "ipa": "ɕin⁵¹ y⁵¹", "syllable_count": 2, "sentences": [{"text": "他说话算数，在朋友中很有信誉。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家老店的信誉一直很好。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意要讲信誉，不能骗人。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是不守时，信誉越来越差。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李借钱一定还，在大家心中很有信誉。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司说话不算数，已经没有信誉了。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信誉要慢慢积累，说错一句话也可能毁掉它。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西我选信誉好的商店。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他答应的事都做到了，所以信誉很高。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保住信誉，老板把钱还给了客人。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "信誉度", "label": "复合"}, {"form": "信譽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "他人觉得某人说话算数、可靠的好名声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c82921da-4675-443e-aa98-940b45501dcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87229, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信誉", "is_correct": true, "explanation": "“信誉”指大家认为某人说话算数、可靠的好名声，与句中“说话算数”相符。"}, {"text": "面积", "is_correct": false, "explanation": "语义：“面积”指物体表面的大小，不能用来说一个人在朋友中的名声。"}, {"text": "长度", "is_correct": false, "explanation": "语义：“长度”指长短，不能用来形容一个人在朋友中的声望。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指身体的外形，与朋友之间的评价无关。"}], "explanations": {"信誉": "“信誉”指大家认为某人说话算数、可靠的好名声，与句中“说话算数”相符。", "面积": "语义：“面积”指物体表面的大小，不能用来说一个人在朋友中的名声。", "长度": "语义：“长度”指长短，不能用来形容一个人在朋友中的声望。", "身材": "体貌：“身材”指身体的外形，与朋友之间的评价无关。"}, "sentence_index": 0, "correct_answer": "信誉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛，我对自己很有信誉。", "explanation": "这里应该用〈信心〉。“信誉”指他人对某人可靠、守信的信任，不能用来说自己的自信。"}, {"text": "他对理想有坚定的信誉。", "explanation": "这里应该用〈信念〉。“信誉”是他人对某人的信任和好评，不能用来说对理想的坚持。"}, {"text": "这里手机没有信誉。", "explanation": "这里应该用〈信号〉。“信誉”指人或企业的可靠程度，不能指手机接收的电波信号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87229, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信誉", "is_correct": true, "explanation": "“信誉”需要长期积累，也可能因一句错话被毁掉，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”由遗传和生长决定，不能说“慢慢积累”，也不会因一句话被“毁掉”。"}, {"text": "影子", "is_correct": false, "explanation": "语义：“影子”是光线被挡住后形成的暗影，不能积累，也不会因一句话被毁掉。"}, {"text": "温度", "is_correct": false, "explanation": "语义：“温度”指冷热程度，不能靠慢慢积累而来，也不会因一句话被毁掉。"}], "explanations": {"信誉": "“信誉”需要长期积累，也可能因一句错话被毁掉，符合句意。", "身高": "搭配：“身高”由遗传和生长决定，不能说“慢慢积累”，也不会因一句话被“毁掉”。", "影子": "语义：“影子”是光线被挡住后形成的暗影，不能积累，也不会因一句话被毁掉。", "温度": "语义：“温度”指冷热程度，不能靠慢慢积累而来，也不会因一句话被毁掉。"}, "sentence_index": 6, "correct_answer": "信誉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位歌手的信誉很大，很多人都喜欢他。", "explanation": "这里应该用〈名气〉。“信誉”强调他人对可靠性的信任，说歌手受欢迎、知名度高要用〈名气〉。"}, {"text": "通知里的信誉很重要，请大家注意。", "explanation": "这里应该用〈信息〉。“信誉”指人或企业的可靠程度，不能指通知里的内容。"}, {"text": "我忘了带信誉，没法付钱。", "explanation": "这里应该用〈信用卡〉。“信誉”是别人对你可靠程度的评价，不是能带在身上付钱的卡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87229, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很信誉，说的话都算数。", "corrected_sentence": "他很讲信誉，说的话都算数。", "error_description": "缺少动词：“很信誉”不通，应补上动词“讲”，说“很讲信誉”。“讲”和“信誉”是动宾关系，“讲信誉”表示重视并遵守信用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87229, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直很珍惜这只信誉，从不随便答应别人。", "corrected_sentence": "他一直很珍惜这份信誉，从不随便答应别人。", "error_description": "错误形式：“这只信誉”。正确形式：“这份信誉”。“信誉”是抽象名词，量词用“份”，不能用“只”（“只”多用于动物、手或小件物品）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
