INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87230, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在信用方面所获得的好名声和他人的信任。", "primary_collocate": null, "pronunciation": "xìn yù", "ipa": "ɕin⁵¹ y⁵¹", "syllable_count": 2, "sentences": [{"text": "这家银行的信誉很高。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司靠诚实经营赢得了信誉。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总不按时还钱，个人信誉受到了影响。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店卖假货会损害自己的信誉。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家网店信誉不错，我放心买。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把信誉看得比利润还重要。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业的信誉是多年积累出来的。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为了维护信誉，主动退了货。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信誉不好的公司，没有人愿意合作。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "良好的信誉能帮公司借到更多钱。", "target_word": "信誉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "信誉度", "label": "复合"}, {"form": "信譽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "企业或个人在信用方面获得的名声和信任", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c82921da-4675-443e-aa98-940b45501dcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87230, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信誉", "is_correct": true, "explanation": "“信誉”指银行在信用方面获得的好评，与“很高”搭配，符合句意。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人或动物的外形，不能用来形容银行。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”通常说“大”或“小”，不说“很高”。"}, {"text": "脸色", "is_correct": false, "explanation": "语义：“脸色”指面部的颜色，不能用来说银行的好评。"}], "explanations": {"信誉": "“信誉”指银行在信用方面获得的好评，与“很高”搭配，符合句意。", "身材": "体貌：“身材”指人或动物的外形，不能用来形容银行。", "体积": "搭配：“体积”通常说“大”或“小”，不说“很高”。", "脸色": "语义：“脸色”指面部的颜色，不能用来说银行的好评。"}, "sentence_index": 0, "correct_answer": "信誉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试我很有信誉。", "explanation": "这里应该用〈信心〉。“信誉”指他人对某人或企业的信任，不能用来说自己的自信。"}, {"text": "通知里的信誉很重要，请大家注意。", "explanation": "这里应该用〈信息〉。“信誉”指人或企业的可靠程度，不能指通知里的内容。"}, {"text": "他的信誉让他在困难中很平静。", "explanation": "这里应该用〈信仰〉。“信誉”指他人对某人的信任，不能指宗教或精神上的信奉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87230, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信誉", "is_correct": true, "explanation": "“信誉”是靠长期诚实经营积累起来的，符合句意。"}, {"text": "长相", "is_correct": false, "explanation": "体貌：“长相”指人的容貌，不能用于企业。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指物体的轻重，不是靠多年积累形成的。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，与企业无关，也不是靠积累得来的。"}], "explanations": {"信誉": "“信誉”是靠长期诚实经营积累起来的，符合句意。", "长相": "体貌：“长相”指人的容貌，不能用于企业。", "重量": "语义：“重量”指物体的轻重，不是靠多年积累形成的。", "体温": "语义：“体温”指身体的温度，与企业无关，也不是靠积累得来的。"}, "sentence_index": 6, "correct_answer": "信誉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对事业有坚定的信誉。", "explanation": "这里应该用〈信念〉。“信誉”指他人对某人可靠性的信任，不能用来说对事业的坚持。"}, {"text": "这位画家的信誉很大，他的画很贵。", "explanation": "这里应该用〈名气〉。“信誉”强调他人对可靠性的信任，说画家出名、受追捧要用〈名气〉。"}, {"text": "我忘了带信誉，没法付钱。", "explanation": "这里应该用〈信用卡〉。“信誉”是别人对企业或个人可靠程度的评价，不是能带在身上付钱的卡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家企业多年经营，积累着很好的信誉。", "corrected_sentence": "这家企业多年经营，积累了很好的信誉。", "error_description": "错误形式：“积累着”。正确形式：“积累了”。“多年经营”后已经有了结果，要用“了”表示完成，不能用表示持续的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家企业的信誉已经恢复着。", "corrected_sentence": "这家企业的信誉已经恢复了。", "error_description": "错误形式：“恢复着”。正确形式：“恢复了”。“恢复”表示已经完成的变化，要用“了”；“着”表示持续的状态，不符合句意。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
