INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87231, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "只能是没有别的办法，只有这一个办法。", "primary_collocate": null, "pronunciation": "zhǐ néng", "ipa": "ʈʂɨ˨˩ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "车坏了，我们只能走路回家。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有别的办法，我只能等他回来。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，比赛只能明天再开始。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱不够，他只能向朋友借。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯坏了，大家只能走楼梯上去。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听不懂，只能请老师再说一遍。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络不好，会议只能改到下午。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "票卖完了，我们只能明天再来。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人在国外，生病了也只能自己去医院。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车，我只能给老板打电话说晚到。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：别无选择，不得不这样做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62420910-ffdd-4a2d-9c1d-95797acdc4fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87231, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示两件事一起发生，与“车坏了”带来的无奈选择不合。"}, {"text": "只能", "is_correct": true, "explanation": "只能：表示没有别的办法，只有这一个选择，与“车坏了”的语境相合。"}, {"text": "偏", "is_correct": false, "explanation": "语义：“偏”表示故意与预期相反，与“车坏了”的无奈语境不合。"}, {"text": "吃", "is_correct": false, "explanation": "语法：“吃”是动词，放在“我们”之后不能修饰“走路回家”，句子不成立。"}], "explanations": {"同时": "语义：“同时”表示两件事一起发生，与“车坏了”带来的无奈选择不合。", "只能": "只能：表示没有别的办法，只有这一个选择，与“车坏了”的语境相合。", "偏": "语义：“偏”表示故意与预期相反，与“车坏了”的无奈语境不合。", "吃": "语法：“吃”是动词，放在“我们”之后不能修饰“走路回家”，句子不成立。"}, "sentence_index": 0, "correct_answer": "只能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试我只能差两分就及格了。", "explanation": "这里应该用〈只差〉。「只差」表示还缺一点点，「只能」表示只有这一种办法，不能用来说差多少。"}, {"text": "车上只能剩两个座位。", "explanation": "这里应该用〈只剩〉。「只剩」表示其余的都已没有，只留下这些；「只能」表示只有这一种办法，不能用来说剩下的数量。"}, {"text": "只能多读书，就能提高。", "explanation": "这里应该用〈只要〉。“只要……就……”表示充分条件，“只能”不用于这种条件句。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87231, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意为之，与“网络不好”造成的被动改期不合。"}, {"text": "只能", "is_correct": true, "explanation": "只能：表示没有别的办法，只有这一个选择，与“网络不好”导致改期的语境相合。"}, {"text": "吃", "is_correct": false, "explanation": "语法：“吃”是动词，不能用来表示会议改期，句子不成立。"}, {"text": "特意", "is_correct": false, "explanation": "语义：“特意”表示专门为某事，与“网络不好”的原因不合。"}], "explanations": {"故意": "语义：“故意”表示有意为之，与“网络不好”造成的被动改期不合。", "只能": "只能：表示没有别的办法，只有这一个选择，与“网络不好”导致改期的语境相合。", "吃": "语法：“吃”是动词，不能用来表示会议改期，句子不成立。", "特意": "语义：“特意”表示专门为某事，与“网络不好”的原因不合。"}, "sentence_index": 6, "correct_answer": "只能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "修这辆车只能需要一个小时。", "explanation": "这里应该用〈只需〉。「只需」表示只要求这些，「只能」表示只有这一种可能或办法，不能用来说需要多长时间。"}, {"text": "他不是小气，只能不爱说话。", "explanation": "这里应该用〈只是〉。「只是」表示转折，「只能」表示只有这一种可能或办法，不能用于转折。"}, {"text": "只能多运动，就能保持健康。", "explanation": "这里应该用〈只要〉。“只要……就……”表示充分条件，“只能”不用于这种条件句。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87231, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车票没有了，我们只能会坐下一班。", "corrected_sentence": "车票没有了，我们只能坐下一班。", "error_description": "错误：“只能会坐”。正确：“只能坐”。“只能”已表示没有别的办法，其后不再叠加助动词“会”，应说“只能坐下一班”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87231, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "没有车，他只能只能走路去学校。", "corrected_sentence": "没有车，他只能走路去学校。", "error_description": "错误：“只能只能”。正确：“只能”。“只能”是副词，不能重复使用；应说“他只能走路去学校”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
