INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87232, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示只有这一种可能或办法。", "primary_collocate": null, "pronunciation": "zhǐ néng", "ipa": "ʈʂɨ˨˩ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这条路太窄，车只能一辆一辆地过。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店只能用现金，不能刷卡。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆的书只能在这里看。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子只能喝一点儿牛奶。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电梯只能坐八个人。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间很小，只能放一张床。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机只能打电话，不能上网。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他现在只能吃很软的东西。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议室只能坐二十个人。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药只能在医院买到。", "target_word": "只能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词：范围受限，只有这一种可能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62420910-ffdd-4a2d-9c1d-95797acdc4fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87232, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一起", "is_correct": false, "explanation": "语义：车一起过，与“一辆一辆地”的意思矛盾。"}, {"text": "只能", "is_correct": true, "explanation": "只能：表示范围受限，只有这一种可能，与“一辆一辆地过”相合。"}, {"text": "同时", "is_correct": false, "explanation": "语义：车同时过，与“一辆一辆地”的意思矛盾。"}, {"text": "吃", "is_correct": false, "explanation": "语法：“吃”是动词，放在“车”之后不能表示通行方式，句子不成立。"}], "explanations": {"一起": "语义：车一起过，与“一辆一辆地”的意思矛盾。", "只能": "只能：表示范围受限，只有这一种可能，与“一辆一辆地过”相合。", "同时": "语义：车同时过，与“一辆一辆地”的意思矛盾。", "吃": "语法：“吃”是动词，放在“车”之后不能表示通行方式，句子不成立。"}, "sentence_index": 0, "correct_answer": "只能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室里只能剩三张桌子。", "explanation": "这里应该用〈只剩〉。「只剩」表示其余的都已没有，只留下这些；「只能」表示只有这一种可能或办法，不能用来说剩下的数量。"}, {"text": "他只能差一分就及格了。", "explanation": "这里应该用〈只差〉。「只差」表示还缺一点点，「只能」表示只有这一种办法，不能用来说差多少。"}, {"text": "只能多练，就能进步。", "explanation": "这里应该用〈只要〉。“只要……就……”表示充分条件，“只能”不用于这种条件句。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修", "is_correct": false, "explanation": "语法：“修”是动词，放在“手机”之后不能修饰“打电话”，句子不成立。"}, {"text": "只能", "is_correct": true, "explanation": "只能：表示范围受限，只有这一种可能，与“不能上网”的限制相合。"}, {"text": "偏", "is_correct": false, "explanation": "语义：“偏”表示故意与预期相反，与“不能上网”的限制不合。"}, {"text": "又", "is_correct": false, "explanation": "语义：“又”表示重复，与“不能上网”的限制不相合。"}], "explanations": {"修": "语法：“修”是动词，放在“手机”之后不能修饰“打电话”，句子不成立。", "只能": "只能：表示范围受限，只有这一种可能，与“不能上网”的限制相合。", "偏": "语义：“偏”表示故意与预期相反，与“不能上网”的限制不合。", "又": "语义：“又”表示重复，与“不能上网”的限制不相合。"}, "sentence_index": 6, "correct_answer": "只能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "做这道题只能需要十分钟。", "explanation": "这里应该用〈只需〉。「只需」表示只要求这些，「只能」表示只有这一种可能或办法，不能用来说需要多长时间。"}, {"text": "他不是坏人，只能有点粗心。", "explanation": "这里应该用〈只是〉。「只是」表示转折，「只能」表示只有这一种可能或办法，不能用于转折。"}, {"text": "只能你多努力，就能考上大学。", "explanation": "这里应该用〈只要〉。“只要……就……”表示充分条件，“只能”不用于这种条件句。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆小车只能会坐四个人。", "corrected_sentence": "这辆小车只能坐四个人。", "error_description": "错误：“只能会坐”。正确：“只能坐”。“只能”已表示范围受限，其后不再叠加助动词“会”，应说“只能坐四个人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路只能只能过一辆车。", "corrected_sentence": "这条路只能过一辆车。", "error_description": "错误：“只能只能”。正确：“只能”。“只能”是副词，不能重复使用；应说“这条路只能过一辆车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
