INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87233, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "预计是事情还没有发生，先想一想大概会怎样。", "primary_collocate": null, "pronunciation": "yù jì", "ipa": "y˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "预计明天会下大雨，你出门要带伞。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我预计他今天晚上会很晚回家。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生预计她下个星期就能出院。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师预计这次考试不会太难。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都预计这家公司明年会越来越好。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有预计到路上会有这么多车。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气象专家预计周末天气会变冷。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他预计自己三天后就能做完工作。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也没有预计到会出这样的事。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司预计新手机很快会卖得很好。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "对还没发生的事先做大概的判断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '679c1d60-cd18-4bd7-984c-952bf355ca55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87233, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "预计", "is_correct": true, "explanation": "预计（yù jì）是正确答案：事先估计将要发生的事。"}, {"text": "雨季", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，雨季意思是多雨的季节。"}, {"text": "玉器", "is_correct": false, "explanation": "q 与 j 声母不同（qì 与 jì），玉器意思是玉石做的器物。"}, {"text": "预制", "is_correct": false, "explanation": "zh 与 j 声母不同（zhì 与 jì），预制意思是事先制作好。"}], "explanations": {"预计": "预计（yù jì）是正确答案：事先估计将要发生的事。", "雨季": "yǔ（第三声）与 yù（第四声）声调不同，雨季意思是多雨的季节。", "玉器": "q 与 j 声母不同（qì 与 jì），玉器意思是玉石做的器物。", "预制": "zh 与 j 声母不同（zhì 与 jì），预制意思是事先制作好。"}, "sentence_index": null, "correct_answer": "预计"}, "level_3": {"options": [{"text": "预计", "is_correct": true, "explanation": "预计是正确答案：事先判断明天会下大雨。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体动作，不能用来判断天气。"}, {"text": "拥抱", "is_correct": false, "explanation": "配价：“拥抱”需要人作宾语，不能带“明天会下大雨”这样的小句。"}, {"text": "冲洗", "is_correct": false, "explanation": "语义：“冲洗”指用水清洗，与对天气的判断无关。"}], "explanations": {"预计": "预计是正确答案：事先判断明天会下大雨。", "咳嗽": "语义：“咳嗽”是身体动作，不能用来判断天气。", "拥抱": "配价：“拥抱”需要人作宾语，不能带“明天会下大雨”这样的小句。", "冲洗": "语义：“冲洗”指用水清洗，与对天气的判断无关。"}, "sentence_index": 0, "correct_answer": "预计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我提前预计了一张机票。", "explanation": "这里应该用〈预订〉。预计指估计事情将要发生，订机票要用预订。"}, {"text": "上课前，我们要预计课文。", "explanation": "这里应该用〈预习〉。预计指对未来事情的估计，课前学习新内容要用预习。"}, {"text": "出发前，我提前预计好了行李。", "explanation": "这里应该用〈预备〉。预计指估计事情的走向，提前准备物品要用预备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87233, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预计", "is_correct": true, "explanation": "预计是正确答案：气象专家事先判断周末的天气。"}, {"text": "监督", "is_correct": false, "explanation": "搭配：“监督”的对象是人或工作，不能监督“天气”。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：“品尝”指尝味道，与天气变化无关。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”需要车辆作宾语，句中没有可驾驶的车辆。"}], "explanations": {"预计": "预计是正确答案：气象专家事先判断周末的天气。", "监督": "搭配：“监督”的对象是人或工作，不能监督“天气”。", "品尝": "语义：“品尝”指尝味道，与天气变化无关。", "驾驶": "配价：“驾驶”需要车辆作宾语，句中没有可驾驶的车辆。"}, "sentence_index": 6, "correct_answer": "预计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我提前预计了下午三点的牙科检查。", "explanation": "这里应该用〈预约〉。预计指估计事情将要发生，约定看病的时间要用预约。"}, {"text": "舞会前，同学们预计了一遍节目。", "explanation": "这里应该用〈预演〉。预计指估计事情的发展，正式演出前排练要用预演。"}, {"text": "下雨前，妈妈预计了两把雨伞。", "explanation": "这里应该用〈准备〉。预计指估计事情将要怎样，提前把东西备好要用准备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87233, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们预计地下周会收到结果。", "corrected_sentence": "我们预计下周会收到结果。", "error_description": "错误形式：“我们预计地下周会收到结果”。正确形式：“我们预计下周会收到结果”。“预计”后面直接接时间词和小句，不能加“地”；“地”只用在修饰动词的状语后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87233, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我预计过明天会下雨。", "corrected_sentence": "我预计明天会下雨。", "error_description": "错误形式：“我预计过明天会下雨”。正确形式：“我预计明天会下雨”。“预计”后面接的是对将来的判断，“过”表示已经有过的经历，不能和估计将来的小句一起用，要去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
