INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87234, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "事先计算或估计。", "primary_collocate": null, "pronunciation": "yù jì", "ipa": "y˥˩ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "这次旅行预计要花五千块钱。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂预计今年能做十万件衣服。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "修这座桥预计需要两年时间。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我预计这本书一共有三百页。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校预计下个月有两千个学生来参加。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板预计这个月能赚十万块。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房子预计明年三月就能盖好。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司预计今年的成本会比去年多一成。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我预计这些菜够十个人吃。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院预计每天会有五百个病人来看病。", "target_word": "预计", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事先估算数量、时间或费用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '679c1d60-cd18-4bd7-984c-952bf355ca55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87234, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "预计", "is_correct": true, "explanation": "预计（yù jì）是正确答案：事先计算或估计数量、时间或费用。"}, {"text": "雨季", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，雨季意思是多雨的季节。"}, {"text": "玉器", "is_correct": false, "explanation": "q 与 j 声母不同（qì 与 jì），玉器意思是玉石做的器物。"}, {"text": "预制", "is_correct": false, "explanation": "zh 与 j 声母不同（zhì 与 jì），预制意思是事先制作好。"}], "explanations": {"预计": "预计（yù jì）是正确答案：事先计算或估计数量、时间或费用。", "雨季": "yǔ（第三声）与 yù（第四声）声调不同，雨季意思是多雨的季节。", "玉器": "q 与 j 声母不同（qì 与 jì），玉器意思是玉石做的器物。", "预制": "zh 与 j 声母不同（zhì 与 jì），预制意思是事先制作好。"}, "sentence_index": null, "correct_answer": "预计"}, "level_3": {"options": [{"text": "预计", "is_correct": true, "explanation": "预计是正确答案：事先估计这次旅行要花费的钱数。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：“微笑”是表情，与花钱无关，句意不通。"}, {"text": "告别", "is_correct": false, "explanation": "搭配：“告别”后接的是人或地方，不能与“要花五千块钱”搭配。"}, {"text": "拥抱", "is_correct": false, "explanation": "配价：“拥抱”需要人作宾语，句中没有可拥抱的对象。"}], "explanations": {"预计": "预计是正确答案：事先估计这次旅行要花费的钱数。", "微笑": "语义：“微笑”是表情，与花钱无关，句意不通。", "告别": "搭配：“告别”后接的是人或地方，不能与“要花五千块钱”搭配。", "拥抱": "配价：“拥抱”需要人作宾语，句中没有可拥抱的对象。"}, "sentence_index": 0, "correct_answer": "预计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人预计了一座新桥。", "explanation": "这里应该用〈修建〉。预计指事先估计数量、时间或费用，建造桥梁要用修建。"}, {"text": "我们预计了客厅。", "explanation": "这里应该用〈装修〉。预计用于估计数量或费用，对房间进行改造要用装修。"}, {"text": "画家预计了一幅地图。", "explanation": "这里应该用〈绘制〉。预计指事先估计，画地图要用绘制。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87234, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "预计", "is_correct": true, "explanation": "预计是正确答案：估计房子明年三月能建好。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是身体动作，房子不会咳嗽，句意不通。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”需要车辆作宾语，句中缺少可驾驶的对象。"}, {"text": "监督", "is_correct": false, "explanation": "搭配：“监督”的对象是人或工作，房子不能监督“明年三月就能盖好”这样的事。"}], "explanations": {"预计": "预计是正确答案：估计房子明年三月能建好。", "咳嗽": "语义：“咳嗽”是身体动作，房子不会咳嗽，句意不通。", "驾驶": "配价：“驾驶”需要车辆作宾语，句中缺少可驾驶的对象。", "监督": "搭配：“监督”的对象是人或工作，房子不能监督“明年三月就能盖好”这样的事。"}, "sentence_index": 6, "correct_answer": "预计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们预计了新课文。", "explanation": "这里应该用〈预习〉。预计用于估计数量、时间或费用，课前学习课文要用预习。"}, {"text": "厨师预计了一桌好菜。", "explanation": "这里应该用〈烹饪〉。预计指事先估计，做菜要用烹饪。"}, {"text": "他们预计了一本教材。", "explanation": "这里应该用〈编写〉。预计用于估计，编写书籍要用编写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂预计地明年能完工。", "corrected_sentence": "工厂预计明年能完工。", "error_description": "错误形式：“工厂预计地明年能完工”。正确形式：“工厂预计明年能完工”。“预计”后面直接接时间词和小句，不能加“地”；“地”只用在修饰动词的状语后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器预计得能用十年。", "corrected_sentence": "这台机器预计能用十年。", "error_description": "错误形式：“这台机器预计得能用十年”。正确形式：“这台机器预计能用十年”。“得”用于动词后接补语，“预计”后面直接接能愿动词短语时不能加“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
