INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87235, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87235, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抢救是遇到危险时，赶紧去救人或救东西。", "primary_collocate": null, "pronunciation": "qiǎng jiù", "ipa": "tɕʰjɑŋ˨˩ tɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "消防员正在抢救困在楼上的老人。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员冲进大楼抢救里面的孩子。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大水来了，我们赶紧抢救仓库里的粮食。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失火时，他先抢救了家里的照片。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震以后，大家一起抢救倒塌房子里的人。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆着火了，老师们去抢救那些旧书。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船快沉了，船员们抢救着船上的货物。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他冲进火里抢救了一只小狗。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水快冲进村子了，大家赶紧抢救家里的东西。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们先抢救病人，别管行李了。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抢救了", "label": "完成体"}, {"form": "抢救着", "label": "进行体"}, {"form": "抢救过", "label": "经历体"}, {"form": "抢救室", "label": "复合词"}], "register": "中性", "sense_fingerprint": "遇到危险时赶紧去救人或救东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c98c2ea0-82f7-4d76-b905-50f0974de4d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87235, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欺负", "is_correct": false, "explanation": "语义：消防员的职责是救人，说他欺负被困的老人与救援情境完全相反。"}, {"text": "扑灭", "is_correct": false, "explanation": "搭配：“扑灭”搭配火、火苗等对象，不能用来搭配人。"}, {"text": "抢救", "is_correct": true, "explanation": "正确：“抢救”指在危急时刻迅速施救，与“困在楼上”的险情相符。"}, {"text": "惊吓", "is_correct": false, "explanation": "语义：“惊吓”是使人受惊，与消防员赶来施救的情境矛盾。"}], "explanations": {"欺负": "语义：消防员的职责是救人，说他欺负被困的老人与救援情境完全相反。", "扑灭": "搭配：“扑灭”搭配火、火苗等对象，不能用来搭配人。", "抢救": "正确：“抢救”指在危急时刻迅速施救，与“困在楼上”的险情相符。", "惊吓": "语义：“惊吓”是使人受惊，与消防员赶来施救的情境矛盾。"}, "sentence_index": 0, "correct_answer": "抢救"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春节前大家都去超市抢救打折的鸡蛋。", "explanation": "这里应该用〈抢购〉。“抢救”指危急时刻的紧急施救，争着买打折商品要用“抢购”。"}, {"text": "这个基金会每年抢救几百名贫困学生，资助他们上学。", "explanation": "这里应该用〈救助〉。“抢救”强调紧急施救，长期资助贫困学生要用“救助”。"}, {"text": "强盗在街上抢救了路人的钱包。", "explanation": "这里应该用〈抢劫〉。“抢救”是施救，这里描述的是强行夺取财物的犯罪行为，要用“抢劫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87235, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：船快沉了，船员还在欣赏货物，与紧急险情完全矛盾。"}, {"text": "画", "is_correct": false, "explanation": "搭配：“画”的对象是图像或画面，不能用来搭配货物。"}, {"text": "卖", "is_correct": false, "explanation": "语义：船快沉了还在卖货，与紧急施救的情境不符。"}, {"text": "抢救", "is_correct": true, "explanation": "正确：“抢救”指危急时刻迅速施救，与“船快沉了”的险情相符。"}], "explanations": {"欣赏": "语义：船快沉了，船员还在欣赏货物，与紧急险情完全矛盾。", "画": "搭配：“画”的对象是图像或画面，不能用来搭配货物。", "卖": "语义：船快沉了还在卖货，与紧急施救的情境不符。", "抢救": "正确：“抢救”指危急时刻迅速施救，与“船快沉了”的险情相符。"}, "sentence_index": 6, "correct_answer": "抢救"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生每周抢救他的皮肤病，已经好几个月了。", "explanation": "这里应该用〈治疗〉。“抢救”只用于紧急危险时的施救，长期的慢性皮肤病要用“治疗”。"}, {"text": "他每天都抢救一次自己的汽车，让它保持干净。", "explanation": "这里应该用〈保养〉。“抢救”只用于危急时刻，日常保持车子干净要用“保养”。"}, {"text": "医生每个月都抢救一次他的牙齿，看看有没有蛀牙。", "explanation": "这里应该用〈检查〉。“抢救”不用于例行的定期检查，看有没有蛀牙要用“检查”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87235, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防员被抢救了那位摔倒的老人。", "corrected_sentence": "消防员抢救了那位摔倒的老人。", "error_description": "“被”误用：“抢救”的施事是消防员，主动施救应直接说“消防员抢救了……”，不能在施救者前加“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87235, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生终于把病人抢救过去了。", "corrected_sentence": "医生终于把病人抢救过来了。", "error_description": "补语误用：病人被救回来要用“过来”，“过去”表示离开，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
