INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87236, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87236, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在危急情况下迅速施救。", "primary_collocate": null, "pronunciation": "qiǎng jiù", "ipa": "tɕʰjɑŋ˨˩ tɕjoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "医生用了三个小时抢救这个病人。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机晕倒后，路人马上打电话叫人来抢救。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子被救上岸时没有了呼吸，医生马上抢救他。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他中暑晕倒后，医生全力抢救他。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院抢救过很多重病的人。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士把昏迷的老人送进急诊室抢救。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车祸发生后，警察和医生一起抢救伤者。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃错药了，家人急忙送他去医院抢救。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人突然倒在路上，年轻人马上抢救他。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳的人没有了呼吸，救生员立刻抢救。", "target_word": "抢救", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抢救了", "label": "完成体"}, {"form": "抢救着", "label": "进行体"}, {"form": "抢救过", "label": "经历体"}, {"form": "抢救室", "label": "复合词"}], "register": "中性", "sense_fingerprint": "危急时刻迅速施救，多指医疗急救", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c98c2ea0-82f7-4d76-b905-50f0974de4d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87236, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欺骗", "is_correct": false, "explanation": "语义：医生用三个小时去欺骗病人，与救治病人的职业行为相反。"}, {"text": "扑灭", "is_correct": false, "explanation": "搭配：“扑灭”搭配火、火苗等对象，不能用来搭配病人。"}, {"text": "抢救", "is_correct": true, "explanation": "正确：“抢救”指危急时刻迅速施救，与“用了三个小时”的救治过程相符。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：“冷落”是不理睬，与医生全力救治的情境矛盾。"}], "explanations": {"欺骗": "语义：医生用三个小时去欺骗病人，与救治病人的职业行为相反。", "扑灭": "搭配：“扑灭”搭配火、火苗等对象，不能用来搭配病人。", "抢救": "正确：“抢救”指危急时刻迅速施救，与“用了三个小时”的救治过程相符。", "冷落": "语义：“冷落”是不理睬，与医生全力救治的情境矛盾。"}, "sentence_index": 0, "correct_answer": "抢救"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他感冒了，妈妈在家抢救他。", "explanation": "这里应该用〈照顾〉。“抢救”只用于危急时刻的紧急施救，普通感冒的照料要用“照顾”。"}, {"text": "医生每个月抢救一次他的心脏，看看有没有问题。", "explanation": "这里应该用〈检查〉。“抢救”不用于例行检查，定期看心脏有没有问题要用“检查”。"}, {"text": "孩子哭个不停，妈妈抢救他，轻轻拍他的背。", "explanation": "这里应该用〈安慰〉。“抢救”指紧急救护，哭闹的孩子只需要安慰，要用“安慰”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87236, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通缉", "is_correct": false, "explanation": "语义：“通缉”指追捕罪犯，用来说伤者不合适，与医生救治的情境矛盾。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所，不能用来搭配伤者。"}, {"text": "抢救", "is_correct": true, "explanation": "正确：“抢救”指紧急施救，与“车祸发生后”的情境相符。"}, {"text": "取笑", "is_correct": false, "explanation": "语义：“取笑”是嘲笑，与医生和警察救治伤者的情境矛盾。"}], "explanations": {"通缉": "语义：“通缉”指追捕罪犯，用来说伤者不合适，与医生救治的情境矛盾。", "打扫": "搭配：“打扫”的对象是场所，不能用来搭配伤者。", "抢救": "正确：“抢救”指紧急施救，与“车祸发生后”的情境相符。", "取笑": "语义：“取笑”是嘲笑，与医生和警察救治伤者的情境矛盾。"}, "sentence_index": 6, "correct_answer": "抢救"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跑得很快，每次都抢救第一的位置。", "explanation": "这里应该用〈抢占〉。“抢救”是紧急施救，争抢位置要用“抢占”。"}, {"text": "周末商场里大家都在抢救打折的衣服。", "explanation": "这里应该用〈抢购〉。“抢救”指紧急施救，争着买打折商品要用“抢购”。"}, {"text": "小偷在路上抢救了老人的包。", "explanation": "这里应该用〈抢夺〉。“抢救”是施救，这里描述的是强行夺取财物，要用“抢夺”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87236, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们去年抢救了过一个病人。", "corrected_sentence": "我们去年抢救过一个病人。", "error_description": "体标误用：表示曾经做过要用“抢救过”，“了过”的组合不对，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87236, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "救生员把溺水的孩子抢救。", "corrected_sentence": "救生员把溺水的孩子抢救过来。", "error_description": "“把”字句不完整：“把”字句中动词“抢救”后要有补语，应在后面加“过来”，说“把溺水的孩子抢救过来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfbded26-6ae5-43a4-93e9-2299e59fd500') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
