INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87237, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "个中人是自己做过这件事、懂里面事情的人。", "primary_collocate": null, "pronunciation": "gè zhōng rén", "ipa": "kɤ˥˩ ʈʂʊŋ˥ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "他是这一行的个中人，最清楚做这一行的苦。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有个中人，才懂这份工作有多难。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他自己开过饭馆，是这一行的个中人。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个中人都知道，做这一行很不容易。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我作为个中人，所以明白你的难处。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当过十年护士，算是这一行的个中人。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听个中人说，这件事没有想象的那么简单。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想学开车，就去问个中人。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不是这一行的个中人，很难明白其中的辛苦。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当过运动员，作为个中人，说话很有分量。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "個中人", "label": "繁体"}], "register": "书面", "sense_fingerprint": "亲身做过某事、懂其中甘苦的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e64b3b0f-81c3-4b52-bcde-e97b5fd7793c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87237, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "局外人", "is_correct": false, "explanation": "语义：“局外人”指不在事情之中的人，与“最清楚这一行的苦”相矛盾。"}, {"text": "个中人", "is_correct": true, "explanation": "正确。“个中人”指亲身做过这件事、懂其中甘苦的人，与“最清楚这一行的苦”相合。"}, {"text": "菜鸟", "is_correct": false, "explanation": "语域：“菜鸟”是网络口语，与这句书面语的语体不协调；且指新手，也与“最清楚”矛盾。"}, {"text": "门外汉", "is_correct": false, "explanation": "语义：“门外汉”指对某事完全不懂的人，与“最清楚这一行的苦”相矛盾。"}], "explanations": {"局外人": "语义：“局外人”指不在事情之中的人，与“最清楚这一行的苦”相矛盾。", "个中人": "正确。“个中人”指亲身做过这件事、懂其中甘苦的人，与“最清楚这一行的苦”相合。", "菜鸟": "语域：“菜鸟”是网络口语，与这句书面语的语体不协调；且指新手，也与“最清楚”矛盾。", "门外汉": "语义：“门外汉”指对某事完全不懂的人，与“最清楚这一行的苦”相矛盾。"}, "sentence_index": 0, "correct_answer": "个中人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对修表一窍不通，是修表的个中人。", "explanation": "这里应该用〈外行〉。个中人指自己做过这件事、懂其中情况的人，对修表一窍不通的人不能称个中人。"}, {"text": "她从没亲手做过这件事，一直是这件事的个中人。", "explanation": "这里应该用〈局外人〉。个中人指自己做过这件事、懂其中情况的人，从没亲手做过的人不能称个中人。"}, {"text": "他只看过别人做，自己从没动过手，是这一行的个中人。", "explanation": "这里应该用〈旁观者〉。个中人指自己做过这件事的人，只看过别人做、自己没动过手的人不能称个中人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87237, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鹦鹉", "is_correct": false, "explanation": "语义：鹦鹉只会学话，讲不出亲身经历的经验，与“没有想象的那么简单”的句意不符。"}, {"text": "个中人", "is_correct": true, "explanation": "正确。“听个中人说”指听亲身经历过这件事的人讲，与“没有想象的那么简单”的经验之谈相合。"}, {"text": "外星人", "is_correct": false, "explanation": "语义：外星人并非亲历此事的人，讲不出“这件事”的实际经验，与句意相矛盾。"}, {"text": "傻子", "is_correct": false, "explanation": "语域：“傻子”是口语贬称，用在书面语境中不协调，且说话人不可信，不符合“听……说”的语境。"}], "explanations": {"鹦鹉": "语义：鹦鹉只会学话，讲不出亲身经历的经验，与“没有想象的那么简单”的句意不符。", "个中人": "正确。“听个中人说”指听亲身经历过这件事的人讲，与“没有想象的那么简单”的经验之谈相合。", "外星人": "语义：外星人并非亲历此事的人，讲不出“这件事”的实际经验，与句意相矛盾。", "傻子": "语域：“傻子”是口语贬称，用在书面语境中不协调，且说话人不可信，不符合“听……说”的语境。"}, "sentence_index": 6, "correct_answer": "个中人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他只是在旁边看热闹的个中人，从没下过一盘棋。", "explanation": "这里应该用〈旁观者〉。个中人指自己做过这件事、懂其中甘苦的人，从没下过棋的人不能称个中人。"}, {"text": "他连病历都看不懂，是医院这一行的个中人。", "explanation": "这里应该用〈门外汉〉。个中人指自己做过这件事、懂其中情况的人，连病历都看不懂的人不能称个中人。"}, {"text": "他只是台下的个中人，连一句台词都背不出来。", "explanation": "这里应该用〈观众〉。个中人指懂其中甘苦、亲身做过的人，连台词都背不出的观众不能称个中人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87237, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只个中人讲的话很实在。", "corrected_sentence": "这位个中人讲的话很实在。", "error_description": "量词错误：“个中人”指人，量词应用“位”或“个”，不能用“只”（“只”多用于动物、成对之物）。应改为「这位个中人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87237, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是这一行个中人。", "corrected_sentence": "她是这一行的个中人。", "error_description": "的字遗漏：定语“这一行”与中心语“个中人”之间须加“的”，应为「她是这一行的个中人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87238, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87238, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87238, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身处其中、熟悉内情的人。", "primary_collocate": null, "pronunciation": "gè zhōng rén", "ipa": "kɤ˥˩ ʈʂʊŋ˥ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "个中人才知道公司里发生了什么。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是这件事的个中人，说得很清楚。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个中人说，这次比赛早就有安排了。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为个中人，她不愿意多谈那件事。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件旧案的个中人，现在都不在了。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听一位个中人讲，学校要换校长了。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有个中人，才清楚演艺圈的内情。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他身为个中人，知道这里面的所有秘密。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者去找了几位个中人了解情况。", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个中人不说，外人怎么会知道呢？", "target_word": "个中人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "個中人", "label": "繁体"}], "register": "书面", "sense_fingerprint": "身在事情之中、了解内幕的当事人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e64b3b0f-81c3-4b52-bcde-e97b5fd7793c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87238, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外人", "is_correct": false, "explanation": "语义：“外人”指公司之外的人，不可能知道公司内部的情况，与“才知道公司里发生了什么”相矛盾。"}, {"text": "个中人", "is_correct": true, "explanation": "正确。“个中人”指身处其中、熟悉内情的人，与“才知道公司里发生了什么”相合。"}, {"text": "吃瓜群众", "is_correct": false, "explanation": "语域：“吃瓜群众”是网络俗语，与这句书面语的语体不协调；且并非身在其中之人。"}, {"text": "路人", "is_correct": false, "explanation": "语义：路人与公司无关，不可能了解公司内部的事，与句意相矛盾。"}], "explanations": {"外人": "语义：“外人”指公司之外的人，不可能知道公司内部的情况，与“才知道公司里发生了什么”相矛盾。", "个中人": "正确。“个中人”指身处其中、熟悉内情的人，与“才知道公司里发生了什么”相合。", "吃瓜群众": "语域：“吃瓜群众”是网络俗语，与这句书面语的语体不协调；且并非身在其中之人。", "路人": "语义：路人与公司无关，不可能了解公司内部的事，与句意相矛盾。"}, "sentence_index": 0, "correct_answer": "个中人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这行完全是个中人，连门道都摸不着。", "explanation": "这里应该用〈门外汉〉。个中人指身处其中、熟悉内情的人，连门道都摸不着的人不能称个中人。"}, {"text": "路过的游客也是个中人，对这件事很了解。", "explanation": "这里应该用〈局外人〉。个中人指身处其中、熟悉内情的人，路过的游客并不身在其中，应说局外人。"}, {"text": "他只是台下的个中人，对内情一无所知。", "explanation": "这里应该用〈观众〉。个中人指身处其中、熟悉内情的人，台下观众对内情一无所知，不能称个中人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87238, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "观众", "is_correct": false, "explanation": "语义：观众只是看演出的人，并不了解演艺圈的内情，与“清楚演艺圈的内情”相矛盾。"}, {"text": "个中人", "is_correct": true, "explanation": "正确。“个中人”指身处其中、熟悉内情的人，与“清楚演艺圈的内情”相合。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：小学生接触不到演艺圈的内部情况，与“清楚演艺圈的内情”相矛盾。"}, {"text": "旁人", "is_correct": false, "explanation": "语义：“旁人”指不在其中的旁观者，与“清楚演艺圈的内情”相矛盾。"}], "explanations": {"观众": "语义：观众只是看演出的人，并不了解演艺圈的内情，与“清楚演艺圈的内情”相矛盾。", "个中人": "正确。“个中人”指身处其中、熟悉内情的人，与“清楚演艺圈的内情”相合。", "小学生": "语义：小学生接触不到演艺圈的内部情况，与“清楚演艺圈的内情”相矛盾。", "旁人": "语义：“旁人”指不在其中的旁观者，与“清楚演艺圈的内情”相矛盾。"}, "sentence_index": 6, "correct_answer": "个中人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是书法的个中人，从没碰过毛笔。", "explanation": "这里应该用〈行外人〉。个中人指身处其中、熟悉内情的人，从没碰过毛笔的人并不身在其中，不能称个中人。"}, {"text": "他是修车的个中人，连发动机都没见过。", "explanation": "这里应该用〈外人〉。个中人指身处其中、熟悉内情的人，连发动机都没见过的人不能称个中人。"}, {"text": "他是这起案子的个中人，却从来没听说过这起案子。", "explanation": "这里应该用〈局外人〉。个中人指身处其中、熟悉内情的人，从没听说过这起案子的人并不身在其中，不能称个中人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只个中人说的话很有道理。", "corrected_sentence": "那位个中人说的话很有道理。", "error_description": "量词错误：“个中人”指人，量词应用“位”或“个”，不能用“只”。应改为「那位个中人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是这家店个中人。", "corrected_sentence": "她是这家店的个中人。", "error_description": "的字遗漏：定语“这家店”与中心语“个中人”之间须加“的”，应为「她是这家店的个中人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
