INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87239, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于定期举行的会议、比赛等，表示第几次。", "primary_collocate": null, "pronunciation": "jiè", "ipa": "tɕjɛ˥˩", "syllable_count": 1, "sentences": [{"text": "第三十三届奥运会在巴黎举行。", "target_word": "届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是第一届足球比赛。", "target_word": "届", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的第十届运动会明天开始。", "target_word": "届", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下一届比赛在北京举行。", "target_word": "届", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他参加了上一届运动会。", "target_word": "届", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "第二十二届世界杯在卡塔尔举行。", "target_word": "届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这届运动会很热闹。", "target_word": "届", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "第五届读书会有一百多人来。", "target_word": "届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我第一次参加这一届大会。", "target_word": "届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上一届比赛，我们班得了第一名。", "target_word": "届", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "屆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "量词：定期举行的会议或比赛的第几回", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96df1d2b-98d4-4058-aa95-b548c2ba3b98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87239, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "届", "is_correct": true, "explanation": "正确：“届”（jiè）是量词，表示定期会议或比赛的第几回。"}, {"text": "街", "is_correct": false, "explanation": "jiē（第一声）与 jiè（第四声）声调不同，意思是街道。"}, {"text": "节", "is_correct": false, "explanation": "jié（第二声）与 jiè（第四声）声调不同，意思是节日或节目。"}, {"text": "姐", "is_correct": false, "explanation": "jiě（第三声）与 jiè（第四声）声调不同，意思是姐姐。"}, {"text": "接", "is_correct": false, "explanation": "jiē（第一声）与 jiè（第四声）声调不同，意思是接收、接到。"}], "explanations": {"届": "正确：“届”（jiè）是量词，表示定期会议或比赛的第几回。", "街": "jiē（第一声）与 jiè（第四声）声调不同，意思是街道。", "节": "jié（第二声）与 jiè（第四声）声调不同，意思是节日或节目。", "姐": "jiě（第三声）与 jiè（第四声）声调不同，意思是姐姐。", "接": "jiē（第一声）与 jiè（第四声）声调不同，意思是接收、接到。"}, "sentence_index": null, "correct_answer": "届"}, "level_3": {"options": [{"text": "届", "is_correct": true, "explanation": "正确：“第三十三届奥运会”中，“届”用于定期举行的比赛计数。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于平面的东西，不能用来计数奥运会。"}, {"text": "位", "is_correct": false, "explanation": "语义：“位”用于人，奥运会不是人，不能用“位”计数。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、桥、建筑等大型固定物，不用于运动会。"}], "explanations": {"届": "正确：“第三十三届奥运会”中，“届”用于定期举行的比赛计数。", "张": "搭配：“张”用于平面的东西，不能用来计数奥运会。", "位": "语义：“位”用于人，奥运会不是人，不能用“位”计数。", "座": "搭配：“座”用于山、桥、建筑等大型固定物，不用于运动会。"}, "sentence_index": 0, "correct_answer": "届"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这届小说很精彩，大家都在读。", "explanation": "这里应该用〈部〉。小说用“部”计数，“届”只用于定期举行的会议、比赛或毕业班。"}, {"text": "这届树长得很高。", "explanation": "这里应该用〈棵〉。树用“棵”计数，“届”只用于定期举行的会议、比赛或毕业班。"}, {"text": "这届火车开得很快。", "explanation": "这里应该用〈列〉。火车用“列”计数，“届”只用于定期举行的会议或比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87239, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "届", "is_correct": true, "explanation": "正确：“届”（jiè）是量词，表示定期会议或比赛的第几回。"}, {"text": "解", "is_correct": false, "explanation": "jiě（第三声）与 jiè（第四声）声调不同，意思是解开、解答。"}, {"text": "结", "is_correct": false, "explanation": "jié（第二声）与 jiè（第四声）声调不同，意思是结束、结果。"}, {"text": "阶", "is_correct": false, "explanation": "jiē（第一声）与 jiè（第四声）声调不同，意思是台阶、阶段。"}, {"text": "截", "is_correct": false, "explanation": "jié（第二声）与 jiè（第四声）声调不同，意思是截止、截断。"}], "explanations": {"届": "正确：“届”（jiè）是量词，表示定期会议或比赛的第几回。", "解": "jiě（第三声）与 jiè（第四声）声调不同，意思是解开、解答。", "结": "jié（第二声）与 jiè（第四声）声调不同，意思是结束、结果。", "阶": "jiē（第一声）与 jiè（第四声）声调不同，意思是台阶、阶段。", "截": "jié（第二声）与 jiè（第四声）声调不同，意思是截止、截断。"}, "sentence_index": null, "correct_answer": "届"}, "level_3": {"options": [{"text": "届", "is_correct": true, "explanation": "正确：“我们这届运动会”中，“届”表示这一次定期举行的运动会。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”多用于动物或成对物品中的一个，不能用于运动会。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于有柄或可握的东西，不能用于运动会。"}, {"text": "株", "is_correct": false, "explanation": "语义：“株”用于植物，运动会不能用“株”计数。"}], "explanations": {"届": "正确：“我们这届运动会”中，“届”表示这一次定期举行的运动会。", "只": "搭配：“只”多用于动物或成对物品中的一个，不能用于运动会。", "把": "搭配：“把”用于有柄或可握的东西，不能用于运动会。", "株": "语义：“株”用于植物，运动会不能用“株”计数。"}, "sentence_index": 6, "correct_answer": "届"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这届手术很成功。", "explanation": "这里应该用〈次〉。手术是一次性的事，“届”只用于定期举行的会议、比赛或毕业班。"}, {"text": "这届事故很严重。", "explanation": "这里应该用〈起〉。事故用“起”计数，“届”只用于定期举行的会议、比赛或毕业班。"}, {"text": "这届火灾很严重。", "explanation": "这里应该用〈场〉。火灾用“场”计数，“届”只用于定期举行的会议、比赛或毕业班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_u