INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87241, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "鬼是故事里的东西，人们说它是人死后变成的，常让人害怕。", "primary_collocate": null, "pronunciation": "guǐ", "ipa": "kuei˨˩˦", "syllable_count": 1, "sentences": [{"text": "这部电影里的鬼让我很害怕。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "万圣节那天，他穿着白衣服扮成鬼。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的鬼每天晚上都会哭。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明说他不怕鬼，可是不敢关灯。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里说，鬼白天看不见，晚上才出来。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我们讲了一个鬼的故事。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑黑的房间里，好像有一个鬼在看我。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟听了鬼的故事，晚上不敢去厕所。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个鬼穿着白衣服，头发很长。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，鬼最怕太阳。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个鬼", "label": "量词"}, {"form": "鬼魂", "label": "复合"}], "register": "中性", "sense_fingerprint": "故事里让人害怕的、人死后变成的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '679c1d60-cd18-4bd7-984c-952bf355ca55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87241, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鬼", "is_correct": true, "explanation": "guǐ（第三声）指故事中让人害怕、人死后变成的东西，是本词的读音和意思。"}, {"text": "贵", "is_correct": false, "explanation": "guì（第四声）与 guǐ（第三声）声调不同，意思是价格高。"}, {"text": "归", "is_correct": false, "explanation": "guī（第一声）与 guǐ（第三声）声调不同，意思是返回。"}, {"text": "悔", "is_correct": false, "explanation": "huǐ（第三声）与 guǐ 声母不同（h 与 g），意思是后悔。"}], "explanations": {"鬼": "guǐ（第三声）指故事中让人害怕、人死后变成的东西，是本词的读音和意思。", "贵": "guì（第四声）与 guǐ（第三声）声调不同，意思是价格高。", "归": "guī（第一声）与 guǐ（第三声）声调不同，意思是返回。", "悔": "huǐ（第三声）与 guǐ 声母不同（h 与 g），意思是后悔。"}, "sentence_index": null, "correct_answer": "鬼"}, "level_3": {"options": [{"text": "鬼", "is_correct": true, "explanation": "正确：“鬼”是电影里让人害怕的东西，符合“让我很害怕”的语境。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“让我很害怕”需要令人恐惧的人或事物作主语，“价格”不能让人害怕。"}, {"text": "米饭", "is_correct": false, "explanation": "语义：“米饭”不是令人害怕的东西，与“电影里”的恐怖情节冲突。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是疾病，不是电影里让人害怕的形象，句意不通。"}], "explanations": {"鬼": "正确：“鬼”是电影里让人害怕的东西，符合“让我很害怕”的语境。", "价格": "搭配：“让我很害怕”需要令人恐惧的人或事物作主语，“价格”不能让人害怕。", "米饭": "语义：“米饭”不是令人害怕的东西，与“电影里”的恐怖情节冲突。", "感冒": "语义：“感冒”是疾病，不是电影里让人害怕的形象，句意不通。"}, "sentence_index": 0, "correct_answer": "鬼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个鬼每天都按时上课，从不迟到。", "explanation": "这里应该用〈学生〉。“鬼”指人死后变成的灵魂，不能用来指正在上学的学生，说“这个学生”才自然。"}, {"text": "鬼在商店里卖水果，价格很便宜。", "explanation": "这里应该用〈老板〉。“鬼”指故事里人死后变成的东西，不能用来指在商店里卖东西的人，说“老板”才自然。"}, {"text": "我的鬼每天早上都会去公园散步。", "explanation": "这里应该用〈爷爷〉。“鬼”指人死后变成的灵魂，不能用来指活着的家人，说“我爷爷”才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87241, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "鬼", "is_correct": true, "explanation": "guǐ（第三声）指故事中让人害怕、人死后变成的东西，是本词的读音和意思。"}, {"text": "柜", "is_correct": false, "explanation": "guì（第四声）与 guǐ（第三声）声调不同，意思是柜子。"}, {"text": "规", "is_correct": false, "explanation": "guī（第一声）与 guǐ（第三声）声调不同，意思是规则。"}, {"text": "毁", "is_correct": false, "explanation": "huǐ（第三声）与 guǐ 声母不同（h 与 g），意思是毁坏。"}], "explanations": {"鬼": "guǐ（第三声）指故事中让人害怕、人死后变成的东西，是本词的读音和意思。", "柜": "guì（第四声）与 guǐ（第三声）声调不同，意思是柜子。", "规": "guī（第一声）与 guǐ（第三声）声调不同，意思是规则。", "毁": "huǐ（第三声）与 guǐ 声母不同（h 与 g），意思是毁坏。"}, "sentence_index": null, "correct_answer": "鬼"}, "level_3": {"options": [{"text": "鬼", "is_correct": true, "explanation": "正确：“鬼”会在房间里“看我”，符合句中的视线描写。"}, {"text": "柜子", "is_correct": false, "explanation": "搭配：“看我”需要有视线的人或动物，柜子不能看人。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯是照明用品，与“好像有一个……在看我”的恐怖氛围不协调。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：石头没有眼睛，不能“看我”。"}], "explanations": {"鬼": "正确：“鬼”会在房间里“看我”，符合句中的视线描写。", "柜子": "搭配：“看我”需要有视线的人或动物，柜子不能看人。", "台灯": "语义：台灯是照明用品，与“好像有一个……在看我”的恐怖氛围不协调。", "石头": "搭配：石头没有眼睛，不能“看我”。"}, "sentence_index": 6, "correct_answer": "鬼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的鬼今年二十岁，正在大学读书。", "explanation": "这里应该用〈表哥〉。“鬼”指人死后变成的灵魂，不能用来指活着的亲戚，说“我的表哥”才自然。"}, {"text": "鬼在医院里给病人看病。", "explanation": "这里应该用〈医生〉。“鬼”指人死后变成的灵魂，不能用来指正在给病人看病的人，说“医生”才自然。"}, {"text": "鬼在教室里教我们画画。", "explanation": "这里应该用〈老师〉。“鬼”指人死后变成的灵魂，不能用来指教室里的老师，说“老师”才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87241, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈说，村里那座老房子里住着一块鬼。", "corrected_sentence": "妈妈说，村里那座老房子里住着一个鬼。", "error_description": "量词错误：“鬼”应该用量词“个”，“块”用于块状物，不能用来数“鬼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87241, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "夜里，小院子里有很多鬼们在走动。", "corrected_sentence": "夜里，小院子里有很多鬼在走动。", "error_description": "复数错误：名词前面已经有“很多”，后面就不能再加“们”，正确说法是“很多鬼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
