INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87242, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "迷信或传说中人死后的灵魂。", "primary_collocate": null, "pronunciation": "guǐ", "ipa": "kuei˨˩˦", "syllable_count": 1, "sentences": [{"text": "奶奶说，人死了会变成鬼。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人小时候都怕鬼。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说昨天晚上在老房子里看见了鬼。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你相信世界上有鬼吗？", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传说那座山上有一个鬼。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不信鬼，晚上也敢一个人走夜路。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "七月十五的晚上，鬼会出来走动。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事讲的是一个鬼和一个小男孩。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说这家医院晚上有鬼，没人敢去。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子听了鬼的故事，晚上睡不着觉。", "target_word": "鬼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个鬼", "label": "量词"}, {"form": "鬼魂", "label": "复合"}], "register": "中性", "sense_fingerprint": "迷信或传说里人死后的灵魂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '679c1d60-cd18-4bd7-984c-952bf355ca55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87242, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鬼", "is_correct": true, "explanation": "guǐ（第三声）指迷信或传说中人死后的灵魂，是本词的读音和意思。"}, {"text": "贵", "is_correct": false, "explanation": "guì（第四声）与 guǐ（第三声）声调不同，意思是价格高。"}, {"text": "归", "is_correct": false, "explanation": "guī（第一声）与 guǐ（第三声）声调不同，意思是返回。"}, {"text": "悔", "is_correct": false, "explanation": "huǐ（第三声）与 guǐ 声母不同（h 与 g），意思是后悔。"}], "explanations": {"鬼": "guǐ（第三声）指迷信或传说中人死后的灵魂，是本词的读音和意思。", "贵": "guì（第四声）与 guǐ（第三声）声调不同，意思是价格高。", "归": "guī（第一声）与 guǐ（第三声）声调不同，意思是返回。", "悔": "huǐ（第三声）与 guǐ 声母不同（h 与 g），意思是后悔。"}, "sentence_index": null, "correct_answer": "鬼"}, "level_3": {"options": [{"text": "鬼", "is_correct": true, "explanation": "正确：“鬼”指人死后变成的灵魂，与“人死了会变成”的语境相符。"}, {"text": "灯", "is_correct": false, "explanation": "语义：“灯”不是人死后会变成的东西，与“人死了”的语境冲突。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“变成”后面不能接“名字”，人死后不会变成名字。"}, {"text": "书", "is_correct": false, "explanation": "语义：“书”不是人死后变成的东西，句意不通。"}], "explanations": {"鬼": "正确：“鬼”指人死后变成的灵魂，与“人死了会变成”的语境相符。", "灯": "语义：“灯”不是人死后会变成的东西，与“人死了”的语境冲突。", "名字": "搭配：“变成”后面不能接“名字”，人死后不会变成名字。", "书": "语义：“书”不是人死后变成的东西，句意不通。"}, "sentence_index": 0, "correct_answer": "鬼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的每个鬼都很努力，每天按时交作业。", "explanation": "这里应该用〈人〉。“鬼”指人死后的灵魂，不能用来指班里还活着的同学，说“每个人”才自然。"}, {"text": "鬼在饭店里给客人做菜，做得很好吃。", "explanation": "这里应该用〈厨师〉。“鬼”指人死后的灵魂，不能用来指在饭店做菜的人，说“厨师”才自然。"}, {"text": "家里来了几个鬼，妈妈忙着准备饭菜。", "explanation": "这里应该用〈客人〉。“鬼”指人死后的灵魂，不能用来指来家里做客的人，说“来了几个客人”才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87242, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "鬼", "is_correct": true, "explanation": "guǐ（第三声）指迷信或传说中人死后的灵魂，是本词的读音和意思。"}, {"text": "柜", "is_correct": false, "explanation": "guì（第四声）与 guǐ（第三声）声调不同，意思是柜子。"}, {"text": "规", "is_correct": false, "explanation": "guī（第一声）与 guǐ（第三声）声调不同，意思是规则。"}, {"text": "毁", "is_correct": false, "explanation": "huǐ（第三声）与 guǐ 声母不同（h 与 g），意思是毁坏。"}], "explanations": {"鬼": "guǐ（第三声）指迷信或传说中人死后的灵魂，是本词的读音和意思。", "柜": "guì（第四声）与 guǐ（第三声）声调不同，意思是柜子。", "规": "guī（第一声）与 guǐ（第三声）声调不同，意思是规则。", "毁": "huǐ（第三声）与 guǐ 声母不同（h 与 g），意思是毁坏。"}, "sentence_index": null, "correct_answer": "鬼"}, "level_3": {"options": [{"text": "鬼", "is_correct": true, "explanation": "正确：“鬼”是传说中会在夜里出来活动的灵魂，与“晚上出来走动”相符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳白天出来，与“七月十五的晚上”的时间条件冲突。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“走动”用于人或动物，窗户不能走动。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：石头没有行动能力，不能说“出来走动”。"}], "explanations": {"鬼": "正确：“鬼”是传说中会在夜里出来活动的灵魂，与“晚上出来走动”相符。", "太阳": "语义：太阳白天出来，与“七月十五的晚上”的时间条件冲突。", "窗户": "搭配：“走动”用于人或动物，窗户不能走动。", "石头": "搭配：石头没有行动能力，不能说“出来走动”。"}, "sentence_index": 6, "correct_answer": "鬼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我最好的鬼住在隔壁，我们常常一起上学。", "explanation": "这里应该用〈朋友〉。“鬼”指人死后的灵魂，不能用来指活着的好朋友，说“我最好的朋友”才自然。"}, {"text": "鬼在路口指挥交通，大家都很听话。", "explanation": "这里应该用〈警察〉。“鬼”指人死后的灵魂，不能用来指正在指挥交通的人，说“警察”才自然。"}, {"text": "我的鬼很聪明，学习成绩总是第一。", "explanation": "这里应该用〈同桌〉。“鬼”指人死后的灵魂，不能用来指同班的活人，说“我的同桌”才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "外婆常说，她小时候看见过一张鬼。", "corrected_sentence": "外婆常说，她小时候看见过一个鬼。", "error_description": "量词错误：“鬼”应该用量词“个”，“张”用于平面的东西，不能用来数“鬼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那座老房子里住着很多鬼们。", "corrected_sentence": "那座老房子里住着很多鬼。", "error_description": "复数错误：名词前面已经有“很多”，后面就不能再加“们”，正确说法是“很多鬼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
