INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87243, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "担保是说“我保证他没问题”，要是有问题，我来负责。", "primary_collocate": null, "pronunciation": "dān bǎo", "ipa": "tan⁵⁵ pau²¹⁴", "syllable_count": 2, "sentences": [{"text": "我可以担保他是好人。", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我担保他不会迟到。", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你放心，我担保他没问题。", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师担保这个学生不会说谎。", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理担保新同事能做好这件事。", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁敢担保他明天一定来？", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不能担保他会同意。", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈担保弟弟会按时回家。", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他担保朋友没拿过那本书。", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我担保他做事认真。", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "担保了", "label": "体标"}, {"form": "担保过", "label": "体标"}, {"form": "担保人", "label": "复合"}], "register": "中性", "sense_fingerprint": "口头保证某人或某事没问题，出事自己负责", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e2e0b30-a3a1-4ae4-9be1-ab2c143552df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87243, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "骂", "is_correct": false, "explanation": "语义：“骂”是责备，与“他是好人”的判断矛盾，句子说不通。"}, {"text": "担保", "is_correct": true, "explanation": "担保：口头保证某人没问题并负责，符合“我可以……他是好人”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语是食物，不能接“他是好人”这样的小句。"}, {"text": "吵", "is_correct": false, "explanation": "语义：“吵”指争吵，不能用来说明对一个人的好坏判断。"}], "explanations": {"骂": "语义：“骂”是责备，与“他是好人”的判断矛盾，句子说不通。", "担保": "担保：口头保证某人没问题并负责，符合“我可以……他是好人”的语境。", "吃": "配价：“吃”的宾语是食物，不能接“他是好人”这样的小句。", "吵": "语义：“吵”指争吵，不能用来说明对一个人的好坏判断。"}, "sentence_index": 0, "correct_answer": "担保"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张照片可以担保他当时在场。", "explanation": "这里应该用〈证明〉。担保是人口头保证并负责，照片不能担保；证明事实要用“证明”。"}, {"text": "他担保自己说了谎。", "explanation": "这里应该用〈承认〉。担保是保证某事没问题，承认错误要用“承认”。"}, {"text": "他担保了这件事的原因。", "explanation": "这里应该用〈解释〉。担保指作保并负责，说明原因要用“解释”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87243, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿咬，与能否保证他同意无关。"}, {"text": "卖", "is_correct": false, "explanation": "配价：“卖”后面不能接“他会同意”这样的小句作宾语，句子不通。"}, {"text": "担保", "is_correct": true, "explanation": "担保：口头保证某事没问题并承担责任，符合“我不能……他会同意”的语境。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指燃烧或加热，与他是否同意没有关系。"}], "explanations": {"咬": "语义：“咬”指用牙齿咬，与能否保证他同意无关。", "卖": "配价：“卖”后面不能接“他会同意”这样的小句作宾语，句子不通。", "担保": "担保：口头保证某事没问题并承担责任，符合“我不能……他会同意”的语境。", "烧": "语义：“烧”指燃烧或加热，与他是否同意没有关系。"}, "sentence_index": 6, "correct_answer": "担保"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我担保他昨天去了哪儿。", "explanation": "这里应该用〈知道〉。担保是保证某事没问题，不能接“去了哪儿”这样的疑问内容。"}, {"text": "他担保这道菜太咸了。", "explanation": "这里应该用〈抱怨〉。担保表示保证没问题，说出不满要用“抱怨”。"}, {"text": "我担保老师的帮助。", "explanation": "这里应该用〈感谢〉。担保是保证某人或某事没问题，对帮助表示谢意要用“感谢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87243, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我担保了过他会按时到。", "corrected_sentence": "我担保过他会按时到。", "error_description": "错误在“担保”的体标：“了”和“过”不能同时用在动词后。应说“担保过”，不能说“担保了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87243, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我担保他会不会来。", "corrected_sentence": "我担保他会来。", "error_description": "错误在于「会不会」。担保要接一个确定的内容，不能接正反疑问形式，应说「我担保他会来」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
