INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87244, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "保证某人或某事不出问题，并承担责任。", "primary_collocate": null, "pronunciation": "dān bǎo", "ipa": "tan⁵⁵ pau²¹⁴", "syllable_count": 2, "sentences": [{"text": "银行要有人担保才借钱给他。", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板愿意为这笔贷款担保。", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我可以担保这批货没问题。", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿房子给朋友担保。", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人愿意给他担保。", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的东西，我敢担保质量好。", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来担保这笔钱能还上？", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲为我担保了一笔学费贷款。", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司担保这台机器能用三年。", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行不要你担保，只要工资单。", "target_word": "担保", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "担保了", "label": "体标"}, {"form": "担保过", "label": "体标"}, {"form": "担保人", "label": "复合"}], "register": "中性", "sense_fingerprint": "为借款、货物、质量等事情作保并承担责任", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e2e0b30-a3a1-4ae4-9be1-ab2c143552df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87244, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偷", "is_correct": false, "explanation": "语义：“偷”指暗中拿走别人的东西，与作保、承担责任的意思不符，也不能说明借钱的条件。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与借钱的条件无关，句子说不通。"}, {"text": "担保", "is_correct": true, "explanation": "担保：为借款作保并承担责任，符合“银行要有人担保才借钱”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”一般接“饭”“钱”等宾语，不能用来指借款时需要的保证人。"}], "explanations": {"偷": "语义：“偷”指暗中拿走别人的东西，与作保、承担责任的意思不符，也不能说明借钱的条件。", "唱": "语义：“唱”指发出歌声，与借钱的条件无关，句子说不通。", "担保": "担保：为借款作保并承担责任，符合“银行要有人担保才借钱”的语境。", "吃": "搭配：“吃”一般接“饭”“钱”等宾语，不能用来指借款时需要的保证人。"}, "sentence_index": 0, "correct_answer": "担保"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事的后果由他担保。", "explanation": "这里应该用〈承担〉。担保的对象是借款、货物、质量等具体事项，不能说“后果”由谁担保。"}, {"text": "请把贵重物品交给前台担保。", "explanation": "这里应该用〈保管〉。担保是为某事作保并承担责任，不指看管物品。"}, {"text": "剩下的饭菜要放进冰箱担保。", "explanation": "这里应该用〈保存〉。担保是为借款、货物、质量等作保并承担责任，不指让食物不坏，应说“放进冰箱保存”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87244, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数", "is_correct": false, "explanation": "语义：“数”指点数钱的数目，无法说明这笔钱能否还上。"}, {"text": "担保", "is_correct": true, "explanation": "担保：承担责任、为还款作保，符合“谁来……这笔钱能还上”的语境。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”不与“钱”搭配，修理的对象不能是还款的保证。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指抹去污渍，与这笔钱能否还上没有关系，句子不通。"}], "explanations": {"数": "语义：“数”指点数钱的数目，无法说明这笔钱能否还上。", "担保": "担保：承担责任、为还款作保，符合“谁来……这笔钱能还上”的语境。", "修": "搭配：“修”不与“钱”搭配，修理的对象不能是还款的保证。", "擦": "语义：“擦”指抹去污渍，与这笔钱能否还上没有关系，句子不通。"}, "sentence_index": 6, "correct_answer": "担保"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士认真担保病人。", "explanation": "这里应该用〈照顾〉。担保指作保并承担责任，不用于照料人。"}, {"text": "工人正在担保电视。", "explanation": "这里应该用〈修理〉。担保不指修理物品，修电视要用“修理”。"}, {"text": "司机把这几个箱子担保到车上。", "explanation": "这里应该用〈搬〉。“担保”不能表示把东西移到某处，应说“司机把这几个箱子搬到车上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我替朋友担保了过一笔贷款。", "corrected_sentence": "我替朋友担保过一笔贷款。", "error_description": "错误在“担保”的体标：“过”表示经历，“了”不能与“过”同时用在动词后。应说“担保过”，不能说“担保了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "舅舅我担保了一笔房贷。", "corrected_sentence": "舅舅替我担保了一笔房贷。", "error_description": "“替”不能省略：为谁作保，要用“替”引出受益人“我”，应说“舅舅替我担保了一笔房贷”，不能说“舅舅我担保了一笔房贷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c04a5e88-a9db-40ab-b6be-305f6e0ac38a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
