INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87245, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87245, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "倒着是头在下面、脚在上面，或者是往后面走。", "primary_collocate": null, "pronunciation": "dào zhe", "ipa": "tau⁵¹ ʈʂə", "syllable_count": 2, "sentences": [{"text": "小猫倒着挂在树枝上。", "target_word": "倒着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他能倒着走两分钟。", "target_word": "倒着", "complexity_tier": "T3", "furigana": "tā néng dào zhe zǒu liǎng fēn zhōng.", "sentence_source": "generated"}, {"text": "蝙蝠倒着睡觉。", "target_word": "倒着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他倒着走进房间，不想让妈妈看到脸。", "target_word": "倒着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让他倒着走几步，检查腿。", "target_word": "倒着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他倒着走了几步，差点摔倒。", "target_word": "倒着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机倒着把车开出了小路。", "target_word": "倒着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他倒着躺在沙发上，头垂在下面。", "target_word": "倒着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杂技演员倒着从椅子上滑下来。", "target_word": "倒着", "complexity_tier": "T3", "furigana": "zá jì yǎn yuán dào zhe cóng yǐ zi shàng huá xià lái.", "sentence_source": "generated"}, {"text": "老人为了锻炼身体，每天在公园倒着走路。", "target_word": "倒着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倒着走", "label": "搭配"}, {"form": "倒着站", "label": "搭配"}], "register": "中性", "sense_fingerprint": "身体头朝下脚朝上，或向后退着行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f67254c-2b72-48f7-a62f-6cc95d11eae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87245, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "站着", "is_correct": false, "explanation": "语义：“站着”与“挂在树枝上”的姿势相矛盾，句子不通。"}, {"text": "倒着", "is_correct": true, "explanation": "倒着：指身体头朝下、脚朝上，与“挂在树枝上”的语境相合，句子通顺。"}, {"text": "趴着", "is_correct": false, "explanation": "语义：“趴着”是身体伏在某处的姿势，与“挂在树枝上”矛盾。"}, {"text": "缝着", "is_correct": false, "explanation": "搭配：“缝”的对象是布料、衣物，不能用来修饰小猫挂在树枝上的动作。"}], "explanations": {"站着": "语义：“站着”与“挂在树枝上”的姿势相矛盾，句子不通。", "倒着": "倒着：指身体头朝下、脚朝上，与“挂在树枝上”的语境相合，句子通顺。", "趴着": "语义：“趴着”是身体伏在某处的姿势，与“挂在树枝上”矛盾。", "缝着": "搭配：“缝”的对象是布料、衣物，不能用来修饰小猫挂在树枝上的动作。"}, "sentence_index": 0, "correct_answer": "倒着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他倒着向我问好，我很高兴。", "explanation": "这里容易和表示转折的“倒”（反而）混淆。“倒着”只指头朝下或向后退着行动，不能修饰“问好”。"}, {"text": "他倒着交了作业，老师很满意。", "explanation": "这里容易和表示转折的“倒”（反而）混淆。“倒着”只指头朝下或向后退着行动，不能修饰“交作业”。"}, {"text": "他倒着赞美了我的朋友。", "explanation": "这里容易和表示转折的“倒”（反而）混淆。“倒着”只指头朝下或向后退着行动，不能修饰“赞美”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87245, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "停着", "is_correct": false, "explanation": "语义：“停着”与“把车开出了小路”的行驶动作相矛盾，句子不通。"}, {"text": "拆着", "is_correct": false, "explanation": "搭配：“拆”的对象一般是物件，拆着的车无法再开出去，与后半句矛盾。"}, {"text": "倒着", "is_correct": true, "explanation": "倒着：指向后退着行驶，与“把车开出了小路”的语境相合，句子通顺。"}, {"text": "躺着", "is_correct": false, "explanation": "语义：“躺着”是身体平躺的姿势，无法同时完成开车的动作。"}], "explanations": {"停着": "语义：“停着”与“把车开出了小路”的行驶动作相矛盾，句子不通。", "拆着": "搭配：“拆”的对象一般是物件，拆着的车无法再开出去，与后半句矛盾。", "倒着": "倒着：指向后退着行驶，与“把车开出了小路”的语境相合，句子通顺。", "躺着": "语义：“躺着”是身体平躺的姿势，无法同时完成开车的动作。"}, "sentence_index": 6, "correct_answer": "倒着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的内容倒着很有趣。", "explanation": "这里容易和表示转折的“倒”（反而）混淆。“倒着”只指头朝下或向后退着行动，不能修饰“有趣”这类描述内容的词。"}, {"text": "他倒着同意了我的想法。", "explanation": "这里容易和表示转折的“倒”（反而）混淆。“倒着”只指头朝下或向后退着行动，不能修饰“同意”这种表态的动作。"}, {"text": "我的同学倒着长高了一厘米。", "explanation": "这里容易和表示转折的“倒”（反而）混淆。“倒着”只指头朝下或向后退着行动，长高是身高增加，不能修饰它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87245, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他倒着了走进房间，没有说话。", "corrected_sentence": "他倒着走进房间，没有说话。", "error_description": "“倒着”后面多加了“了”，形成“倒着了走”。“了”不能放在“倒着”和动词之间，应删去，写作“倒着走进房间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87245, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他倒着从树上了滑下来。", "corrected_sentence": "他倒着从树上滑了下来。", "error_description": "“了”应紧跟动词“滑”，写作“滑了下来”；“了”放在“滑”前面是错误的，应移到动词后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
