INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87246, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "颠倒方向或位置；与正常方向相反。", "primary_collocate": null, "pronunciation": "dào zhe", "ipa": "tau⁵¹ ʈʂə", "syllable_count": 2, "sentences": [{"text": "他把书倒着放在桌子上。", "target_word": "倒着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把名单倒着念一遍，从最后一个开始。", "target_word": "倒着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画倒着挂，你看出来了吗？", "target_word": "倒着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会倒着写自己的名字。", "target_word": "倒着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把杯子倒着放进柜子里，水才会流出去。", "target_word": "倒着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把顺序倒着排，最后一名排第一。", "target_word": "倒着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他倒着背了一遍这首诗，大家都笑了。", "target_word": "倒着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片倒着看也很有意思。", "target_word": "倒着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把帽子倒着戴，样子很特别。", "target_word": "倒着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字倒着写就成了另一个字。", "target_word": "倒着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倒过来", "label": "补语形式"}, {"form": "倒着走", "label": "搭配"}], "register": "中性", "sense_fingerprint": "把方向、位置或顺序颠倒，与正常相反", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f67254c-2b72-48f7-a62f-6cc95d11eae2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跑着", "is_correct": false, "explanation": "语义：“跑”是奔跑的动作，与“放在桌子上”的平稳动作矛盾，句子说不通。"}, {"text": "倒着", "is_correct": true, "explanation": "倒着：表示方向或位置颠倒，与“把书”“放在桌子上”的语境相合，句子通顺。"}, {"text": "洗着", "is_correct": false, "explanation": "搭配：“洗”一般搭配衣物、器具，不能说把书洗着放。"}, {"text": "唱着", "is_correct": false, "explanation": "语义：“唱着”是边唱歌边做事，与“把书放在桌子上”的动作无关，句子不通。"}], "explanations": {"跑着": "语义：“跑”是奔跑的动作，与“放在桌子上”的平稳动作矛盾，句子说不通。", "倒着": "倒着：表示方向或位置颠倒，与“把书”“放在桌子上”的语境相合，句子通顺。", "洗着": "搭配：“洗”一般搭配衣物、器具，不能说把书洗着放。", "唱着": "语义：“唱着”是边唱歌边做事，与“把书放在桌子上”的动作无关，句子不通。"}, "sentence_index": 0, "correct_answer": "倒着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师倒着表扬了我的作业，我很高兴。", "explanation": "这里容易和表示转折的“倒”（反而）混淆。“倒着”只表示方向或位置颠倒，不能修饰“表扬”这种言语动作。"}, {"text": "他倒着同意了我的建议。", "explanation": "这里容易和表示转折的“倒”（反而）混淆。“倒着”只表示方向或位置颠倒，不能修饰“同意”。"}, {"text": "天气倒着热了起来。", "explanation": "这里容易和表示转折的“倒”（反而）混淆。“倒着”只表示方向或位置颠倒，不能修饰“热起来”这种温度变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缝着", "is_correct": false, "explanation": "搭配：“缝”的对象是布料、衣物，不能用来修饰“背诗”。"}, {"text": "叠着", "is_correct": false, "explanation": "语义：“叠”是把东西折起来，与“背了一遍这首诗”毫无关系。"}, {"text": "倒着", "is_correct": true, "explanation": "倒着：这里指颠倒顺序地背诗，与“大家都笑了”的语境相合，句子通顺。"}, {"text": "削着", "is_correct": false, "explanation": "语义：“削”是去掉表皮的动作，与背诗的动作不搭，句子说不通。"}], "explanations": {"缝着": "搭配：“缝”的对象是布料、衣物，不能用来修饰“背诗”。", "叠着": "语义：“叠”是把东西折起来，与“背了一遍这首诗”毫无关系。", "倒着": "倒着：这里指颠倒顺序地背诗，与“大家都笑了”的语境相合，句子通顺。", "削着": "语义：“削”是去掉表皮的动作，与背诗的动作不搭，句子说不通。"}, "sentence_index": 6, "correct_answer": "倒着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班长倒着批评了我的错误，我很不服气。", "explanation": "这里容易和表示转折的“倒”（反而）混淆。“倒着”只表示方向或位置颠倒，不能修饰“批评”。"}, {"text": "他的成绩倒着提高了不少。", "explanation": "这里容易和表示转折的“倒”（反而）混淆。“倒着”只表示方向或位置颠倒，成绩提高是数量增长，不能用它修饰。"}, {"text": "妈妈倒着欢迎了客人。", "explanation": "这里容易和表示转折的“倒”（反而）混淆。“倒着”只表示方向或位置颠倒，不能修饰“欢迎”这类待客的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把相框倒着了放在柜子上。", "corrected_sentence": "她把相框倒着放在柜子上。", "error_description": "“倒着”中的“着”已表示状态，后面不能再加“了”；“倒着了放”是错误的，正确形式是“倒着放”，写作“她把相框倒着放在柜子上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她倒着了读三遍这段话。", "corrected_sentence": "她倒着读了三遍这段话。", "error_description": "“了”应紧跟动词“读”，写作“读了三遍”；“了”放在“倒着”后面、动词前面是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf331079-b55c-4aa3-b7a9-3fa2b6dc5978') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
