INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87247, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87247, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "后年是明年再过去的一年。", "primary_collocate": null, "pronunciation": "hòu nián", "ipa": "xou˥˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "明年我去北京，后年我去上海。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥后年大学毕业。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算后年结婚。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥后年才能修好。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年我八岁，后年我就十岁了。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后年的这个时候，我已经工作了。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司说后年会在这里开新店。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈想后年带我们去国外旅游。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明年不行，后年再说吧。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后年夏天，我们学校要搬家。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "後年", "label": "繁体"}], "register": "通用", "sense_fingerprint": "明年的下一年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0966929-86ca-4ac4-8d16-7e9b2ba39e93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87247, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后年", "is_correct": true, "explanation": "正确：与“明年”并列，指明年的下一年，符合句意。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”指今年以前，与前句的“明年”方向相反。"}, {"text": "前年", "is_correct": false, "explanation": "语义：“前年”指过去的年份，与“明年”的将来时间矛盾。"}, {"text": "后天", "is_correct": false, "explanation": "搭配：“明年”与“后天”不是同一时间单位，并列时应接年份词。"}], "explanations": {"后年": "正确：与“明年”并列，指明年的下一年，符合句意。", "去年": "语义：“去年”指今年以前，与前句的“明年”方向相反。", "前年": "语义：“前年”指过去的年份，与“明年”的将来时间矛盾。", "后天": "搭配：“明年”与“后天”不是同一时间单位，并列时应接年份词。"}, "sentence_index": 0, "correct_answer": "后年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我是后年大学毕业的。", "explanation": "这里应该用〈前年〉。后年指将来的那一年，“是……的”强调的是已经发生的事，表示过去的时间要用前年。"}, {"text": "我学汉语需要后年。", "explanation": "这里应该用〈两年〉。后年是某一年的时间点，表示一段时长时不能用后年。"}, {"text": "我后年都去一次北京，已经去了很多次。", "explanation": "这里应该用〈每年〉。后年只指将来的某一年，不能表示反复发生、已经发生过很多次的事，表示反复要用每年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87247, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后年", "is_correct": true, "explanation": "正确：指明年的下一年，与“会”表示的将来意义一致。"}, {"text": "去岁", "is_correct": false, "explanation": "语域：“去岁”是书面语，口语中的转述句通常不用；另外指过去，与“会”冲突。"}, {"text": "往年", "is_correct": false, "explanation": "语义：“往年”指过去的几年，与“会”表示的将来矛盾。"}, {"text": "从前", "is_correct": false, "explanation": "语义：“从前”指过去的时候，与“会在这里开新店”的未来计划冲突。"}], "explanations": {"后年": "正确：指明年的下一年，与“会”表示的将来意义一致。", "去岁": "语域：“去岁”是书面语，口语中的转述句通常不用；另外指过去，与“会”冲突。", "往年": "语义：“往年”指过去的几年，与“会”表示的将来矛盾。", "从前": "语义：“从前”指过去的时候，与“会在这里开新店”的未来计划冲突。"}, "sentence_index": 6, "correct_answer": "后年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的父母已经后年结婚了。", "explanation": "这里应该用〈去年〉。后年指将来的一年，与“已经……了”表示已经完成的事矛盾，已经发生的年份要用去年。"}, {"text": "学开车需要后年。", "explanation": "这里应该用〈半年〉。后年是某一年的时间点，表示一段时长不能用后年。"}, {"text": "下周见面，就定在后年。", "explanation": "这里应该用〈下周〉。后年指两年以后的那一年，不能用来指一周之内的安排，近期的安排要用下周。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87247, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我弟弟后年上了大学。", "corrected_sentence": "我弟弟后年上大学。", "error_description": "错误：“后年”指将来的时间，表示已完成的“了”与将来时间矛盾，应去掉“了”。正确说法是“我弟弟后年上大学。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87247, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他后年去了英国。", "corrected_sentence": "他后年去英国。", "error_description": "错误：“后年”指将来的某一年，表示已完成的“了”与将来时间矛盾，应去掉“了”。正确说法是“他后年去英国。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
