INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87248, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87248, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指明年的下一年。", "primary_collocate": null, "pronunciation": "hòu nián", "ipa": "xou˥˩ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "奶奶说后年她就七十岁了。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们后年再见面吧。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个比赛后年还会办。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后年春节我想回老家过。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他后年要去英国留学。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年太忙，后年我再休假。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影后年才能看到。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后年的今天是我的生日，我会请你吃饭。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐后年想买一辆新车。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子后年就要上小学了。", "target_word": "后年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "後年", "label": "繁体"}], "register": "通用", "sense_fingerprint": "明年的下一年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0966929-86ca-4ac4-8d16-7e9b2ba39e93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87248, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后年", "is_correct": true, "explanation": "正确：指明年的下一年，与“就七十岁了”的将来年龄相符。"}, {"text": "童年", "is_correct": false, "explanation": "语义：“童年”指孩提时期，与“七十岁”的年龄完全不合。"}, {"text": "青年", "is_correct": false, "explanation": "语义：“青年”指年轻时期，与“七十岁”的年龄完全不合。"}, {"text": "后晌", "is_correct": false, "explanation": "搭配：“后晌”指下午，不能用来限定“就七十岁了”这样的年龄变化。"}], "explanations": {"后年": "正确：指明年的下一年，与“就七十岁了”的将来年龄相符。", "童年": "语义：“童年”指孩提时期，与“七十岁”的年龄完全不合。", "青年": "语义：“青年”指年轻时期，与“七十岁”的年龄完全不合。", "后晌": "搭配：“后晌”指下午，不能用来限定“就七十岁了”这样的年龄变化。"}, "sentence_index": 0, "correct_answer": "后年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "后年我们一起去公园吧，就在下午。", "explanation": "这里应该用〈今天〉。后年指两年以后的那一年，句中“就在下午”说的是当天的事，把后年当作近期的时间用是误用。"}, {"text": "修这个项目需要后年。", "explanation": "这里应该用〈三个月〉。后年是某一年的时间点，表示时长不能用后年。"}, {"text": "我昨天是后年回来的。", "explanation": "这里应该用〈昨天〉。后年指将来的那一年，不能用来说已经发生的事，句中的“昨天”和“是……的”都表示过去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87248, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后年", "is_correct": true, "explanation": "正确：指明年的下一年，与“才能看到”的将来时间相符。"}, {"text": "瞬间", "is_correct": false, "explanation": "搭配：“瞬间”指极短的时刻，不能与需要较长时间才能实现的“才能看到”搭配。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”指刚刚过去的时间，与“才能看到”的将来时段冲突。"}, {"text": "黎明", "is_correct": false, "explanation": "语义：“黎明”指一天的清晨，不能作为“才能看到”这种以年为单位的时间限定。"}], "explanations": {"后年": "正确：指明年的下一年，与“才能看到”的将来时间相符。", "瞬间": "搭配：“瞬间”指极短的时刻，不能与需要较长时间才能实现的“才能看到”搭配。", "刚才": "语义：“刚才”指刚刚过去的时间，与“才能看到”的将来时段冲突。", "黎明": "语义：“黎明”指一天的清晨，不能作为“才能看到”这种以年为单位的时间限定。"}, "sentence_index": 6, "correct_answer": "后年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会议定在后年，下周就要开。", "explanation": "这里应该用〈下周〉。后年指两年以后的那一年，与“下周就要开”的近期安排矛盾，近期的安排要用下周。"}, {"text": "学开车需要后年。", "explanation": "这里应该用〈半年〉。后年是某一年的时间点，表示一段时长不能用后年。"}, {"text": "我们今天就出发，后年才到。", "explanation": "这里应该用〈明天〉。后年指两年以后的那一年，与“今天就出发”相差太远，不能表示到达的时间，明天到达才合理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87248, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐后年当了老师。", "corrected_sentence": "我姐姐后年当老师。", "error_description": "错误：“后年”指将来的时间，表示已完成的“了”与将来时间矛盾，应去掉“了”。正确说法是“我姐姐后年当老师。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87248, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他后年去了英国。", "corrected_sentence": "他后年去英国。", "error_description": "错误：“后年”指将来的某一年，表示已完成的“了”与将来时间矛盾，应去掉“了”。正确说法是“他后年去英国。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
