INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87249, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "扩建是把已经有的房子或路弄得更大。", "primary_collocate": null, "pronunciation": "kuò jiàn", "ipa": "kʰuɔ˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我们家的厨房太小，打算扩建。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷家的房子太小，他想扩建一下。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门前的小路太窄，村里决定扩建。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路太窄了，明年要扩建。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在房子后面扩建了一个小客厅。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想把车库扩建一下，好多放一辆车。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新房子住了几年，孩子多了，只好扩建。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村口的路已经扩建好了，车可以开过去。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房东不同意我们扩建这间小屋。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的老屋要扩建，所以全家先搬出去了。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扩建了", "label": "完成体"}, {"form": "扩建过", "label": "经历体"}, {"form": "擴建", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把已有的房子、院子、道路弄大（日常，家用或村里的小规模）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157c64-73c7-4e54-9585-b5a2f818129e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87249, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扩建", "is_correct": true, "explanation": "“扩建”表示把厨房扩大，与“太小，打算……”的语境相合。"}, {"text": "压缩", "is_correct": false, "explanation": "语义：压缩是使空间变小，与“厨房太小”需要扩大的语境相反。"}, {"text": "粉刷", "is_correct": false, "explanation": "搭配：粉刷用于墙面，不用于扩大厨房的空间。"}, {"text": "缩小", "is_correct": false, "explanation": "语义：缩小与“太小，想变大”的意思相反。"}], "explanations": {"扩建": "“扩建”表示把厨房扩大，与“太小，打算……”的语境相合。", "压缩": "语义：压缩是使空间变小，与“厨房太小”需要扩大的语境相反。", "粉刷": "搭配：粉刷用于墙面，不用于扩大厨房的空间。", "缩小": "语义：缩小与“太小，想变大”的意思相反。"}, "sentence_index": 0, "correct_answer": "扩建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵树太高了，明年要扩建。", "explanation": "这里应该用〈修剪〉。扩建只用于房屋、道路等设施，不用于树木。"}, {"text": "油烟机太脏了，明天要扩建。", "explanation": "这里应该用〈清洗〉。扩建是扩大房屋或道路的规模，油烟机脏了要清洗，不能用“扩建”。"}, {"text": "电梯坏了，明年要扩建。", "explanation": "这里应该用〈检修〉。电梯出故障要检修，扩大规模并不能解决故障。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87249, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扩建", "is_correct": true, "explanation": "“扩建”表示扩大房屋规模，与“孩子多了，只好……”的语境相合。"}, {"text": "缩减", "is_correct": false, "explanation": "语义：缩减是减少规模，与“孩子多了”需要更大空间的语境相反。"}, {"text": "清空", "is_correct": false, "explanation": "搭配：“清空”多用于容器或物品，不说清空房子来容纳更多孩子，句子不成立。"}, {"text": "压缩", "is_correct": false, "explanation": "语义：压缩是使空间变小，与“孩子多了”需要扩大空间的因果相反。"}], "explanations": {"扩建": "“扩建”表示扩大房屋规模，与“孩子多了，只好……”的语境相合。", "缩减": "语义：缩减是减少规模，与“孩子多了”需要更大空间的语境相反。", "清空": "搭配：“清空”多用于容器或物品，不说清空房子来容纳更多孩子，句子不成立。", "压缩": "语义：压缩是使空间变小，与“孩子多了”需要扩大空间的因果相反。"}, "sentence_index": 6, "correct_answer": "扩建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨房的墙要扩建，我们先搬出去了。", "explanation": "这里应该用〈粉刷〉。扩建要扩大结构规模，只是刷墙面要用“粉刷”。"}, {"text": "旧门要扩建，我们先搬出去了。", "explanation": "这里应该用〈更换〉。扩建是扩大规模，换新门要用“更换”。"}, {"text": "地面要扩建，我们先搬出去了。", "explanation": "这里应该用〈清扫〉。扩建的是房屋规模，地面脏了要清扫，扩建地面说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87249, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家把老房子扩建了成两层。", "corrected_sentence": "大家把老房子扩建成了两层。", "error_description": "错在“了”的位置：结果补语结构中“了”应放在“扩建成”之后，写成“扩建成了两层”；插在“扩建”和“成”之间是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87249, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家的厨房已经扩建完着。", "corrected_sentence": "我家的厨房已经扩建完了。", "error_description": "体标错误：“完了”中的“了”表示完成，“着”表示持续状态，与“完”的完成义相冲突；应写成“扩建完了”，不能用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
