INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87250, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在原有基础上扩大建筑规模。", "primary_collocate": null, "pronunciation": "kuò jiàn", "ipa": "kʰuɔ˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "学校打算扩建图书馆。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂去年扩建了两个车间。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机场在原来的基础上扩建，面积增加了一倍。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院扩建后，可以多住三百个病人。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府决定扩建这座体育馆。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园已经扩建过两次。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了接待更多游客，景区正在扩建停车场。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "港口明年春天开始扩建。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的厂房太小，准备在旁边扩建。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所小学扩建以后，多了十个教室。", "target_word": "扩建", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扩建了", "label": "完成体"}, {"form": "扩建过", "label": "经历体"}, {"form": "擴建", "label": "繁体"}], "register": "书面", "sense_fingerprint": "学校、工厂、医院、机场等设施在原有基础上扩大规模（正式，工程类）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157c64-73c7-4e54-9585-b5a2f818129e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87250, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扩建", "is_correct": true, "explanation": "“扩建”表示学校扩大图书馆的规模，与“打算……图书馆”的语境相合。"}, {"text": "缩小", "is_correct": false, "explanation": "语义：缩小与扩建的规模变化方向相反，与学校“打算……图书馆”扩大规模的计划不符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃图书馆。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能接建筑作宾语，“唱图书馆”不成立。"}], "explanations": {"扩建": "“扩建”表示学校扩大图书馆的规模，与“打算……图书馆”的语境相合。", "缩小": "语义：缩小与扩建的规模变化方向相反，与学校“打算……图书馆”扩大规模的计划不符。", "吃": "搭配：“吃”的对象是食物，不能说吃图书馆。", "唱": "搭配：“唱”不能接建筑作宾语，“唱图书馆”不成立。"}, "sentence_index": 0, "correct_answer": "扩建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公园的树枝太长，要扩建。", "explanation": "这里应该用〈修剪〉。扩建指扩大建筑规模，树枝太长要修剪，不能用“扩建”。"}, {"text": "这面墙破了，要扩建。", "explanation": "这里应该用〈修补〉。墙破了要修补，扩建是扩大规模，不能解决破损问题。"}, {"text": "电梯坏了，要扩建。", "explanation": "这里应该用〈检修〉。电梯出故障要检修，扩建不能解决故障。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87250, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扩建", "is_correct": true, "explanation": "“扩建”表示扩大停车场的规模，与“为了接待更多游客”的目的相合。"}, {"text": "缩减", "is_correct": false, "explanation": "语义：缩减会减少停车位，与“为了接待更多游客”的目的相反。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：拆除会让停车位变少，与“接待更多游客”的目的冲突。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能接“停车场”作宾语。"}], "explanations": {"扩建": "“扩建”表示扩大停车场的规模，与“为了接待更多游客”的目的相合。", "缩减": "语义：缩减会减少停车位，与“为了接待更多游客”的目的相反。", "拆除": "语义：拆除会让停车位变少，与“接待更多游客”的目的冲突。", "吃": "搭配：“吃”的对象是食物，不能接“停车场”作宾语。"}, "sentence_index": 6, "correct_answer": "扩建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人正在扩建教室的墙。", "explanation": "这里应该用〈粉刷〉。扩建指扩大建筑规模，只是刷墙要用“粉刷”。"}, {"text": "门锁坏了，我正在扩建。", "explanation": "这里应该用〈修理〉。扩建指扩大建筑规模，门锁坏了要修理，不能用“扩建”。"}, {"text": "我把衣服扩建干净了。", "explanation": "这里应该用〈洗〉。扩建指扩大建筑规模，把衣服弄干净要用“洗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校已经把图书馆扩建了成两层。", "corrected_sentence": "学校已经把图书馆扩建成了两层。", "error_description": "错在“了”的位置：结果补语结构中“了”应放在“扩建成”之后，写成“扩建成了两层”；插在“扩建”和“成”之间是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座体育馆以前从来没扩建了。", "corrected_sentence": "这座体育馆以前从来没扩建过。", "error_description": "体标错误：“从来没”否定过去的经历时，“扩建”后不能用“了”，应改用经历体“过”，写成“没扩建过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
