INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87251, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "光线是让我们能看见东西的亮光。有光线，房间里才不黑。", "primary_collocate": null, "pronunciation": "guāng xiàn", "ipa": "kwɑŋ˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "房间里没有光线，我什么都看不见。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间光线很好，白天不用开灯。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上光线太暗，看书对眼睛不好。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户太小，屋里的光线不够。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山洞里一点光线也没有，我们很害怕。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把窗帘拉开，让光线进来。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光线太暗了，我找不到我的钥匙。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拍照时要有足够的光线。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在昏暗的光线下写作业。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下室没有窗户，光线很差。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}, {"form": "束", "label": "量词"}, {"form": "光線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让人能看见东西的亮度，常说房间、晚上光线好或暗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b66f903-6f7d-4f96-9cc8-707587246b0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87251, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "光鲜", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，光鲜意思是鲜亮、好看。"}, {"text": "光线", "is_correct": true, "explanation": "光线 guāng xiàn：照亮东西的亮光，是本题的正确答案。"}, {"text": "光纤", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，光纤指光导纤维。"}, {"text": "钢线", "is_correct": false, "explanation": "gāng 与 guāng 只差韵母中的 u，声调相同，钢线意思是钢制的线。"}], "explanations": {"光鲜": "xiān（第一声）与 xiàn（第四声）声调不同，光鲜意思是鲜亮、好看。", "光线": "光线 guāng xiàn：照亮东西的亮光，是本题的正确答案。", "光纤": "xiān（第一声）与 xiàn（第四声）声调不同，光纤指光导纤维。", "钢线": "gāng 与 guāng 只差韵母中的 u，声调相同，钢线意思是钢制的线。"}, "sentence_index": null, "correct_answer": "光线"}, "level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "语义：看东西与有没有声音无关，“没有声音，我什么都看不见”句意不通。"}, {"text": "光线", "is_correct": true, "explanation": "“没有光线”导致“看不见”，因果成立，是唯一能填入空格的词。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道靠嗅觉感知，与看不见东西没有关系，句子因果不成立。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度与看不见东西无关，“没有温度，我什么都看不见”句意不通。"}], "explanations": {"声音": "语义：看东西与有没有声音无关，“没有声音，我什么都看不见”句意不通。", "光线": "“没有光线”导致“看不见”，因果成立，是唯一能填入空格的词。", "味道": "语义：味道靠嗅觉感知，与看不见东西没有关系，句子因果不成立。", "温度": "语义：温度与看不见东西无关，“没有温度，我什么都看不见”句意不通。"}, "sentence_index": 0, "correct_answer": "光线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盏台灯的光线很高，适合看书。", "explanation": "这里应该用〈亮度〉。光线说明的是亮暗、强弱，不说高低；台灯的明暗程度要用亮度来描述。"}, {"text": "屋里有一只光线，我能看清东西。", "explanation": "这里应该用〈道〉。光线的量词是“道”或“束”，不能用“只”来计量光线。"}, {"text": "太阳是地球上最大的光线。", "explanation": "这里应该用〈光源〉。光线指射出的那道光，发光的太阳本身是光源，不是光线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87251, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "气味", "is_correct": false, "explanation": "语义：“太暗了”说的是明暗，气味与明暗无关，句子不通。"}, {"text": "光线", "is_correct": true, "explanation": "“太暗了”说明光线弱，所以找不到钥匙，句意通顺，是唯一能填入的词。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量说轻重，不能说“太暗了”，句子不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“暗”用来形容光、色、环境，不用来形容价格。"}], "explanations": {"气味": "语义：“太暗了”说的是明暗，气味与明暗无关，句子不通。", "光线": "“太暗了”说明光线弱，所以找不到钥匙，句意通顺，是唯一能填入的词。", "重量": "语义：重量说轻重，不能说“太暗了”，句子不通。", "价格": "搭配：“暗”用来形容光、色、环境，不用来形容价格。"}, "sentence_index": 6, "correct_answer": "光线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一进门就开了光线。", "explanation": "这里应该用〈灯〉。开的是灯，光线是照射出的光，不能用“开”来操作。"}, {"text": "他的前途一片光线。", "explanation": "这里应该用〈光明〉。光线指照射的光，不能比喻前途；形容前途美好要用〈光明〉。"}, {"text": "他划着光线，点亮了蜡烛。", "explanation": "这里应该用〈火柴〉。划着的是火柴，光线不能被划着；点亮蜡烛要靠火柴，不是光线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87251, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个光线从窗缝照进来，屋里亮了一些。", "corrected_sentence": "一道光线从窗缝照进来，屋里亮了一些。", "error_description": "错误形式“一个光线”，正确形式“一道光线”。光线的量词用“道”（或“束”），“个”不能用于光线。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87251, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋里是一些光线，我能看清桌子。", "corrected_sentence": "屋里有一些光线，我能看清桌子。", "error_description": "错误形式“屋里是一些光线”，正确形式“屋里有一些光线”。表示某处存在光线要用“有”，不用“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87252, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87252, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87252, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "照在物体上、使人能看见物体的光。", "primary_collocate": null, "pronunciation": "guāng xiàn", "ipa": "kwɑŋ˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "阳光透过树叶，光线落在地上。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一道光线从门缝照进来。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光线照在桌子上，桌面很亮。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光线从窗户射进房间。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳下山后，光线慢慢变弱了。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强烈的光线让我睁不开眼睛。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光线照到镜子上，又反射到墙上。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蓝色的光线很冷，黄色的光线很暖。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用手电筒的光线照着黑板。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光线穿过玻璃，照亮了整间屋子。", "target_word": "光线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}, {"form": "束", "label": "量词"}, {"form": "光線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "照射、穿过、反射的那道光，作为物理对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b66f903-6f7d-4f96-9cc8-707587246b0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87252, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "光纤", "is_correct": false, "explanation": "xiān（第一声）与 xiàn（第四声）声调不同，光纤指光导纤维。"}, {"text": "光线", "is_correct": true, "explanation": "光线 guāng xiàn：照射、穿过的那道光，是本题的正确答案。"}, {"text": "光电", "is_correct": false, "explanation": "diàn 与 xiàn 声母不同（d 与 x），声调相同，光电指光与电相关的事物。"}, {"text": "钢线", "is_correct": false, "explanation": "gāng 与 guāng 只差韵母中的 u，声调相同，钢线意思是钢制的线。"}], "explanations": {"光纤": "xiān（第一声）与 xiàn（第四声）声调不同，光纤指光导纤维。", "光线": "光线 guāng xiàn：照射、穿过的那道光，是本题的正确答案。", "光电": "diàn 与 xiàn 声母不同（d 与 x），声调相同，光电指光与电相关的事物。", "钢线": "gāng 与 guāng 只差韵母中的 u，声调相同，钢线意思是钢制的线。"}, "sentence_index": null, "correct_answer": "光线"}, "level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "语义：声音不能“落在地上”，它是振动传播，不是有形的东西。"}, {"text": "光线", "is_correct": true, "explanation": "“光线落在地上”指阳光照射到地面，句意通顺，是唯一能填入的词。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味不会“落在地上”，且与阳光透过树叶的情景无关。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“落”多用于光、雨、叶等，温度不能“落在地上”。"}], "explanations": {"声音": "语义：声音不能“落在地上”，它是振动传播，不是有形的东西。", "光线": "“光线落在地上”指阳光照射到地面，句意通顺，是唯一能填入的词。", "气味": "语义：气味不会“落在地上”，且与阳光透过树叶的情景无关。", "温度": "搭配：“落”多用于光、雨、叶等，温度不能“落在地上”。"}, "sentence_index": 0, "correct_answer": "光线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电灯是屋里最亮的光线。", "explanation": "这里应该用〈光源〉。光线指照射出的光，发光的电灯本身是光源，不是光线。"}, {"text": "一只光线从门缝照进来。", "explanation": "这里应该用〈道〉或〈束〉。光线的量词是“道”或“束”，“只”一般用于动物，不能计量光线。"}, {"text": "爸爸的光线很大，全家人都怕他。", "explanation": "这里应该用〈气势〉。光线指照射的光，不能用来比喻人的气势或威望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重量", "is_correct": false, "explanation": "语义：重量不会“照到”镜子上，也不能被反射，句子不通。"}, {"text": "光线", "is_correct": true, "explanation": "“光线照到镜子上，又反射到墙上”是光的照射与反射，句意通顺，是唯一能填入的词。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：价格不能被“照到”或“反射”，这两个动作在此句中只适用于光。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温不是光，无法照射或反射，句子不成立。"}], "explanations": {"重量": "语义：重量不会“照到”镜子上，也不能被反射，句子不通。", "光线": "“光线照到镜子上，又反射到墙上”是光的照射与反射，句意通顺，是唯一能填入的词。", "价格": "搭配：价格不能被“照到”或“反射”，这两个动作在此句中只适用于光。", "体温": "语义：体温不是光，无法照射或反射，句子不成立。"}, "sentence_index": 6, "correct_answer": "光线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他伸手按下了光线的开关。", "explanation": "这里应该用〈电灯〉。开关属于电灯，光线没有开关；按开关的是电灯，不是光线。"}, {"text": "这束光线坏了，屋里一下子黑了。", "explanation": "这里应该用〈灯泡〉。坏的是灯泡，光线不会坏；灯泡坏了屋里才会变黑。"}, {"text": "他划着光线，点亮了油灯。", "explanation": "这里应该用〈火柴〉。划着的是火柴，光线不能被划着；点亮油灯要靠火柴，不是光线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "强烈的光线照桌子很亮。", "corrected_sentence": "强烈的光线照得桌子很亮。", "error_description": "错误形式“照桌子很亮”，正确形式“照得桌子很亮”。动词与补语之间要用“得”连接，漏掉“得”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天早上，光线会从东窗照进来了。", "corrected_sentence": "明天早上，光线会从东窗照进来。", "error_description": "错误形式“照进来了”，正确形式“照进来”。“会”表示尚未发生，句末的“了”表示动作已经完成，二者搭配不当，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
