INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87253, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "承认是说出做过的事，或者说别人说得对。", "primary_collocate": null, "pronunciation": "chéng rèn", "ipa": "ʈʂʰɤŋ˧˥ ɻən˥˩", "syllable_count": 2, "sentences": [{"text": "他承认昨天是他打破了杯子。", "target_word": "承认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明不敢承认自己做错了。", "target_word": "承认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要承认他说得对。", "target_word": "承认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她承认自己不喜欢这个工作。", "target_word": "承认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟终于承认吃了蛋糕。", "target_word": "承认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很快承认了错误。", "target_word": "承认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板承认公司有问题。", "target_word": "承认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么不承认这件事？", "target_word": "承认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我承认，你比我跑得快。", "target_word": "承认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不承认那封信是他写的。", "target_word": "承认", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "承认了", "label": "体标"}, {"form": "承认过", "label": "体标"}, {"form": "承認", "label": "繁体"}], "register": "中性", "sense_fingerprint": "说出做过的事，或说别人对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eb1202a-debe-449b-9a5c-f738d8413e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87253, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "承认", "is_correct": true, "explanation": "正确：“承认”指说出做过的事，与“他……昨天是他打破了杯子”的内容相合。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”是为喜事举行活动，不能用来说打破杯子这样的过失。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是人、作品或优点，不与“昨天是他打破了杯子”这样的事件搭配。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示对别人的帮助或好意表示谢意，与打破杯子的事实不符。"}], "explanations": {"承认": "正确：“承认”指说出做过的事，与“他……昨天是他打破了杯子”的内容相合。", "庆祝": "语义：“庆祝”是为喜事举行活动，不能用来说打破杯子这样的过失。", "欣赏": "搭配：“欣赏”的对象是人、作品或优点，不与“昨天是他打破了杯子”这样的事件搭配。", "感谢": "语义：“感谢”表示对别人的帮助或好意表示谢意，与打破杯子的事实不符。"}, "sentence_index": 0, "correct_answer": "承认"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老板承认了我的请假。", "explanation": "这里应该用〈同意〉。承认指说出事实或认账，批准请假要用同意。"}, {"text": "他承认了来参加会议。", "explanation": "这里应该用〈答应〉。承认只用于说出事实或认账，表示同意去做某事要用答应。"}, {"text": "我承认那位邻居很久了。", "explanation": "这里应该用〈认识〉。承认是说出事实或认账，知道并交往某人要用认识。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87253, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "承认", "is_correct": true, "explanation": "正确：“承认”表示认账、说出事实，与“老板……公司有问题”相合。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”是为喜事表示庆贺，不能用于“公司有问题”这样的坏消息。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：“批准”的宾语多是申请、计划等，不能接“公司有问题”这样的陈述。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示称赞，与“公司有问题”的内容正好相反。"}], "explanations": {"承认": "正确：“承认”表示认账、说出事实，与“老板……公司有问题”相合。", "祝贺": "语义：“祝贺”是为喜事表示庆贺，不能用于“公司有问题”这样的坏消息。", "批准": "搭配：“批准”的宾语多是申请、计划等，不能接“公司有问题”这样的陈述。", "赞美": "语义：“赞美”表示称赞，与“公司有问题”的内容正好相反。"}, "sentence_index": 6, "correct_answer": "承认"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他承认了这块巨大的石头。", "explanation": "这里应该用〈搬〉。承认指说出事实或认账，搬运石头要用搬。"}, {"text": "我承认这个假期。", "explanation": "这里应该用〈享受〉。承认是说出事实或认账，从假期中得到乐趣要用享受。"}, {"text": "他承认了这条路。", "explanation": "这里应该用〈选择〉。承认是说出事实，挑选路线要用选择。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87253, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他承认很干脆。", "corrected_sentence": "他承认得很干脆。", "error_description": "补语错误：动词“承认”后带补语描写程度时要用“得”，不能省略。正确说法是：他承认得很干脆。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
