INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87254, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对事实或错误表示肯定、认账；同意。", "primary_collocate": null, "pronunciation": "chéng rèn", "ipa": "ʈʂʰɤŋ˧˥ ɻən˥˩", "syllable_count": 2, "sentences": [{"text": "大家都承认这个办法很好。", "target_word": "承认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都承认这个计划有风险。", "target_word": "承认", "complexity_tier": "T3", "furigana": "wǒ men dōu chéng rèn zhè ge jì huà yǒu fēng xiǎn", "sentence_source": "generated"}, {"text": "他承认自己输了这场比赛。", "target_word": "承认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不愿承认自己也有错。", "target_word": "承认", "complexity_tier": "T3", "furigana": "tā bù yuàn chéng rèn zì jǐ yě yǒu cuò", "sentence_source": "generated"}, {"text": "老师承认这次题目太难了。", "target_word": "承认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人承认她是最好的歌手。", "target_word": "承认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他承认这件事自己有责任。", "target_word": "承认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的人都承认他的成绩。", "target_word": "承认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不承认有这个合同。", "target_word": "承认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有承认过我们是朋友。", "target_word": "承认", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "承认了", "label": "体标"}, {"form": "承认过", "label": "体标"}, {"form": "承認", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对事实或错误表示肯定、认账、同意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eb1202a-debe-449b-9a5c-f738d8413e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87254, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "承认", "is_correct": true, "explanation": "正确：“承认”表示肯定、认可，与“大家都……这个办法很好”相合。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与“这个办法很好”的评价相矛盾。"}, {"text": "缴纳", "is_correct": false, "explanation": "搭配：“缴纳”的宾语是税款、费用等，不能接“这个办法很好”这样的评价。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”是对喜事表示庆贺，不能接一个评价性的陈述。"}], "explanations": {"承认": "正确：“承认”表示肯定、认可，与“大家都……这个办法很好”相合。", "讨厌": "语义：“讨厌”表示厌恶，与“这个办法很好”的评价相矛盾。", "缴纳": "搭配：“缴纳”的宾语是税款、费用等，不能接“这个办法很好”这样的评价。", "祝贺": "语义：“祝贺”是对喜事表示庆贺，不能接一个评价性的陈述。"}, "sentence_index": 0, "correct_answer": "承认"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她承认了很大的打击。", "explanation": "这里应该用〈承受〉。承认指说出事实或认账，忍受打击要用承受。"}, {"text": "妈妈承认了一件衣服。", "explanation": "这里应该用〈挑选〉。承认指说出事实或认账，挑出想要的东西要用挑选。"}, {"text": "我承认了那张旧桌子。", "explanation": "这里应该用〈搬〉。承认是说出事实或认账，挪动家具要用搬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87254, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "承认", "is_correct": true, "explanation": "正确：“承认”表示认账，与“他……这件事自己有责任”相合。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞好人好事，与“这件事自己有责任”的陈述不相合。"}, {"text": "鼓励", "is_correct": false, "explanation": "搭配：“鼓励”的对象是人或行为，不接“这件事自己有责任”这种事实陈述。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示乐意接待或接受，与“这件事自己有责任”不相合。"}], "explanations": {"承认": "正确：“承认”表示认账，与“他……这件事自己有责任”相合。", "表扬": "语义：“表扬”是称赞好人好事，与“这件事自己有责任”的陈述不相合。", "鼓励": "搭配：“鼓励”的对象是人或行为，不接“这件事自己有责任”这种事实陈述。", "欢迎": "语义：“欢迎”表示乐意接待或接受，与“这件事自己有责任”不相合。"}, "sentence_index": 6, "correct_answer": "承认"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他承认了很多经验。", "explanation": "这里应该用〈收获〉。承认是说出事实或认账，获得经验要用收获。"}, {"text": "我承认不了这种噪音。", "explanation": "这里应该用〈忍受〉。承认是认账、说出事实，忍受噪音要用忍受。"}, {"text": "爱迪生承认了电灯。", "explanation": "这里应该用〈发明〉。承认是说出事实或认账，创造出新东西要用发明。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他承认地很快。", "corrected_sentence": "他承认得很快。", "error_description": "补语标记错误：动词后带补语描写程度时要用“得”，“地”用于动词前的状语。正确说法是：他承认得很快。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有承认了那件事。", "corrected_sentence": "他没有承认过那件事。", "error_description": "体标错误：「没有」否定经历时要用「过」，不能用「了」。正确说法是：他没有承认过那件事。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
