INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87255, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "改革家是想出新办法，把旧办法变得更好的人。", "primary_collocate": null, "pronunciation": "gǎi gé jiā", "ipa": "kaɪ˨˩˦ kɤ˧˥ tɕjɑ˥˥", "syllable_count": 3, "sentences": [{"text": "我的朋友总想改变旧办法，他像个改革家。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司来了一位年轻的改革家。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位改革家想出了更快的办事办法。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是学校里的小改革家，常有新想法。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的旧办法太慢，妈妈成了家里的改革家。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的改革家不怕改变旧习惯。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位改革家把旧工作方法改得更好。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们都叫他办公室里的改革家。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板请来一位改革家，帮公司想新办法。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是我们班的改革家，常常提出新规则。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "改革家们", "label": "复数"}], "register": "中性", "sense_fingerprint": "想出新办法、把旧办法变得更好的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046a46c1-f6ab-4b59-a727-080c82d4af4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87255, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钟表", "is_correct": false, "explanation": "语义：钟表是计时的器具，不是总想改变旧办法的人，“像个钟表”说不通。"}, {"text": "老古董", "is_correct": false, "explanation": "语义：老古董指守旧的东西，与“总想改变旧办法”的意思相反。"}, {"text": "改革家", "is_correct": true, "explanation": "正确。改革家指想出新办法、把旧办法变得更好的人，与“改变旧办法”相呼应。"}, {"text": "木头", "is_correct": false, "explanation": "搭配：“像个木头”形容人呆板，与“总想改变旧办法”的描写不符。"}], "explanations": {"钟表": "语义：钟表是计时的器具，不是总想改变旧办法的人，“像个钟表”说不通。", "老古董": "语义：老古董指守旧的东西，与“总想改变旧办法”的意思相反。", "改革家": "正确。改革家指想出新办法、把旧办法变得更好的人，与“改变旧办法”相呼应。", "木头": "搭配：“像个木头”形容人呆板，与“总想改变旧办法”的描写不符。"}, "sentence_index": 0, "correct_answer": "改革家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位改革家在马拉松比赛中跑了第一。", "explanation": "这里应该用〈运动员〉。改革家指想出新办法、把旧办法变好的人，跑比赛的是运动员。"}, {"text": "他总是坚持旧办法，是个改革家。", "explanation": "这里应该用〈保守派〉。改革家要想出新办法，坚持旧办法的人是保守派，与改革家意思相反。"}, {"text": "这位改革家骗走了老人的钱。", "explanation": "这里应该用〈骗子〉。改革家指想出新办法、把旧办法变好的人，骗钱的人要用“骗子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87255, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乘客", "is_correct": false, "explanation": "语义：乘客不负责改进工作方法，“把旧工作方法改得更好”与乘客身份不符。"}, {"text": "改革家", "is_correct": true, "explanation": "正确。改革家指想出新办法、把旧办法变得更好的人，与句中“改旧工作方法”相符。"}, {"text": "游客", "is_correct": false, "explanation": "搭配：“把旧工作方法改得更好”需要有工作经验的人，“游客”与之不搭配。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人的身份与改进工作方法无关，句子说不通。"}], "explanations": {"乘客": "语义：乘客不负责改进工作方法，“把旧工作方法改得更好”与乘客身份不符。", "改革家": "正确。改革家指想出新办法、把旧办法变得更好的人，与句中“改旧工作方法”相符。", "游客": "搭配：“把旧工作方法改得更好”需要有工作经验的人，“游客”与之不搭配。", "病人": "语义：病人的身份与改进工作方法无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "改革家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位改革家每天在路上开出租车。", "explanation": "这里应该用〈司机〉。改革家指想出新办法、把旧办法变好的人，开出租车的是司机。"}, {"text": "那位改革家在课堂上睡大觉。", "explanation": "这里应该用〈学生〉。改革家指想出新办法、把旧办法变好的人，课堂上睡大觉的是学生。"}, {"text": "那位改革家偷了我的钱包。", "explanation": "这里应该用〈小偷〉。改革家指想出新办法、把旧办法变好的人，偷东西的人是小偷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87255, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班来了一条有新想法的改革家。", "corrected_sentence": "我们班来了一位有新想法的改革家。", "error_description": "量词错误：指人的“改革家”应用“位”，“条”用于细长的东西。正确说法是“一位有新想法的改革家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87255, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多年轻人都想成为有新想法改革家。", "corrected_sentence": "很多年轻人都想成为有新想法的改革家。", "error_description": "定语漏“的”：“有新想法”修饰“改革家”，中间应加“的”。正确说法是“有新想法的改革家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
