INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87256, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "倡导并推行改革的人。", "primary_collocate": null, "pronunciation": "gǎi gé jiā", "ipa": "kaɪ˨˩˦ kɤ˧˥ tɕjɑ˥˥", "syllable_count": 3, "sentences": [{"text": "这位改革家让国家变得更强大。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位有名的改革家。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改革家提出了新的教育制度。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书里写了很多改革家的故事。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位改革家一生都在推行新政策。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改革家常常要面对很多反对的声音。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想做一名勇敢的改革家。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市曾经有一位著名的改革家。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位改革家推动了税收制度的变化。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人都尊敬这位改革家。", "target_word": "改革家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "改革家们", "label": "复数"}], "register": "书面", "sense_fingerprint": "倡导并推行社会或制度改革的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046a46c1-f6ab-4b59-a727-080c82d4af4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小偷", "is_correct": false, "explanation": "语义：小偷不能使国家变得更强大，与句子的意思相反。"}, {"text": "改革家", "is_correct": true, "explanation": "正确。改革家指推行改革的人，能够让国家变得更强大。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人需要治疗，不能让国家变得更强大。"}, {"text": "邻居", "is_correct": false, "explanation": "搭配：“让国家变得更强大”需要推动国家发展的人，“邻居”不搭配。"}], "explanations": {"小偷": "语义：小偷不能使国家变得更强大，与句子的意思相反。", "改革家": "正确。改革家指推行改革的人，能够让国家变得更强大。", "病人": "语义：病人需要治疗，不能让国家变得更强大。", "邻居": "搭配：“让国家变得更强大”需要推动国家发展的人，“邻居”不搭配。"}, "sentence_index": 0, "correct_answer": "改革家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位改革家画了一幅很美的油画。", "explanation": "这里应该用〈画家〉。改革家指推行变革的人，画油画的是画家。"}, {"text": "这位改革家正在医院里给病人打针。", "explanation": "这里应该用〈护士〉。改革家指推行变革的人，给病人打针的是护士。"}, {"text": "这位改革家在奥运会上拿了金牌。", "explanation": "这里应该用〈运动员〉。改革家指推行变革的人，拿金牌的是运动员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乞丐", "is_correct": false, "explanation": "语义：乞丐的身份与“勇敢的”改革者相反，句子意思说不通。"}, {"text": "改革家", "is_correct": true, "explanation": "正确。“想做一名勇敢的”后接的是推行改革、有担当的人。"}, {"text": "婴儿", "is_correct": false, "explanation": "搭配：“做一名”后要接职业或身份，“婴儿”不是可以“想做”的身份。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有人的意志，不能“想做”某种人，句子说不通。"}], "explanations": {"乞丐": "语义：乞丐的身份与“勇敢的”改革者相反，句子意思说不通。", "改革家": "正确。“想做一名勇敢的”后接的是推行改革、有担当的人。", "婴儿": "搭配：“做一名”后要接职业或身份，“婴儿”不是可以“想做”的身份。", "石头": "语义：石头没有人的意志，不能“想做”某种人，句子说不通。"}, "sentence_index": 6, "correct_answer": "改革家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位改革家发现了一种新元素。", "explanation": "这里应该用〈科学家〉。改革家指推行变革的人，发现新元素要用“科学家”。"}, {"text": "这位改革家治好了很多病人。", "explanation": "这里应该用〈医生〉。改革家不做治疗工作，治病的人要用“医生”。"}, {"text": "这位改革家在考试中作弊。", "explanation": "这里应该用〈学生〉。改革家指推行变革的人，考试作弊的人是学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个时代出现了一只杰出的改革家。", "corrected_sentence": "那个时代出现了一位杰出的改革家。", "error_description": "量词错误：指人的“改革家”应用“位”，“只”用于动物等。正确说法是“一位杰出的改革家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很多年轻人都想成为一座改革家。", "corrected_sentence": "很多年轻人都想成为一位改革家。", "error_description": "量词错误：指人的“改革家”应用“位”，“座”用于山、桥、房屋等大型物体。正确说法是“一位改革家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
