INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87257, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "克拉是用来说宝石有多重的一种叫法。", "primary_collocate": null, "pronunciation": "kè lā", "ipa": "kʰɤ˥˩ la˥", "syllable_count": 2, "sentences": [{"text": "买钻石的时候，要先问有几克拉。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说这颗宝石有四克拉。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗钻石有三克拉，很漂亮。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝石越大，克拉数就越高。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的钻石都按克拉卖。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗钻石是八克拉的，很重。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想买一颗大一点的，至少两克拉。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里最大的那颗宝石有二十克拉。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着标签，上面写着三克拉。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一颗五克拉的钻石要很多钱。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "克拉钻", "label": "复合"}], "register": "中性", "sense_fingerprint": "用来说宝石有多重的一种叫法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4cf27cd-43b5-427b-9ffd-1e148fc0d9bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87257, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "克拉", "is_correct": true, "explanation": "正确。问宝石有几克拉，问的是宝石的重量，与“钻石”相合。"}, {"text": "辆", "is_correct": false, "explanation": "搭配：“辆”用于车，不能用来问钻石的重量。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”用于书籍，钻石不能用“本”来计数。"}, {"text": "篇", "is_correct": false, "explanation": "语义：“篇”用于文章，与钻石毫无关系。"}], "explanations": {"克拉": "正确。问宝石有几克拉，问的是宝石的重量，与“钻石”相合。", "辆": "搭配：“辆”用于车，不能用来问钻石的重量。", "本": "搭配：“本”用于书籍，钻石不能用“本”来计数。", "篇": "语义：“篇”用于文章，与钻石毫无关系。"}, "sentence_index": 0, "correct_answer": "克拉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这包饼干有五百克拉。", "explanation": "这里应该用〈克〉。克拉只用于宝石，饼干的重量要用〈克〉。"}, {"text": "这片药有二十克拉。", "explanation": "这里应该用〈毫克〉。克拉只用于宝石，药的剂量要用〈毫克〉。"}, {"text": "这筐葡萄重十克拉。", "explanation": "这里应该用〈公斤〉。克拉只用于宝石，葡萄的重量要用〈公斤〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87257, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "克拉", "is_correct": true, "explanation": "正确。“至少两克拉”说的是宝石的重量，与“大一点的”相合。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”多用于动物或成对的物件，不能用来数要买的钻石。"}, {"text": "首", "is_correct": false, "explanation": "搭配：“首”用于诗歌、歌曲，不能用来数钻石。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、建筑等大型物体，不能用来数要买的钻石。"}], "explanations": {"克拉": "正确。“至少两克拉”说的是宝石的重量，与“大一点的”相合。", "只": "搭配：“只”多用于动物或成对的物件，不能用来数要买的钻石。", "首": "搭配：“首”用于诗歌、歌曲，不能用来数钻石。", "座": "搭配：“座”用于山、建筑等大型物体，不能用来数要买的钻石。"}, "sentence_index": 6, "correct_answer": "克拉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一袋五克拉的大米要很多钱。", "explanation": "用错对象：克拉只用来称宝石，大米的重量应该用〈公斤〉。"}, {"text": "我的书包重三克拉。", "explanation": "用错对象：克拉只用于宝石，书包的重量要用〈千克〉。"}, {"text": "这辆自行车有八克拉。", "explanation": "用错对象：克拉只用于宝石，自行车的重量应该用〈千克〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87257, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐的耳环上镶着克拉的宝石。", "corrected_sentence": "姐姐的耳环上镶着两克拉的宝石。", "error_description": "缺数词：量词“克拉”前必须有数词，应说“两克拉的宝石”，不能只说“克拉的宝石”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87257, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "证书上写着这颗钻石有五颗克拉。", "corrected_sentence": "证书上写着这颗钻石有五克拉。", "error_description": "双重量词：“克拉”前面已有数量，不能再加“颗”，应说“五克拉”，不能说“五颗克拉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
