INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87258, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "宝石的重量单位，一克拉等于二百毫克。", "primary_collocate": null, "pronunciation": "kè lā", "ipa": "kʰɤ˥˩ la˥", "syllable_count": 2, "sentences": [{"text": "这颗钻石有两克拉重。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的戒指上有一颗一克拉的钻石。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一克拉等于二百毫克。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块宝石重五克拉。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里有一颗三克拉的红宝石。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十克拉的钻石非常贵。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗蓝宝石只有半克拉。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送给妈妈一颗两克拉的绿宝石。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这枚戒指上的钻石大约零点五克拉。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗宝石重八克拉，很贵。", "target_word": "克拉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "克拉钻", "label": "复合"}], "register": "中性", "sense_fingerprint": "宝石的重量单位，一克拉等于二百毫克", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4cf27cd-43b5-427b-9ffd-1e148fc0d9bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87258, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "克拉", "is_correct": true, "explanation": "正确。克拉是宝石的重量单位，与“钻石”“重”相合。"}, {"text": "辆", "is_correct": false, "explanation": "搭配：“辆”用于车，不能用来量宝石的重量。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、建筑等大型物体，不能用来量宝石的重量。"}, {"text": "颗", "is_correct": false, "explanation": "语义：“颗”数的是颗粒，不表示重量，“两颗重”说不通。"}], "explanations": {"克拉": "正确。克拉是宝石的重量单位，与“钻石”“重”相合。", "辆": "搭配：“辆”用于车，不能用来量宝石的重量。", "座": "搭配：“座”用于山、建筑等大型物体，不能用来量宝石的重量。", "颗": "语义：“颗”数的是颗粒，不表示重量，“两颗重”说不通。"}, "sentence_index": 0, "correct_answer": "克拉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这袋糖有五百克拉。", "explanation": "这里应该用〈克〉。克拉只用于宝石的重量，糖的重量要用〈克〉。"}, {"text": "每片药有二十克拉。", "explanation": "这里应该用〈毫克〉。克拉只用于宝石，药的剂量通常用〈毫克〉。"}, {"text": "这箱苹果重十克拉。", "explanation": "这里应该用〈公斤〉。克拉只用于宝石，苹果的重量要用〈公斤〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87258, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "克拉", "is_correct": true, "explanation": "正确。“半克拉”是宝石的重量，与“蓝宝石”相合。"}, {"text": "首", "is_correct": false, "explanation": "搭配：“首”用于诗歌、歌曲，不能用来量宝石。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”用于书籍，宝石不能用“本”来计量。"}, {"text": "棵", "is_correct": false, "explanation": "搭配：“棵”用于树木、植物，不能用来量宝石。"}], "explanations": {"克拉": "正确。“半克拉”是宝石的重量，与“蓝宝石”相合。", "首": "搭配：“首”用于诗歌、歌曲，不能用来量宝石。", "本": "搭配：“本”用于书籍，宝石不能用“本”来计量。", "棵": "搭配：“棵”用于树木、植物，不能用来量宝石。"}, "sentence_index": 6, "correct_answer": "克拉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这袋大米重五克拉。", "explanation": "用错对象：克拉只用来称宝石，大米的重量应该用〈公斤〉。"}, {"text": "这个西瓜有三克拉。", "explanation": "用错对象：克拉只用于宝石，西瓜的重量要用〈千克〉。"}, {"text": "这只小猫重两克拉。", "explanation": "用错对象：克拉只用于宝石，小猫的体重要用〈克〉或〈千克〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这颗红宝石有克拉重。", "corrected_sentence": "这颗红宝石有三克拉重。", "error_description": "缺数词：量词“克拉”前必须有数词，应说“有三克拉重”，不能只说“有克拉重”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这颗蓝宝石有三颗克拉重。", "corrected_sentence": "这颗蓝宝石有三克拉重。", "error_description": "双重量词：“克拉”本身就是量词，前面已有“三”，不能再加“颗”，应说“三克拉”，不能说“三颗克拉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
