INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87259, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "改革者是带头把旧办法改成新办法的人。", "primary_collocate": null, "pronunciation": "gǎi gé zhě", "ipa": "kaɪ˨˩˦ kɤ˧˥ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "他是我们村的改革者。", "target_word": "改革者", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "改革者把旧规定改成了新规定。", "target_word": "改革者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是工厂里第一个改革者。", "target_word": "改革者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的改革者会听大家的话。", "target_word": "改革者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位改革者每天都想新办法。", "target_word": "改革者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "改革者不怕别人说他。", "target_word": "改革者", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我爷爷年轻时是一位改革者。", "target_word": "改革者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "改革者让这家小店有了新样子。", "target_word": "改革者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都叫他改革者，因为他爱改旧办法。", "target_word": "改革者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校来了一位年轻的改革者。", "target_word": "改革者", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "改革者们", "label": "复数"}], "register": "书面语", "sense_fingerprint": "带头把旧办法改成新办法的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83c1835b-777f-4252-a671-77d7f731f642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87259, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改革者", "is_correct": true, "explanation": "「改革者」指带头改旧办法的人，可以指“他”，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“他”是人，不能是石头。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“他”是人，不能是河流。"}, {"text": "学术", "is_correct": false, "explanation": "搭配：“学术”指学问领域，“是……的”后不能接它来指人。"}], "explanations": {"改革者": "「改革者」指带头改旧办法的人，可以指“他”，符合句意。", "石头": "语义：“他”是人，不能是石头。", "河流": "语义：“他”是人，不能是河流。", "学术": "搭配：“学术”指学问领域，“是……的”后不能接它来指人。"}, "sentence_index": 0, "correct_answer": "改革者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位改革者坚持一切都照老办法做，什么也不肯改。", "explanation": "这里应该用〈守旧的人〉。改革者是带头把旧办法改成新办法的人，坚持老办法、什么都不肯改的人不能叫改革者。"}, {"text": "这位改革者领导人民推翻了旧王朝。", "explanation": "这里应该用〈革命者〉。改革者只是改变旧办法，不推翻王朝。"}, {"text": "这位改革者反对一切新办法。", "explanation": "这里应该用〈保守的人〉。改革者推动新办法，不会反对一切新办法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87259, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改革者", "is_correct": true, "explanation": "「改革者」是人，年轻时可以是一位改革者，符合句意。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：“年轻时”的人不可能是婴儿，与句中“年轻时”矛盾。"}, {"text": "仙女", "is_correct": false, "explanation": "语义：现实中的爷爷不是仙女。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是人，不能用“一位”来指，与句意不符。"}], "explanations": {"改革者": "「改革者」是人，年轻时可以是一位改革者，符合句意。", "婴儿": "语义：“年轻时”的人不可能是婴儿，与句中“年轻时”矛盾。", "仙女": "语义：现实中的爷爷不是仙女。", "河流": "语义：河流不是人，不能用“一位”来指，与句意不符。"}, "sentence_index": 6, "correct_answer": "改革者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他最怕改变，所以大家都叫他改革者。", "explanation": "这里应该用〈老顽固〉。改革者是带头改变旧办法的人，最怕改变的人不是改革者。"}, {"text": "这位改革者从来不带头，只跟着别人用老办法。", "explanation": "这里应该用〈跟随者〉。改革者是带头把旧办法改成新办法的人，不带头、只用老办法的人不能叫改革者。"}, {"text": "这位改革者想把新办法全都改回旧办法。", "explanation": "这里应该用〈守旧的人〉。改革者是把旧办法改成新办法的人，把新办法改回旧办法正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87259, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们村来了一只改革者。", "corrected_sentence": "我们村来了一位改革者。", "error_description": "量词错误：“改革者”指人，应用“位”；“只”多用于动物，应改为“一位改革者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87259, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都很喜欢这条改革者。", "corrected_sentence": "大家都很喜欢这位改革者。", "error_description": "量词错误：“改革者”指人，应用“位”；“条”多用于鱼、河等长条形的东西，应改为“这位改革者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
