INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87260, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "进行或推动改革的人。", "primary_collocate": null, "pronunciation": "gǎi gé zhě", "ipa": "kaɪ˨˩˦ kɤ˧˥ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "他是学校里的改革者。", "target_word": "改革者", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位改革者想改变旧办法。", "target_word": "改革者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "改革者要有勇气。", "target_word": "改革者", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多改革者一开始没有人支持。", "target_word": "改革者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不只是商人，还是一位改革者。", "target_word": "改革者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市需要新的改革者。", "target_word": "改革者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "改革者带着新想法来到村里。", "target_word": "改革者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，改革者常常很孤单。", "target_word": "改革者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "历史书里写过很多有名的改革者。", "target_word": "改革者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的改革者提出了三个办法。", "target_word": "改革者", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "改革者们", "label": "复数"}], "register": "书面语", "sense_fingerprint": "进行或推动改革的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83c1835b-777f-4252-a671-77d7f731f642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87260, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改革者", "is_correct": true, "explanation": "「改革者」指推动改革的人，可以用来指“他”这样的人，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“他”是人，不能是一张桌子。"}, {"text": "树木", "is_correct": false, "explanation": "语义：“他”是人，不能说他是一棵树木。"}, {"text": "学术", "is_correct": false, "explanation": "搭配：“学术”指学问领域，“是……的”后不能接它来指人。"}], "explanations": {"改革者": "「改革者」指推动改革的人，可以用来指“他”这样的人，符合句意。", "桌子": "语义：“他”是人，不能是一张桌子。", "树木": "语义：“他”是人，不能说他是一棵树木。", "学术": "搭配：“学术”指学问领域，“是……的”后不能接它来指人。"}, "sentence_index": 0, "correct_answer": "改革者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位改革者推翻了旧政权。", "explanation": "这里应该用〈革命者〉。改革者只是改变旧办法，不推翻政权。"}, {"text": "这位改革者总是要求大家别改旧规定。", "explanation": "这里应该用〈守旧的人〉。改革者是推动改革、改变旧规定的人，不会要求大家别改。"}, {"text": "这位改革者坚持一切都照老办法做。", "explanation": "这里应该用〈保守的人〉。改革者推动改革，坚持一切照老办法做的人不能叫改革者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改革者", "is_correct": true, "explanation": "「改革者」是人，可以带着新想法来到村里，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有想法，不能“带着新想法”来到村里。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不能“带着新想法”来到村里。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不能带着新想法来到村里，句子说不通。"}], "explanations": {"改革者": "「改革者」是人，可以带着新想法来到村里，符合句意。", "石头": "语义：石头没有想法，不能“带着新想法”来到村里。", "河流": "语义：河流不能“带着新想法”来到村里。", "作业": "搭配：“作业”不能带着新想法来到村里，句子说不通。"}, "sentence_index": 6, "correct_answer": "改革者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他最怕改变，所以大家都叫他改革者。", "explanation": "这里应该用〈老顽固〉。改革者是推动改革的人，最怕改变的人不是改革者。"}, {"text": "这位改革者反对公司的一切新办法。", "explanation": "这里应该用〈保守派〉。改革者推动新办法，不会反对一切新办法。"}, {"text": "这位改革者想把新办法全都改回旧办法。", "explanation": "这里应该用〈守旧的人〉。改革者推动改革，把新办法改回旧办法正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我们村的一只改革者。", "corrected_sentence": "他是我们村的一位改革者。", "error_description": "量词错误：“改革者”指人，应用“位”；“只”多用于动物，应改为“一位改革者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班有两条改革者。", "corrected_sentence": "我们班有两位改革者。", "error_description": "量词错误：“改革者”指人，应用“位”；“条”多用于鱼、河等长条形的东西，应改为“两位改革者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
