INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87261, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "此外是说，除了这些以外，还有别的。", "primary_collocate": null, "pronunciation": "cǐ wài", "ipa": "tsʰɨ˨˩ wai˥˩", "syllable_count": 2, "sentences": [{"text": "他买了苹果和香蕉，此外还买了牛奶。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天要开会，此外下午还要见客人。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会唱歌，此外也会跳舞。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我已经说完了，此外还有一件事要说。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去了北京，此外还去了上海。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店卖书，此外也卖笔和本子。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢红色，此外也喜欢蓝色。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里有一张床，此外还有一个小桌子。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会开车，此外还会修车。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试考听力，此外还考写字。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连词：除了前面提到的这些，还有别的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62420910-ffdd-4a2d-9c1d-95797acdc4fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87261, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此外", "is_correct": true, "explanation": "正确：“此外”表示在苹果和香蕉之外还买了牛奶，是补充的意思。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，但买水果和买牛奶之间并无因果关系。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：“而是”前面需要“不是”，此处没有否定，搭配不成立。"}, {"text": "反之", "is_correct": false, "explanation": "语域：“反之”是书面连词，表示相反的情况，这里是并列补充，并不相反。"}], "explanations": {"此外": "正确：“此外”表示在苹果和香蕉之外还买了牛奶，是补充的意思。", "因此": "语义：“因此”表示因果，但买水果和买牛奶之间并无因果关系。", "而是": "搭配：“而是”前面需要“不是”，此处没有否定，搭配不成立。", "反之": "语域：“反之”是书面连词，表示相反的情况，这里是并列补充，并不相反。"}, "sentence_index": 0, "correct_answer": "此外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们先去了超市，此外去了银行。", "explanation": "这里应该用〈然后〉。此外表示另有补充，不表示先后顺序。"}, {"text": "天气很好，此外我们没去公园。", "explanation": "这里应该用〈不过〉。此外只补充同类内容，不表示转折。"}, {"text": "雨下得很大，此外比赛取消了。", "explanation": "这里应该用〈所以〉。此外不表示因果关系，“雨大”与“比赛取消”之间要用〈所以〉连接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87261, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此外", "is_correct": true, "explanation": "正确：“此外”表示除了喜欢红色，还喜欢蓝色，是补充的意思。"}, {"text": "故而", "is_correct": false, "explanation": "语域：“故而”偏文言，且喜欢红色和喜欢蓝色之间并无因果关系。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示假设的相反结果，与“也喜欢蓝色”的并列补充不符。"}, {"text": "相反", "is_correct": false, "explanation": "语义：“相反”表示与前文对立，而“也喜欢蓝色”是同向的补充，相反的意思不通。"}], "explanations": {"此外": "正确：“此外”表示除了喜欢红色，还喜欢蓝色，是补充的意思。", "故而": "语域：“故而”偏文言，且喜欢红色和喜欢蓝色之间并无因果关系。", "否则": "语义：“否则”表示假设的相反结果，与“也喜欢蓝色”的并列补充不符。", "相反": "语义：“相反”表示与前文对立，而“也喜欢蓝色”是同向的补充，相反的意思不通。"}, "sentence_index": 6, "correct_answer": "此外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们先吃了午饭，此外去看了电影。", "explanation": "这里应该用〈然后〉。此外表示另有补充，不表示先后顺序。"}, {"text": "他昨晚没睡好，此外今天很困。", "explanation": "这里应该用〈因此〉。此外不表示因果关系，“没睡好”与“很困”之间要用〈因此〉连接。"}, {"text": "他答应得很好，此外没有来。", "explanation": "这里应该用〈然而〉。此外只表示补充，不表示转折；“答应得很好”与“没有来”之间的对立要用〈然而〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87261, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天早上跑步，此外却游泳。", "corrected_sentence": "我每天早上跑步，此外还游泳。", "error_description": "错误：“此外却游泳”。正确：“此外还游泳”。“却”表示转折，与“此外”表示补充相矛盾，补充要用“还”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87261, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈会做饭，此外却会做蛋糕。", "corrected_sentence": "妈妈会做饭，此外也会做蛋糕。", "error_description": "错误：“此外却会做蛋糕”。正确：“此外也会做蛋糕”。“却”表示转折，与“此外”的补充语义相矛盾，补充同类内容要用“也”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
