INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87262, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示在上面所说的以外，还有其他。", "primary_collocate": null, "pronunciation": "cǐ wài", "ipa": "tsʰɨ˨˩ wai˥˩", "syllable_count": 2, "sentences": [{"text": "我会说汉语，此外还会说一点儿日语。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给我们午饭，此外每月还有奖金。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢踢球，此外也喜欢游泳。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个周末我要洗衣服，此外还要打扫房间。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上有一本书和一支笔，此外还有一把尺子。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校有图书馆和体育馆，此外还有一个花园。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天工作八个小时，此外还要照顾孩子。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我带了手机和钱包，此外还带了一把伞。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店有中餐，此外也有西餐。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们说话，此外还教我们写字。", "target_word": "此外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连词：列举之后补充，除上述之外还有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62420910-ffdd-4a2d-9c1d-95797acdc4fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87262, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "此外", "is_correct": true, "explanation": "正确：“此外”表示在“会说汉语”之外还有补充，与后半句“还会说一点儿日语”相呼应。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，但会说汉语和会说日语之间并无因果关系。"}, {"text": "然而", "is_correct": false, "explanation": "语域：“然而”偏书面，且前后并无转折关系，与口语化的并列补充不符。"}, {"text": "不过", "is_correct": false, "explanation": "语义：“不过”表示转折，而这句前后是并列补充，并没有对比。"}], "explanations": {"此外": "正确：“此外”表示在“会说汉语”之外还有补充，与后半句“还会说一点儿日语”相呼应。", "所以": "语义：“所以”表示因果，但会说汉语和会说日语之间并无因果关系。", "然而": "语域：“然而”偏书面，且前后并无转折关系，与口语化的并列补充不符。", "不过": "语义：“不过”表示转折，而这句前后是并列补充，并没有对比。"}, "sentence_index": 0, "correct_answer": "此外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我先写作业，此外看电视。", "explanation": "这里应该用〈然后〉。此外表示在所说之外另有补充，不表示动作的先后顺序。"}, {"text": "我很想去，此外没有时间。", "explanation": "这里应该用〈但是〉。此外只用于补充同类内容，不表示转折。"}, {"text": "他生病了，此外没来上课。", "explanation": "这里应该用〈因此〉。此外不表示因果关系，“生病”与“没来上课”之间的因果要用〈因此〉来连接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "此外", "is_correct": true, "explanation": "正确：“此外”表示在工作之外还要照顾孩子，是补充的意思，与“还要”相呼应。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：“而是”需要与前文的“不是”呼应，此处前文没有否定，搭配不成立。"}, {"text": "故而", "is_correct": false, "explanation": "语域：“故而”偏文言，且“工作八个小时”与“照顾孩子”之间并非因果关系。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”表示另一种选择的后果，与“工作之外还要照顾孩子”的补充意思不符。"}], "explanations": {"此外": "正确：“此外”表示在工作之外还要照顾孩子，是补充的意思，与“还要”相呼应。", "而是": "搭配：“而是”需要与前文的“不是”呼应，此处前文没有否定，搭配不成立。", "故而": "语域：“故而”偏文言，且“工作八个小时”与“照顾孩子”之间并非因果关系。", "否则": "语义：“否则”表示另一种选择的后果，与“工作之外还要照顾孩子”的补充意思不符。"}, "sentence_index": 6, "correct_answer": "此外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听到消息，此外马上出发了。", "explanation": "这里应该用〈于是〉。此外只表示补充，不表示承接前面的事件、引出结果。"}, {"text": "他没带伞，此外淋湿了。", "explanation": "这里应该用〈所以〉。此外只表示补充，不表示因果；“没带伞”与“淋湿了”之间的因果要用〈所以〉连接。"}, {"text": "他很努力，此外没有成功。", "explanation": "这里应该用〈却〉。此外不表示转折，“努力”与“没有成功”之间的对立要用〈却〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我去看了电影，此外却去逛了书店。", "corrected_sentence": "周末我去看了电影，此外还去逛了书店。", "error_description": "错误：“此外却去逛了书店”。正确：“此外还去逛了书店”。“却”表示转折，与“此外”表示补充相矛盾，补充要用“还”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天骑车上班，在此外还锻炼身体。", "corrected_sentence": "他每天骑车上班，此外还锻炼身体。", "error_description": "错误在于多加了介词“在”：“此外”是连词，前面不能加“在”，应说“此外还……”。“在此外”是把“在……之外”的说法套用到了连词上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87263, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出狱", "is_correct": true, "explanation": "出狱指离开监狱，与“入狱”正相反，是这一义项的反义词。"}, {"text": "服刑", "is_correct": false, "explanation": "服刑指在监狱里执行刑期，是入狱之后的状态，并不与入狱构成相反关系。"}, {"text": "犯罪", "is_correct": false, "explanation": "犯罪是入狱的原因，不是与入狱相反的行为。"}, {"text": "结婚", "is_correct": false, "explanation": "结婚与入狱之间没有反义关系，两者在意义上互不对立。"}], "correct_answer": "出狱", "explanations": {"出狱": "出狱指离开监狱，与“入狱”正相反，是这一义项的反义词。", "服刑": "服刑指在监狱里执行刑期，是入狱之后的状态，并不与入狱构成相反关系。", "犯罪": "犯罪是入狱的原因，不是与入狱相反的行为。", "结婚": "结婚与入狱之间没有反义关系，两者在意义上互不对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87263, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出狱", "is_correct": true, "explanation": "出狱指离开监狱，与“入狱”正相反，是这一义项的反义词。"}, {"text": "判刑", "is_correct": false, "explanation": "判刑指法院对犯人作出刑罚，是入狱的前提，不是与入狱相反的动作。"}, {"text": "逃跑", "is_correct": false, "explanation": "逃跑是逃离看管，与入狱不构成反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳与入狱无关，两者之间没有反义关系。"}], "correct_answer": "出狱", "explanations": {"出狱": "出狱指离开监狱，与“入狱”正相反，是这一义项的反义词。", "判刑": "判刑指法院对犯人作出刑罚，是入狱的前提，不是与入狱相反的动作。", "逃跑": "逃跑是逃离看管，与入狱不构成反义关系。", "游泳": "游泳与入狱无关，两者之间没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87263, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "入狱是被关进监狱里。做了坏事的人才会这样。", "primary_collocate": null, "pronunciation": "rù yù", "ipa": "ʐu˥˩ y˥˩", "syllable_count": 2, "sentences": [{"text": "做坏事的人会入狱。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓住了小偷，他要入狱了。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想入狱，所以一直很小心。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "入狱以后，他每天都在房间里想家人。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个坏人终于入狱了。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的哥哥因为做了坏事而入狱。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的坏人最后都入狱了。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做错事要改，坏事做多了就会入狱。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他入狱的消息让大家很吃惊。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说自己再也不想入狱。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "入狱了", "label": "体标"}, {"form": "入狱过", "label": "体标"}], "register": "中性", "sense_fingerprint": "被关进监狱里，做了坏事的人才会这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4cf27cd-43b5-427b-9ffd-1e148fc0d9bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87263, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "入狱", "is_correct": true, "explanation": "入狱 rù yù：被关进监狱，是本词的读音和词义。"}, {"text": "如玉", "is_correct": false, "explanation": "如玉 rúyù：第一音节 rú（第二声）与 rù（第四声）声调不同，意思是像玉一样。"}, {"text": "如遇", "is_correct": false, "explanation": "如遇 rúyù：第一音节 rú（第二声）与 rù（第四声）声调不同，意思是如果碰到。"}, {"text": "路遇", "is_correct": false, "explanation": "路遇 lùyù：第一音节声母 l 与 rù 的 r 不同，意思是在路上遇见。"}], "explanations": {"入狱": "入狱 rù yù：被关进监狱，是本词的读音和词义。", "如玉": "如玉 rúyù：第一音节 rú（第二声）与 rù（第四声）声调不同，意思是像玉一样。", "如遇": "如遇 rúyù：第一音节 rú（第二声）与 rù（第四声）声调不同，意思是如果碰到。", "路遇": "路遇 lùyù：第一音节声母 l 与 rù 的 r 不同，意思是在路上遇见。"}, "sentence_index": null, "correct_answer": "入狱"}, "level_3": {"options": [{"text": "入狱", "is_correct": true, "explanation": "正确。入狱指被关进监狱，与“做坏事”的后果相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳与做坏事的人会怎样无关，句子不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌和做坏事没有因果关系，句子不通。"}, {"text": "殉职", "is_correct": false, "explanation": "语域：殉职是庄重的书面语，指因公牺牲，与这句日常的说法不合。"}], "explanations": {"入狱": "正确。入狱指被关进监狱，与“做坏事”的后果相符。", "游泳": "语义：游泳与做坏事的人会怎样无关，句子不通。", "唱歌": "语义：唱歌和做坏事没有因果关系，句子不通。", "殉职": "语域：殉职是庄重的书面语，指因公牺牲，与这句日常的说法不合。"}, "sentence_index": 0, "correct_answer": "入狱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从国外入狱，回到了家乡。", "explanation": "这里应该用〈入境〉。入境指进入国境，入狱只指被关进监狱，不能用于说进入某个国家。"}, {"text": "他十八岁入狱，成为了一名党员。", "explanation": "这里应该用〈入党〉。入党指加入中国共产党，入狱只指被关进监狱，两者不能互换。"}, {"text": "他每天下午入狱去超市买菜。", "explanation": "这个词不这么用。入狱只表示因犯罪被关进监狱，不能用来表示到某个地方办事或购物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87263, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "入狱", "is_correct": true, "explanation": "正确。入狱指被关进监狱，符合电影里坏人最后的结局。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞与坏人最后的结局无关，句子不通。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：下棋与坏人的结局不构成关系，句子不通。"}, {"text": "驾崩", "is_correct": false, "explanation": "语域：驾崩是专用于帝王去世的庄重词，用在坏人身上语域不合。"}], "explanations": {"入狱": "正确。入狱指被关进监狱，符合电影里坏人最后的结局。", "跳舞": "语义：跳舞与坏人最后的结局无关，句子不通。", "下棋": "语义：下棋与坏人的结局不构成关系，句子不通。", "驾崩": "语域：驾崩是专用于帝王去世的庄重词，用在坏人身上语域不合。"}, "sentence_index": 6, "correct_answer": "入狱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他七岁入狱，成了一年级的小学生。", "explanation": "这里应该用〈入学〉。入学指开始上学，入狱只指被关进监狱，不能用于说上小学。"}, {"text": "这家公司的员工每天都入狱上班。", "explanation": "这个词不这么用。入狱只表示被关进监狱，不能用来说进入单位工作，应说“去上班”。"}, {"text": "他想在家里入狱看书。", "explanation": "这个词不这么用。入狱只表示被关进监狱，不能用来说在某处看书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87263, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法官判他把入狱三年。", "corrected_sentence": "法官判他入狱三年。", "error_description": "错误在“把入狱”：入狱是不及物动词，不能放在“把”字结构中，应说“法官判他入狱三年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87263, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的哥哥被入狱了。", "corrected_sentence": "他的哥哥入狱了。", "error_description": "错误在“被入狱”：入狱不能和“被”连用，应说“他的哥哥入狱了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87264, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出狱", "is_correct": true, "explanation": "出狱指离开监狱，与“入狱”（被关进监狱）正相反，是这一义项的反义词。"}, {"text": "服刑", "is_correct": false, "explanation": "服刑指在监狱里执行刑期，是入狱之后的状态，并不与入狱构成相反关系。"}, {"text": "犯罪", "is_correct": false, "explanation": "犯罪是入狱的原因，不是与入狱相反的行为。"}, {"text": "结婚", "is_correct": false, "explanation": "结婚与入狱之间没有反义关系，两者在意义上互不对立。"}], "correct_answer": "出狱", "explanations": {"出狱": "出狱指离开监狱，与“入狱”（被关进监狱）正相反，是这一义项的反义词。", "服刑": "服刑指在监狱里执行刑期，是入狱之后的状态，并不与入狱构成相反关系。", "犯罪": "犯罪是入狱的原因，不是与入狱相反的行为。", "结婚": "结婚与入狱之间没有反义关系，两者在意义上互不对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
