INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87264, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "因犯罪被关进监狱。", "primary_collocate": null, "pronunciation": "rù yù", "ipa": "ʐu˥˩ y˥˩", "syllable_count": 2, "sentences": [{"text": "他因为偷东西入狱了。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院判那个商人入狱五年。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他入狱以后，家人很难过。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人入狱前是一名老师。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为打人，他差点儿入狱。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾经入狱过。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听说朋友入狱，马上去看他。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做了坏事，就可能入狱。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出狱后，不想再入狱了。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官说，他要入狱三年。", "target_word": "入狱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "入狱了", "label": "体标"}, {"form": "入狱过", "label": "体标"}], "register": "中性", "sense_fingerprint": "因犯罪被关进监狱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4cf27cd-43b5-427b-9ffd-1e148fc0d9bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87264, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "入狱", "is_correct": true, "explanation": "入狱 rù yù：因犯罪被关进监狱，是本词的读音和词义。"}, {"text": "如玉", "is_correct": false, "explanation": "如玉 rúyù：第一音节 rú（第二声）与 rù（第四声）声调不同，意思是像玉一样。"}, {"text": "如遇", "is_correct": false, "explanation": "如遇 rúyù：第一音节 rú（第二声）与 rù（第四声）声调不同，意思是如果碰到。"}, {"text": "路遇", "is_correct": false, "explanation": "路遇 lùyù：第一音节声母 l 与 rù 的 r 不同，意思是在路上遇见。"}], "explanations": {"入狱": "入狱 rù yù：因犯罪被关进监狱，是本词的读音和词义。", "如玉": "如玉 rúyù：第一音节 rú（第二声）与 rù（第四声）声调不同，意思是像玉一样。", "如遇": "如遇 rúyù：第一音节 rú（第二声）与 rù（第四声）声调不同，意思是如果碰到。", "路遇": "路遇 lùyù：第一音节声母 l 与 rù 的 r 不同，意思是在路上遇见。"}, "sentence_index": null, "correct_answer": "入狱"}, "level_3": {"options": [{"text": "入狱", "is_correct": true, "explanation": "正确。入狱指因犯罪被关进监狱，与“因为偷东西”的原因相符。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：毕业指修完学业离开学校，与偷东西无关，句子荒谬不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚与偷东西没有因果关系，句子不通。"}, {"text": "殉职", "is_correct": false, "explanation": "语域：殉职是庄重的书面语，指因公牺牲，与偷东西这种日常语境不合。"}], "explanations": {"入狱": "正确。入狱指因犯罪被关进监狱，与“因为偷东西”的原因相符。", "毕业": "语义：毕业指修完学业离开学校，与偷东西无关，句子荒谬不通。", "结婚": "语义：结婚与偷东西没有因果关系，句子不通。", "殉职": "语域：殉职是庄重的书面语，指因公牺牲，与偷东西这种日常语境不合。"}, "sentence_index": 0, "correct_answer": "入狱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他因为发烧入狱了。", "explanation": "这里应该用〈入院〉。入院指住进医院治病，入狱只指被关进监狱，因病不能说入狱。"}, {"text": "这批货物昨天入狱了，现在放在仓库里。", "explanation": "这里应该用〈入库〉。入库指货物进入仓库，入狱只指人因犯罪被关进监狱，不能用于物品。"}, {"text": "他每天早上入狱去上班。", "explanation": "这个词不这么用。入狱只表示因犯罪被关进监狱，不能用来表示走进单位工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "入狱", "is_correct": true, "explanation": "正确。听说朋友入狱，马上去探望，句意通顺。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：朋友游泳的消息不需要马上去看他，句子不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与“马上去看他”的语境没有关系，句子不通。"}, {"text": "驾崩", "is_correct": false, "explanation": "语域：驾崩只用于帝王去世，用来说普通朋友，语域不合。"}], "explanations": {"入狱": "正确。听说朋友入狱，马上去探望，句意通顺。", "游泳": "语义：朋友游泳的消息不需要马上去看他，句子不通。", "唱歌": "语义：唱歌与“马上去看他”的语境没有关系，句子不通。", "驾崩": "语域：驾崩只用于帝王去世，用来说普通朋友，语域不合。"}, "sentence_index": 6, "correct_answer": "入狱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为肺炎入狱三天，后来好了。", "explanation": "这里应该用〈住院〉。因病住院要说住院，入狱指被关进监狱，不能用于治病。"}, {"text": "他从农村入狱，找到了工作。", "explanation": "这里应该用〈进城〉。进城指从乡村到城市，入狱只指被关进监狱，不指进入某地。"}, {"text": "他每个周末都入狱去图书馆学习。", "explanation": "这个词不这么用。入狱只表示被关进监狱，不能用来说去某个场所学习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他因为打架被入狱了。", "corrected_sentence": "他因为打架入狱了。", "error_description": "错误在“被入狱”：入狱是不及物动词，不能和“被”连用。应说“他因为打架入狱了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年因为打架入狱着。", "corrected_sentence": "他去年因为打架入狱了。", "error_description": "错误在“入狱着”：入狱表示一次性完成的动作，不能用“着”表示持续状态，应说“入狱了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
