INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87267, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "绝对是一点儿也不会错，一定是这样。", "primary_collocate": null, "pronunciation": "jué duì", "ipa": "tɕɥe˧˥ tuei˥˩", "syllable_count": 2, "sentences": [{"text": "这个答案绝对是对的。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看他的样子，绝对是生病了。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个声音绝对是我妈妈的。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天绝对会下雨，你带伞吧。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家的菜绝对好吃，我吃过很多次。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她绝对是最好的人选。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这绝对是真的，我亲眼看见了。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天他绝对会来，他已经答应了。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法绝对有用。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听这个口音，他绝对是北京人。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "絕對", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词：十分肯定，判断一定不会错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62420910-ffdd-4a2d-9c1d-95797acdc4fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87267, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绝对", "is_correct": true, "explanation": "正确：“绝对”表示十分肯定、一定不会错，修饰判断词“是”，与“是对的”相符。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上发生，与对答案正误的判断无关，句意不通。"}, {"text": "比较", "is_correct": false, "explanation": "搭配：“比较”表示相对程度，不能用在判断句“是……的”前。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”修饰形容词或动词，不修饰判断词“是”。"}], "explanations": {"绝对": "正确：“绝对”表示十分肯定、一定不会错，修饰判断词“是”，与“是对的”相符。", "立刻": "语义：“立刻”表示马上发生，与对答案正误的判断无关，句意不通。", "比较": "搭配：“比较”表示相对程度，不能用在判断句“是……的”前。", "太": "搭配：“太”修饰形容词或动词，不修饰判断词“是”。"}, "sentence_index": 0, "correct_answer": "绝对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他绝对会来吧，我也说不准。", "explanation": "这里应该用〈可能〉。〈绝对〉表示十分肯定，与“我也说不准”的不确定相矛盾；表示推测时要用〈可能〉。"}, {"text": "这个答案绝对是对的，不过我也不太确定。", "explanation": "这里应该用〈也许〉。〈绝对〉表示完全肯定，与“不太确定”相矛盾；表示不确定时要用〈也许〉。"}, {"text": "我绝对不太清楚这件事，你问问别人吧。", "explanation": "这里应该用〈大概〉。〈绝对〉表示十分肯定，与“不太清楚”所表示的不确定相矛盾；表示不确定时要用〈大概〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87267, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绝对", "is_correct": true, "explanation": "正确：“绝对”表示一点儿也不会错，与“我亲眼看见了”的依据相呼应。"}, {"text": "不见得", "is_correct": false, "explanation": "语义：“不见得”表示不一定，与“我亲眼看见了”的确定语气相矛盾。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”是程度副词，不能修饰判断词“是”。"}, {"text": "特意", "is_correct": false, "explanation": "语义：“特意”表示有意为之，与对事实的判断不搭。"}], "explanations": {"绝对": "正确：“绝对”表示一点儿也不会错，与“我亲眼看见了”的依据相呼应。", "不见得": "语义：“不见得”表示不一定，与“我亲眼看见了”的确定语气相矛盾。", "非常": "搭配：“非常”是程度副词，不能修饰判断词“是”。", "特意": "语义：“特意”表示有意为之，与对事实的判断不搭。"}, "sentence_index": 6, "correct_answer": "绝对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班的纪律绝对不能违反，但是可以偶尔违反。", "explanation": "这里应该用〈通常〉。〈绝对〉表示毫无例外，与“可以偶尔违反”的例外相矛盾；表示大多数情况要用〈通常〉。"}, {"text": "这只猫绝对很乖，不过有时也很调皮。", "explanation": "这里应该用〈一般〉。〈绝对〉表示毫无例外，与“有时也很调皮”的例外相矛盾；表示大多数情况要用〈一般〉。"}, {"text": "他绝对是北京人，不过我不太确定。", "explanation": "这里应该用〈可能〉。〈绝对〉表示十分肯定，与“我不太确定”相矛盾；表示推测时要用〈可能〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87267, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天晚上很绝对会有雨。", "corrected_sentence": "今天晚上绝对会有雨。", "error_description": "错误：“很绝对”。正确：“绝对”。“绝对”是副词，表示十分肯定，不能再被程度副词“很”修饰；应说“今天晚上绝对会有雨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87267, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事绝对的是假的，别信。", "corrected_sentence": "这件事绝对是假的，别信。", "error_description": "错误在于多加了“的”：“绝对”是副词，修饰判断词“是”，不能加“的”变成“绝对的”。应说“绝对是假的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
