INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87268, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示完全，一定；毫无例外。", "primary_collocate": null, "pronunciation": "jué duì", "ipa": "tɕɥe˧˥ tuei˥˩", "syllable_count": 2, "sentences": [{"text": "这件事绝对不能告诉别人。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话绝对可靠。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做绝对没有问题。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我绝对不会忘记你。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的水绝对干净，你可以放心喝。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子绝对不能一个人过马路。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时绝对不可以看手机。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是绝对安全的办法。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你绝对不要骑车太快。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人绝对值得相信。", "target_word": "绝对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "絕對", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词：完全，毫无例外，常用于否定或强调", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62420910-ffdd-4a2d-9c1d-95797acdc4fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87268, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绝对", "is_correct": true, "explanation": "正确：“绝对”表示毫无例外，与否定词“不能”搭配，强调禁止。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时，与“毫无例外”的“绝对不能”相矛盾。"}, {"text": "比较", "is_correct": false, "explanation": "搭配：“比较”表示相对程度，不能修饰“不能”这类绝对的否定。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示时间上刚发生，与“一律不能告诉别人”的意思不符。"}], "explanations": {"绝对": "正确：“绝对”表示毫无例外，与否定词“不能”搭配，强调禁止。", "偶尔": "语义：“偶尔”表示有时，与“毫无例外”的“绝对不能”相矛盾。", "比较": "搭配：“比较”表示相对程度，不能修饰“不能”这类绝对的否定。", "刚刚": "语义：“刚刚”表示时间上刚发生，与“一律不能告诉别人”的意思不符。"}, "sentence_index": 0, "correct_answer": "绝对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事绝对能成功，不过我也说不好。", "explanation": "这里应该用〈也许〉。〈绝对〉表示完全肯定，与“我也说不好”的不确定相矛盾；表示不确定时要用〈也许〉。"}, {"text": "我每天绝对早起，只有生病的时候例外。", "explanation": "这里应该用〈通常〉。〈绝对〉表示毫无例外，与“只有生病的时候例外”矛盾；表示大多数情况时要用〈通常〉。"}, {"text": "我绝对不太确定他会不会来，你再问问别人吧。", "explanation": "这里应该用〈大概〉。〈绝对〉表示十分肯定，与“不太确定”的不肯定相矛盾；表示不确定时要用〈大概〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87268, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绝对", "is_correct": true, "explanation": "正确：“绝对”表示毫无例外，与“不可以”搭配，强调考试期间一律禁止看手机。"}, {"text": "差点儿", "is_correct": false, "explanation": "语义：“差点儿”表示几乎要发生，与“绝对不可以”的禁令语气不符。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”表示程度过高，不能修饰“不可以”这类禁止性的能愿词。"}, {"text": "恰好", "is_correct": false, "explanation": "语义：“恰好”表示碰巧，与“考试时一律禁止看手机”的规定无关。"}], "explanations": {"绝对": "正确：“绝对”表示毫无例外，与“不可以”搭配，强调考试期间一律禁止看手机。", "差点儿": "语义：“差点儿”表示几乎要发生，与“绝对不可以”的禁令语气不符。", "太": "搭配：“太”表示程度过高，不能修饰“不可以”这类禁止性的能愿词。", "恰好": "语义：“恰好”表示碰巧，与“考试时一律禁止看手机”的规定无关。"}, "sentence_index": 6, "correct_answer": "绝对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事我绝对不确定，或许对，或许不对。", "explanation": "这里应该用〈大概〉。〈绝对〉表示十分肯定，与“不确定，或许对，或许不对”相矛盾；表示不确定时要用〈大概〉。"}, {"text": "我绝对会来参加聚会，不过还不一定。", "explanation": "这里应该用〈可能〉。〈绝对〉表示确定无疑，与“还不一定”相矛盾；表示不确定时要用〈可能〉。"}, {"text": "他绝对会迟到，不过有时也很准时。", "explanation": "这里应该用〈常常〉。〈绝对〉表示毫无例外，与“有时也很准时”的例外相矛盾；表示大多数情况要用〈常常〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告绝对的不能外传。", "corrected_sentence": "这份报告绝对不能外传。", "error_description": "错误在于多加了“的”：“绝对”是副词，修饰“不能”，不能加“的”变成“绝对的”，那是形容词，不能修饰动词性短语。应说“绝对不能外传”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事我们绝对的不会放弃。", "corrected_sentence": "这件事我们绝对不会放弃。", "error_description": "错误在于多加了“的”：“绝对”是副词，直接修饰“不会放弃”，不能加“的”变成形容词，形容词不能修饰动词性短语。应说“绝对不会放弃”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17f212a8-4f46-44dc-821d-f4818f8786f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
