INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87269, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "经营是开一个店，做生意，把它管理好。", "primary_collocate": null, "pronunciation": "jīng yíng", "ipa": "tɕiŋ˥ iŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他在学校旁边经营一家小书店。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我父母经营着一家小饭馆。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她经营了十年花店，认识很多客人。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店经营得很好，每天都有很多人来。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想自己开店，可是不会经营。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷以前经营过一家茶店。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要经营好一家小店，不太容易。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们夫妻两个人一起经营这家面馆。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家咖啡店由一位年轻人经营。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友在网上经营一个卖衣服的小店。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "经营了", "label": "完成体"}, {"form": "经营着", "label": "持续体"}, {"form": "经营过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "开店做生意并把它管理好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '679c1d60-cd18-4bd7-984c-952bf355ca55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87269, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经营", "is_correct": true, "explanation": "正确：“经营”指开店做生意并管理，与“在学校旁边经营一家小书店”的语境相符。"}, {"text": "看望", "is_correct": false, "explanation": "搭配：“看望”的对象是人，不能说“看望一家小书店”。"}, {"text": "欢迎", "is_correct": false, "explanation": "搭配：“欢迎”用于迎接客人，不能用于一家书店。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是把东西丢掉，不能说“在学校旁边扔一家小书店”，句意不通。"}], "explanations": {"经营": "正确：“经营”指开店做生意并管理，与“在学校旁边经营一家小书店”的语境相符。", "看望": "搭配：“看望”的对象是人，不能说“看望一家小书店”。", "欢迎": "搭配：“欢迎”用于迎接客人，不能用于一家书店。", "扔": "语义：“扔”是把东西丢掉，不能说“在学校旁边扔一家小书店”，句意不通。"}, "sentence_index": 0, "correct_answer": "经营"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我小时候经营过很多困难，所以特别能吃苦。", "explanation": "这里应该用〈经历〉。“经营”指开店、管理，不能和“困难”搭配，说“经历困难”才自然。"}, {"text": "他负责经营班里的同学。", "explanation": "这里应该用〈管理〉。“经营”多用于店铺、企业，管理学生和同学要用“管理”。"}, {"text": "这个年轻人经营了生活的考验。", "explanation": "这里应该用〈经受〉。“经营”指开店、管理，不能和“考验”搭配，说“经受住了考验”才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87269, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经营", "is_correct": true, "explanation": "正确：“要经营好一家小店”指把小店管理好，与句意相符。"}, {"text": "接待", "is_correct": false, "explanation": "搭配：“接待”的对象是客人，不能说“接待好一家小店”。"}, {"text": "陪伴", "is_correct": false, "explanation": "搭配：“陪伴”的对象是人或动物，不能说“陪伴一家小店”。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”是转换语言，与管理小店无关，句意不通。"}], "explanations": {"经营": "正确：“要经营好一家小店”指把小店管理好，与句意相符。", "接待": "搭配：“接待”的对象是客人，不能说“接待好一家小店”。", "陪伴": "搭配：“陪伴”的对象是人或动物，不能说“陪伴一家小店”。", "翻译": "语义：“翻译”是转换语言，与管理小店无关，句意不通。"}, "sentence_index": 6, "correct_answer": "经营"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去银行经营了存款手续。", "explanation": "这里应该用〈办理〉。“经营”指开店、管理，不能用于“存款手续”，说“办理手续”才自然。"}, {"text": "妈妈每天经营生病的爷爷，很辛苦。", "explanation": "这里应该用〈照顾〉。“经营”不能用于照料人，说“照顾生病的爷爷”才自然。"}, {"text": "我们正在经营严重的环境污染。", "explanation": "这里应该用〈治理〉。“经营”不能和“污染”搭配，说“治理污染”才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87269, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家花店她经营地很好。", "corrected_sentence": "这家花店她经营得很好。", "error_description": "补语错误：“经营”后面带程度补语时要用“得”，不能用“地”（“地”用于状语）。正确说法是“经营得很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87269, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年轻时经营了过一家修车店。", "corrected_sentence": "他年轻时经营过一家修车店。", "error_description": "体标错误：“经营过”表示经历体，动词后不能同时用“了”和“过”。正确说法是“经营过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
