INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87270, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "筹划并管理（企业、商店等）。", "primary_collocate": null, "pronunciation": "jīng yíng", "ipa": "tɕiŋ˥ iŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这家公司主要经营电脑和手机。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他经营一家公司已经二十年了。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工厂经营得不太好，要关门了。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理很会经营，公司每年都赚钱。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把家里的生意交给儿子经营。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家超市经营各种吃的和用的东西。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不会经营，所以公司越做越差。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司经营了五年，终于开始赚钱了。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店由一家大公司经营。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算一起经营一家小工厂。", "target_word": "经营", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "经营了", "label": "完成体"}, {"form": "经营着", "label": "持续体"}, {"form": "经营过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "筹划并管理企业或商店", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '679c1d60-cd18-4bd7-984c-952bf355ca55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87270, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "经营", "is_correct": true, "explanation": "正确：“经营”指管理企业、销售商品，与“这家公司主要经营电脑和手机”的语境相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”的对象是请求、邀请等，不能说“拒绝电脑和手机”作为公司的业务。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与公司主要业务的意思矛盾，句意不通。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”表示想念过去的人或事，与公司主要业务无关。"}], "explanations": {"经营": "正确：“经营”指管理企业、销售商品，与“这家公司主要经营电脑和手机”的语境相符。", "拒绝": "搭配：“拒绝”的对象是请求、邀请等，不能说“拒绝电脑和手机”作为公司的业务。", "忘记": "语义：“忘记”与公司主要业务的意思矛盾，句意不通。", "怀念": "语义：“怀念”表示想念过去的人或事，与公司主要业务无关。"}, "sentence_index": 0, "correct_answer": "经营"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师每天都在经营学生，希望他们进步。", "explanation": "这里应该用〈教育〉。“经营”用于企业、商店，教育学生不能用“经营”。"}, {"text": "医生每天经营病人，希望他们早日康复。", "explanation": "这里应该用〈治疗〉。“经营”不用于医治病人，说“治疗病人”才自然。"}, {"text": "科学家每天经营病毒，寻找治疗的方法。", "explanation": "这里应该用〈研究〉。“经营”不用于研究对象，说“研究病毒”才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经营", "is_correct": true, "explanation": "正确：“他不会经营”指不会管理企业，与“公司越做越差”的因果关系相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与公司经营的好坏没有关系，因果关系不成立。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与经营企业无关，句子的因果关系不成立。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”需要可食用的宾语，“不会吃”与公司经营没有关系，句意不通。"}], "explanations": {"经营": "正确：“他不会经营”指不会管理企业，与“公司越做越差”的因果关系相符。", "唱歌": "语义：“唱歌”与公司经营的好坏没有关系，因果关系不成立。", "游泳": "语义：“游泳”与经营企业无关，句子的因果关系不成立。", "吃": "配价：“吃”需要可食用的宾语，“不会吃”与公司经营没有关系，句意不通。"}, "sentence_index": 6, "correct_answer": "经营"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "消防员正在经营被困的伤者。", "explanation": "这里应该用〈救助〉。“经营”用于企业、商店，救助伤者要用“救助”。"}, {"text": "警察正在经营这起案件。", "explanation": "这里应该用〈调查〉。“经营”不能用于案件，说“调查案件”才自然。"}, {"text": "保洁员每天经营这条街道。", "explanation": "这里应该用〈打扫〉。“经营”不用于清理街道，说“打扫街道”才自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他经营了着一家公司。", "corrected_sentence": "他经营着一家公司。", "error_description": "体标错误：“着”表示动作的持续，动词后不能同时用“了”和“着”。正确说法是“经营着一家公司”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经经营了过一个小工厂。", "corrected_sentence": "他曾经经营过一个小工厂。", "error_description": "体标错误：“经营过”表示经历体，动词后不能同时用“了”和“过”。正确说法是“经营过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68c3275f-1f36-42e1-853d-49a133abf938') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
