INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87273, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "全副是整套都有，一样不少。", "primary_collocate": null, "pronunciation": "quán fù", "ipa": "tɕʰɥɛn˧˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "消防员穿着全副装备冲进了大楼。", "target_word": "全副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带着全副画具搬到了新城市。", "target_word": "全副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们穿上全副护甲，站在门口。", "target_word": "全副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑士穿上全副盔甲，走出了城堡。", "target_word": "全副", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "登山队员背着全副装备出发了。", "target_word": "全副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员穿上全副行头，开始表演。", "target_word": "全副", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察带着全副装备守在银行外面。", "target_word": "全副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "潜水员穿好全副潜水装备就下水了。", "target_word": "全副", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去钓鱼前，买了全副渔具。", "target_word": "全副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生穿戴好全副防护装备，走进病房。", "target_word": "全副", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "整套齐全，一样不少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e64b3b0f-81c3-4b52-bcde-e97b5fd7793c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87273, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精巧", "is_correct": false, "explanation": "搭配：“精巧”形容细致小巧的器物，不能用来修饰消防员穿戴的装备。"}, {"text": "全副", "is_correct": true, "explanation": "正确。“全副”指整套齐全、一样不少，与“穿着……装备冲进了大楼”相合。"}, {"text": "魁梧", "is_correct": false, "explanation": "体貌：“魁梧”形容人的体格，不能用来修饰装备。"}, {"text": "空", "is_correct": false, "explanation": "语义：“空”指里面没有东西，与“穿着……装备冲进了大楼”的意思相矛盾。"}], "explanations": {"精巧": "搭配：“精巧”形容细致小巧的器物，不能用来修饰消防员穿戴的装备。", "全副": "正确。“全副”指整套齐全、一样不少，与“穿着……装备冲进了大楼”相合。", "魁梧": "体貌：“魁梧”形容人的体格，不能用来修饰装备。", "空": "语义：“空”指里面没有东西，与“穿着……装备冲进了大楼”的意思相矛盾。"}, "sentence_index": 0, "correct_answer": "全副"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他身上全副的伤痕都还没好。", "explanation": "这里应该用〈全身〉。全副修饰整套装备等物件，不修饰伤痕。"}, {"text": "他穿上全副的一件外套，就出门了。", "explanation": "这里误用了〈全副〉。全副指整套、一样不少，与“一件”的单件矛盾，不能修饰单件外套。"}, {"text": "这些书我全副带走了。", "explanation": "这里应该用〈全部〉。全副修饰整套装备等物件，不用于书等零散物件的全部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87273, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "苗条", "is_correct": false, "explanation": "体貌：“苗条”形容人的体形，不能用来修饰装备。"}, {"text": "全副", "is_correct": true, "explanation": "正确。“全副”指整套齐全，与“带着全副装备守在银行外面”相合。"}, {"text": "温柔", "is_correct": false, "explanation": "搭配：“温柔”形容人的性格或态度，不能用来修饰装备。"}, {"text": "假", "is_correct": false, "explanation": "语义：“假”指不真实，警察带着假装备守卫，与其职责相矛盾。"}], "explanations": {"苗条": "体貌：“苗条”形容人的体形，不能用来修饰装备。", "全副": "正确。“全副”指整套齐全，与“带着全副装备守在银行外面”相合。", "温柔": "搭配：“温柔”形容人的性格或态度，不能用来修饰装备。", "假": "语义：“假”指不真实，警察带着假装备守卫，与其职责相矛盾。"}, "sentence_index": 6, "correct_answer": "全副"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全副天空都是乌云。", "explanation": "这里应该用〈整个〉。全副修饰整套装备等物件，不修饰天空。"}, {"text": "全副老师都来了，只差校长。", "explanation": "这里应该用〈全体〉。全副修饰整套装备等物件，不修饰老师等人员。"}, {"text": "今天他只戴了全副的一只手套。", "explanation": "这里误用了〈全副〉：全副指整套、一样不少，而“一只”是单件，与之矛盾；手套应说〈一副〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87273, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他穿着一副全副护具上了场。", "corrected_sentence": "他穿着全副护具上了场。", "error_description": "数量错误：“全副”本身已表示整套齐全，前面不能再加数量词“一副”。应为「穿着全副护具」，不能写成「一副全副护具」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87273, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他穿着很全副铠甲来到现场。", "corrected_sentence": "他穿着全副铠甲来到现场。", "error_description": "“全副”是表示整套齐全的属性词，不能受程度副词“很”修饰，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
