INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87274, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "整套的、全部的（装备等）。", "primary_collocate": null, "pronunciation": "quán fù", "ipa": "tɕʰɥɛn˧˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "他背着全副装备走进了森林。", "target_word": "全副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们穿着全副战甲，准备出发。", "target_word": "全副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个骑马的人穿着全副铠甲。", "target_word": "全副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安穿着全副制服，守着大门。", "target_word": "全副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "探险队带了全副登山装备。", "target_word": "全副", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿着全副工具来修水管。", "target_word": "全副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "特警穿戴好全副防护装备冲进了房间。", "target_word": "全副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄影师背着全副器材上了山。", "target_word": "全副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "滑雪者穿好全副滑雪装备，从山顶冲下来。", "target_word": "全副", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们穿好全副装备，一步一步走近敌人。", "target_word": "全副", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "整套的、全部的装备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e64b3b0f-81c3-4b52-bcde-e97b5fd7793c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87274, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容人的身材，不能用来修饰背着的装备。"}, {"text": "全副", "is_correct": true, "explanation": "正确。“全副”指整套的装备，与“背着……装备走进了森林”相合。"}, {"text": "甜美", "is_correct": false, "explanation": "搭配：“甜美”多形容声音、笑容，不能用来修饰装备，搭配不当。"}, {"text": "空", "is_correct": false, "explanation": "语义：“空”表示里面没有东西，与“背着装备走进了森林”的意思相矛盾。"}], "explanations": {"矮小": "体貌：“矮小”形容人的身材，不能用来修饰背着的装备。", "全副": "正确。“全副”指整套的装备，与“背着……装备走进了森林”相合。", "甜美": "搭配：“甜美”多形容声音、笑容，不能用来修饰装备，搭配不当。", "空": "语义：“空”表示里面没有东西，与“背着装备走进了森林”的意思相矛盾。"}, "sentence_index": 0, "correct_answer": "全副"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全副房间都收拾干净了。", "explanation": "这里应该用〈全部〉。全副修饰整套装备等物件，不修饰房间。"}, {"text": "全副乘客都下车了。", "explanation": "这里应该用〈全体〉。全副修饰整套装备等物件，不修饰乘客等人。"}, {"text": "他戴着全副的一只耳环，去参加晚会。", "explanation": "这里误用了〈全副〉：全副指整套、一样不少，与“一只”的单件矛盾；耳环成对，应说〈一对〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "瘦弱", "is_correct": false, "explanation": "体貌：“瘦弱”形容人的体格，不能用来修饰防护装备。"}, {"text": "全副", "is_correct": true, "explanation": "正确。“全副”指整套的装备，与“穿戴好……防护装备冲进了房间”相合。"}, {"text": "精神", "is_correct": false, "explanation": "搭配：“精神”形容人的状态，修饰防护装备搭配不当。"}, {"text": "无效", "is_correct": false, "explanation": "语义：“无效”表示没有作用，与“穿戴好防护装备冲进房间”的做法相矛盾。"}], "explanations": {"瘦弱": "体貌：“瘦弱”形容人的体格，不能用来修饰防护装备。", "全副": "正确。“全副”指整套的装备，与“穿戴好……防护装备冲进了房间”相合。", "精神": "搭配：“精神”形容人的状态，修饰防护装备搭配不当。", "无效": "语义：“无效”表示没有作用，与“穿戴好防护装备冲进房间”的做法相矛盾。"}, "sentence_index": 6, "correct_answer": "全副"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议全副人员都到齐了。", "explanation": "这里应该用〈全体〉。全副修饰整套装备，不用于人员。"}, {"text": "全副城市都停电了。", "explanation": "这里应该用〈整个〉。全副只修饰整套装备，不能修饰城市。"}, {"text": "车上只有全副的一个轮胎。", "explanation": "这里误用了〈全副〉：全副指整套、一样不少，而“一个”是单件，与之矛盾；应删去“全副”，说“车上只有一个轮胎”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防队员穿好一副全副防护服出发了。", "corrected_sentence": "消防队员穿好全副防护服出发了。", "error_description": "数量错误：“全副”本身已表示整套齐全，前面不能再加数量词“一副”。应为「穿好全副防护服」，不能写成「一副全副防护服」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她穿好很全副装备，骑车出发了。", "corrected_sentence": "她穿好全副装备，骑车出发了。", "error_description": "“全副”不能受程度副词“很”修饰，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cb1be39-7926-42f2-9d30-b93febba9078') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
