INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87275, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能人是很会做事、本领很大的人。", "primary_collocate": null, "pronunciation": "néng rén", "ipa": "nəŋ˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "我们村里有一位能人，什么都会修。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司请来一位能人管理工厂。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说他是个能人，没有他解决不了的问题。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王经理是公司里的能人，客户都很信任他。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想把小店开好，得请一位能人来帮忙。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能人也有不会的事，要多向别人学习。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就是班里的能人，电脑坏了都找他。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们队里能人很多，所以今年赢了比赛。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里来了一位能人，帮大家种出了好水果。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你真是个能人，这么快就把车修好了。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "很会做事、本领很大的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eb1202a-debe-449b-9a5c-f738d8413e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87275, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "能人", "is_correct": true, "explanation": "正确：“能人”指很会做事、本领大的人，与“什么都会修”相符。"}, {"text": "懒人", "is_correct": false, "explanation": "语义：“懒人”不做事，与“什么都会修”相矛盾。"}, {"text": "废物", "is_correct": false, "explanation": "语域：“废物”是贬斥用语，与这里客观称赞的语境不协调，且与“什么都会修”相矛盾。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”指生病的人，与“什么都会修”的能力描述不合。"}], "explanations": {"能人": "正确：“能人”指很会做事、本领大的人，与“什么都会修”相符。", "懒人": "语义：“懒人”不做事，与“什么都会修”相矛盾。", "废物": "语域：“废物”是贬斥用语，与这里客观称赞的语境不协调，且与“什么都会修”相矛盾。", "病人": "语义：“病人”指生病的人，与“什么都会修”的能力描述不合。"}, "sentence_index": 0, "correct_answer": "能人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头是村里的能人。", "explanation": "这里不能用〈能人〉。能人指很会做事、本领大的人，不能用来说石头。"}, {"text": "这把椅子是家里的能人。", "explanation": "这里不能用〈能人〉。能人指人，不能用来说椅子这样的物品。"}, {"text": "这间屋子是村里的能人。", "explanation": "这里不能用〈能人〉。能人指很会做事的人，不能用来说房屋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87275, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "能人", "is_correct": true, "explanation": "正确：“能人”指有本事的人，与“从小就是班里的……电脑坏了都找他”相合。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：“陌生人”与“从小就是班里的”矛盾，大家不会向陌生人求助修电脑。"}, {"text": "客人", "is_correct": false, "explanation": "语义：“客人”不是班里的成员，与“从小就是班里的”不合。"}, {"text": "居民", "is_correct": false, "explanation": "搭配：“居民”指住在某地区的人，不能说“班里的居民”。"}], "explanations": {"能人": "正确：“能人”指有本事的人，与“从小就是班里的……电脑坏了都找他”相合。", "陌生人": "语义：“陌生人”与“从小就是班里的”矛盾，大家不会向陌生人求助修电脑。", "客人": "语义：“客人”不是班里的成员，与“从小就是班里的”不合。", "居民": "搭配：“居民”指住在某地区的人，不能说“班里的居民”。"}, "sentence_index": 6, "correct_answer": "能人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很佩服他的能人。", "explanation": "这里应该用〈能力〉。能人指有本领的人，不能用来指一个人的能力。"}, {"text": "这次考试他得了能人。", "explanation": "这里不能用〈能人〉。能人指有本领的人，不能指奖品或成绩。"}, {"text": "我的书包里装着一位能人。", "explanation": "这里不能用〈能人〉。能人是有本领的人，不能装在书包这样的物品里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87275, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的父亲是一只能人，木工活都会做。", "corrected_sentence": "他的父亲是一位能人，木工活都会做。", "error_description": "量词错误：“能人”指人，应用量词“位”或“个”，“只”用于动物等。正确说法是：他的父亲是一位能人，木工活都会做。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87275, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只能人修好了厂里所有的机器。", "corrected_sentence": "这位能人修好了厂里所有的机器。", "error_description": "量词错误：「能人」指人，应用量词「位」或「个」，「只」用于动物等。正确说法是：这位能人修好了厂里所有的机器。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
