INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87276, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指有才能、本领大的人。", "primary_collocate": null, "pronunciation": "néng rén", "ipa": "nəŋ˧˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他是学校里公认的能人，数学和画画都很好。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小城出了不少能人。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李是我们公司的能人，大小事他都能办。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会做饭、会开车、会修车，他真是个能人。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到难题时，我们都去找那位能人。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是个能人，一个人管三家店。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的能人太多，我得多向他们学习。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能人不一定说得多，但做事很快。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村长想请几位能人回来帮助家乡。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别看他年轻，其实是个很有本事的能人。", "target_word": "能人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "有才能、本领大的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eb1202a-debe-449b-9a5c-f738d8413e68') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87276, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "能人", "is_correct": true, "explanation": "正确：“能人”指有才能、本领大的人，与“数学和画画都很好”相合。"}, {"text": "差生", "is_correct": false, "explanation": "语义：“差生”指成绩差的学生，与“数学和画画都很好”矛盾。"}, {"text": "路人", "is_correct": false, "explanation": "语义：“路人”指过路的人，与“学校里公认的”和“数学和画画都很好”都对不上。"}, {"text": "蠢货", "is_correct": false, "explanation": "语域：“蠢货”是粗俗的骂人话，与“公认”的客观评价语域不符，也与后句矛盾。"}], "explanations": {"能人": "正确：“能人”指有才能、本领大的人，与“数学和画画都很好”相合。", "差生": "语义：“差生”指成绩差的学生，与“数学和画画都很好”矛盾。", "路人": "语义：“路人”指过路的人，与“学校里公认的”和“数学和画画都很好”都对不上。", "蠢货": "语域：“蠢货”是粗俗的骂人话，与“公认”的客观评价语域不符，也与后句矛盾。"}, "sentence_index": 0, "correct_answer": "能人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座大桥是村里的能人。", "explanation": "这里不能用〈能人〉。能人指人，不能用来说桥这样的建筑。"}, {"text": "这块地是村里的能人。", "explanation": "这里不能用〈能人〉。能人指很会做事、本领大的人，不能用来说土地。"}, {"text": "这把伞是我们家的能人。", "explanation": "这里不能用〈能人〉。能人指人，不能用来说伞这样的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "能人", "is_correct": true, "explanation": "正确：“能人”指有本事的人，与“这里的……太多，我得多向他们学习”相合。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：“乞丐”没有可以学习的本领，与“我得多向他们学习”不合。"}, {"text": "罪犯", "is_correct": false, "explanation": "语义：“罪犯”是违法的人，不值得向他们学习，与语境相矛盾。"}, {"text": "垃圾", "is_correct": false, "explanation": "搭配：“多向他们学习”的对象是人，不说向“垃圾”学习，搭配不当。"}], "explanations": {"能人": "正确：“能人”指有本事的人，与“这里的……太多，我得多向他们学习”相合。", "乞丐": "语义：“乞丐”没有可以学习的本领，与“我得多向他们学习”不合。", "罪犯": "语义：“罪犯”是违法的人，不值得向他们学习，与语境相矛盾。", "垃圾": "搭配：“多向他们学习”的对象是人，不说向“垃圾”学习，搭配不当。"}, "sentence_index": 6, "correct_answer": "能人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很佩服他的能人。", "explanation": "这里应该用〈能力〉。能人指有本领的人，不能用来指一个人的能力。"}, {"text": "这次比赛他拿了能人。", "explanation": "这里不能用〈能人〉。能人指有本领的人，不能指奖品或名次。"}, {"text": "这碗能人很好吃。", "explanation": "这里不能用〈能人〉。能人指有本事的人，不能用来指食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们厂来了一头能人，修机器很快。", "corrected_sentence": "我们厂来了一位能人，修机器很快。", "error_description": "量词错误：“能人”指人，应用量词“位”，“头”用于牲畜，不能用来数人。正确说法是：我们厂来了一位能人，修机器很快。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是我见过最有本事的一台能人。", "corrected_sentence": "他是我见过最有本事的一位能人。", "error_description": "量词错误：“能人”指人，应用量词“位”，“台”用于机器等，不能用来数人。正确说法是：他是我见过最有本事的一位能人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8513492-e14a-421d-b6c4-6142b24a11c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
