INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87277, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "日志是每天写下来的事情的本子。", "primary_collocate": null, "pronunciation": "rì zhì", "ipa": "ɻʅ⁵¹ ʈʂʅ⁵¹", "syllable_count": 2, "sentences": [{"text": "我每天晚上都在日志里写几句话。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的日志放在桌子上。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈有写日志的习惯。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本日志我已经写了三年。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把今天的事写进了日志。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我翻开旧日志，想起了很多事。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的日志里有很多照片。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把日志带到学校去了。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们每周写一篇日志。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在日志中写着自己的心情。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日誌", "label": "繁体"}], "register": "中性", "sense_fingerprint": "每天记事的本子，类似日记", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c82921da-4675-443e-aa98-940b45501dcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87277, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "日志", "is_correct": true, "explanation": "“日志”指每天记事的本子，与听到的读音一致。"}, {"text": "日式", "is_correct": false, "explanation": "shì 与 zhì 只有声母不同（sh 与 zh），“日式”意思是日本式的，不是记事本。"}, {"text": "日食", "is_correct": false, "explanation": "shí 与 zhì 声母和声调都不同，“日食”是太阳被月亮挡住的现象。"}, {"text": "立志", "is_correct": false, "explanation": "lì 与 rì 声母不同（l 与 r），“立志”意思是下定决心。"}], "explanations": {"日志": "“日志”指每天记事的本子，与听到的读音一致。", "日式": "shì 与 zhì 只有声母不同（sh 与 zh），“日式”意思是日本式的，不是记事本。", "日食": "shí 与 zhì 声母和声调都不同，“日食”是太阳被月亮挡住的现象。", "立志": "lì 与 rì 声母不同（l 与 r），“立志”意思是下定决心。"}, "sentence_index": null, "correct_answer": "日志"}, "level_3": {"options": [{"text": "日志", "is_correct": true, "explanation": "“日志”是每天写记录的本子，可以在里面写几句话，符合句意。"}, {"text": "电视", "is_correct": false, "explanation": "语义：“电视”是播放节目的机器，不能在里面写字。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：“饼干”是食品，不能用来写字，与“写几句话”搭配不当。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是冷藏食物的家电，不能在里面写字。"}], "explanations": {"日志": "“日志”是每天写记录的本子，可以在里面写几句话，符合句意。", "电视": "语义：“电视”是播放节目的机器，不能在里面写字。", "饼干": "搭配：“饼干”是食品，不能用来写字，与“写几句话”搭配不当。", "冰箱": "语义：“冰箱”是冷藏食物的家电，不能在里面写字。"}, "sentence_index": 0, "correct_answer": "日志"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "墙上挂着一本新日志，可以看今天几号。", "explanation": "这里应该用〈日历〉。“日志”是记事的本子，看日期要用〈日历〉。"}, {"text": "明天下午的会议已经写进日志里了。", "explanation": "这里应该用〈日程〉。“日志”记录已经发生的事情，安排未来的会议要用〈日程〉。"}, {"text": "这篇论文发表在国际日志上。", "explanation": "这里应该用〈期刊〉。“日志”是每天记事的本子，发表论文的刊物叫〈期刊〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87277, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日志", "is_correct": true, "explanation": "“日志”里可以夹放照片，符合句意。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是水的流动，不能在里面放很多照片。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“钥匙”是开锁用的小物件，里面不会有很多照片，搭配不当。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“大海”是广阔的海洋，不能说它里面有很多照片。"}], "explanations": {"日志": "“日志”里可以夹放照片，符合句意。", "河流": "语义：“河流”是水的流动，不能在里面放很多照片。", "钥匙": "搭配：“钥匙”是开锁用的小物件，里面不会有很多照片，搭配不当。", "大海": "语义：“大海”是广阔的海洋，不能说它里面有很多照片。"}, "sentence_index": 6, "correct_answer": "日志"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我看了看日志，今天是星期五。", "explanation": "这里应该用〈日历〉。“日志”记录每天发生的事，查日期要用〈日历〉。"}, {"text": "上课时他认真地记日志。", "explanation": "这里应该用〈笔记〉。“日志”是按天记事的本子，上课时的记录要用〈笔记〉。"}, {"text": "他每天给远方的妈妈写日志。", "explanation": "这里应该用〈写信〉。“日志”是自己每天记事的本子，不用来寄给别人，给远方的人写东西要用〈写信〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87277, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天写完一只日志才睡觉。", "corrected_sentence": "我每天写完一本日志才睡觉。", "error_description": "量词错误：“日志”是本子，量词应用“本”，“只”多用于动物或小件物品。应说“写完一本日志才睡觉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87277, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我翻开了一台旧日志。", "corrected_sentence": "我翻开了一本旧日志。", "error_description": "错误形式：“一台旧日志”。正确形式：“一本旧日志”。“日志”是本子，量词用“本”；“台”多用于机器、电器等。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
