INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87278, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "每天记录事情或工作情况的文字；也指计算机运行记录。", "primary_collocate": null, "pronunciation": "rì zhì", "ipa": "ɻʅ⁵¹ ʈʂʅ⁵¹", "syllable_count": 2, "sentences": [{"text": "工作日志要每天写。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在工作日志里记下了今天的会议。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板每天下班前看大家的日志。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑出问题了，请查一下系统日志。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务器的日志保存了三十天。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "程序出错时，日志里会有提示。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把今天的日志发给经理。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士每天要写工作日志。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日志太长了，我找不到错误在哪儿。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师打开日志，找到了问题。", "target_word": "日志", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工作日志", "label": "复合"}, {"form": "系统日志", "label": "复合"}, {"form": "日誌", "label": "繁体"}], "register": "中性", "sense_fingerprint": "工作记录或计算机运行记录", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c82921da-4675-443e-aa98-940b45501dcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87278, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "日志", "is_correct": true, "explanation": "“日志”指工作记录或系统运行记录，与听到的读音一致。"}, {"text": "日式", "is_correct": false, "explanation": "shì 与 zhì 只有声母不同（sh 与 zh），“日式”意思是日本式的，不是记录。"}, {"text": "日食", "is_correct": false, "explanation": "shí 与 zhì 声母和声调都不同，“日食”是太阳被月亮挡住的现象。"}, {"text": "立志", "is_correct": false, "explanation": "lì 与 rì 声母不同（l 与 r），“立志”意思是下定决心。"}], "explanations": {"日志": "“日志”指工作记录或系统运行记录，与听到的读音一致。", "日式": "shì 与 zhì 只有声母不同（sh 与 zh），“日式”意思是日本式的，不是记录。", "日食": "shí 与 zhì 声母和声调都不同，“日食”是太阳被月亮挡住的现象。", "立志": "lì 与 rì 声母不同（l 与 r），“立志”意思是下定决心。"}, "sentence_index": null, "correct_answer": "日志"}, "level_3": {"options": [{"text": "日志", "is_correct": true, "explanation": "“工作日志”是每天要写的工作记录，符合句意。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“钥匙”不是可以写的东西，不能说“要每天写”。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是遮雨的用品，不是需要书写的内容。"}, {"text": "茶杯", "is_correct": false, "explanation": "语义：“茶杯”是盛水喝茶的器具，不需要每天书写。"}], "explanations": {"日志": "“工作日志”是每天要写的工作记录，符合句意。", "钥匙": "搭配：“钥匙”不是可以写的东西，不能说“要每天写”。", "雨伞": "语义：“雨伞”是遮雨的用品，不是需要书写的内容。", "茶杯": "语义：“茶杯”是盛水喝茶的器具，不需要每天书写。"}, "sentence_index": 0, "correct_answer": "日志"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的电费日志已经寄来了。", "explanation": "这里应该用〈账单〉。“日志”是记录工作或系统运行情况的记录，不是缴费通知。"}, {"text": "出差前要检查一下行李日志。", "explanation": "这里应该用〈清单〉。“日志”是按时间记录过程的记录，不是列出物品的单子。"}, {"text": "我看了看系统日志，今天是星期五。", "explanation": "这里应该用〈日历〉。“日志”记录工作或系统运行情况，查日期要用〈日历〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日志", "is_correct": true, "explanation": "“日志”是每天的工作记录，可以发给经理，符合句意。"}, {"text": "冰淇淋", "is_correct": false, "explanation": "语义：“冰淇淋”是食品，不是工作记录，不能发给经理。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：“发给”一般搭配文件、材料，不搭配“鞋子”。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：“外貌”指人的容貌，不能当作工作内容发给经理。"}], "explanations": {"日志": "“日志”是每天的工作记录，可以发给经理，符合句意。", "冰淇淋": "语义：“冰淇淋”是食品，不是工作记录，不能发给经理。", "鞋子": "搭配：“发给”一般搭配文件、材料，不搭配“鞋子”。", "外貌": "体貌：“外貌”指人的容貌，不能当作工作内容发给经理。"}, "sentence_index": 6, "correct_answer": "日志"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在会上做了工作日志。", "explanation": "这里应该用〈报告〉。“做报告”是向别人汇报工作；“日志”是平时记录的本子，不用来在会上汇报。"}, {"text": "明天的会议已经安排在日志里了。", "explanation": "这里应该用〈日程〉。“日志”记录已经发生的事，安排未来的会议要用〈日程〉。"}, {"text": "这篇论文发表在国际日志上。", "explanation": "这里应该用〈期刊〉。“日志”是工作或系统的记录，发表论文的刊物叫〈期刊〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只工作日志要今天交给经理。", "corrected_sentence": "这份工作日志要今天交给经理。", "error_description": "错误形式：“这只工作日志”。正确形式：“这份工作日志”。“日志”是书面材料，量词用“份”，不用“只”（“只”多用于动物、手或小件物品）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工程师的日志写很详细。", "corrected_sentence": "工程师的日志写得很详细。", "error_description": "错误形式：“写很详细”。正确形式：“写得很详细”。动词后带状态补语时要用“得”连接，不能直接用“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '932a57fe-9398-41db-9fdd-1b79fde921e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
