INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87279, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "谢谢是别人帮了我们，我们说的话。", "primary_collocate": null, "pronunciation": "xiè xie", "ipa": "ɕje˥˩ ɕje", "syllable_count": 2, "sentences": [{"text": "你帮我拿包，谢谢！", "target_word": "谢谢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师给我一本书，我说：“谢谢！”", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“这是你的水。”“谢谢，放这儿吧。”", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给我让了座，我对他说谢谢。", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友送我回家，我连声说谢谢。", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友接过糖，大声说：“谢谢阿姨！”", "target_word": "谢谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员送来了菜，我小声说了句谢谢。", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，别人帮了你，要说谢谢。", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“门我来开。”“谢谢，你真好！”", "target_word": "谢谢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老人下车时，对司机说了声谢谢。", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "謝謝", "label": "繁体"}], "register": "口语", "sense_fingerprint": "受到帮助后说的客套话，独立使用的感谢用语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 6 above tier T1: 3 words above tier T1 (max 2): 服务员 (Zipf 3.93), 送来 (Zipf 3.93), 小声 (Zipf 3.6)']::text[], '8d78632b-8856-4b08-affc-b5331421b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87279, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谢谢", "is_correct": true, "explanation": "正确：“谢谢”表示感激，与“你帮我拿包”的语境吻合。"}, {"text": "再见", "is_correct": false, "explanation": "语义：“再见”是告别用语，与帮忙后的致谢不符。"}, {"text": "哎呀", "is_correct": false, "explanation": "语义：“哎呀”是惊叹语，不表示感谢。"}, {"text": "对不起", "is_correct": false, "explanation": "语义：“对不起”表示道歉，与感谢的语境相反。"}], "explanations": {"谢谢": "正确：“谢谢”表示感激，与“你帮我拿包”的语境吻合。", "再见": "语义：“再见”是告别用语，与帮忙后的致谢不符。", "哎呀": "语义：“哎呀”是惊叹语，不表示感谢。", "对不起": "语义：“对不起”表示道歉，与感谢的语境相反。"}, "sentence_index": 0, "correct_answer": "谢谢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他摔倒了，腿还在流血，我对他说了声谢谢。", "explanation": "这里应该说〈你没事吧〉。见别人受伤要表示关心，“谢谢”表示感激，不能用来关心或安慰。"}, {"text": "我不小心踩到了他的脚，连忙说了声谢谢。", "explanation": "这里应该用〈对不起〉。踩到别人要道歉，“谢谢”表示感激，不能用来道歉。"}, {"text": "我弄丢了他的伞，还连声对他说谢谢。", "explanation": "这里应该说〈对不起〉。弄丢别人的东西要道歉，“谢谢”表示感激，不能替代道歉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87279, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谢谢", "is_correct": true, "explanation": "正确：“谢谢”表示小声致谢，与服务员送菜的语境吻合。"}, {"text": "晚安", "is_correct": false, "explanation": "语义：“晚安”是夜间道别，与送菜后的致谢语境不符。"}, {"text": "哇", "is_correct": false, "explanation": "语义：“哇”表示惊叹，不用来表示感谢。"}, {"text": "唉", "is_correct": false, "explanation": "语域：“唉”是叹息声，不是礼貌的致谢用语。"}], "explanations": {"谢谢": "正确：“谢谢”表示小声致谢，与服务员送菜的语境吻合。", "晚安": "语义：“晚安”是夜间道别，与送菜后的致谢语境不符。", "哇": "语义：“哇”表示惊叹，不用来表示感谢。", "唉": "语域：“唉”是叹息声，不是礼貌的致谢用语。"}, "sentence_index": 6, "correct_answer": "谢谢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朋友考上了大学，我对他说了声谢谢。", "explanation": "这里应该用〈恭喜〉。对方取得好成绩要道贺，“谢谢”是感谢用语，不能替代道贺。"}, {"text": "他的父亲刚去世，我对他说了声谢谢。", "explanation": "这里应该用〈节哀〉。遇到他人丧亲要表示哀悼，“谢谢”表示感激，不能替代哀悼。"}, {"text": "孩子不小心摔碎了碗，我却对他说了声谢谢。", "explanation": "这里应该用〈没关系〉。别人不小心犯错要宽慰，“谢谢”表示感激，不能用来宽慰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87279, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次多亏你，很谢谢！", "corrected_sentence": "这次多亏你，谢谢！", "error_description": "“谢谢”作独立使用的感谢用语，前面不加程度副词“很”；应说“谢谢”或“非常感谢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87279, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他帮我开了门，我连声说谢谢的。", "corrected_sentence": "他帮我开了门，我连声说谢谢。", "error_description": "“谢谢”作独立说出的感谢用语，后面不加“的”；应说“连声说谢谢”，不说“谢谢的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
