INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87280, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向某人表示感谢，后常带受谢者作宾语。", "primary_collocate": null, "pronunciation": "xiè xie", "ipa": "ɕje˥˩ ɕje", "syllable_count": 2, "sentences": [{"text": "我想谢谢你的帮助。", "target_word": "谢谢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "谢谢你送我的花。", "target_word": "谢谢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我要好好谢谢那位医生。", "target_word": "谢谢", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他帮了我很多，我想谢谢他。", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢大家今天来参加我的生日会。", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我打电话谢谢她，因为她借给我伞。", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你一直照顾着我的小狗。", "target_word": "谢谢", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要不是你，我早就迟到了，谢谢你！", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请替我谢谢你的妈妈，饭很好吃。", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他向每一位客人鞠躬，谢谢他们。", "target_word": "谢谢", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "謝謝", "label": "繁体"}], "register": "口语", "sense_fingerprint": "向某人表示感谢，后面常带对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d78632b-8856-4b08-affc-b5331421b71a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谢谢", "is_correct": true, "explanation": "正确：“谢谢”向人表示感谢，与“你的帮助”搭配。"}, {"text": "收拾", "is_correct": false, "explanation": "搭配：“收拾”用于房间、东西，不接“帮助”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”是清理场所，不能打扫“帮助”。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示反感，与“我想”表达的感激心情不符。"}], "explanations": {"谢谢": "正确：“谢谢”向人表示感谢，与“你的帮助”搭配。", "收拾": "搭配：“收拾”用于房间、东西，不接“帮助”。", "打扫": "搭配：“打扫”是清理场所，不能打扫“帮助”。", "讨厌": "语义：“讨厌”表示反感，与“我想”表达的感激心情不符。"}, "sentence_index": 0, "correct_answer": "谢谢"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我不小心弄坏了他的书，我想谢谢他。", "explanation": "这里应该用〈道歉〉。弄坏别人的东西要向人道歉，“谢谢”表示感激，不能用来表示歉意。"}, {"text": "我一进门就吵醒了他，我连声说谢谢。", "explanation": "这里应该用〈抱歉〉。吵醒别人要表示歉意，“谢谢”表示感激，不能用来道歉。"}, {"text": "孩子考试没考好，妈妈却谢谢他。", "explanation": "这里应该用〈鼓励〉。孩子考试失利要鼓励，“谢谢”表示感激，不能替代鼓励。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谢谢", "is_correct": true, "explanation": "正确：“谢谢”向人表示感谢，与“一直照顾”的语境吻合。"}, {"text": "责怪", "is_correct": false, "explanation": "语义：“责怪”是怪罪，与感激的语境相反。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”表示厌烦，与“一直照顾”的感激语境相反。"}, {"text": "驱赶", "is_correct": false, "explanation": "搭配：“驱赶”是赶走，与“一直照顾”这类动作不搭配。"}], "explanations": {"谢谢": "正确：“谢谢”向人表示感谢，与“一直照顾”的语境吻合。", "责怪": "语义：“责怪”是怪罪，与感激的语境相反。", "嫌弃": "语义：“嫌弃”表示厌烦，与“一直照顾”的感激语境相反。", "驱赶": "搭配：“驱赶”是赶走，与“一直照顾”这类动作不搭配。"}, "sentence_index": 6, "correct_answer": "谢谢"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的女儿刚考上名校，我想谢谢他。", "explanation": "这里应该用〈恭喜〉。对方家人取得好成绩要道贺，“谢谢”是感谢用语，不能替代道贺。"}, {"text": "他把我的饭洒了一地，我忍不住谢谢了他几句。", "explanation": "这里应该用〈埋怨〉。对别人的过失表示不满要用“埋怨”，“谢谢”表示感激，不能用来抱怨。"}, {"text": "他谢谢我们一路平安。", "explanation": "这里应该用〈祝福〉。祝对方平安要用“祝福”，“谢谢”不能表示祝愿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想谢谢了你的礼物。", "corrected_sentence": "我想谢谢你的礼物。", "error_description": "“想”表示打算，动作还没发生，后面的“谢谢”不能加表示完成的“了”：应说“想谢谢你的礼物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们连声谢谢了他。", "corrected_sentence": "我们连声谢谢他。", "error_description": "重叠式动词“谢谢”带宾语时一般不加“了”：应说“连声谢谢他”，不说“连声谢谢了他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e8cc7a2f-ad07-4e4c-87d1-1568aba3801c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87281, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "晚来", "is_correct": true, "explanation": "晚来与早来相对，指比别人更晚到达这里，是这一义项的反义词。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“早来”的先后顺序无关，不是反义词。"}, {"text": "吃饭", "is_correct": false, "explanation": "与“早来”的先后顺序无关，不是反义词。"}, {"text": "读书", "is_correct": false, "explanation": "与“早来”的先后顺序无关，不是反义词。"}], "correct_answer": "晚来", "explanations": {"晚来": "晚来与早来相对，指比别人更晚到达这里，是这一义项的反义词。", "睡觉": "与“早来”的先后顺序无关，不是反义词。", "吃饭": "与“早来”的先后顺序无关，不是反义词。", "读书": "与“早来”的先后顺序无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87281, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "晚来", "is_correct": true, "explanation": "晚来与早来相对，指比别人更晚到达这里，是这一义项的反义词。"}, {"text": "洗澡", "is_correct": false, "explanation": "与“早来”的先后顺序无关，不是反义词。"}, {"text": "打扫", "is_correct": false, "explanation": "与“早来”的先后顺序无关，不是反义词。"}, {"text": "散步", "is_correct": false, "explanation": "与“早来”的先后顺序无关，不是反义词。"}], "correct_answer": "晚来", "explanations": {"晚来": "晚来与早来相对，指比别人更晚到达这里，是这一义项的反义词。", "洗澡": "与“早来”的先后顺序无关，不是反义词。", "打扫": "与“早来”的先后顺序无关，不是反义词。", "散步": "与“早来”的先后顺序无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87281, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "早来是比别人更早地到这里。", "primary_collocate": null, "pronunciation": "zǎo lái", "ipa": "tsɑʊ̯˨˩˦ laɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "我比同事早来，办公室没有人。", "target_word": "早来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比大家早来，已经坐好了。", "target_word": "早来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早来的同学先占了座位。", "target_word": "早来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我比你早来三天，可以带你去看看。", "target_word": "早来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早来的人可以先选房间。", "target_word": "早来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他比我早来这个城市两年。", "target_word": "早来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟比我们早来，正在门口等着。", "target_word": "早来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么比别人早来这么多？", "target_word": "早来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她比我们早来这里十年，认识很多人。", "target_word": "早来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早来了一年，对这里很熟。", "target_word": "早来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "早来了", "label": "体标（了）"}, {"form": "早来过", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "比别人更早到达这里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c817ef8-4072-4671-8660-bc5321147c0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87281, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早来", "is_correct": true, "explanation": "早来指比别人更早到达这里，与“比同事”和“办公室没有人”的语境相符。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：结婚不是到达某地的动作，不能用“比同事”来比较。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生是一次性事件，不能用来比较到达的先后。"}, {"text": "莅临", "is_correct": false, "explanation": "语域：莅临是书面、敬辞用语，与这句口语语境不相称。"}], "explanations": {"早来": "早来指比别人更早到达这里，与“比同事”和“办公室没有人”的语境相符。", "结婚": "语义：结婚不是到达某地的动作，不能用“比同事”来比较。", "出生": "语义：出生是一次性事件，不能用来比较到达的先后。", "莅临": "语域：莅临是书面、敬辞用语，与这句口语语境不相称。"}, "sentence_index": 0, "correct_answer": "早来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "消息传来后，他立刻早来了现场。", "explanation": "这里应该用〈赶到〉。早来指比别人更早到这里，不表示事情发生后急忙前往。"}, {"text": "他比大家早来，却又比大家晚到。", "explanation": "早来表示比别人更早到这里，这句又说比别人晚到，前后矛盾，不能这样用。"}, {"text": "这条马路比我们早来十年了。", "explanation": "这里应该用〈修通〉。早来只用于人或能到达这里的事物，马路不会来，应说修通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87281, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早来", "is_correct": true, "explanation": "早来指比别人更早到达这里，与“弟弟比我们”和“正在门口等着”的语境相符。"}, {"text": "形成", "is_correct": false, "explanation": "语义：形成指事物逐渐成形，不能用来比较人到达的先后。"}, {"text": "逝去", "is_correct": false, "explanation": "语域：逝去是书面语，带有消逝的意味，与这句口语语境不相称。"}, {"text": "复兴", "is_correct": false, "explanation": "语义：复兴多用于国家、经济等，不能用来比较人到达的先后。"}], "explanations": {"早来": "早来指比别人更早到达这里，与“弟弟比我们”和“正在门口等着”的语境相符。", "形成": "语义：形成指事物逐渐成形，不能用来比较人到达的先后。", "逝去": "语域：逝去是书面语，带有消逝的意味，与这句口语语境不相称。", "复兴": "语义：复兴多用于国家、经济等，不能用来比较人到达的先后。"}, "sentence_index": 6, "correct_answer": "早来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市比我早来一年，已经换了市长。", "explanation": "城市不能“来”。“早来”只用于能来到此处的人或事物，这句把“城市”当作到达的主语，不能这样用。"}, {"text": "这间房子早来了一个月。", "explanation": "这里应该用〈装修好〉。早来只用于能来到此处的人或事物，房子不会来，这句把“来”的主语用错了。"}, {"text": "这次考试他早来了第一名。", "explanation": "这里应该用〈考了〉。早来指比别人更早到达这里，不能表示取得名次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87281, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她每天都比我们早来了，先开门。", "corrected_sentence": "她每天都比我们早来，先开门。", "error_description": "“每天都”表示习惯性动作，与表示完成的“了”不相容，句中不能用“了”。错误形式：“她每天都比我们早来了”；正确形式：“她每天都比我们早来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87281, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个学校的老师很比学生早来。", "corrected_sentence": "这个学校的老师都比学生早来。", "error_description": "错误在副词：“很”是程度副词，不能修饰“比”字短语，此处应用表示全部的“都”。错误形式：“很比学生早来”；正确形式：“都比学生早来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87282, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "晚来", "is_correct": true, "explanation": "晚来与早来相对，指比预定或平常的时间更晚到来，是这一义项的反义词。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“早来”的时间先后无关，不是反义词。"}, {"text": "吃饭", "is_correct": false, "explanation": "与“早来”的时间先后无关，不是反义词。"}, {"text": "读书", "is_correct": false, "explanation": "与“早来”的时间先后无关，不是反义词。"}], "correct_answer": "晚来", "explanations": {"晚来": "晚来与早来相对，指比预定或平常的时间更晚到来，是这一义项的反义词。", "睡觉": "与“早来”的时间先后无关，不是反义词。", "吃饭": "与“早来”的时间先后无关，不是反义词。", "读书": "与“早来”的时间先后无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87282, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "晚来", "is_correct": true, "explanation": "晚来与早来相对，指比预定或平常的时间更晚到来，是这一义项的反义词。"}, {"text": "洗澡", "is_correct": false, "explanation": "与“早来”的时间先后无关，不是反义词。"}, {"text": "打扫", "is_correct": false, "explanation": "与“早来”的时间先后无关，不是反义词。"}, {"text": "散步", "is_correct": false, "explanation": "与“早来”的时间先后无关，不是反义词。"}], "correct_answer": "晚来", "explanations": {"晚来": "晚来与早来相对，指比预定或平常的时间更晚到来，是这一义项的反义词。", "洗澡": "与“早来”的时间先后无关，不是反义词。", "打扫": "与“早来”的时间先后无关，不是反义词。", "散步": "与“早来”的时间先后无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87282, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "提前到来；比预定或平常的时间更早地来。", "primary_collocate": null, "pronunciation": "zǎo lái", "ipa": "tsɑʊ̯˨˩˦ laɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "今天我想早来一会儿。", "target_word": "早来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他比平时早来了半小时。", "target_word": "早来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议八点开始，你可以早来。", "target_word": "早来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天早来的人可以先吃饭。", "target_word": "早来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人比约定时间早来了，我们还没准备好。", "target_word": "早来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说周一要早来打扫教室。", "target_word": "早来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年春天早来了一个月。", "target_word": "早来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他早来了十分钟，一个人坐着等。", "target_word": "早来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怕堵车，所以早来了。", "target_word": "早来", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你早来帮忙。", "target_word": "早来", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "早来了", "label": "体标（了）"}, {"form": "早来过", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "比预定或平常的时间提前到来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c817ef8-4072-4671-8660-bc5321147c0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87282, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早来", "is_correct": true, "explanation": "早来指比预定或平常的时间提前到，符合“今天我想早来一会儿”的语境。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：毕业是一次性完成学业，不能用“想…一会儿”来描述。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生是一次性事件，不能持续“一会儿”，与句子不符。"}, {"text": "莅临", "is_correct": false, "explanation": "语域：莅临是书面、敬辞用语，与这句口语语境不相称。"}], "explanations": {"早来": "早来指比预定或平常的时间提前到，符合“今天我想早来一会儿”的语境。", "毕业": "语义：毕业是一次性完成学业，不能用“想…一会儿”来描述。", "出生": "语义：出生是一次性事件，不能持续“一会儿”，与句子不符。", "莅临": "语域：莅临是书面、敬辞用语，与这句口语语境不相称。"}, "sentence_index": 0, "correct_answer": "早来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "消息传来后，他立刻早来了现场。", "explanation": "这里应该用〈赶到〉。早来指比预定或平常的时间提前到达，不表示事情发生后急忙前往，这句的语境是急赶，应说赶到。"}, {"text": "会议八点开始，他八点半才早来。", "explanation": "早来表示比预定时间提前到，这句说八点半才到，属于晚到，与早来的意思相反，不能这样用。"}, {"text": "会议开始了，他还没到，我们等他的时候，他早来了。", "explanation": "这里应该用〈来了〉。早来指比预定时间提前到达，与“还没到”同时出现，前后矛盾；“早来”不能用于已经晚到的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87282, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "早来", "is_correct": true, "explanation": "早来指比平常的时间提前来到，与“今年春天”和“一个月”的语境相符。"}, {"text": "形成", "is_correct": false, "explanation": "语义：形成指逐渐成形，不能说持续了一个月，与季节来临的语境不符。"}, {"text": "打印", "is_correct": false, "explanation": "语义：打印是人为操作，不能用来描述季节的提前，与句意不符。"}, {"text": "复兴", "is_correct": false, "explanation": "语义：复兴多用于国家、经济等，不能用来描述季节的到来。"}], "explanations": {"早来": "早来指比平常的时间提前来到，与“今年春天”和“一个月”的语境相符。", "形成": "语义：形成指逐渐成形，不能说持续了一个月，与季节来临的语境不符。", "打印": "语义：打印是人为操作，不能用来描述季节的提前，与句意不符。", "复兴": "语义：复兴多用于国家、经济等，不能用来描述季节的到来。"}, "sentence_index": 6, "correct_answer": "早来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条马路早来了一个月。", "explanation": "这里应该用〈修通〉。早来只用于能来到此处的人或事物，马路不会来，应说修通。"}, {"text": "这间房子早来了一个月。", "explanation": "这里应该用〈装修好〉。早来只用于能来到此处的人或事物，房子不会来，这句把“来”的主语用错了。"}, {"text": "这棵树早来了一个月。", "explanation": "这里应该用〈早开花〉。早来只用于能来到此处的人或事物，树不会来，这句把“来”的主语用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87282, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天都早来了，帮大家开门。", "corrected_sentence": "他每天都早来，帮大家开门。", "error_description": "“每天都”表示习惯性动作，与表示完成的“了”不相容，句中不能用“了”。错误形式：“他每天都早来了”；正确形式：“他每天都早来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87282, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他明天要早来了半小时。", "corrected_sentence": "他明天要早来半小时。", "error_description": "“明天要”表示将来，还没有发生，不能在“早来”后加表示完成的“了”。错误形式：“明天要早来了半小时”；正确形式：“明天要早来半小时”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2148ebc6-1f27-460e-91d3-06a14eeef028') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
