INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87284, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "全程马拉松的简称，全程约四十二点一九五公里。", "primary_collocate": null, "pronunciation": "quán mǎ", "ipa": "tɕʰɥɛn˧˥ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "全马一共四十二点一九五公里。", "target_word": "全马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天用四小时跑了全马。", "target_word": "全马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半马是全马的一半。", "target_word": "全马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全马的路线经过老城区。", "target_word": "全马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报名全马的人有两万多个。", "target_word": "全马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全马的起点在市中心。", "target_word": "全马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想跑全马，目标是跑进四小时。", "target_word": "全马", "complexity_tier": "T3", "furigana": "tā xiǎng pǎo quán mǎ, mù biāo shì pǎo jìn sì xiǎo shí.", "sentence_source": "generated"}, {"text": "今年的全马，天气特别好。", "target_word": "全马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全马选手都要穿号码布。", "target_word": "全马", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑全马的人，要先好好练习。", "target_word": "全马", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场全马", "label": "量词（场）"}, {"form": "全馬", "label": "繁体"}], "register": "口语", "sense_fingerprint": "全程马拉松的简称，全程四十二点一九五公里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '157552df-a86f-4558-b9ec-500c2d87da0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87284, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "半马", "is_correct": false, "explanation": "语义：半马全程约二十一公里，与“四十二点一九五公里”不符。"}, {"text": "全马", "is_correct": true, "explanation": "正确。全马指全程马拉松，全程约四十二点一九五公里，与句中的数字相合。"}, {"text": "短跑", "is_correct": false, "explanation": "语义：短跑的距离很短，不可能一共四十二点一九五公里。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：咖啡没有距离，不与“公里”搭配。"}], "explanations": {"半马": "语义：半马全程约二十一公里，与“四十二点一九五公里”不符。", "全马": "正确。全马指全程马拉松，全程约四十二点一九五公里，与句中的数字相合。", "短跑": "语义：短跑的距离很短，不可能一共四十二点一九五公里。", "咖啡": "搭配：咖啡没有距离，不与“公里”搭配。"}, "sentence_index": 0, "correct_answer": "全马"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶在厨房里做了一份全马。", "explanation": "这里把〈全马〉当成了食物。全马指比赛，不是菜，不能用“做了一份”来表示做的菜。"}, {"text": "这次旅行全马都很顺利。", "explanation": "这里应该用〈全程〉。全马特指马拉松比赛，不能用来指整段旅程。"}, {"text": "农场里的全马都很健壮。", "explanation": "这里把〈全马〉当成了马。全马指比赛，不指动物，所以不能说“农场里的全马”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87284, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "电影", "is_correct": false, "explanation": "搭配：“跑”不与“电影”搭配，句意不通。"}, {"text": "全马", "is_correct": true, "explanation": "正确。全马是一场跑完全程的马拉松比赛，与“跑进四小时”的目标相合。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是疾病，不能被“跑”，句意不通。"}, {"text": "数学", "is_correct": false, "explanation": "语义：“数学”是学科，不能用“跑”来说，句意不通。"}], "explanations": {"电影": "搭配：“跑”不与“电影”搭配，句意不通。", "全马": "正确。全马是一场跑完全程的马拉松比赛，与“跑进四小时”的目标相合。", "感冒": "语义：“感冒”是疾病，不能被“跑”，句意不通。", "数学": "语义：“数学”是学科，不能用“跑”来说，句意不通。"}, "sentence_index": 6, "correct_answer": "全马"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我表弟就是全马，跑得很快。", "explanation": "这里把〈全马〉当成了人。全马指比赛，不指人，应说“跑全马的人”。"}, {"text": "我们全马一起去吃饭。", "explanation": "这里应该用〈全家〉。全马指比赛，不能指一家人。"}, {"text": "我用全马的时间打扫了房间。", "explanation": "这里把〈全马〉当成了一段时间。全马是比赛名称，不能表示时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年参加了一只全马，成绩很好。", "corrected_sentence": "他去年参加了一场全马，成绩很好。", "error_description": "错误：“一只”的量词“只”用于动物或小物件，全马是比赛，应改为“一场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐跑着全马，很厉害。", "corrected_sentence": "我姐姐跑过全马，很厉害。", "error_description": "错误：“全马”是一次完成的比赛，表示跑完的经历要用“过”，不能用“着”表示持续，应说“跑过全马”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cb825-c0b4-48bd-9283-9eddacabb02e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
