INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87285, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "那样是指那个样子，不是这个样子。", "primary_collocate": null, "pronunciation": "nà yàng", "ipa": "na˥˩ jɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他不是你说的那样。", "target_word": "那样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你别那样。", "target_word": "那样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我也想变得像他那样。", "target_word": "那样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那样的事情，我不想再做了。", "target_word": "那样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不喜欢那样的工作。", "target_word": "那样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你不要那样，他会难过的。", "target_word": "那样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事情就是那样，没有别的原因。", "target_word": "那样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我小时候就是那样。", "target_word": "那样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是那样，什么事都不在乎。", "target_word": "那样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈不让我那样。", "target_word": "那样", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "那樣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "代词；指那个样子、那种情况，可单独作宾语或说“像那样”“那样的”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f0f3827-7eef-4040-8225-662f43c0b4c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87285, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "那样", "is_correct": true, "explanation": "指“你说的那个样子”，回指上文所说的情况，正确。"}, {"text": "怎样", "is_correct": false, "explanation": "语义：“怎样”是疑问代词，用来问方式，不能指代已经说出的样子，与“不是”后面的陈述不合。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”指人，不能指代“你说的样子”。"}, {"text": "怎么样", "is_correct": false, "explanation": "搭配：“不是你说的怎么样”缺少所指内容，“怎么样”是疑问结构，不能在“不是……的”后充当宾语。"}], "explanations": {"那样": "指“你说的那个样子”，回指上文所说的情况，正确。", "怎样": "语义：“怎样”是疑问代词，用来问方式，不能指代已经说出的样子，与“不是”后面的陈述不合。", "谁": "语义：“谁”指人，不能指代“你说的样子”。", "怎么样": "搭配：“不是你说的怎么样”缺少所指内容，“怎么样”是疑问结构，不能在“不是……的”后充当宾语。"}, "sentence_index": 0, "correct_answer": "那样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那样的话，我们明天再去吧。", "explanation": "这里的“那样的话”是承接用法，表示“在那种情况下”，属于另一义项，不指示“那个样子”，与本词用法不同。"}, {"text": "我今天走了那样远的路，腿都酸了。", "explanation": "这里的“那样”是程度用法，修饰“远”的程度，属于另一义项，指程度而非“那个样子”，与本词用法不同。"}, {"text": "这首歌那样动听，我听了好几遍。", "explanation": "这里的“那样”是程度用法，修饰形容词“动听”，属于另一义项，不指代“那个样子”，与本词用法不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87285, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那样", "is_correct": true, "explanation": "指上文所说的情形，与“就是”搭配，正确。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”是疑问代词，“事情就是什么”无所指，句意不成立。"}, {"text": "那里", "is_correct": false, "explanation": "配价：“就是”后需要状态或样子，“那里”是处所词，不能充当这一成分。"}, {"text": "哪个", "is_correct": false, "explanation": "语义：“哪个”用于询问具体事物，与“就是”后的概括性陈述不合。"}], "explanations": {"那样": "指上文所说的情形，与“就是”搭配，正确。", "什么": "语义：“什么”是疑问代词，“事情就是什么”无所指，句意不成立。", "那里": "配价：“就是”后需要状态或样子，“那里”是处所词，不能充当这一成分。", "哪个": "语义：“哪个”用于询问具体事物，与“就是”后的概括性陈述不合。"}, "sentence_index": 6, "correct_answer": "那样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "月亮那样圆，照得院子里发亮。", "explanation": "这里的“那样”是程度用法，修饰形容词“圆”，属于另一义项，不指代“那个样子”，与本词用法不同。"}, {"text": "他那样喜欢音乐，我们都很佩服。", "explanation": "这里的“那样”是程度副词，修饰动词“喜欢”的程度，属于另一义项，与本词指代“那个样子”的用法不同。"}, {"text": "这间屋子那样安静，我很快就睡着了。", "explanation": "这里的“那样”是程度用法，修饰形容词“安静”，属于另一义项，与本词指代“那个样子”的用法不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87285, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不是你想的那样那样。", "corrected_sentence": "他不是你想的那样。", "error_description": "错误形式：“他不是你想的那样那样”；正确形式：“他不是你想的那样”。多写了一个“那样”，重复使用，句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87285, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我最讨厌那样人。", "corrected_sentence": "我最讨厌那样的人。", "error_description": "错误形式：“那样人”；正确形式：“那样的人”。“那样”修饰名词时须加“的”，漏掉“的”，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
