INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87286, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指示代词，指较远的性质、状态或方式。", "primary_collocate": null, "pronunciation": "nà yàng", "ipa": "na˥˩ jɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他跑得那样快，我追不上。", "target_word": "那样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那座山那样高，我爬不上去。", "target_word": "那样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你为什么那样生气？", "target_word": "那样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她唱歌那样好听，大家都喜欢。", "target_word": "那样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没想到事情会那样难。", "target_word": "那样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他那样努力，一定能成功。", "target_word": "那样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "湖水那样蓝，像一块玻璃。", "target_word": "那样", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师那样热情地帮助我们。", "target_word": "那样", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这间屋子那样安静，我很快就睡着了。", "target_word": "那样", "complexity_tier": "T3", "furigana": "zhè jiān wū zi nà yàng ān jìng wǒ hěn kuài jiù shuì zháo le", "sentence_source": "generated"}, {"text": "他说得那样清楚，大家都听懂了。", "target_word": "那样", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "那樣", "label": "繁体"}], "register": "中性", "sense_fingerprint": "指示代词；放在形容词或动词前，指较远事物的程度、状态或方式，如那样快、那样努力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f0f3827-7eef-4040-8225-662f43c0b4c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87286, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "那样", "is_correct": true, "explanation": "表示“跑得那么快”的程度，修饰形容词“快”，正确。"}, {"text": "怎么", "is_correct": false, "explanation": "语义：“怎么”是疑问副词，询问方式或原因，不表示程度陈述，“跑得怎么快”句意不成立。"}, {"text": "却", "is_correct": false, "explanation": "搭配：“却”表示转折，不能修饰“快”表达程度，“跑得却快”不成立。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”表示限定范围，不表示程度，“跑得只快”不能表达句中的意思。"}], "explanations": {"那样": "表示“跑得那么快”的程度，修饰形容词“快”，正确。", "怎么": "语义：“怎么”是疑问副词，询问方式或原因，不表示程度陈述，“跑得怎么快”句意不成立。", "却": "搭配：“却”表示转折，不能修饰“快”表达程度，“跑得却快”不成立。", "只": "搭配：“只”表示限定范围，不表示程度，“跑得只快”不能表达句中的意思。"}, "sentence_index": 0, "correct_answer": "那样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那样的话，我们明天再去吧。", "explanation": "这里的“那样的话”是承接用法，表示“在那种情况下”，属于另一义项，不指示性质、状态或方式，与本词用法不同。"}, {"text": "你别那样，大家都在看你。", "explanation": "这里的“那样”单独作宾语，指代某种行为样子，属于另一义项，不修饰形容词或动词表示程度、方式，与本词用法不同。"}, {"text": "那样一来，事情就简单多了。", "explanation": "这里的“那样一来”是承接用法，表示“这样一来”的推论，属于另一义项，不指示性质、状态或方式，与本词用法不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87286, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "那样", "is_correct": true, "explanation": "表示“湖水那么蓝”的程度，修饰形容词“蓝”，正确。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”是疑问代词，不表示程度，“湖水什么蓝”句意不成立。"}, {"text": "哪里", "is_correct": false, "explanation": "语义：“哪里”指地点或疑问，不能修饰形容词表程度。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”指人，不能修饰形容词“蓝”，句意不成立。"}], "explanations": {"那样": "表示“湖水那么蓝”的程度，修饰形容词“蓝”，正确。", "什么": "语义：“什么”是疑问代词，不表示程度，“湖水什么蓝”句意不成立。", "哪里": "语义：“哪里”指地点或疑问，不能修饰形容词表程度。", "谁": "语义：“谁”指人，不能修饰形容词“蓝”，句意不成立。"}, "sentence_index": 6, "correct_answer": "那样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那样看来，他今天不会来了。", "explanation": "这里的“那样看来”是推断用法，表示“据那种情况看”，属于另一义项，不指示性质、状态或方式，与本词用法不同。"}, {"text": "那样说来，这件事就好办了。", "explanation": "这里的“那样说来”是承接用法，表示“照那样说”，属于另一义项，与本词指代性质、状态或方式的用法不同。"}, {"text": "我小时候也是那样。", "explanation": "这里的“那样”单独作谓语成分，指代“那个样子”，属于另一义项，不修饰形容词或动词表示程度、方式，与本词用法不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87286, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她说那样流利，大家都很佩服。", "corrected_sentence": "她说得那样流利，大家都很佩服。", "error_description": "错误形式：“说那样流利”；正确形式：“说得那样流利”。“那样流利”作补语，须用“得”引出，漏掉“得”，句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87286, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路那样得长，走起来很累。", "corrected_sentence": "这条路那样长，走起来很累。", "error_description": "错误形式：“那样得长”；正确形式：“那样长”。“那样长”直接作谓语，“那样”后不能加结构助词“得”，加了“得”句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
