INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87287, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "晓得是知道，明白。", "primary_collocate": null, "pronunciation": "xiǎo de", "ipa": "ɕjaʊ˨˩˦ tɤ", "syllable_count": 2, "sentences": [{"text": "他不晓得怎么走，所以问了人。", "target_word": "晓得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你晓得我为什么生气吗？", "target_word": "晓得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我晓得了，谢谢你告诉我。", "target_word": "晓得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事只有他晓得真相。", "target_word": "晓得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她晓得自己错了，一直在哭。", "target_word": "晓得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你晓得这个字怎么读吗？", "target_word": "晓得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他晓得天要下雨，就带了伞。", "target_word": "晓得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不晓得这家店今天开不开门。", "target_word": "晓得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子大了，自然晓得好坏。", "target_word": "晓得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁晓得他明天会不会来？", "target_word": "晓得", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不晓得", "label": "否定"}, {"form": "晓得了", "label": "体标"}, {"form": "晓不晓得", "label": "正反问"}], "register": "口语", "sense_fingerprint": "知道、明白（口语，表示对情况或原因有所了解）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83c1835b-777f-4252-a671-77d7f731f642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87287, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晓得", "is_correct": true, "explanation": "正确：“不晓得怎么走”表示不知道走的方法，句意通顺。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”不能带“怎么走”这样的小句，句子说不通。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”的对象是具体的东西，不能接表示方法的小句。"}, {"text": "脱", "is_correct": false, "explanation": "配价：“脱”是及物动词，宾语应是衣物，不能接小句。"}], "explanations": {"晓得": "正确：“不晓得怎么走”表示不知道走的方法，句意通顺。", "喝": "语义：“喝”不能带“怎么走”这样的小句，句子说不通。", "扔": "语义：“扔”的对象是具体的东西，不能接表示方法的小句。", "脱": "配价：“脱”是及物动词，宾语应是衣物，不能接小句。"}, "sentence_index": 0, "correct_answer": "晓得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈晓得了一锅粥。", "explanation": "这里应该用〈煮〉。晓得不能接具体的食物作宾语，只表示知道某件事。"}, {"text": "他晓得了一个拥抱。", "explanation": "这里应该用〈给〉。晓得表示知道，不能与“拥抱”这种动作搭配；表示给人拥抱要说〈给〉。"}, {"text": "他晓得了一场大雨。", "explanation": "这里应该用〈下〉。晓得不能与“大雨”这类天气搭配；表示下雨要说〈下〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87287, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晓得", "is_correct": true, "explanation": "正确：晓得表示知道，句子是说他知道要下雨，所以带了伞。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”不能带“天要下雨”这样的小句作宾语，句子说不通。"}, {"text": "种", "is_correct": false, "explanation": "语义：“种”的对象是植物，不能接表示事情的小句。"}, {"text": "跳", "is_correct": false, "explanation": "配价：“跳”是不及物动词，不能带小句作宾语。"}], "explanations": {"晓得": "正确：晓得表示知道，句子是说他知道要下雨，所以带了伞。", "写": "语义：“写”不能带“天要下雨”这样的小句作宾语，句子说不通。", "种": "语义：“种”的对象是植物，不能接表示事情的小句。", "跳": "配价：“跳”是不及物动词，不能带小句作宾语。"}, "sentence_index": 6, "correct_answer": "晓得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他晓得了一把伞。", "explanation": "这里应该用〈撑〉。晓得表示知道，不能接具体的物品作宾语；撑伞要说〈撑〉。"}, {"text": "他晓得了一个篮球。", "explanation": "这里应该用〈买〉。晓得表示知道，不能接球类器材作宾语；“买一个篮球”才自然。"}, {"text": "他晓得了一跤。", "explanation": "这里应该用〈摔〉。晓得表示知道，不能接表示跌倒的“一跤”，摔倒要用〈摔〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87287, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他晓得着这件事了。", "corrected_sentence": "他晓得这件事了。", "error_description": "体标误用：“晓得”表示状态，不能加“着”，应去掉“着”，说“他晓得这件事了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87287, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不晓得过他今天来不来。", "corrected_sentence": "我不晓得他今天来不来。", "error_description": "体标误用：“不晓得”表示现在不知道，不能加经历体“过”，应去掉“过”，说“我不晓得他今天来不来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
