INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87288, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "知道；懂得。", "primary_collocate": null, "pronunciation": "xiǎo de", "ipa": "ɕjaʊ˨˩˦ tɤ", "syllable_count": 2, "sentences": [{"text": "我不晓得他住在哪里。", "target_word": "晓得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你晓得明天几点开会吗？", "target_word": "晓得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩子还不晓得钱有多重要。", "target_word": "晓得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他早就晓得这件事了。", "target_word": "晓得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈晓得我今天考试，一早就叫我起床。", "target_word": "晓得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个道理，谁都晓得。", "target_word": "晓得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你晓得怎么坐地铁去机场吗？", "target_word": "晓得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我晓得你很忙，所以没有打电话。", "target_word": "晓得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做错了事，自己心里晓得。", "target_word": "晓得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我，我说我不晓得答案。", "target_word": "晓得", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不晓得", "label": "否定"}, {"form": "晓得了", "label": "体标"}, {"form": "晓不晓得", "label": "正反问"}], "register": "口语", "sense_fingerprint": "知道、懂得（口语，表示了解某事或某个道理）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83c1835b-777f-4252-a671-77d7f731f642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87288, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "晓得", "is_correct": true, "explanation": "正确：晓得表示知道，句子说的是“不知道他住在哪里”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能带“他住在哪里”这样的小句作宾语，句子说不通。"}, {"text": "搬", "is_correct": false, "explanation": "配价：“搬”的宾语应是具体的东西，不能接整个小句。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象是衣物等，不能接表示地点的小句。"}], "explanations": {"晓得": "正确：晓得表示知道，句子说的是“不知道他住在哪里”。", "吃": "语义：“吃”不能带“他住在哪里”这样的小句作宾语，句子说不通。", "搬": "配价：“搬”的宾语应是具体的东西，不能接整个小句。", "洗": "语义：“洗”的对象是衣物等，不能接表示地点的小句。"}, "sentence_index": 0, "correct_answer": "晓得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他晓得了一个苹果。", "explanation": "这里应该用〈买〉。晓得表示知道某件事或某个道理，不能接具体的东西作宾语。"}, {"text": "他晓得了三遍这本书。", "explanation": "这里应该用〈读〉。晓得只表示知道，不能与“三遍”这样的次数搭配。"}, {"text": "他晓得了一双鞋。", "explanation": "这里应该用〈穿〉。晓得表示知道，不能接鞋子这类可穿戴物作宾语；穿鞋要说〈穿〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87288, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "晓得", "is_correct": true, "explanation": "正确：晓得后接“怎么坐地铁”，表示知道方法，句子通顺。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能带“怎么坐地铁”这样的小句作宾语，句子说不通。"}, {"text": "摘", "is_correct": false, "explanation": "语义：“摘”的对象是植物或果实，不能接表示方法的小句。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”是不及物动词，不能带小句作宾语。"}], "explanations": {"晓得": "正确：晓得后接“怎么坐地铁”，表示知道方法，句子通顺。", "唱": "语义：“唱”不能带“怎么坐地铁”这样的小句作宾语，句子说不通。", "摘": "语义：“摘”的对象是植物或果实，不能接表示方法的小句。", "跑": "配价：“跑”是不及物动词，不能带小句作宾语。"}, "sentence_index": 6, "correct_answer": "晓得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他晓得了一碗饭。", "explanation": "这里应该用〈吃〉。晓得表示知道，不能接食物作宾语；吃东西要说〈吃〉。"}, {"text": "他晓得了一根跳绳。", "explanation": "这里应该用〈买〉。晓得表示知道，不能接运动器材作宾语；“买一根跳绳”才自然。"}, {"text": "他晓得了一杯牛奶。", "explanation": "这里应该用〈喝〉。晓得表示知道，不能接饮品作宾语；喝牛奶要说〈喝〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87288, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我早就晓得着这件事了。", "corrected_sentence": "我早就晓得这件事了。", "error_description": "体标误用：“晓得”表示状态，不能加“着”，应去掉“着”，说“我早就晓得这件事了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87288, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我正在晓得这件事。", "corrected_sentence": "我晓得这件事。", "error_description": "“晓得”表示状态，不能用“正在”表示进行，应删去“正在”，说“我晓得这件事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
