INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87289, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87289, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "其间是在那段时间里面。", "primary_collocate": null, "pronunciation": "qí jiān", "ipa": "tɕʰi˧˥ tɕiɛn˥", "syllable_count": 2, "sentences": [{"text": "他去年在北京学习了三个月，其间认识了很多朋友。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我生病住院一周，其间朋友常来看我。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在上海工作了三年，其间只回过两次家。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛一共三天，其间天天下雨。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暑假我在奶奶家住了一个月，其间学会了做饭。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈出差十天，其间爸爸照顾我。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司装修了两周，其间我们在家工作。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在中国工作了五年，其间一直住在同一个地方。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节放假七天，其间商店都关门了。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们结婚三年，其间搬了两次家。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "指前面所说的那段时间之内", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba8f283-b84f-405a-98d3-c66977be6fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87289, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "旗舰", "is_correct": false, "explanation": "旗舰 qí jiàn 与 其间 qí jiān 只有第二个音节的声调不同（jiàn 第四声，jiān 第一声），意思是同类产品中最好的一个。"}, {"text": "器件", "is_correct": false, "explanation": "器件 qì jiàn 与 其间 qí jiān 两个音节的声调都不同，意思是电子元件之类的零件。"}, {"text": "其间", "is_correct": true, "explanation": "其间 qí jiān 即正确答案，指前面所说的那段时间之内。"}, {"text": "席间", "is_correct": false, "explanation": "席间 xí jiān 与 其间 qí jiān 只有声母不同（x 与 q），声调相同，意思是宴席进行的过程之中。"}, {"text": "起见", "is_correct": false, "explanation": "起见 qǐ jiàn 与 其间 qí jiān 两个音节的声调都不同，意思是“为了……考虑”（如“为安全起见”）。"}], "explanations": {"旗舰": "旗舰 qí jiàn 与 其间 qí jiān 只有第二个音节的声调不同（jiàn 第四声，jiān 第一声），意思是同类产品中最好的一个。", "器件": "器件 qì jiàn 与 其间 qí jiān 两个音节的声调都不同，意思是电子元件之类的零件。", "其间": "其间 qí jiān 即正确答案，指前面所说的那段时间之内。", "席间": "席间 xí jiān 与 其间 qí jiān 只有声母不同（x 与 q），声调相同，意思是宴席进行的过程之中。", "起见": "起见 qǐ jiàn 与 其间 qí jiān 两个音节的声调都不同，意思是“为了……考虑”（如“为安全起见”）。"}, "sentence_index": null, "correct_answer": "其间"}, "level_3": {"options": [{"text": "房间", "is_correct": false, "explanation": "配价：“认识”要求人作主语，“房间”是地点，不能作“认识”的主语。"}, {"text": "行李", "is_correct": false, "explanation": "语义：“行李”是物品，不会“认识很多朋友”。"}, {"text": "其间", "is_correct": true, "explanation": "正确。其间指前面所说的那段时间之内，这里指三个月的学习期间。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”是交通工具，不会“认识很多朋友”，句子不通。"}], "explanations": {"房间": "配价：“认识”要求人作主语，“房间”是地点，不能作“认识”的主语。", "行李": "语义：“行李”是物品，不会“认识很多朋友”。", "其间": "正确。其间指前面所说的那段时间之内，这里指三个月的学习期间。", "汽车": "语义：“汽车”是交通工具，不会“认识很多朋友”，句子不通。"}, "sentence_index": 0, "correct_answer": "其间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一出门其间就下雨了。", "explanation": "这里应该用〈那时〉，指某一个时刻。“其间”指一段时间之内，不能用来指“出门”这样的时间点。"}, {"text": "我们吃完饭其间去散步。", "explanation": "这里应该用〈之后〉，表示一件事完成以后。“其间”指前面提到的那段时间之内，不能用来指某个动作完成的先后。"}, {"text": "我下班其间吃了晚饭。", "explanation": "这里应该用〈以后〉，表示下班之后才吃饭。“其间”指一段时间之内，不能用来限定“下班”这样的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87289, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工地", "is_correct": false, "explanation": "语义：“工地”是地点，不是时间，不能作“我们在家工作”的时间状语。"}, {"text": "其间", "is_correct": true, "explanation": "正确。前文说公司装修了两周，其间指这两周之内。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是物品，不能表示一段时间，句子不通。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：“饭菜”是食物，不能表示时间，句子不通。"}], "explanations": {"工地": "语义：“工地”是地点，不是时间，不能作“我们在家工作”的时间状语。", "其间": "正确。前文说公司装修了两周，其间指这两周之内。", "钥匙": "语义：“钥匙”是物品，不能表示一段时间，句子不通。", "饭菜": "语义：“饭菜”是食物，不能表示时间，句子不通。"}, "sentence_index": 6, "correct_answer": "其间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "出发其间要检查一遍行李。", "explanation": "这里应该用〈之前〉，表示在出发这个时间点之前。“其间”要指一段持续的时间，“出发”是一个时间点，不能用“其间”。"}, {"text": "我到机场其间很紧张。", "explanation": "这里应该用〈当时〉，指说话所指的那个时候。“其间”要指一段持续的时间，“到机场”是一个动作，不能用“其间”来限定。"}, {"text": "他下午三点其间去了超市。", "explanation": "这里应该用〈当时〉，指某一个时刻。“其间”指一段时间之内，“下午三点”是时间点，不能用“其间”来限定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87289, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在上海工作了两年，其间了换过三次工作。", "corrected_sentence": "我在上海工作了两年，其间换过三次工作。", "error_description": "“了”不能放在时间名词“其间”之后，应删去，说“其间换过三次工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87289, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在广州住了四年，其间的换过两次房子。", "corrected_sentence": "我在广州住了四年，其间换过两次房子。", "error_description": "“的”后接的是动词短语“换过两次房子”，没有中心语，构成不完整的修饰成分，句子不通；应去掉“的”，说“其间换过两次房子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
