INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在前面所说的那些事物之中，相当于“其中”。", "primary_collocate": null, "pronunciation": "qí jiān", "ipa": "tɕʰi˧˥ tɕiɛn˥", "syllable_count": 2, "sentences": [{"text": "山上长满了树，其间有一条小路。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架上放着很多书，其间夹着一张旧照片。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖边有几座小房子，其间种着很多花。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老城区有很多小街，其间开着几家老茶馆。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草地上开满了小花，其间飞着几只蝴蝶。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边有几块大石头，其间长着一些小草。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片竹林很密，其间有一个小水池。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盘子里放着几块饼干，其间夹着一张小纸条。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广场上站满了人，其间有几个小孩在跑来跑去。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "院子里种了几棵树，其间放着一张石桌。", "target_word": "其间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "指前面所说的那个范围之内，相当于其中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ba8f283-b84f-405a-98d3-c66977be6fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87290, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "旗舰", "is_correct": false, "explanation": "旗舰 qí jiàn 与 其间 qí jiān 只有第二个音节的声调不同（jiàn 第四声，jiān 第一声），意思是同类产品中最好的一个。"}, {"text": "器件", "is_correct": false, "explanation": "器件 qì jiàn 与 其间 qí jiān 两个音节的声调都不同，意思是电子元件之类的零件。"}, {"text": "其间", "is_correct": true, "explanation": "其间 qí jiān 即正确答案，指前面所说的那个范围之内。"}, {"text": "席间", "is_correct": false, "explanation": "席间 xí jiān 与 其间 qí jiān 只有声母不同（x 与 q），声调相同，意思是宴席进行的过程之中。"}, {"text": "起见", "is_correct": false, "explanation": "起见 qǐ jiàn 与 其间 qí jiān 两个音节的声调都不同，意思是“为了……考虑”（如“为安全起见”）。"}], "explanations": {"旗舰": "旗舰 qí jiàn 与 其间 qí jiān 只有第二个音节的声调不同（jiàn 第四声，jiān 第一声），意思是同类产品中最好的一个。", "器件": "器件 qì jiàn 与 其间 qí jiān 两个音节的声调都不同，意思是电子元件之类的零件。", "其间": "其间 qí jiān 即正确答案，指前面所说的那个范围之内。", "席间": "席间 xí jiān 与 其间 qí jiān 只有声母不同（x 与 q），声调相同，意思是宴席进行的过程之中。", "起见": "起见 qǐ jiàn 与 其间 qí jiān 两个音节的声调都不同，意思是“为了……考虑”（如“为安全起见”）。"}, "sentence_index": null, "correct_answer": "其间"}, "level_3": {"options": [{"text": "房间", "is_correct": false, "explanation": "语义：“房间”是室内的空间，与“山上长满了树”的场景不符。"}, {"text": "时间", "is_correct": false, "explanation": "配价：“有”要求一个空间作存在的处所，“时间”不能充当处所。"}, {"text": "其间", "is_correct": true, "explanation": "正确。其间指前面所说的那片树林之中，这里指树丛之中有一条小路。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“大海”与“山上长满了树”的场景矛盾，不会有一条小路。"}], "explanations": {"房间": "语义：“房间”是室内的空间，与“山上长满了树”的场景不符。", "时间": "配价：“有”要求一个空间作存在的处所，“时间”不能充当处所。", "其间": "正确。其间指前面所说的那片树林之中，这里指树丛之中有一条小路。", "大海": "语义：“大海”与“山上长满了树”的场景矛盾，不会有一条小路。"}, "sentence_index": 0, "correct_answer": "其间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他其间站着一个人。", "explanation": "这里应该用〈旁边〉，指靠近某人的位置。“其间”需要一群事物作范围，“他”只是单个人，不能作其间的范围。"}, {"text": "那只猫其间趴着一只狗。", "explanation": "这里应该用〈身上〉，指附着在物体表面。“其间”需要一群事物作范围，“那只猫”是单个动物，不能用于此。"}, {"text": "我和弟弟其间有一个小秘密。", "explanation": "这里应该用〈之间〉，表示两者之间的关系。“其间”指一群事物之中的一部分，不用于两个人之间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是空间，不能说“时间有一个小水池”。"}, {"text": "其间", "is_correct": true, "explanation": "正确。其间指前面所说的竹林之中，这里指竹林里有一个小水池。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是处所，不能作存在的地方，句子不通。"}, {"text": "答案", "is_correct": false, "explanation": "语义：“答案”与竹林的场景无关，不能表示处所。"}], "explanations": {"时间": "语义：“时间”不是空间，不能说“时间有一个小水池”。", "其间": "正确。其间指前面所说的竹林之中，这里指竹林里有一个小水池。", "声音": "语义：“声音”不是处所，不能作存在的地方，句子不通。", "答案": "语义：“答案”与竹林的场景无关，不能表示处所。"}, "sentence_index": 6, "correct_answer": "其间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个孩子其间站着一位老师。", "explanation": "这里应该用〈身边〉，指靠近某人的位置。“其间”需要一群事物作范围，“那个孩子”是单个人，不能作其间的范围。"}, {"text": "那位老师其间拿着几本书。", "explanation": "这里应该用〈手里〉，指拿着东西的位置。“其间”需要一群事物作范围，“那位老师”是单个人，不能用于此。"}, {"text": "我的车其间停着一辆自行车。", "explanation": "这里应该用〈旁边〉，指靠近某处的位置。“其间”需要一群事物作范围，“我的车”是单个物体，不能作其间的范围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "衣柜里挂着几件外套，其间里有一件是新买的。", "corrected_sentence": "衣柜里挂着几件外套，其间有一件是新买的。", "error_description": "“其间”本身已含“之中”的意思，后面不能再加“里”；应删去“里”，说“其间有一件是新买的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厨房的柜子里放着几瓶酱油，其间中有一瓶已经过期了。", "corrected_sentence": "厨房的柜子里放着几瓶酱油，其间有一瓶已经过期了。", "error_description": "“其间”本身已含“之中”的意思，后面不能再加“中”；应说“其间有一瓶已经过期了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca19d34d-6d23-406d-8b4e-7c32212bc9ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
