INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87293, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "部是数书、电影这些东西的词。", "primary_collocate": null, "pronunciation": "bù", "ipa": "pu˥˩", "syllable_count": 1, "sentences": [{"text": "我昨天看了一部电影。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影很好看。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一部很长的小说。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一部词典。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹最喜欢这部动画片。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影我看过三次。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部小说讲的是一个小男孩的故事。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看过那部电影吗？", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拍了一部关于家乡的电影。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷有一部老字典，用了很多年。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用来数书、电影的量词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01ececac-152b-4004-ac0a-24281145fd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87293, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "部", "is_correct": true, "explanation": "部 bù（第四声），用于书、电影等作品的量词。"}, {"text": "补", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，意思是补充。"}, {"text": "铺", "is_correct": false, "explanation": "pù 与 bù 声母不同（p 与 b），意思是店铺。"}, {"text": "木", "is_correct": false, "explanation": "mù 与 bù 声母不同（m 与 b），意思是木头。"}], "explanations": {"部": "部 bù（第四声），用于书、电影等作品的量词。", "补": "bǔ（第三声）与 bù（第四声）声调不同，意思是补充。", "铺": "pù 与 bù 声母不同（p 与 b），意思是店铺。", "木": "mù 与 bù 声母不同（m 与 b），意思是木头。"}, "sentence_index": null, "correct_answer": "部"}, "level_3": {"options": [{"text": "部", "is_correct": true, "explanation": "部用于书、电影这类作品，「我昨天看了一部电影」正确。"}, {"text": "台", "is_correct": false, "explanation": "语义：台用于机器、设备，电影不是机器或设备。"}, {"text": "篇", "is_correct": false, "explanation": "语义：篇用于文章等文字作品，电影不是文字作品。"}, {"text": "张", "is_correct": false, "explanation": "搭配：张多用于平面、纸张类的东西，不说「一张电影」。"}], "explanations": {"部": "部用于书、电影这类作品，「我昨天看了一部电影」正确。", "台": "语义：台用于机器、设备，电影不是机器或设备。", "篇": "语义：篇用于文章等文字作品，电影不是文字作品。", "张": "搭配：张多用于平面、纸张类的东西，不说「一张电影」。"}, "sentence_index": 0, "correct_answer": "部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一部伞。", "explanation": "这里应该用〈把〉。部用于书、电影这类作品，伞是有柄的东西，要用〈把〉。"}, {"text": "我买了一部苹果。", "explanation": "这里应该用〈个〉。部不用于水果，苹果要用〈个〉。"}, {"text": "客厅里放着一部沙发。", "explanation": "这里应该用〈张〉。部不用于家具，沙发要用〈张〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87293, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "部", "is_correct": true, "explanation": "部 bù（第四声），用于书、电影等作品的量词。"}, {"text": "捕", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，意思是抓捕。"}, {"text": "目", "is_correct": false, "explanation": "mù 与 bù 声母不同（m 与 b），意思是眼睛。"}, {"text": "付", "is_correct": false, "explanation": "fù 与 bù 声母不同（f 与 b），意思是付款。"}], "explanations": {"部": "部 bù（第四声），用于书、电影等作品的量词。", "捕": "bǔ（第三声）与 bù（第四声）声调不同，意思是抓捕。", "目": "mù 与 bù 声母不同（m 与 b），意思是眼睛。", "付": "fù 与 bù 声母不同（f 与 b），意思是付款。"}, "sentence_index": null, "correct_answer": "部"}, "level_3": {"options": [{"text": "部", "is_correct": true, "explanation": "部用于书、电影这类作品，「这部小说」正确。"}, {"text": "首", "is_correct": false, "explanation": "语义：首用于诗歌、歌曲，小说不是诗歌或歌曲。"}, {"text": "支", "is_correct": false, "explanation": "搭配：支多用于杆状物或队伍，不说「这支小说」。"}, {"text": "幅", "is_correct": false, "explanation": "语义：幅用于画作、布匹，小说不是画作。"}], "explanations": {"部": "部用于书、电影这类作品，「这部小说」正确。", "首": "语义：首用于诗歌、歌曲，小说不是诗歌或歌曲。", "支": "搭配：支多用于杆状物或队伍，不说「这支小说」。", "幅": "语义：幅用于画作、布匹，小说不是画作。"}, "sentence_index": 6, "correct_answer": "部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她买了一部鞋。", "explanation": "这里应该用〈双〉。部用于书、电影这类作品，鞋成双计算，要用〈双〉。"}, {"text": "他穿了一部衣服。", "explanation": "这里应该用〈件〉。部不用于衣物，衣服要用〈件〉。"}, {"text": "农场里有一部牛。", "explanation": "这里应该用〈头〉。部不用于牲畜，牛要用〈头〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87293, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天买了一部新衣服。", "corrected_sentence": "我昨天买了一件新衣服。", "error_description": "量词错误：衣服的量词应用「件」，不能用「部」；「部」用于书、电影等作品，应说「一件新衣服」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
