INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87294, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于手机、电话、电梯、电视剧、机器等。", "primary_collocate": null, "pronunciation": "bù", "ipa": "pu˥˩", "syllable_count": 1, "sentences": [{"text": "我新买了一部手机。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室里有两部电话。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电梯坏了。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电视剧一共有四十集。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一部旧相机拍了很多照片。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部机器可以自己工作。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用一部新手机给妈妈打电话。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家客厅里有一部电话。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这部手机给我。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大楼里新装了一部电梯。", "target_word": "部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用于手机、电话、电视剧、机器等的量词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01ececac-152b-4004-ac0a-24281145fd2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87294, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "部", "is_correct": true, "explanation": "部 bù（第四声），用于手机、电视剧、机器等的量词。"}, {"text": "补", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，意思是补充。"}, {"text": "铺", "is_correct": false, "explanation": "pù 与 bù 声母不同（p 与 b），意思是店铺。"}, {"text": "木", "is_correct": false, "explanation": "mù 与 bù 声母不同（m 与 b），意思是木头。"}], "explanations": {"部": "部 bù（第四声），用于手机、电视剧、机器等的量词。", "补": "bǔ（第三声）与 bù（第四声）声调不同，意思是补充。", "铺": "pù 与 bù 声母不同（p 与 b），意思是店铺。", "木": "mù 与 bù 声母不同（m 与 b），意思是木头。"}, "sentence_index": null, "correct_answer": "部"}, "level_3": {"options": [{"text": "部", "is_correct": true, "explanation": "部用于手机、机器等，「我新买了一部手机」正确。"}, {"text": "篇", "is_correct": false, "explanation": "语义：篇用于文章等文字作品，手机不是文字作品。"}, {"text": "张", "is_correct": false, "explanation": "搭配：张多用于纸张、平面的东西，不说「一张手机」。"}, {"text": "首", "is_correct": false, "explanation": "语义：首用于诗歌、歌曲，手机不是诗歌或歌曲。"}], "explanations": {"部": "部用于手机、机器等，「我新买了一部手机」正确。", "篇": "语义：篇用于文章等文字作品，手机不是文字作品。", "张": "搭配：张多用于纸张、平面的东西，不说「一张手机」。", "首": "语义：首用于诗歌、歌曲，手机不是诗歌或歌曲。"}, "sentence_index": 0, "correct_answer": "部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他送给我一部花。", "explanation": "这里应该用〈朵〉。部用于机器、电视剧等，花要用〈朵〉。"}, {"text": "书包里有一部笔。", "explanation": "这里应该用〈支〉。部不用于文具，笔要用〈支〉。"}, {"text": "我们住在一部房子里。", "explanation": "这里应该用〈座〉。部不用于房屋，房子要用〈座〉或〈套〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87294, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "部", "is_correct": true, "explanation": "部 bù（第四声），用于手机、电视剧、机器等的量词。"}, {"text": "捕", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，意思是抓捕。"}, {"text": "目", "is_correct": false, "explanation": "mù 与 bù 声母不同（m 与 b），意思是眼睛。"}, {"text": "付", "is_correct": false, "explanation": "fù 与 bù 声母不同（f 与 b），意思是付款。"}], "explanations": {"部": "部 bù（第四声），用于手机、电视剧、机器等的量词。", "捕": "bǔ（第三声）与 bù（第四声）声调不同，意思是抓捕。", "目": "mù 与 bù 声母不同（m 与 b），意思是眼睛。", "付": "fù 与 bù 声母不同（f 与 b），意思是付款。"}, "sentence_index": null, "correct_answer": "部"}, "level_3": {"options": [{"text": "部", "is_correct": true, "explanation": "部可用于手机、电话等，「一部新手机」正确。"}, {"text": "本", "is_correct": false, "explanation": "搭配：本用于书籍、本子，不说「一本手机」。"}, {"text": "条", "is_correct": false, "explanation": "搭配：条用于细长的东西，如鱼、河、裤子，不说「一条手机」。"}, {"text": "朵", "is_correct": false, "explanation": "语义：朵用于花、云，手机不是花或云。"}], "explanations": {"部": "部可用于手机、电话等，「一部新手机」正确。", "本": "搭配：本用于书籍、本子，不说「一本手机」。", "条": "搭配：条用于细长的东西，如鱼、河、裤子，不说「一条手机」。", "朵": "语义：朵用于花、云，手机不是花或云。"}, "sentence_index": 6, "correct_answer": "部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈做了一部蛋糕。", "explanation": "这里应该用〈块〉。部不用于食物，蛋糕要用〈块〉。"}, {"text": "他钓到了一部鱼。", "explanation": "这里应该用〈条〉。部不用于鱼，鱼要用〈条〉。"}, {"text": "院子里养着一部鸡。", "explanation": "这里应该用〈只〉。部不用于动物，鸡要用〈只〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我弟弟昨天买了一部的新手机。", "corrected_sentence": "我弟弟昨天买了一部新手机。", "error_description": "结构错误：数量短语「一部」与名词之间不能加「的」，「一部的新手机」不成立，应说「一部新手机」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部的电视剧很好看。", "corrected_sentence": "这部电视剧很好看。", "error_description": "结构错误：指示词加量词「这部」后直接接名词，中间不能加「的」，应说「这部电视剧」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f486e30-3ae2-4f13-aa8f-30c337825229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
