INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87295, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "月相是月亮每天看起来不同的样子，有时圆，有时弯。", "primary_collocate": null, "pronunciation": "yuè xiàng", "ipa": "ɥœ˥˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "月亮每天的月相都不一样。", "target_word": "月相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚的月相是弯弯的。", "target_word": "月相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶根据月相，就知道是几号。", "target_word": "月相", "complexity_tier": "T3", "furigana": "yuè xiàng", "sentence_source": "generated"}, {"text": "孩子们在本子上画了一周的月相。", "target_word": "月相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月相有时圆，有时弯。", "target_word": "月相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道今天的月相叫什么吗？", "target_word": "月相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天晚上都记下月相。", "target_word": "月相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图画着一个月里的月相。", "target_word": "月相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从新月到满月，月相一直在变化。", "target_word": "月相", "complexity_tier": "T3", "furigana": "yuè xiàng", "sentence_source": "generated"}, {"text": "老师教我们看月相。", "target_word": "月相", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "月相变化", "label": "复合"}, {"form": "月相图", "label": "复合"}], "register": "中性", "sense_fingerprint": "月亮每天看起来不同的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046a46c1-f6ab-4b59-a727-080c82d4af4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87295, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "月相", "is_correct": true, "explanation": "正确：月相是月亮每天看起来不同的样子。"}, {"text": "越线", "is_correct": false, "explanation": "xiàn（第四声）与 xiàng（第四声）韵母不同：an 与 ang，意思是越过界线，与月相无关。"}, {"text": "月饷", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是每月的薪饷。"}, {"text": "月线", "is_correct": false, "explanation": "xiàn 与 xiàng 韵母不同：an 与 ang，意思是月度走势线。"}], "explanations": {"月相": "正确：月相是月亮每天看起来不同的样子。", "越线": "xiàn（第四声）与 xiàng（第四声）韵母不同：an 与 ang，意思是越过界线，与月相无关。", "月饷": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是每月的薪饷。", "月线": "xiàn 与 xiàng 韵母不同：an 与 ang，意思是月度走势线。"}, "sentence_index": null, "correct_answer": "月相"}, "level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：月亮没有价格，“每天的价格都不一样”与月亮无关。"}, {"text": "月相", "is_correct": true, "explanation": "正确：月相指月亮每天看起来不同的样子，与“都不一样”相符。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”用于食物或气味，不用来说月亮的样子。"}, {"text": "工资", "is_correct": false, "explanation": "语义：月亮不发工资，“每天的工资”与月亮矛盾。"}], "explanations": {"价格": "语义：月亮没有价格，“每天的价格都不一样”与月亮无关。", "月相": "正确：月相指月亮每天看起来不同的样子，与“都不一样”相符。", "味道": "搭配：“味道”用于食物或气味，不用来说月亮的样子。", "工资": "语义：月亮不发工资，“每天的工资”与月亮矛盾。"}, "sentence_index": 0, "correct_answer": "月相"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夜里月相很亮，照得院子里一片白。", "explanation": "这里应该用〈月光〉。月相指月亮形状的变化，不指照下来的光。"}, {"text": "今晚发生了一次月相，月亮变成了暗红色。", "explanation": "这里应该用〈月食〉。月亮变成暗红色是月食现象，月相指月亮形状的变化。"}, {"text": "我每天早上看一看墙上的月相，就知道今天是星期几。", "explanation": "这里应该用〈月历〉。月相指月亮形状的变化，不是挂在墙上、用来查日期的月历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87295, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "月相", "is_correct": true, "explanation": "正确：月相是月亮每天看起来不同的样子。"}, {"text": "意象", "is_correct": false, "explanation": "yì（第四声）与 yuè 韵母不同，后字 xiàng 相同。意思是文学作品中的形象，与月相无关。"}, {"text": "夜香", "is_correct": false, "explanation": "yè 与 yuè 韵母不同，xiāng（第一声）与 xiàng（第四声）声调不同。意思是夜里散发的花香。"}, {"text": "预想", "is_correct": false, "explanation": "yù 与 yuè 韵母不同，xiǎng（第三声）与 xiàng（第四声）声调不同。意思是事先的设想。"}], "explanations": {"月相": "正确：月相是月亮每天看起来不同的样子。", "意象": "yì（第四声）与 yuè 韵母不同，后字 xiàng 相同。意思是文学作品中的形象，与月相无关。", "夜香": "yè 与 yuè 韵母不同，xiāng（第一声）与 xiàng（第四声）声调不同。意思是夜里散发的花香。", "预想": "yù 与 yuè 韵母不同，xiǎng（第三声）与 xiàng（第四声）声调不同。意思是事先的设想。"}, "sentence_index": null, "correct_answer": "月相"}, "level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "语义：太阳白天出现，晚上看不到，与“每天晚上”矛盾。"}, {"text": "晨雾", "is_correct": false, "explanation": "语义：晨雾指清晨的雾，晚上记下晨雾与“每天晚上”矛盾。"}, {"text": "日出", "is_correct": false, "explanation": "语义：日出在清晨，晚上不会出现，与“每天晚上”矛盾。"}, {"text": "月相", "is_correct": true, "explanation": "正确：月相是月亮每天看起来不同的样子，晚上可以观察并记录。"}], "explanations": {"太阳": "语义：太阳白天出现，晚上看不到，与“每天晚上”矛盾。", "晨雾": "语义：晨雾指清晨的雾，晚上记下晨雾与“每天晚上”矛盾。", "日出": "语义：日出在清晨，晚上不会出现，与“每天晚上”矛盾。", "月相": "正确：月相是月亮每天看起来不同的样子，晚上可以观察并记录。"}, "sentence_index": 6, "correct_answer": "月相"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "月相绕着地球转，每个月转一圈。", "explanation": "这里应该用〈月球〉。月球才会绕着地球转，月相是月亮的形状变化。"}, {"text": "妈妈问我今天是几月相。", "explanation": "这里应该用〈月份〉。月相指月亮形状的变化，不用来表示是几月。"}, {"text": "湖面上有一片月相，像被风吹散了。", "explanation": "这里应该用〈月影〉。月相指月亮形状的变化，不是投在湖面上的影子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87295, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在本子上画了三只月相。", "corrected_sentence": "我们在本子上画了三种月相。", "error_description": "错误：“只”用于动物等，不能修饰“月相”。应改为“种”（或“个”），即“三种月相”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87295, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书介绍了八种月相们。", "corrected_sentence": "这本书介绍了八种月相。", "error_description": "词缀错误：“们”只用于指人或表人的名词，不能加在“月相”后面。应去掉“们”，说“八种月相”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
