INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87296, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "月球被太阳照亮部分在地球上看到的不同形状。", "primary_collocate": null, "pronunciation": "yuè xiàng", "ipa": "ɥœ˥˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "月相是我们在地球上看到的月球形状。", "target_word": "月相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月相变化是因为太阳照亮的部分不同。", "target_word": "月相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "满月是一种月相，月亮看起来很圆。", "target_word": "月相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学课上，我们学习了月相的成因。", "target_word": "月相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球、月球和太阳的位置会改变月相。", "target_word": "月相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上弦月是半圆形的月相。", "target_word": "月相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手电筒和球做了一个月相实验。", "target_word": "月相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用图片讲解月相的名称。", "target_word": "月相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球上的人看到的月相，每月重复一次。", "target_word": "月相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要观察月相，最好在晚上没有云的时候。", "target_word": "月相", "complexity_tier": "T3", "furigana": "yuè xiàng", "sentence_source": "generated"}], "morphological_forms": [{"form": "月相变化", "label": "复合"}, {"form": "月相图", "label": "复合"}], "register": "书面", "sense_fingerprint": "月球被太阳照亮的部分在地球上呈现的形状", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '046a46c1-f6ab-4b59-a727-080c82d4af4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87296, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "月相", "is_correct": true, "explanation": "正确：月相指月球被太阳照亮的部分在地球上看到的形状。"}, {"text": "越线", "is_correct": false, "explanation": "xiàn（第四声）与 xiàng（第四声）韵母不同：an 与 ang，意思是越过界线，与月相无关。"}, {"text": "月饷", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是每月的薪饷。"}, {"text": "月线", "is_correct": false, "explanation": "xiàn 与 xiàng 韵母不同：an 与 ang，意思是月度走势线。"}], "explanations": {"月相": "正确：月相指月球被太阳照亮的部分在地球上看到的形状。", "越线": "xiàn（第四声）与 xiàng（第四声）韵母不同：an 与 ang，意思是越过界线，与月相无关。", "月饷": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是每月的薪饷。", "月线": "xiàn 与 xiàng 韵母不同：an 与 ang，意思是月度走势线。"}, "sentence_index": null, "correct_answer": "月相"}, "level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "语义：太阳是恒星，不是月球被照亮后的形状，与“月球形状”矛盾。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹是阳光经水汽折射形成的景象，与“月球形状”不符。"}, {"text": "星座", "is_correct": false, "explanation": "搭配：“星座”指星星组成的图形，不说“月球的形状”。"}, {"text": "月相", "is_correct": true, "explanation": "正确：月相指月亮被照亮部分在地球上看到的形状，与句中“月球形状”相符。"}], "explanations": {"太阳": "语义：太阳是恒星，不是月球被照亮后的形状，与“月球形状”矛盾。", "彩虹": "语义：彩虹是阳光经水汽折射形成的景象，与“月球形状”不符。", "星座": "搭配：“星座”指星星组成的图形，不说“月球的形状”。", "月相": "正确：月相指月亮被照亮部分在地球上看到的形状，与句中“月球形状”相符。"}, "sentence_index": 0, "correct_answer": "月相"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今晚发生了一次月相，月亮变成了暗红色。", "explanation": "这里应该用〈月食〉。月亮变成暗红色是月食现象，月相指月亮形状的变化。"}, {"text": "月相照在窗台上，亮亮的。", "explanation": "这里应该用〈月光〉。月相指形状的变化，不指照下来的光。"}, {"text": "海边的月相每天涨落两次，渔船都要等它涨上来再出海。", "explanation": "这里应该用〈潮汐〉。月相指月球被照亮部分的形状，海水每天涨落的是潮汐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01cebb8a-1503-46fc-8817-0957501ce55d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDE