INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87297, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "分分钟是说很快很快，一下子就会发生。", "primary_collocate": null, "pronunciation": "fēn fēn zhōng", "ipa": "fən˥ fən˥ ʈʂʊŋ˥", "syllable_count": 3, "sentences": [{"text": "太阳这么大，雪人分分钟就化了。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别放在桌边，杯子分分钟会掉下去。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子一哭，妈妈分分钟跑过来了。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买票的人太多，票分分钟卖完了。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不快点儿，菜分分钟就凉了。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水太热了，分分钟会烫伤手。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生气了，分分钟会走掉。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店很火，分分钟排满了人。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风这么大，帽子分分钟会飞走。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药很有用，分分钟就不疼了。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "很快很快，一下子就会发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dee2df57-fb87-4f86-b7e0-dc23161c9f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87297, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一向如此，与“就化了”这种刚发生的变化矛盾。"}, {"text": "分分钟", "is_correct": true, "explanation": "“分分钟”表示很快、一下子就会发生，符合太阳大、雪很快化掉的语境。"}, {"text": "千万", "is_correct": false, "explanation": "语义：“千万”表示务必，不能用来叙述已经发生的变化。"}, {"text": "好好", "is_correct": false, "explanation": "搭配：“好好”修饰行为，不修饰“化”这类自然变化。"}], "explanations": {"从来": "语义：“从来”表示一向如此，与“就化了”这种刚发生的变化矛盾。", "分分钟": "“分分钟”表示很快、一下子就会发生，符合太阳大、雪很快化掉的语境。", "千万": "语义：“千万”表示务必，不能用来叙述已经发生的变化。", "好好": "搭配：“好好”修饰行为，不修饰“化”这类自然变化。"}, "sentence_index": 0, "correct_answer": "分分钟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "树苗分分钟长成了大树。", "explanation": "这里应该用〈慢慢〉。“分分钟”说瞬间或很快发生，树木长成大树是缓慢的过程。"}, {"text": "我分分钟研究了这个问题一年。", "explanation": "这里应该去掉〈分分钟〉。它表示很快完成，与长期的研究过程矛盾，这种过程应说〈花了〉。"}, {"text": "我开车分分钟从北京到了上海，用了两天。", "explanation": "这里应该去掉〈分分钟〉。它表示很快，不能和“用了两天”这样的长时间一起用；说用时长应说“我开车从北京到上海〈花了〉两天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87297, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已经发生，与“会走掉”的预测矛盾。"}, {"text": "分分钟", "is_correct": true, "explanation": "“分分钟”表示很快、一下子就会发生，符合生气后很快离开的语境。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”指长久不变，与“走掉”这种一次性动作不相容。"}, {"text": "白白", "is_correct": false, "explanation": "搭配：“白白”表示徒然，多修饰徒劳的结果，不能用于这里的预测。"}], "explanations": {"已经": "语义：“已经”表示已经发生，与“会走掉”的预测矛盾。", "分分钟": "“分分钟”表示很快、一下子就会发生，符合生气后很快离开的语境。", "永远": "语义：“永远”指长久不变，与“走掉”这种一次性动作不相容。", "白白": "搭配：“白白”表示徒然，多修饰徒劳的结果，不能用于这里的预测。"}, "sentence_index": 6, "correct_answer": "分分钟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他分分钟学了十年钢琴。", "explanation": "这里不能用〈分分钟〉。它表示很快，与“十年”的长时间矛盾，应说“他〈花了〉十年学钢琴”。"}, {"text": "这座桥分分钟建成了，历时五年。", "explanation": "这里应该去掉〈分分钟〉。它表示瞬间或很快，不能用于历时很久的工程，这种工程应说〈需要〉。"}, {"text": "孩子分分钟慢慢地长大了。", "explanation": "这里不能用〈分分钟〉。它表示很快发生，与长大这种漫长过程矛盾，应改用〈一年一年〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87297, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屏幕很分分钟就黑了。", "corrected_sentence": "屏幕分分钟就黑了。", "error_description": "错误在于“很”修饰“分分钟”。“分分钟”不能被程度副词修饰。正确应为“屏幕分分钟就黑了”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87297, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的分分钟就出门了。", "corrected_sentence": "他分分钟就出门了。", "error_description": "错误在于“分分钟”前多加了“的”。“分分钟”是副词，不能加“的”修饰。正确应为“他分分钟就出门了”，去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
