INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87298, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87298, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "口语，指随时、很快；也指极短的时间。", "primary_collocate": null, "pronunciation": "fēn fēn zhōng", "ipa": "fən˥ fən˥ ʈʂʊŋ˥", "syllable_count": 3, "sentences": [{"text": "你再不走，分分钟会迟到。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天这么黑，分分钟要下雨了。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你等我一下，我分分钟就回来。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电了，分分钟会关机。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题很简单，分分钟能解决。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从我家到学校，骑车分分钟就到。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上买东西，分分钟就能送到。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要小心，分分钟会出错。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜太容易了，分分钟学会。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很聪明，分分钟就看懂了。", "target_word": "分分钟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "口语，表示随时可能或很快就能做到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dee2df57-fb87-4f86-b7e0-dc23161c9f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87298, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示事情已经发生，与“你再不走”所假设的将来不符。"}, {"text": "分分钟", "is_correct": true, "explanation": "“分分钟”表示很快或随时就会发生，符合“你再不走，……会迟到”的假设语境。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”表示一向如此，多与否定或已然事件搭配，不与“会”的预测共现。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”指出乎意料地突然发生，与条件句中的预测不符。"}], "explanations": {"已经": "语义：“已经”表示事情已经发生，与“你再不走”所假设的将来不符。", "分分钟": "“分分钟”表示很快或随时就会发生，符合“你再不走，……会迟到”的假设语境。", "从来": "搭配：“从来”表示一向如此，多与否定或已然事件搭配，不与“会”的预测共现。", "忽然": "语义：“忽然”指出乎意料地突然发生，与条件句中的预测不符。"}, "sentence_index": 0, "correct_answer": "分分钟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇论文分分钟写了三年。", "explanation": "这里不能用〈分分钟〉。它只表示很快或极短的时间，不能修饰“写了三年”这样的长时间，应改用〈花了〉。"}, {"text": "我分分钟读完了那本厚书，用了整整一个月。", "explanation": "这里不能用〈分分钟〉。它表示瞬间完成，与“整整一个月”的持续时间矛盾，若要说读的时间长应用〈花了〉。"}, {"text": "我在医院分分钟住了五年。", "explanation": "这里不能用〈分分钟〉。它表示很快或极短时间，住院这类长期状态应改用〈一直〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87298, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "慢慢", "is_correct": false, "explanation": "语义：“慢慢”说速度慢，与“送到”的快捷形成矛盾。"}, {"text": "分分钟", "is_correct": true, "explanation": "“分分钟”表示很快就能完成，符合网购送达很快的语境。"}, {"text": "千万", "is_correct": false, "explanation": "语义：“千万”表示务必、一定，不能用来陈述送达的结果。"}, {"text": "好好", "is_correct": false, "explanation": "搭配：“好好”多修饰行为或能力，不修饰“送到”这类结果。"}], "explanations": {"慢慢": "语义：“慢慢”说速度慢，与“送到”的快捷形成矛盾。", "分分钟": "“分分钟”表示很快就能完成，符合网购送达很快的语境。", "千万": "语义：“千万”表示务必、一定，不能用来陈述送达的结果。", "好好": "搭配：“好好”多修饰行为或能力，不修饰“送到”这类结果。"}, "sentence_index": 6, "correct_answer": "分分钟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他分分钟慢慢地走回了家。", "explanation": "这里不能用〈分分钟〉。它表示很快，与缓慢的走路方式矛盾，若要说走得慢应用〈缓缓〉。"}, {"text": "考试分分钟在下周三开始。", "explanation": "这里不能用〈分分钟〉。它表示随时或很快就会发生，不用于已经确定的日期，应改用〈定于〉。"}, {"text": "他分分钟一步一步地爬上了山。", "explanation": "这里不能用〈分分钟〉。它表示很快，与一步一步的缓慢攀登矛盾，这种过程应说〈逐渐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很分分钟就能把饭做好。", "corrected_sentence": "我分分钟就能把饭做好。", "error_description": "错误在于“很”修饰“分分钟”。“分分钟”是表示很快的副词，不能再被程度副词“很”修饰。正确应为“我分分钟就能把饭做好”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个游戏很简单，你的分分钟就能学会。", "corrected_sentence": "这个游戏很简单，你分分钟就能学会。", "error_description": "错误在于“分分钟”前多加了“的”。“分分钟”是副词，直接放在主语后、动词前，不能加“的”。正确应为“你分分钟就能学会”，去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
