INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87300, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "二分之一；整体分成两个相等部分中的一部分。", "primary_collocate": null, "pronunciation": "yī bàn", "ipa": "i˥ pan˥˩", "syllable_count": 2, "sentences": [{"text": "全班一半的学生是女生，男女人数一样多。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的工资，一半用来交房租。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市一半的人都骑自行车。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生中有一半来自外国。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话，一半是真的，一半是假的。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司一半的员工会说英语。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，全班四十人，一半的人没有及格，二十人及格了。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年中，他有一半时间在国外。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的观众里，一半是小孩子。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一半的同学今天没有来上课。", "target_word": "一半", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一半儿", "label": "儿化"}, {"form": "一大半", "label": "复合"}], "register": "中性", "sense_fingerprint": "整体的二分之一，表示数量或比例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1493551b-beb8-436c-890d-5f7aa674fb8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87300, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一半", "is_correct": true, "explanation": "一半：整体的二分之一，正是听到的 yī bàn。"}, {"text": "一般", "is_correct": false, "explanation": "“一般”（yì bān）与“一半”的声调不同，意思是普通、大体上。"}, {"text": "一班", "is_correct": false, "explanation": "“一班”（yī bān）与“一半”末尾声调不同，意思是第一个班。"}, {"text": "一版", "is_correct": false, "explanation": "“一版”（yī bǎn）与“一半”末尾声调不同，意思是第一版。"}], "explanations": {"一半": "一半：整体的二分之一，正是听到的 yī bàn。", "一般": "“一般”（yì bān）与“一半”的声调不同，意思是普通、大体上。", "一班": "“一班”（yī bān）与“一半”末尾声调不同，意思是第一个班。", "一版": "“一版”（yī bǎn）与“一半”末尾声调不同，意思是第一版。"}, "sentence_index": null, "correct_answer": "一半"}, "level_3": {"options": [{"text": "全部", "is_correct": false, "explanation": "语义：“全部”指全体，句子强调的是其中一部分学生。"}, {"text": "一半", "is_correct": true, "explanation": "一半：全班学生中的二分之一，与句意相符。"}, {"text": "所有", "is_correct": false, "explanation": "语义：“所有”指全体，与“男女人数一样多”的句意矛盾。"}, {"text": "三分之一", "is_correct": false, "explanation": "语义：句子表示的是整体的二分之一，不能说三分之一。"}], "explanations": {"全部": "语义：“全部”指全体，句子强调的是其中一部分学生。", "一半": "一半：全班学生中的二分之一，与句意相符。", "所有": "语义：“所有”指全体，与“男女人数一样多”的句意矛盾。", "三分之一": "语义：句子表示的是整体的二分之一，不能说三分之一。"}, "sentence_index": 0, "correct_answer": "一半"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "全班三十人，有一半来自外国，就是十个人。", "explanation": "这里应该用〈三分之一〉。三十人的一半是十五人，十个人只是三分之一。"}, {"text": "学生中有一半是男生，另一半是女生，还有一半是老师。", "explanation": "这里应该用〈一部分〉。两个一半已是全部，再说一个一半就超出了整体。"}, {"text": "学生中有一半来自外国，另一半也来自外国。", "explanation": "这里应该用〈全部〉。两个一半都来自外国，就是全部学生来自外国。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87300, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一半", "is_correct": true, "explanation": "一半：这次考试中有一半的人没及格，符合句意。"}, {"text": "全部", "is_correct": false, "explanation": "语义：全班四十人都没及格，与“二十人及格了”的句意矛盾。"}, {"text": "少数", "is_correct": false, "explanation": "语义：二十人及格，没及格的也是二十人，不能说“少数”。"}, {"text": "大部分", "is_correct": false, "explanation": "语义：“大部分”表示绝大多数，与“一半”的数量不符。"}], "explanations": {"一半": "一半：这次考试中有一半的人没及格，符合句意。", "全部": "语义：全班四十人都没及格，与“二十人及格了”的句意矛盾。", "少数": "语义：二十人及格，没及格的也是二十人，不能说“少数”。", "大部分": "语义：“大部分”表示绝大多数，与“一半”的数量不符。"}, "sentence_index": 6, "correct_answer": "一半"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全班四十人，一半是十个人。", "explanation": "这里应该用〈四分之一〉。四十人的一半是二十人，十个人只是四分之一。"}, {"text": "一半的同学是女生，一半的同学是男生，还有一半的同学是老师。", "explanation": "这里应该用〈其余〉。两个一半已是全部同学，不能再有第三个一半。"}, {"text": "全班四十人，只来了一个人，一半的同学没来。", "explanation": "这里应该用〈大部分〉。四十人只来了一个，没来的远远超过一半。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87300, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛，一半个人没有晋级。", "corrected_sentence": "这次比赛，一半的人没有晋级。", "error_description": "错误在“一半”后接量词“个”：“一半”后应接“的”再接名词，说“一半的人”，不能说“一半个人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87300, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一半地学生今天没来上课。", "corrected_sentence": "一半的学生今天没来上课。", "error_description": "错误在“地”：“一半”修饰名词时要用“的”，应说“一半的学生”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87303, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87303, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87303, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "功率是说一台机器有多大力气，做事有多快。", "primary_collocate": null, "pronunciation": "gōng lǜ", "ipa": "kʊŋ˥ ly˥˩", "syllable_count": 2, "sentences": [{"text": "这台机器功率很大，干活很快。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "功率小的电器，用电也少。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买空调时，我先看功率大不大。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台洗衣机的功率太小，洗得很慢。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "功率越大的灯，看起来越亮。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电饭锅的功率是八百瓦。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车功率高，开得很快。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吹风机功率大，头发干得快。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小风扇功率不大，声音很小。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人换了一台功率更大的机器。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "机器、电器的力量大小和工作快慢，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b66f903-6f7d-4f96-9cc8-707587246b0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87303, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公路", "is_correct": false, "explanation": "lù 与 lǜ 韵母不同（u 与 ü），公路意思是公共的道路。"}, {"text": "功率", "is_correct": true, "explanation": "功率 gōng lǜ：机器、电器做功的力量和快慢，是本题的正确答案。"}, {"text": "攻略", "is_correct": false, "explanation": "第二个音节 lüè 与 lǜ 韵母不同（多了 e），攻略意思是策略、指南。"}, {"text": "功力", "is_correct": false, "explanation": "lì 与 lǜ 韵母不同（i 与 ü），功力意思是本领、功夫。"}], "explanations": {"公路": "lù 与 lǜ 韵母不同（u 与 ü），公路意思是公共的道路。", "功率": "功率 gōng lǜ：机器、电器做功的力量和快慢，是本题的正确答案。", "攻略": "第二个音节 lüè 与 lǜ 韵母不同（多了 e），攻略意思是策略、指南。", "功力": "lì 与 lǜ 韵母不同（i 与 ü），功力意思是本领、功夫。"}, "sentence_index": null, "correct_answer": "功率"}, "level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "搭配：价格说“高”或“低”，不说“很大”，句子不通。"}, {"text": "功率", "is_correct": true, "explanation": "“功率很大”说明机器做功的力量大，与“干活很快”因果吻合，是唯一能填入的词。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：颜色说深浅、鲜艳，不说“很大”，与机器干活无关。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道的强弱与干活快慢无关，句子因果不通。"}], "explanations": {"价格": "搭配：价格说“高”或“低”，不说“很大”，句子不通。", "功率": "“功率很大”说明机器做功的力量大，与“干活很快”因果吻合，是唯一能填入的词。", "颜色": "搭配：颜色说深浅、鲜艳，不说“很大”，与机器干活无关。", "味道": "语义：味道的强弱与干活快慢无关，句子因果不通。"}, "sentence_index": 0, "correct_answer": "功率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的功率很好，能一口气爬上七楼。", "explanation": "这里应该用〈体力〉。功率说的是做功快慢，日常多用于机器、电器；能一口气爬上七楼说的是人的体力。"}, {"text": "这台空调每个月的功率很大，电费很高。", "explanation": "这里应该用〈耗电量〉。功率表示单位时间做功的快慢，不按月计算；一段时间用了多少电要说耗电量。"}, {"text": "他的功率很大，能扛起一百斤大米。", "explanation": "这里应该用〈力气〉。能扛起多重的东西看的是力气大小，不是做功快慢的功率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87303, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "搭配：年龄说“大”“小”，不说“高”，句子不通。"}, {"text": "功率", "is_correct": true, "explanation": "“功率高”说明动力强，所以开得快，句意通顺，是唯一能填入的词。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：重量说“重”“轻”，不说“高”，且与“开得很快”没有关系。"}, {"text": "心情", "is_correct": false, "explanation": "语义：车没有心情，“心情高”也不是车的属性，句子不通。"}], "explanations": {"年龄": "搭配：年龄说“大”“小”，不说“高”，句子不通。", "功率": "“功率高”说明动力强，所以开得快，句意通顺，是唯一能填入的词。", "重量": "搭配：重量说“重”“轻”，不说“高”，且与“开得很快”没有关系。", "心情": "语义：车没有心情，“心情高”也不是车的属性，句子不通。"}, "sentence_index": 6, "correct_answer": "功率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电饭锅的功率是八百公斤。", "explanation": "这里应该用〈瓦〉。功率的单位是瓦（W），公斤是重量的单位，不能用来计量功率。"}, {"text": "这种药的功率很好，吃一片就见效。", "explanation": "这里应该用〈功效〉。功率只用于机器、电器，药物的作用要说功效。"}, {"text": "这顿饭的功率很高，吃完很有劲。", "explanation": "这里应该用〈热量〉。功率只用于机器、电器，食物的能量要说热量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87303, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台吸尘器的功率很多，吸得很干净。", "corrected_sentence": "这台吸尘器的功率很大，吸得很干净。", "error_description": "错误形式“功率很多”，正确形式“功率很大”。形容功率的高低要用“大”，不用“多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87303, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车间里换了一台功率更大电机。", "corrected_sentence": "车间里换了一台功率更大的电机。", "error_description": "错误形式“功率更大电机”，正确形式“功率更大的电机”。修饰名词的短语后面要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
