INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87304, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "单位时间内所做的功，表示做功快慢的物理量。", "primary_collocate": null, "pronunciation": "gōng lǜ", "ipa": "kʊŋ˥ ly˥˩", "syllable_count": 2, "sentences": [{"text": "物理课上，老师讲了功率的意思。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "功率等于功除以时间。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "功率的单位是瓦。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做功越快，功率越大。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人做同样的功，用时少的功率大。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题要我们算出灯的功率。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "功率表示做功的快慢。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间相同，做功多的功率大。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用公式算出了电动机的功率。", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台起重机的功率是多少瓦？", "target_word": "功率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物理学术语，功除以时间，单位是瓦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b66f903-6f7d-4f96-9cc8-707587246b0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87304, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公立", "is_correct": false, "explanation": "lì 与 lǜ 韵母不同（i 与 ü），公立意思是由公家设立的。"}, {"text": "功率", "is_correct": true, "explanation": "功率 gōng lǜ：单位时间内所做的功，表示做功快慢的物理量，是本题的正确答案。"}, {"text": "公路", "is_correct": false, "explanation": "lù 与 lǜ 韵母不同（u 与 ü），公路意思是公共的道路。"}, {"text": "攻略", "is_correct": false, "explanation": "第二个音节 lüè 与 lǜ 韵母不同（多了 e），攻略意思是策略、指南。"}], "explanations": {"公立": "lì 与 lǜ 韵母不同（i 与 ü），公立意思是由公家设立的。", "功率": "功率 gōng lǜ：单位时间内所做的功，表示做功快慢的物理量，是本题的正确答案。", "公路": "lù 与 lǜ 韵母不同（u 与 ü），公路意思是公共的道路。", "攻略": "第二个音节 lüè 与 lǜ 韵母不同（多了 e），攻略意思是策略、指南。"}, "sentence_index": null, "correct_answer": "功率"}, "level_3": {"options": [{"text": "诗歌", "is_correct": false, "explanation": "语义：物理课上讲诗歌的意思，与课程内容不符，句子不通。"}, {"text": "功率", "is_correct": true, "explanation": "物理课上讲的是“功率”这一物理概念，句意通顺，是唯一能填入的词。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：物理课上讲菜谱的意思，与课程内容不符。"}, {"text": "哥们儿", "is_correct": false, "explanation": "语域：“哥们儿”是口语词，不用于课堂讲解的语境，句子也不通。"}], "explanations": {"诗歌": "语义：物理课上讲诗歌的意思，与课程内容不符，句子不通。", "功率": "物理课上讲的是“功率”这一物理概念，句意通顺，是唯一能填入的词。", "菜谱": "语义：物理课上讲菜谱的意思，与课程内容不符。", "哥们儿": "语域：“哥们儿”是口语词，不用于课堂讲解的语境，句子也不通。"}, "sentence_index": 0, "correct_answer": "功率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "汽车的功率越快，刹车距离越长。", "explanation": "这里应该用〈速度〉。功率表示做功的快慢，本身不说“快”；物体运动的快慢要用速度。"}, {"text": "这台电机的功率是八百米。", "explanation": "这里应该用〈瓦〉。功率的单位是瓦，米是长度单位，不能用来计量功率。"}, {"text": "他的功率很大，一拳能打碎砖头。", "explanation": "这里应该用〈力气〉。一拳打碎砖头靠的是力气（力的大小），功率表示做功快慢，不表示力气大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87304, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：颜色不表示做功的快慢，句子不通。"}, {"text": "功率", "is_correct": true, "explanation": "“功率表示做功的快慢”正是功率的定义，句意正确，是唯一能填入的词。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄与物理概念无关，不能表示做功的快慢。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：体重说的是重量，不能用来“表示做功的快慢”。"}], "explanations": {"颜色": "语义：颜色不表示做功的快慢，句子不通。", "功率": "“功率表示做功的快慢”正是功率的定义，句意正确，是唯一能填入的词。", "年龄": "语义：年龄与物理概念无关，不能表示做功的快慢。", "体重": "搭配：体重说的是重量，不能用来“表示做功的快慢”。"}, "sentence_index": 6, "correct_answer": "功率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台起重机的功率很多。", "explanation": "这里应该用〈功能〉。功率指做功的快慢，不指功能的多少；说功能多要用“功能”。"}, {"text": "这个小孩的功率很大，一个人就能搬动大石头。", "explanation": "这里应该用〈力气〉。能搬动大石头靠的是力气大小，功率表示做功快慢，不表示力气。"}, {"text": "这次考试的功率是两个小时。", "explanation": "这里应该用〈时长〉。功率是做功快慢的物理量，不指时间长短；考试持续的时间要说时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电机的功率很多，转得很快。", "corrected_sentence": "这台电机的功率很大，转得很快。", "error_description": "错误形式“功率很多”，正确形式“功率很大”。形容功率的高低要用“大”，不用“多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天这台机器的功率会提高了。", "corrected_sentence": "明天这台机器的功率会提高。", "error_description": "错误形式“提高了”，正确形式“提高”。“会”表示尚未发生，句末的“了”表示动作已经完成，二者搭配不当，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
