INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87305, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "黄是像香蕉皮那样的颜色。", "primary_collocate": null, "pronunciation": "huáng", "ipa": "xwɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "熟的香蕉皮是黄的。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天到了，树叶都黄了。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个柠檬很黄，应该熟了。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸放久了，已经黄了。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的牙有点黄。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢穿那件黄的衣服。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玉米放在太阳下，越晒越黄。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些香蕉还不太黄，先别吃。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脸很黄，可能生病了。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄的那个是我的杯子。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "黄黄的", "label": "重叠"}, {"form": "黃", "label": "繁体"}], "register": "通用", "sense_fingerprint": "香蕉皮那样的黄色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0966929-86ca-4ac4-8d16-7e9b2ba39e93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87305, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "黄", "is_correct": true, "explanation": "正确：黄 huáng（第二声），指香蕉皮那样的颜色。"}, {"text": "荒", "is_correct": false, "explanation": "荒 huāng（第一声）与 huáng（第二声）声调不同，意思是荒芜。"}, {"text": "谎", "is_correct": false, "explanation": "谎 huǎng（第三声）与 huáng（第二声）声调不同，意思是说假话。"}, {"text": "环", "is_correct": false, "explanation": "环 huán 与 huáng 韵母不同（an 与 ang），意思是圆环。"}, {"text": "晃", "is_correct": false, "explanation": "晃 huàng（第四声）与 huáng（第二声）声调不同，意思是摇动。"}], "explanations": {"黄": "正确：黄 huáng（第二声），指香蕉皮那样的颜色。", "荒": "荒 huāng（第一声）与 huáng（第二声）声调不同，意思是荒芜。", "谎": "谎 huǎng（第三声）与 huáng（第二声）声调不同，意思是说假话。", "环": "环 huán 与 huáng 韵母不同（an 与 ang），意思是圆环。", "晃": "晃 huàng（第四声）与 huáng（第二声）声调不同，意思是摇动。"}, "sentence_index": null, "correct_answer": "黄"}, "level_3": {"options": [{"text": "黄", "is_correct": true, "explanation": "正确：熟香蕉的果皮呈黄色，符合句意。"}, {"text": "绿", "is_correct": false, "explanation": "语义：熟香蕉皮通常是黄色的，“绿”与句中的“熟的”冲突。"}, {"text": "蓝", "is_correct": false, "explanation": "语义：熟香蕉皮不会是蓝色，“蓝”与句意不符。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不用来描述果皮的颜色。"}], "explanations": {"黄": "正确：熟香蕉的果皮呈黄色，符合句意。", "绿": "语义：熟香蕉皮通常是黄色的，“绿”与句中的“熟的”冲突。", "蓝": "语义：熟香蕉皮不会是蓝色，“蓝”与句意不符。", "甜": "搭配：“甜”形容味道，不用来描述果皮的颜色。"}, "sentence_index": 0, "correct_answer": "黄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌很黄，我很喜欢听。", "explanation": "这里应该用〈好听〉。在这个义项里“黄”只表示颜色，不能用来形容歌好不好听，要用〈好听〉。"}, {"text": "他放学后的心情很黄。", "explanation": "这里应该用〈好〉。“黄”只表示颜色，形容心情要用〈好〉之类的词，不能说心情黄。"}, {"text": "他跑得很黄。", "explanation": "这里应该用〈快〉。“黄”是颜色形容词，不能用来描写动作“跑”的快慢，描写跑的速度要用〈快〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87305, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "黄", "is_correct": true, "explanation": "正确：黄 huáng（第二声），指颜色。"}, {"text": "慌", "is_correct": false, "explanation": "慌 huāng（第一声）与 huáng（第二声）声调不同，意思是慌张。"}, {"text": "还", "is_correct": false, "explanation": "还 huán 与 huáng 韵母不同（an 与 ang），意思是归还。"}, {"text": "狂", "is_correct": false, "explanation": "狂 kuáng 与 huáng 声母不同（k 与 h），意思是疯狂。"}], "explanations": {"黄": "正确：黄 huáng（第二声），指颜色。", "慌": "慌 huāng（第一声）与 huáng（第二声）声调不同，意思是慌张。", "还": "还 huán 与 huáng 韵母不同（an 与 ang），意思是归还。", "狂": "狂 kuáng 与 huáng 声母不同（k 与 h），意思是疯狂。"}, "sentence_index": null, "correct_answer": "黄"}, "level_3": {"options": [{"text": "黄", "is_correct": true, "explanation": "正确：玉米越晒颜色越深，变成黄色，符合句意。"}, {"text": "紫", "is_correct": false, "explanation": "语义：玉米晒干后不会变成紫色，“紫”与“越晒越”的颜色变化不符。"}, {"text": "灰", "is_correct": false, "explanation": "语义：玉米晒干后颜色不会变灰，与句中的颜色变化冲突。"}, {"text": "绿", "is_correct": false, "explanation": "语义：玉米晒干后不会变成绿色，“绿”与“越晒越”的颜色变化不符。"}], "explanations": {"黄": "正确：玉米越晒颜色越深，变成黄色，符合句意。", "紫": "语义：玉米晒干后不会变成紫色，“紫”与“越晒越”的颜色变化不符。", "灰": "语义：玉米晒干后颜色不会变灰，与句中的颜色变化冲突。", "绿": "语义：玉米晒干后不会变成绿色，“绿”与“越晒越”的颜色变化不符。"}, "sentence_index": 6, "correct_answer": "黄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的生活很黄，每天都很开心。", "explanation": "这里应该用〈幸福〉。“黄”只表示颜色，不能形容生活的状态，形容生活过得好要用〈幸福〉。"}, {"text": "孩子们笑得很黄，声音很大。", "explanation": "这里应该用〈开心〉。“黄”是颜色形容词，不能描写笑的样子，笑得高兴要用〈开心〉。"}, {"text": "我的梦很黄，醒来很累。", "explanation": "这里应该用〈奇怪〉。“黄”只表示颜色，不能用来形容梦境，描述梦的内容要用〈奇怪〉之类的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors 