INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87306, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "像金子或向日葵花那样的颜色。", "primary_collocate": null, "pronunciation": "huáng", "ipa": "xwɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "向日葵的花是黄的。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "田里的油菜花开得很黄。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿着一条黄裙子。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的稻子黄了，像金子一样。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只小鸭子的毛是黄的。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路灯下，地上一片黄。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "麦子熟了，田野一片黄。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天穿着一件黄的外套。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菊花开了，黄得像金子。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了一朵黄的花。", "target_word": "黄", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "黄黄的", "label": "重叠"}, {"form": "黃", "label": "繁体"}], "register": "通用", "sense_fingerprint": "金子、向日葵花那样的黄色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0966929-86ca-4ac4-8d16-7e9b2ba39e93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87306, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "黄", "is_correct": true, "explanation": "正确：黄 huáng（第二声），指金子、向日葵花那样的颜色。"}, {"text": "荒", "is_correct": false, "explanation": "荒 huāng（第一声）与 huáng（第二声）声调不同，意思是荒芜。"}, {"text": "谎", "is_correct": false, "explanation": "谎 huǎng（第三声）与 huáng（第二声）声调不同，意思是说假话。"}, {"text": "环", "is_correct": false, "explanation": "环 huán 与 huáng 韵母不同（an 与 ang），意思是圆环。"}, {"text": "晃", "is_correct": false, "explanation": "晃 huàng（第四声）与 huáng（第二声）声调不同，意思是摇动。"}], "explanations": {"黄": "正确：黄 huáng（第二声），指金子、向日葵花那样的颜色。", "荒": "荒 huāng（第一声）与 huáng（第二声）声调不同，意思是荒芜。", "谎": "谎 huǎng（第三声）与 huáng（第二声）声调不同，意思是说假话。", "环": "环 huán 与 huáng 韵母不同（an 与 ang），意思是圆环。", "晃": "晃 huàng（第四声）与 huáng（第二声）声调不同，意思是摇动。"}, "sentence_index": null, "correct_answer": "黄"}, "level_3": {"options": [{"text": "黄", "is_correct": true, "explanation": "正确：向日葵的花是黄色的，符合句意。"}, {"text": "蓝", "is_correct": false, "explanation": "语义：向日葵花通常不是蓝色，“蓝”与句中的主语不符。"}, {"text": "紫", "is_correct": false, "explanation": "语义：向日葵花不是紫色，“紫”与句意冲突。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不用来描述花的颜色。"}], "explanations": {"黄": "正确：向日葵的花是黄色的，符合句意。", "蓝": "语义：向日葵花通常不是蓝色，“蓝”与句中的主语不符。", "紫": "语义：向日葵花不是紫色，“紫”与句意冲突。", "甜": "搭配：“甜”形容味道，不用来描述花的颜色。"}, "sentence_index": 0, "correct_answer": "黄"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜很黄，太咸了。", "explanation": "这里应该用〈难吃〉。“黄”只表示颜色，不能形容味道，味道不好要用〈难吃〉。"}, {"text": "小狗叫得很黄。", "explanation": "这里应该用〈响〉。“黄”是颜色形容词，不能描写叫声的大小，叫得大声要用〈响〉。"}, {"text": "妈妈的声音很黄，很温柔。", "explanation": "这里应该用〈柔和〉。“黄”只表示颜色，不用来形容声音，声音温和要用〈柔和〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87306, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "黄", "is_correct": true, "explanation": "正确：黄 huáng（第二声），指颜色。"}, {"text": "慌", "is_correct": false, "explanation": "慌 huāng（第一声）与 huáng（第二声）声调不同，意思是慌张。"}, {"text": "还", "is_correct": false, "explanation": "还 huán 与 huáng 韵母不同（an 与 ang），意思是归还。"}, {"text": "狂", "is_correct": false, "explanation": "狂 kuáng 与 huáng 声母不同（k 与 h），意思是疯狂。"}], "explanations": {"黄": "正确：黄 huáng（第二声），指颜色。", "慌": "慌 huāng（第一声）与 huáng（第二声）声调不同，意思是慌张。", "还": "还 huán 与 huáng 韵母不同（an 与 ang），意思是归还。", "狂": "狂 kuáng 与 huáng 声母不同（k 与 h），意思是疯狂。"}, "sentence_index": null, "correct_answer": "黄"}, "level_3": {"options": [{"text": "黄", "is_correct": true, "explanation": "正确：麦子成熟后田野呈金黄色，符合句意。"}, {"text": "绿", "is_correct": false, "explanation": "语义：麦子熟了，田野应是金黄色，“绿”与“熟了”冲突。"}, {"text": "灰", "is_correct": false, "explanation": "语义：成熟的麦田呈金黄色，不是灰色，“灰”与句意冲突。"}, {"text": "蓝", "is_correct": false, "explanation": "语义：麦子成熟后田野呈金黄色，“蓝”与句意冲突。"}], "explanations": {"黄": "正确：麦子成熟后田野呈金黄色，符合句意。", "绿": "语义：麦子熟了，田野应是金黄色，“绿”与“熟了”冲突。", "灰": "语义：成熟的麦田呈金黄色，不是灰色，“灰”与句意冲突。", "蓝": "语义：麦子成熟后田野呈金黄色，“蓝”与句意冲突。"}, "sentence_index": 6, "correct_answer": "黄"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的脚步很黄，走得很稳。", "explanation": "这里应该用〈轻〉。“黄”是颜色形容词，不能形容脚步，脚步轻要用〈轻〉。"}, {"text": "这个消息让我的心很黄。", "explanation": "这里应该用〈高兴〉。“黄”只表示颜色，不能形容内心的感受，让人高兴要用〈高兴〉。"}, {"text": "他的歌声很黄，大家都爱听。", "explanation": "这里应该用〈动听〉。“黄”只表示颜色，不能形容歌声，歌声好听要用〈动听〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这朵菊花黄很。", "corrected_sentence": "这朵菊花很黄。", "error_description": "错误：形容词“黄”前面要加程度副词“很”，词序应为“很黄”，不能说“黄很”。正确说法是“这朵菊花很黄。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那片田黄很。", "corrected_sentence": "那片田很黄。", "error_description": "错误：形容词“黄”前面要加程度副词“很”，词序应为“很黄”，不能说“黄很”。正确说法是“那片田很黄。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87307, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上届", "is_correct": true, "explanation": "上届指上一届，与本届在时间上相对，是反义词。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户指房屋墙上透光通风的开口，与本届没有反义关系。"}, {"text": "饭店", "is_correct": false, "explanation": "饭店指供人吃饭住宿的地方，与本届没有反义关系。"}, {"text": "学年", "is_correct": false, "explanation": "学年指一个学习年度，与本届没有反义关系。"}], "correct_answer": "上届", "explanations": {"上届": "上届指上一届，与本届在时间上相对，是反义词。", "窗户": "窗户指房屋墙上透光通风的开口，与本届没有反义关系。", "饭店": "饭店指供人吃饭住宿的地方，与本届没有反义关系。", "学年": "学年指一个学习年度，与本届没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87307, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下届", "is_correct": true, "explanation": "下届指下一届，与本届在时间上相对，是反义词。"}, {"text": "天气", "is_correct": false, "explanation": "天气指一段时间内的气象状况，与本届没有反义关系。"}, {"text": "家乡", "is_correct": false, "explanation": "家乡指出生或长大的地方，与本届没有反义关系。"}, {"text": "学期", "is_correct": false, "explanation": "学期指一个学习阶段，与本届没有反义关系。"}], "correct_answer": "下届", "explanations": {"下届": "下届指下一届，与本届在时间上相对，是反义词。", "天气": "天气指一段时间内的气象状况，与本届没有反义关系。", "家乡": "家乡指出生或长大的地方，与本届没有反义关系。", "学期": "学期指一个学习阶段，与本届没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87307, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "本届是这一次，比如这一次的比赛或大会。", "primary_collocate": null, "pronunciation": "běn jiè", "ipa": "pən˨˩ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "本届足球赛，我们班踢得不错。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本届大会有两百多人参加。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本届比赛的规则和去年不一样。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本届博览会在上海开幕了。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本届歌唱比赛有一千人报名。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本届展览会的门票是五十元。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本届比赛中，他拿到了第一名。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本届大学生运动会明天开幕。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本届论坛请来了很多专家。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本届春节晚会的节目很有意思。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本屆", "label": "繁体"}], "register": "正式", "sense_fingerprint": "指这一次的比赛、大会、展会等定期举办的活动，与上届、下届相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d04d293-e650-4428-be70-164f690aefe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87307, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眼镜", "is_correct": false, "explanation": "语义：“眼镜”是戴在眼睛上的物品，不能指足球赛，句子说不通。"}, {"text": "本届", "is_correct": true, "explanation": "正确：本届指这一次，与足球赛和我们班的比赛相符。"}, {"text": "童年", "is_correct": false, "explanation": "语义：“童年”指儿童时期，与“这一次的足球赛”不能相配。"}, {"text": "午餐", "is_correct": false, "explanation": "搭配：“午餐”不能修饰“足球赛”，搭配不自然。"}], "explanations": {"眼镜": "语义：“眼镜”是戴在眼睛上的物品，不能指足球赛，句子说不通。", "本届": "正确：本届指这一次，与足球赛和我们班的比赛相符。", "童年": "语义：“童年”指儿童时期，与“这一次的足球赛”不能相配。", "午餐": "搭配：“午餐”不能修饰“足球赛”，搭配不自然。"}, "sentence_index": 0, "correct_answer": "本届"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本届地震造成了很大损失。", "explanation": "这里应该用〈本次〉。本届只用于定期举办、按届计算的活动，地震是一次性事件，要用本次。"}, {"text": "本届大会都会表彰优秀员工。", "explanation": "这里应该用〈每届〉。本届指这一届，说每一届都会怎样要用每届。"}, {"text": "他本届长高了五厘米。", "explanation": "这里应该用〈今年〉。本届只用于届次，身高的变化要说今年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87307, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地铁", "is_correct": false, "explanation": "搭配：“地铁”不能修饰“比赛”，搭配不自然。"}, {"text": "本届", "is_correct": true, "explanation": "正确：本届指这一次，与“比赛中拿到第一名”相符。"}, {"text": "月光", "is_correct": false, "explanation": "语义：“月光”指月亮的光，不能指比赛，句子说不通。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：“窗帘”是挂在窗上的布，不能指比赛，句子说不通。"}], "explanations": {"地铁": "搭配：“地铁”不能修饰“比赛”，搭配不自然。", "本届": "正确：本届指这一次，与“比赛中拿到第一名”相符。", "月光": "语义：“月光”指月亮的光，不能指比赛，句子说不通。", "窗帘": "语义：“窗帘”是挂在窗上的布，不能指比赛，句子说不通。"}, "sentence_index": 6, "correct_answer": "本届"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "本届的心情很好，想出去走走。", "explanation": "这里应该用〈今天〉。本届只用于届次，心情不能用本届，要说今天的心情。"}, {"text": "本届的食堂很干净，大家都很满意。", "explanation": "这里应该用〈本校〉。本届只用于届次，食堂要用本校来说明所属。"}, {"text": "本届的晚餐很丰富，每个人都吃饱了。", "explanation": "这里应该用〈这回〉。本届只用于定期的届次活动，一顿晚餐要用这回。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87307, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "本届一个比赛的裁判很公正。", "corrected_sentence": "本届比赛的裁判很公正。", "error_description": "错误：“本届”后面多加了数量词“一个”。“本届”本身已表示“这一届”，不能再和“一个”并用，应直接说“本届比赛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87307, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本届歌唱比赛的报名人数很多。", "corrected_sentence": "本届歌唱比赛的报名人数很多。", "error_description": "错误：“本届”前面多加了指示词“这”。“本届”本身已表示“这一届”，不能再和“这”并用，应直接说“本届歌唱比赛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
