INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87308, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指现在这一届，当前这一次。", "primary_collocate": null, "pronunciation": "běn jiè", "ipa": "pən˨˩ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "本届运动会下个月在北京举行。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本届毕业生中有很多人想出国学习。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本届比赛的冠军是一位年轻的姑娘。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校本届学生会的会长是李明。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本届大会的主题是保护环境。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本届奥运会我最喜欢看游泳比赛。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本届世界杯的参加国比以前多。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本届电影节上，这部电影得了大奖。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本届班长是大家一起选出来的。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本届艺术节的票很快就卖完了。", "target_word": "本届", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本屆", "label": "繁体"}], "register": "正式", "sense_fingerprint": "指当前正在举行或刚举行的这一届会议、比赛、活动或任期，与上届、下届相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d04d293-e650-4428-be70-164f690aefe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87308, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上届", "is_correct": false, "explanation": "语义：上届指已经过去的一届，不能是下个月才举行的运动会。"}, {"text": "本届", "is_correct": true, "explanation": "正确：本届指现在这一届，与“下个月在北京举行”相符。"}, {"text": "去年", "is_correct": false, "explanation": "语义：去年已经过去，与“下个月举行”的时间相冲突。"}, {"text": "本季", "is_correct": false, "explanation": "搭配：“季”指季节或赛季，一般不说“本季运动会”，搭配不自然。"}], "explanations": {"上届": "语义：上届指已经过去的一届，不能是下个月才举行的运动会。", "本届": "正确：本届指现在这一届，与“下个月在北京举行”相符。", "去年": "语义：去年已经过去，与“下个月举行”的时间相冲突。", "本季": "搭配：“季”指季节或赛季，一般不说“本季运动会”，搭配不自然。"}, "sentence_index": 0, "correct_answer": "本届"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本届事故造成了三名学生受伤。", "explanation": "这里应该用〈本次〉。本届只用于定期举办、按届计算的活动，一次性的事故要用本次。"}, {"text": "本届的比赛每年都在夏天举行。", "explanation": "这里应该用〈每届〉。本届只指这一届，说每年、每一届都怎样要用每届。"}, {"text": "本届的销售额比上季度增加了。", "explanation": "这里应该用〈本季度〉。本届用于届次，季度、月份等周期要用本季度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本地", "is_correct": false, "explanation": "语义：“本地”指本地区，与“世界杯”的全球范围不符。"}, {"text": "本色", "is_correct": false, "explanation": "语义：“本色”指事物原来的样子，不能指世界杯的届次，句子说不通。"}, {"text": "本届", "is_correct": true, "explanation": "正确：本届指这一届，与世界杯的届次相符。"}, {"text": "本校", "is_correct": false, "explanation": "语义：“本校”指我们学校，与“世界杯”的范围不符。"}], "explanations": {"本地": "语义：“本地”指本地区，与“世界杯”的全球范围不符。", "本色": "语义：“本色”指事物原来的样子，不能指世界杯的届次，句子说不通。", "本届": "正确：本届指这一届，与世界杯的届次相符。", "本校": "语义：“本校”指我们学校，与“世界杯”的范围不符。"}, "sentence_index": 6, "correct_answer": "本届"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "本届的天气很好，适合去郊游。", "explanation": "这里应该用〈本周〉。本届只用于届次，天气不能说本届，要说本周的天气。"}, {"text": "本届的特产很有名。", "explanation": "这里应该用〈本地〉。本届只用于届次，特产要用本地来说明产地。"}, {"text": "本届的作业很多，大家都做到很晚。", "explanation": "这里应该用〈今天〉。本届只用于届次，作业要说今天的作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们协会这本届理事长是张先生。", "corrected_sentence": "我们协会本届理事长是张先生。", "error_description": "错误：“本届”前面多加了指示词“这”。“本届”本身已表示“这一届”，不能再和“这”并用，应直接说“本届理事长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "本届一个艺术节的开幕式非常热闹。", "corrected_sentence": "本届艺术节的开幕式非常热闹。", "error_description": "错误：“本届”后面多加了数量词“一个”。“本届”本身已表示“这一届”，不能再和“一个”并用，应直接说“本届艺术节”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
