INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87310, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安定", "is_correct": true, "explanation": "安定指社会稳定、局势平静，与“动乱”意思相反。"}, {"text": "整洁", "is_correct": false, "explanation": "整洁指干净整齐，与“动乱”没有反义关系。"}, {"text": "富裕", "is_correct": false, "explanation": "富裕指钱财充足，与“动乱”的意思无关，不构成反义。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮指光线充足、亮堂，与“动乱”没有反义关系。"}], "correct_answer": "安定", "explanations": {"安定": "安定指社会稳定、局势平静，与“动乱”意思相反。", "整洁": "整洁指干净整齐，与“动乱”没有反义关系。", "富裕": "富裕指钱财充足，与“动乱”的意思无关，不构成反义。", "明亮": "明亮指光线充足、亮堂，与“动乱”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87310, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "社会秩序混乱不安、局势动荡的状况。", "primary_collocate": null, "pronunciation": "dòng luàn", "ipa": "tʊŋ˥˩ lwan˥˩", "syllable_count": 2, "sentences": [{"text": "那个国家发生了动乱，很多人离开了。", "target_word": "动乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争带来了长期的动乱。", "target_word": "动乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动乱结束后，人们的生活慢慢好起来。", "target_word": "动乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在动乱的年代，很多孩子不能上学。", "target_word": "动乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府想尽快平息这场动乱。", "target_word": "动乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动乱让城市里的商店都关门了。", "target_word": "动乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在动乱中失去了家人。", "target_word": "动乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场动乱持续了三年。", "target_word": "动乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济不好，社会就容易出现动乱。", "target_word": "动乱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，那里的动乱已经停止了。", "target_word": "动乱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "動亂", "label": "繁体"}], "register": "书面", "sense_fingerprint": "国家或社会长期不稳定、局势动荡的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b66f903-6f7d-4f96-9cc8-707587246b0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动乱", "is_correct": true, "explanation": "动乱指社会秩序混乱不安，与“发生”搭配，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“发生”后面接事件，不说“发生天气”，这里应填社会局势的动荡。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，不是事件，不能说“发生饺子”。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园是场所，不能作为事件发生，句子说不通。"}], "explanations": {"动乱": "动乱指社会秩序混乱不安，与“发生”搭配，符合句意。", "天气": "搭配：“发生”后面接事件，不说“发生天气”，这里应填社会局势的动荡。", "饺子": "语义：饺子是食物，不是事件，不能说“发生饺子”。", "公园": "语义：公园是场所，不能作为事件发生，句子说不通。"}, "sentence_index": 0, "correct_answer": "动乱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两人的动乱越来越激烈，谁也不肯让步。", "explanation": "这里应该用〈争执〉。“动乱”指国家或社会局势动荡，不用于两人之间的争执；两人争执要说“争执”。"}, {"text": "会议的安排出现了动乱，大家都不知道该去哪里开会。", "explanation": "这里应该用〈混乱〉。“动乱”指社会局势动荡，不用来形容会议安排乱；安排乱要说“混乱”。"}, {"text": "电影院里传来了动乱声，大家都回头看。", "explanation": "这里应该用〈喧哗〉。“动乱”指社会局势动荡，不用来形容电影院里的吵闹声；吵闹声要说“喧哗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动乱", "is_correct": true, "explanation": "动乱指社会局势动荡，“在…中”后接事件，符合句意。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不是会让人失去家人的社会局势，句子说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是能让人失去家人的情境。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日用品，不是事件，不能表示使人失去家人的情况。"}], "explanations": {"动乱": "动乱指社会局势动荡，“在…中”后接事件，符合句意。", "作业": "语义：作业是学习任务，不是会让人失去家人的社会局势，句子说不通。", "冰箱": "语义：冰箱是家电，不是能让人失去家人的情境。", "雨伞": "语义：雨伞是日用品，不是事件，不能表示使人失去家人的情况。"}, "sentence_index": 6, "correct_answer": "动乱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听到消息后，心里满是动乱，半天说不出话。", "explanation": "这里应该用〈惊慌〉。“动乱”指社会局势动荡，不用来形容人心里的惊慌；心里惊慌要说“惊慌”。"}, {"text": "他的话在会上引起了动乱，大家都愣住了。", "explanation": "这里应该用〈骚动〉。“动乱”指社会局势动荡，用于会上一阵小小的骚动不合适；这里应说“骚动”。"}, {"text": "两家公司之间的动乱，闹了好几年才解决。", "explanation": "这里应该用〈纠纷〉。“动乱”指国家或社会局势动荡，不用于公司之间的经济纠纷；公司之间的争议要说“纠纷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只动乱让很多村庄都变穷了。", "corrected_sentence": "一场动乱让很多村庄都变穷了。", "error_description": "错误：“一只动乱”。正确：“一场动乱”。“只”用于动物等，“动乱”是事件，量词应用“场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "动乱的后，很多工厂都关门了。", "corrected_sentence": "动乱之后，很多工厂都关门了。", "error_description": "错误：“动乱的后”。正确：“动乱之后”。表示“…以后”的时间结构要用“之”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87311, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不同", "is_correct": true, "explanation": "反义：“一致”指大家想法一样，“不同”指想法不一样。"}, {"text": "清晰", "is_correct": false, "explanation": "“清晰”说清楚、明白，与“一致”没有反义关系。"}, {"text": "漫长", "is_correct": false, "explanation": "“漫长”形容时间很长，与“一致”没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”形容质地，与“一致”没有反义关系。"}], "correct_answer": "不同", "explanations": {"不同": "反义：“一致”指大家想法一样，“不同”指想法不一样。", "清晰": "“清晰”说清楚、明白，与“一致”没有反义关系。", "漫长": "“漫长”形容时间很长，与“一致”没有反义关系。", "柔软": "“柔软”形容质地，与“一致”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
