INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87311, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一致是大家的想法或者做法都一样。", "primary_collocate": null, "pronunciation": "yí zhì", "ipa": "i˧˥ ʈʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "我们俩的想法很一致。", "target_word": "一致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的做法一致，所以很快就完成了。", "target_word": "一致", "complexity_tier": "T3", "furigana": "tā men de zuò fǎ yí zhì, suǒ yǐ hěn kuài jiù wán chéng le.", "sentence_source": "generated"}, {"text": "大家的看法一致，都想去海边。", "target_word": "一致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸和妈妈的意见一直很一致。", "target_word": "一致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和学生对这件事的想法一致吗？", "target_word": "一致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人说的话不太一致。", "target_word": "一致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们对买房子的想法完全一致。", "target_word": "一致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全家人的想法一致，都想养狗。", "target_word": "一致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话和做法一致，大家都相信他。", "target_word": "一致", "complexity_tier": "T3", "furigana": "tā de huà hé zuò fǎ yí zhì, dà jiā dōu xiāng xìn tā.", "sentence_source": "generated"}, {"text": "同学们的做法一致，都帮了他。", "target_word": "一致", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "大家的想法、做法都一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0966929-86ca-4ac4-8d16-7e9b2ba39e93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87311, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一致", "is_correct": true, "explanation": "yí（第二声）zhì（第四声），意思是大家的想法或做法相同。"}, {"text": "意志", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）声调不同，意思是意志。"}, {"text": "一直", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）、zhí（第二声）与 zhì（第四声）声调不同，意思是一直。"}, {"text": "遗址", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是遗址。"}, {"text": "移植", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，意思是移植。"}], "explanations": {"一致": "yí（第二声）zhì（第四声），意思是大家的想法或做法相同。", "意志": "yì（第四声）与 yí（第二声）声调不同，意思是意志。", "一直": "yì（第四声）与 yí（第二声）、zhí（第二声）与 zhì（第四声）声调不同，意思是一直。", "遗址": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是遗址。", "移植": "zhí（第二声）与 zhì（第四声）声调不同，意思是移植。"}, "sentence_index": null, "correct_answer": "一致"}, "level_3": {"options": [{"text": "一致", "is_correct": true, "explanation": "正确：“一致”说多人的想法相同，符合句意。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”形容味道，不能说想法很咸。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体形，不能用来形容想法。"}, {"text": "冰凉", "is_correct": false, "explanation": "语义：“冰凉”说的是温度，与“想法很”搭配不通。"}], "explanations": {"一致": "正确：“一致”说多人的想法相同，符合句意。", "咸": "搭配：“咸”形容味道，不能说想法很咸。", "高大": "体貌：“高大”形容人或物的体形，不能用来形容想法。", "冰凉": "语义：“冰凉”说的是温度，与“想法很”搭配不通。"}, "sentence_index": 0, "correct_answer": "一致"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和哥哥长得很一致。", "explanation": "这里应该用〈一样〉。“一致”说想法或做法相符，不用来描述长相。"}, {"text": "他一致地反对我们的计划。", "explanation": "这里想表达“一直”的意思，应说“他一直反对我们的计划”。“一致”指多人或多方的意见相符，只有“他”一个人时不能这样用。"}, {"text": "我们俩的关系很一致。", "explanation": "这里应该用〈融洽〉。“一致”用于意见、做法相符，不用来形容关系和睦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87311, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一致", "is_correct": true, "explanation": "yí（第二声）zhì（第四声），意思是大家的想法或做法相同。"}, {"text": "已知", "is_correct": false, "explanation": "yǐ（第三声）与 yí（第二声）、zhī（第一声）与 zhì（第四声）声调不同，意思是已知。"}, {"text": "一只", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）、zhī（第一声）与 zhì（第四声）声调不同，意思是一只。"}, {"text": "移植", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，意思是把东西移到别处种植或安装。"}, {"text": "益智", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）声调不同，意思是增益智力。"}], "explanations": {"一致": "yí（第二声）zhì（第四声），意思是大家的想法或做法相同。", "已知": "yǐ（第三声）与 yí（第二声）、zhī（第一声）与 zhì（第四声）声调不同，意思是已知。", "一只": "yì（第四声）与 yí（第二声）、zhī（第一声）与 zhì（第四声）声调不同，意思是一只。", "移植": "zhí（第二声）与 zhì（第四声）声调不同，意思是把东西移到别处种植或安装。", "益智": "yì（第四声）与 yí（第二声）声调不同，意思是增益智力。"}, "sentence_index": null, "correct_answer": "一致"}, "level_3": {"options": [{"text": "一致", "is_correct": true, "explanation": "正确：“一致”说想法相符，符合“完全”的修饰。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能说想法清脆。"}, {"text": "芬芳", "is_correct": false, "explanation": "语义：“芬芳”说气味，与“想法”不搭。"}, {"text": "笨重", "is_correct": false, "explanation": "搭配：“笨重”形容物体，不能说想法笨重。"}], "explanations": {"一致": "正确：“一致”说想法相符，符合“完全”的修饰。", "清脆": "搭配：“清脆”形容声音，不能说想法清脆。", "芬芳": "语义：“芬芳”说气味，与“想法”不搭。", "笨重": "搭配：“笨重”形容物体，不能说想法笨重。"}, "sentence_index": 6, "correct_answer": "一致"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这对双胞胎的样子很一致，连妈妈都分不清。", "explanation": "这里应该用〈相像〉。“一致”说想法或做法相符，不用来说样子相似。"}, {"text": "我们俩的身高很一致，都是一米七。", "explanation": "这里应该用〈一样高〉。“一致”不用来描述身高。"}, {"text": "我们班一致有三十人，大家都很友好。", "explanation": "这里应该用〈一共〉。“一致”表示相符，不表示总数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, mod