INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87311, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们俩的想法一致地，就一起去吧。", "corrected_sentence": "我们俩的想法一致了，就一起去吧。", "error_description": "错误：“一致”后面用了“地”。“一致”在这里作谓语，不能加“地”做状语；应说“想法一致了”，用“了”表示已经达到一致。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87311, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的做法一致地，所以很快完成了任务。", "corrected_sentence": "我们的做法一致了，所以很快完成了任务。", "error_description": "错误：“一致”后面用了“地”。“一致”在这里作谓语，不能加“地”做状语；应说“做法一致了”，用“了”表示已经达到一致。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87312, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不同", "is_correct": true, "explanation": "反义：“一致”指意见相同、没有分歧，“不同”指意见不一样。"}, {"text": "清晰", "is_correct": false, "explanation": "“清晰”说清楚、明白，与“一致”没有反义关系。"}, {"text": "漫长", "is_correct": false, "explanation": "“漫长”形容时间很长，与“一致”没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”形容质地，与“一致”没有反义关系。"}], "correct_answer": "不同", "explanations": {"不同": "反义：“一致”指意见相同、没有分歧，“不同”指意见不一样。", "清晰": "“清晰”说清楚、明白，与“一致”没有反义关系。", "漫长": "“漫长”形容时间很长，与“一致”没有反义关系。", "柔软": "“柔软”形容质地，与“一致”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
