INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87312, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有分歧；步调、意见等完全相同。", "primary_collocate": null, "pronunciation": "yí zhì", "ipa": "i˧˥ ʈʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "两国领导人的意见完全一致。", "target_word": "一致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队上下步调一致，赢了比赛。", "target_word": "一致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在这个问题上看法一致，很快做出了决定。", "target_word": "一致", "complexity_tier": "T3", "furigana": "tā men zài zhè ge wèn tí shàng kàn fǎ yí zhì, hěn kuài zuò chū le jué dìng.", "sentence_source": "generated"}, {"text": "会上大家意见一致，通过了计划。", "target_word": "一致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的目标一致，所以合作很顺利。", "target_word": "一致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动作要一致，不能有快有慢。", "target_word": "一致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家对新计划的意见完全一致，没有人反对。", "target_word": "一致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们对这件事的说法完全一致。", "target_word": "一致", "complexity_tier": "T3", "furigana": "wǒ men duì zhè jiàn shì de shuō fǎ wán quán yí zhì.", "sentence_source": "generated"}, {"text": "董事会成员的看法基本一致。", "target_word": "一致", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家步调一致，才能把事情做好。", "target_word": "一致", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "没有分歧，步调、意见完全相同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0966929-86ca-4ac4-8d16-7e9b2ba39e93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87312, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一致", "is_correct": true, "explanation": "yí（第二声）zhì（第四声），意思是没有分歧、意见完全相同。"}, {"text": "意志", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）声调不同，意思是意志。"}, {"text": "一直", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）、zhí（第二声）与 zhì（第四声）声调不同，意思是一直。"}, {"text": "遗址", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是遗址。"}, {"text": "移植", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，意思是移植。"}], "explanations": {"一致": "yí（第二声）zhì（第四声），意思是没有分歧、意见完全相同。", "意志": "yì（第四声）与 yí（第二声）声调不同，意思是意志。", "一直": "yì（第四声）与 yí（第二声）、zhí（第二声）与 zhì（第四声）声调不同，意思是一直。", "遗址": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是遗址。", "移植": "zhí（第二声）与 zhì（第四声）声调不同，意思是移植。"}, "sentence_index": null, "correct_answer": "一致"}, "level_3": {"options": [{"text": "一致", "is_correct": true, "explanation": "正确：“一致”说意见完全相同，符合句意。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能说意见很甜。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容体形，不能用来形容意见。"}, {"text": "冰凉", "is_correct": false, "explanation": "语义：“冰凉”说温度，与“意见完全”搭配不通。"}], "explanations": {"一致": "正确：“一致”说意见完全相同，符合句意。", "甜": "搭配：“甜”形容味道，不能说意见很甜。", "高大": "体貌：“高大”形容体形，不能用来形容意见。", "冰凉": "语义：“冰凉”说温度，与“意见完全”搭配不通。"}, "sentence_index": 0, "correct_answer": "一致"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这对双胞胎的长相很一致，连老师都分不清。", "explanation": "这里应该用〈相像〉。“一致”说想法或做法相符，不用来说长相。"}, {"text": "我们俩的关系很一致，已经好多年了。", "explanation": "这里应该用〈深厚〉。“一致”用于意见、做法相符，不用来形容关系。"}, {"text": "他一致地拒绝了我们的邀请。", "explanation": "这里想表达“一直”的意思，应说“他一直拒绝我们的邀请”。“一致”指多人或多方的态度相符，只有“他”一个人时不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87312, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "一致", "is_correct": true, "explanation": "yí（第二声）zhì（第四声），意思是步调、意见完全相同。"}, {"text": "已知", "is_correct": false, "explanation": "yǐ（第三声）与 yí（第二声）、zhī（第一声）与 zhì（第四声）声调不同，意思是已知。"}, {"text": "一只", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）、zhī（第一声）与 zhì（第四声）声调不同，意思是一只。"}, {"text": "移植", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，意思是把东西移到别处种植或安装。"}, {"text": "益智", "is_correct": false, "explanation": "yì（第四声）与 yí（第二声）声调不同，意思是增益智力。"}], "explanations": {"一致": "yí（第二声）zhì（第四声），意思是步调、意见完全相同。", "已知": "yǐ（第三声）与 yí（第二声）、zhī（第一声）与 zhì（第四声）声调不同，意思是已知。", "一只": "yì（第四声）与 yí（第二声）、zhī（第一声）与 zhì（第四声）声调不同，意思是一只。", "移植": "zhí（第二声）与 zhì（第四声）声调不同，意思是把东西移到别处种植或安装。", "益智": "yì（第四声）与 yí（第二声）声调不同，意思是增益智力。"}, "sentence_index": null, "correct_answer": "一致"}, "level_3": {"options": [{"text": "一致", "is_correct": true, "explanation": "正确：“一致”说大家意见完全相同、没有分歧，符合句意。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能说意见清脆。"}, {"text": "芬芳", "is_correct": false, "explanation": "语义：“芬芳”说气味，与“意见”无关。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”形容质地，不能说意见柔软。"}], "explanations": {"一致": "正确：“一致”说大家意见完全相同、没有分歧，符合句意。", "清脆": "搭配：“清脆”形容声音，不能说意见清脆。", "芬芳": "语义：“芬芳”说气味，与“意见”无关。", "柔软": "搭配：“柔软”形容质地，不能说意见柔软。"}, "sentence_index": 6, "correct_answer": "一致"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和朋友的身高很一致，都是一米六。", "explanation": "这里应该用〈一样高〉。“一致”不用来描述身高。"}, {"text": "他一致地吃完了一整盘饺子。", "explanation": "这里想表达“一口气”的意思，应说“他一口气吃完了一整盘饺子”。“一致”指多人或多方的行动相符，只有“他”一个人时不能这样用。"}, {"text": "这篇文章一致有五段，读起来很顺。", "explanation": "这里应该用〈一共〉。“一致”表示相符，不表示总数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国的领导人在这次会谈后意见一致地。", "corrected_sentence": "两国的领导人在这次会谈后意见一致了。", "error_description": "错误：“一致”后面用了“地”。“一致”在这里作谓语，不能加“地”；应说“意见一致了”，用“了”表示已经达到一致。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "球队的步调一致地，比赛赢了。", "corrected_sentence": "球队的步调一致了，比赛赢了。", "error_description": "错误：“一致”后面用了“地”。“一致”在这里作谓语，不能加“地”；应说“步调一致了”，用“了”表示已经达到一致。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
