INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87317, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "历史意义是这件事对后来的日子有很大的影响。", "primary_collocate": null, "pronunciation": "lì shǐ yì yì", "ipa": "li˥˩ ʂʅ˨˩˦ i˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "这件事很有历史意义。", "target_word": "历史意义", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师讲了这次会议的历史意义。", "target_word": "历史意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥有很大的历史意义。", "target_word": "历史意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道这一天的历史意义吗？", "target_word": "历史意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项政策对后来的发展有历史意义。", "target_word": "历史意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书记着一件有历史意义的事。", "target_word": "历史意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说这个决定很有历史意义。", "target_word": "历史意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不懂这个节日的历史意义。", "target_word": "历史意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛有没有历史意义？", "target_word": "历史意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，那次搬家对我们家有历史意义。", "target_word": "历史意义", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "某件事对后来的日子有很大影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83c1835b-777f-4252-a671-77d7f731f642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87317, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史意义", "is_correct": true, "explanation": "「历史意义」指事件对后来历史的重要影响，与“很有”搭配，符合句意。"}, {"text": "能力", "is_correct": false, "explanation": "语义：“这件事”本身不具备“能力”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“很有”后接的是分量、价值类名词，“体重”不能这样搭配。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：“年纪”指人的年龄，不能用于事情。"}], "explanations": {"历史意义": "「历史意义」指事件对后来历史的重要影响，与“很有”搭配，符合句意。", "能力": "语义：“这件事”本身不具备“能力”。", "体重": "搭配：“很有”后接的是分量、价值类名词，“体重”不能这样搭配。", "年纪": "语义：“年纪”指人的年龄，不能用于事情。"}, "sentence_index": 0, "correct_answer": "历史意义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的历史意义很大。", "explanation": "这里应该用〈力气〉。历史意义指事件对历史的重要影响，不能用来形容人的体力。"}, {"text": "这道数学题的历史意义很简单。", "explanation": "这里应该用〈答案〉。历史意义指事件对历史的重要影响，不指题目的答案。"}, {"text": "我弟弟的历史意义很好。", "explanation": "这里应该用〈成绩〉。历史意义指事件对历史的重要影响，不指学习的分数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87317, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历史意义", "is_correct": true, "explanation": "「历史意义」指决定对历史发展的重要影响，与“很有”搭配，符合句意。"}, {"text": "嗓子", "is_correct": false, "explanation": "语义：“决定”没有嗓子，不能“很有嗓子”。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“决定”没有身高，不能说“很有身高”。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：“决定”不是能留下脚印的东西，句中不能说“很有脚印”。"}], "explanations": {"历史意义": "「历史意义」指决定对历史发展的重要影响，与“很有”搭配，符合句意。", "嗓子": "语义：“决定”没有嗓子，不能“很有嗓子”。", "身高": "语义：“决定”没有身高，不能说“很有身高”。", "脚印": "语义：“决定”不是能留下脚印的东西，句中不能说“很有脚印”。"}, "sentence_index": 6, "correct_answer": "历史意义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆自行车的历史意义很快。", "explanation": "这里应该用〈速度〉。历史意义指事件对历史的重要影响，不能用来说明交通工具的快慢。"}, {"text": "这个面包的历史意义很香。", "explanation": "这里应该用〈香味〉。历史意义指事件对历史的重要影响，不能用来形容食物的气味。"}, {"text": "这杯咖啡的历史意义很烫。", "explanation": "这里应该用〈温度〉。历史意义指事件对历史的重要影响，不能用来形容饮料的冷热。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87317, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事很历史意义。", "corrected_sentence": "这件事有很大的历史意义。", "error_description": "程度副词“很”不能修饰名词“历史意义”，应说“有很大的历史意义”或“很有历史意义”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87317, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他明白了这件事历史意义。", "corrected_sentence": "他明白了这件事的历史意义。", "error_description": "定语漏“的”：“这件事”修饰“历史意义”时要加“的”，应为“这件事的历史意义”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
