INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87318, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某事件或人物对历史发展所起的重要作用与价值。", "primary_collocate": null, "pronunciation": "lì shǐ yì yì", "ipa": "li˥˩ ʂʅ˨˩˦ i˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "这场战争有重要的历史意义。", "target_word": "历史意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学者研究了这项发明的历史意义。", "target_word": "历史意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次改革具有历史意义。", "target_word": "历史意义", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位老人的工作有历史意义。", "target_word": "历史意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书里写过这个人物的历史意义。", "target_word": "历史意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长城的历史意义非常大。", "target_word": "历史意义", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们要看到这件事的历史意义。", "target_word": "历史意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的发现有很大的历史意义。", "target_word": "历史意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个条约的历史意义，大家都很清楚。", "target_word": "历史意义", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座古城对国家有历史意义。", "target_word": "历史意义", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "事件或人物对历史发展的重要作用与价值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83c1835b-777f-4252-a671-77d7f731f642') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87318, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史意义", "is_correct": true, "explanation": "「历史意义」指事件对历史发展的重要作用，与“重要的”搭配，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "语义：战争没有身高，不能说“重要的身高”。"}, {"text": "门牌号", "is_correct": false, "explanation": "语义：战争不是有门牌号的东西，句中不成立。"}, {"text": "嗓音", "is_correct": false, "explanation": "搭配：“重要的”一般修饰作用、影响类名词，“嗓音”不能这样搭配。"}], "explanations": {"历史意义": "「历史意义」指事件对历史发展的重要作用，与“重要的”搭配，符合句意。", "身高": "语义：战争没有身高，不能说“重要的身高”。", "门牌号": "语义：战争不是有门牌号的东西，句中不成立。", "嗓音": "搭配：“重要的”一般修饰作用、影响类名词，“嗓音”不能这样搭配。"}, "sentence_index": 0, "correct_answer": "历史意义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次事故的历史意义很严重。", "explanation": "这里应该用〈后果〉。历史意义指对历史发展的重要作用，不指事故的坏结果。"}, {"text": "这个孩子的历史意义增加了很多。", "explanation": "这里应该用〈体重〉。历史意义指事件或人物对历史发展的重要作用，不指人的体重。"}, {"text": "这种药的历史意义很苦。", "explanation": "这里应该用〈味道〉。历史意义指事件或人物对历史发展的重要作用，不指药的苦味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历史意义", "is_correct": true, "explanation": "「历史意义」指事件的重要价值，“看到……的历史意义”符合句意。"}, {"text": "地址", "is_correct": false, "explanation": "语义：“这件事”没有地址，不能“看到这件事的地址”来理解它。"}, {"text": "性别", "is_correct": false, "explanation": "语义：事件没有性别，句中不成立。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“这件事”没有味道，句中不成立。"}], "explanations": {"历史意义": "「历史意义」指事件的重要价值，“看到……的历史意义”符合句意。", "地址": "语义：“这件事”没有地址，不能“看到这件事的地址”来理解它。", "性别": "语义：事件没有性别，句中不成立。", "味道": "语义：“这件事”没有味道，句中不成立。"}, "sentence_index": 6, "correct_answer": "历史意义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条狗的历史意义很响。", "explanation": "这里应该用〈叫声〉。历史意义指事件或人物对历史发展的重要作用，不能用来形容声音的大小。"}, {"text": "这个苹果的历史意义很红。", "explanation": "这里应该用〈颜色〉。历史意义指事件或人物对历史发展的重要作用，不能用来形容物体的颜色。"}, {"text": "这辆车的历史意义很快。", "explanation": "这里应该用〈速度〉。历史意义指事件或人物对历史发展的重要作用，不能用来形容车的快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次会议很历史意义。", "corrected_sentence": "这次会议有很大的历史意义。", "error_description": "程度副词“很”不能修饰名词“历史意义”，应说“有很大的历史意义”或“很有历史意义”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座桥被有历史意义。", "corrected_sentence": "这座桥有历史意义。", "error_description": "“有”表示拥有，不能用“被”引导，应去掉“被”，说“这座桥有历史意义”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4228f373-c193-47c6-a436-97b96b692f0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
