INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87319, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动用是把东西拿出来用。", "primary_collocate": null, "pronunciation": "dòng yòng", "ipa": "tʊŋ˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我不想动用银行里的存款。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他动用了存了十年的钱买房子。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的备用粮食不到最后不能动用。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱只能在急用时动用。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生动用了药箱里的最后一瓶药。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，我们动用了仓库里的旧被子。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想动用妈妈留下的那笔钱。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些工具很贵，平时不要随便动用。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他动用自己的积蓄开了一家小店。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的救急物资，只有遇到危险才能动用。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "动用了", "label": "了体标"}, {"form": "动用过", "label": "过体标"}], "register": "正式", "sense_fingerprint": "动用+存款/储备/物资：把留存的东西拿出来用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1eb026d-f55f-4628-a2a2-eaf33fe1d183') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87319, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动用", "is_correct": true, "explanation": "正确。“动用”指把留存的存款拿出来用，与“银行里的存款”搭配，符合句意。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能支配“存款”，说“喝存款”不通。"}, {"text": "赚", "is_correct": false, "explanation": "语义：“赚”指获取收入，而“存款”已经存在银行里，与句意矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能支配“存款”，说“唱存款”搭配不当。"}], "explanations": {"动用": "正确。“动用”指把留存的存款拿出来用，与“银行里的存款”搭配，符合句意。", "喝": "搭配：“喝”不能支配“存款”，说“喝存款”不通。", "赚": "语义：“赚”指获取收入，而“存款”已经存在银行里，与句意矛盾。", "唱": "搭配：“唱”不能支配“存款”，说“唱存款”搭配不当。"}, "sentence_index": 0, "correct_answer": "动用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他动用了一个笑话来逗大家开心。", "explanation": "这里应该用〈讲〉。动用指拿出留存的钱物或资源来用，讲笑话要说〈讲〉。"}, {"text": "他动用了流利的英语和客人交谈。", "explanation": "这里应该用〈运用〉。动用指拿出留存的资金、物资来用，语言能力要说〈运用〉。"}, {"text": "我们经常动用这把剪刀剪纸。", "explanation": "这里应该用〈使用〉。动用指拿出留存或重要的资源，日常用一把剪刀要说〈使用〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87319, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动用", "is_correct": true, "explanation": "正确。“动用”指拿出留存的钱来用，与“妈妈留下的那笔钱”搭配，符合句意。"}, {"text": "迷路", "is_correct": false, "explanation": "语法：“迷路”是不及物动词，不能带“那笔钱”作宾语，句子不通。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”是责备他人，与“那笔钱”和“我想”的语境完全不合。"}, {"text": "盼望", "is_correct": false, "explanation": "配价：“盼望”后接的是事件或愿望，不能直接带“那笔钱”作宾语。"}], "explanations": {"动用": "正确。“动用”指拿出留存的钱来用，与“妈妈留下的那笔钱”搭配，符合句意。", "迷路": "语法：“迷路”是不及物动词，不能带“那笔钱”作宾语，句子不通。", "骂": "语义：“骂”是责备他人，与“那笔钱”和“我想”的语境完全不合。", "盼望": "配价：“盼望”后接的是事件或愿望，不能直接带“那笔钱”作宾语。"}, "sentence_index": 6, "correct_answer": "动用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家动用了丰盛的晚餐。", "explanation": "这里应该用〈享用〉。动用指把留存的钱物拿出来用，吃丰盛的晚餐要说〈享用〉。"}, {"text": "我动用了朋友的一把雨伞。", "explanation": "这里应该用〈借用〉。动用指把自己留存的钱物拿出来用，向朋友借一把雨伞要说〈借用〉。"}, {"text": "他动用了老板的热情招待。", "explanation": "这里应该用〈享受〉。动用用于资源，热情招待是享受的对象，要说〈享受〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87319, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她动用了珍藏的那瓶酒了招待客人。", "corrected_sentence": "她动用了珍藏的那瓶酒招待客人。", "error_description": "错误：句中多出一个“了”。“动用了”已表示完成，宾语“珍藏的那瓶酒”后不应再加“了”，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87319, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她动用了那笔奖金了买新冰箱。", "corrected_sentence": "她动用了那笔奖金买新冰箱。", "error_description": "错误：句中多出一个“了”。“动用了”已表示完成，宾语“那笔奖金”后不应再加“了”，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
