INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87320, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使用（人力、物力、资金等）。", "primary_collocate": null, "pronunciation": "dòng yòng", "ipa": "tʊŋ˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "公司动用了一百万资金开新店。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了救火，政府动用了很多人力。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目动用了大量的物力和财力。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不想动用公司的备用资金。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警方动用了二十辆车去找孩子。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校动用经费修了一条新路。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们必须动用所有力量完成任务。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司动用全部人力赶这批货。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震后，国家动用军队帮助灾区。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院动用了最好的设备给他检查。", "target_word": "动用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "动用了", "label": "了体标"}, {"form": "动用过", "label": "过体标"}], "register": "正式", "sense_fingerprint": "动用+人力/物力/资金：调动使用大量资源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1eb026d-f55f-4628-a2a2-eaf33fe1d183') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87320, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动用", "is_correct": true, "explanation": "正确。“动用”指调用人力、物力、资金等资源，与“一百万资金”搭配，语体正式，符合句意。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”只能支配饮品，不能说“喝资金”，句子不通。"}, {"text": "捐", "is_correct": false, "explanation": "语义：“捐”指无偿赠予他人，与“公司开新店”的自用目的相矛盾。"}, {"text": "查", "is_correct": false, "explanation": "语义：“查”指检查、查看，与“一百万资金开新店”的句意不符。"}], "explanations": {"动用": "正确。“动用”指调用人力、物力、资金等资源，与“一百万资金”搭配，语体正式，符合句意。", "喝": "搭配：“喝”只能支配饮品，不能说“喝资金”，句子不通。", "捐": "语义：“捐”指无偿赠予他人，与“公司开新店”的自用目的相矛盾。", "查": "语义：“查”指检查、查看，与“一百万资金开新店”的句意不符。"}, "sentence_index": 0, "correct_answer": "动用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他动用了一句玩笑话来逗大家开心。", "explanation": "这里应该用〈讲〉。动用指调用人力、物力、资金等资源，讲玩笑话要说〈讲〉。"}, {"text": "他动用这个机会练习英语。", "explanation": "这里应该用〈利用〉。动用只用于人力、物力、资金等资源，抓住机会要用〈利用〉。"}, {"text": "他动用一支笔写完了作业。", "explanation": "这里应该用〈使用〉。动用指大规模调用资源，一支笔这样的日常用物要用〈使用〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87320, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动用", "is_correct": true, "explanation": "正确。“动用”指调用人力、物力等资源，与“所有力量”搭配，符合“完成任务”的语境。"}, {"text": "鼓励", "is_correct": false, "explanation": "搭配：“鼓励”针对人，不能说“鼓励所有力量”，搭配不当。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“完成任务”的目的相反，句意自相矛盾。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”意味着不再使用力量，与“完成任务”的要求相矛盾。"}], "explanations": {"动用": "正确。“动用”指调用人力、物力等资源，与“所有力量”搭配，符合“完成任务”的语境。", "鼓励": "搭配：“鼓励”针对人，不能说“鼓励所有力量”，搭配不当。", "放弃": "语义：“放弃”与“完成任务”的目的相反，句意自相矛盾。", "忘记": "语义：“忘记”意味着不再使用力量，与“完成任务”的要求相矛盾。"}, "sentence_index": 6, "correct_answer": "动用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他动用了那首歌的旋律来打动观众。", "explanation": "这里应该用〈运用〉。动用指调用人力、物力、资金等资源，旋律属于艺术手法，要说〈运用〉。"}, {"text": "这个方法动用了很大的作用。", "explanation": "这里应该用〈发挥〉。动用只用于人力、物力、资金等资源，作用要说〈发挥〉。"}, {"text": "我动用了同学的一块橡皮。", "explanation": "这里应该用〈借用〉。动用指调用大量或重要的资源，向同学借一块橡皮要用〈借用〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防队动用了几十名队员了去灭火。", "corrected_sentence": "消防队动用了几十名队员去灭火。", "error_description": "错误：句中多出一个“了”。“动用了”已表示完成，宾语“几十名队员”后不应再加“了”，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "抢修队动用了大批人力了抢修电路。", "corrected_sentence": "抢修队动用了大批人力抢修电路。", "error_description": "错误：句中多出一个“了”。“动用了”已表示完成，宾语“大批人力”后不应再加“了”，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
