INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87321, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "杀进是一下子冲进去打。", "primary_collocate": null, "pronunciation": "shā jìn", "ipa": "ʂa˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "战士们从大门杀进了城里。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一脚踢开门，杀进屋里。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人太多，我们没法杀进去。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一队骑兵杀进了敌人的营地。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个武士一个人杀进了敌人的大营。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举着刀，杀进了人群里。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人守着门，我们怎么杀进来？", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天还没亮，他们就杀进了村子。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里，英雄一个人杀进了坏人的家。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家喊着口号，杀进了对方的阵地。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "杀进了", "label": "完成体"}, {"form": "杀进过", "label": "经历体"}, {"form": "杀进去", "label": "趋向补语"}, {"form": "杀进来", "label": "趋向补语"}, {"form": "殺進", "label": "繁体"}], "register": "口语", "sense_fingerprint": "战斗或打斗中猛地冲进某处（城、屋、营地、人群）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157c64-73c7-4e54-9585-b5a2f818129e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87321, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "杀进", "is_correct": true, "explanation": "正确答案。杀进（shā jìn）指战斗中猛冲进入某处。"}, {"text": "傻劲", "is_correct": false, "explanation": "shǎ（第三声）与 shā（第一声）声调不同，意思是傻劲，指傻乎乎的劲头。"}, {"text": "沙金", "is_correct": false, "explanation": "jīn（第一声）与 jìn（第四声）声调不同，意思是沙金，指沙子里的金。"}, {"text": "扎进", "is_correct": false, "explanation": "zhā 与 shā 声母不同（zh 与 sh），意思是扎进，指刺入。"}], "explanations": {"杀进": "正确答案。杀进（shā jìn）指战斗中猛冲进入某处。", "傻劲": "shǎ（第三声）与 shā（第一声）声调不同，意思是傻劲，指傻乎乎的劲头。", "沙金": "jīn（第一声）与 jìn（第四声）声调不同，意思是沙金，指沙子里的金。", "扎进": "zhā 与 shā 声母不同（zh 与 sh），意思是扎进，指刺入。"}, "sentence_index": null, "correct_answer": "杀进"}, "level_3": {"options": [{"text": "杀进", "is_correct": true, "explanation": "正确。战士们从大门猛冲进城，符合“战斗中猛冲进入”的意思。"}, {"text": "驶入", "is_correct": false, "explanation": "搭配：“驶入”一般用于车船，不能用来说战士步行进城。"}, {"text": "送进", "is_correct": false, "explanation": "配价：“送进”要带受送的对象，句中缺少宾语，“送进城里”不成立。"}, {"text": "飞进", "is_correct": false, "explanation": "语义：战士不会飞，“飞进”与句中描写的进城情境矛盾。"}], "explanations": {"杀进": "正确。战士们从大门猛冲进城，符合“战斗中猛冲进入”的意思。", "驶入": "搭配：“驶入”一般用于车船，不能用来说战士步行进城。", "送进": "配价：“送进”要带受送的对象，句中缺少宾语，“送进城里”不成立。", "飞进": "语义：战士不会飞，“飞进”与句中描写的进城情境矛盾。"}, "sentence_index": 0, "correct_answer": "杀进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小猫趁门没关，杀进了厨房。", "explanation": "这里应该用〈溜进〉。杀进指猛冲进去、带有打斗义，悄悄进去要用溜进。"}, {"text": "这家人昨天杀进了新房子，还没收拾好东西。", "explanation": "这里应该用〈搬进〉。杀进指猛冲进去打，搬进新居要用搬进。"}, {"text": "孩子累了，杀进了被窝里就睡着了。", "explanation": "这里应该用〈钻进〉。杀进有猛冲、打斗的意味，钻进被窝要用钻进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87321, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "杀进", "is_correct": true, "explanation": "正确答案。杀进（shā jìn）指战斗中猛冲进入某处。"}, {"text": "撒进", "is_correct": false, "explanation": "sǎ（第三声）与 shā（第一声）声母、声调都相近但不同，意思是撒进，指把东西散落进去。"}, {"text": "插进", "is_correct": false, "explanation": "chā 与 shā 声母不同（ch 与 sh），意思是插进，指插入。"}, {"text": "闪进", "is_correct": false, "explanation": "韵母不同（shǎn 的韵母是 an，shā 是 a），声调也不同，意思是闪进，指突然溜入。"}], "explanations": {"杀进": "正确答案。杀进（shā jìn）指战斗中猛冲进入某处。", "撒进": "sǎ（第三声）与 shā（第一声）声母、声调都相近但不同，意思是撒进，指把东西散落进去。", "插进": "chā 与 shā 声母不同（ch 与 sh），意思是插进，指插入。", "闪进": "韵母不同（shǎn 的韵母是 an，shā 是 a），声调也不同，意思是闪进，指突然溜入。"}, "sentence_index": null, "correct_answer": "杀进"}, "level_3": {"options": [{"text": "杀进", "is_correct": true, "explanation": "正确。“坏人守着门”的情境下，“我们怎么杀进来”指强行冲入。"}, {"text": "吃进", "is_correct": false, "explanation": "语义：“吃进”指把东西咽下去，不能用来说人进入门里。"}, {"text": "飘进", "is_correct": false, "explanation": "语义：人不会飘，“飘进来”与句中守门的紧张情境不合。"}, {"text": "倒进", "is_correct": false, "explanation": "搭配：“倒进”的对象是液体，不能说“我们倒进来”。"}], "explanations": {"杀进": "正确。“坏人守着门”的情境下，“我们怎么杀进来”指强行冲入。", "吃进": "语义：“吃进”指把东西咽下去，不能用来说人进入门里。", "飘进": "语义：人不会飘，“飘进来”与句中守门的紧张情境不合。", "倒进": "搭配：“倒进”的对象是液体，不能说“我们倒进来”。"}, "sentence_index": 6, "correct_answer": "杀进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他看见朋友来了，杀进了屋里聊天。", "explanation": "这里应该用〈走进〉。杀进有猛攻、打斗的意味，朋友来了进屋聊天只说走进。"}, {"text": "老师杀进了教室。", "explanation": "这里应该用〈走进〉。杀进指猛攻进入，老师平常进教室只说走进。"}, {"text": "朋友下班回家，杀进了院子。", "explanation": "这里应该用〈走进〉。杀进有猛攻的意味，下班回家进院子只说走进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87321, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "士兵们从北门杀进着宫殿。", "corrected_sentence": "士兵们从北门杀进了宫殿。", "error_description": "体标错误：“杀进”描述一次已经完成的攻入，应接完成标记“了”，说“杀进了宫殿”；用“着”表示持续，与这次攻入不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87321, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都在屋里，敌人从门外杀进去，快关门！", "corrected_sentence": "我们都在屋里，敌人从门外杀进来，快关门！", "error_description": "趋向补语错误：说话人在屋里，敌人朝这边进入要用“进来”；“进去”表示朝远离说话人的方向进入，应说“杀进来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
