INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87322, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比赛中强势打入某个名次、轮次或区域。", "primary_collocate": null, "pronunciation": "shā jìn", "ipa": "ʂa˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "中国队杀进了决赛。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们连赢三场，杀进了四强。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位年轻选手第一次杀进总决赛。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队在最后十分钟杀进禁区，打进一球。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李杀进了网球比赛的第二轮。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的篮球队杀进了全市前八名。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁能杀进下一轮比赛，还不知道。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一路赢下来，杀进了半决赛。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王杀进了乒乓球比赛的前三名。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没人想到，这支小球队能杀进八强。", "target_word": "杀进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "杀进了", "label": "完成体"}, {"form": "杀进过", "label": "经历体"}, {"form": "杀进去", "label": "趋向补语"}, {"form": "殺進", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比赛中强势打入某个名次、轮次或区域（决赛、四强、禁区）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157c64-73c7-4e54-9585-b5a2f818129e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87322, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "杀进", "is_correct": true, "explanation": "正确答案。杀进（shā jìn）指比赛中强势打入某个名次或轮次。"}, {"text": "撒进", "is_correct": false, "explanation": "sǎ（第三声）与 shā（第一声）读音相近但不同，意思是撒进，指把东西散落进去。"}, {"text": "扎进", "is_correct": false, "explanation": "zhā 与 shā 声母不同（zh 与 sh），意思是扎进，指刺入。"}, {"text": "闪进", "is_correct": false, "explanation": "韵母不同（shǎn 的韵母是 an，shā 是 a），声调也不同，意思是闪进，指突然溜入。"}], "explanations": {"杀进": "正确答案。杀进（shā jìn）指比赛中强势打入某个名次或轮次。", "撒进": "sǎ（第三声）与 shā（第一声）读音相近但不同，意思是撒进，指把东西散落进去。", "扎进": "zhā 与 shā 声母不同（zh 与 sh），意思是扎进，指刺入。", "闪进": "韵母不同（shǎn 的韵母是 an，shā 是 a），声调也不同，意思是闪进，指突然溜入。"}, "sentence_index": null, "correct_answer": "杀进"}, "level_3": {"options": [{"text": "杀进", "is_correct": true, "explanation": "正确。“中国队___了决赛”要用表示晋级的“杀进”。"}, {"text": "淘汰", "is_correct": false, "explanation": "搭配：“淘汰”要带被淘汰的选手作宾语，不能说“淘汰了决赛”。"}, {"text": "推进", "is_correct": false, "explanation": "语义：“推进”指推动事物前进，不能用来说球队晋级，“推进了决赛”句意不通。"}, {"text": "逃入", "is_correct": false, "explanation": "语义：“逃入”是逃跑进入，与中国队晋级决赛的意思相反。"}], "explanations": {"杀进": "正确。“中国队___了决赛”要用表示晋级的“杀进”。", "淘汰": "搭配：“淘汰”要带被淘汰的选手作宾语，不能说“淘汰了决赛”。", "推进": "语义：“推进”指推动事物前进，不能用来说球队晋级，“推进了决赛”句意不通。", "逃入": "语义：“逃入”是逃跑进入，与中国队晋级决赛的意思相反。"}, "sentence_index": 0, "correct_answer": "杀进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班也杀进了运动会，大家都很高兴。", "explanation": "这里应该用〈参加〉。杀进表示在比赛中晋级、进入名次，只是报名或参加，不能说杀进。"}, {"text": "前锋在第八十分钟杀进一球，锁定了胜利。", "explanation": "这里应该用〈打进〉。杀进用于晋级或进入名次、区域，进球要说打进。"}, {"text": "我们最终杀进了奖杯。", "explanation": "这里应该用〈捧走〉。杀进指进入名次或轮次，拿到奖杯应说捧走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87322, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "杀进", "is_correct": true, "explanation": "正确答案。杀进（shā jìn）指比赛中强势打入某个名次或轮次。"}, {"text": "傻劲", "is_correct": false, "explanation": "shǎ（第三声）与 shā（第一声）声调不同，意思是傻劲，指傻乎乎的劲头。"}, {"text": "沙金", "is_correct": false, "explanation": "jīn（第一声）与 jìn（第四声）声调不同，意思是沙金，指沙子里的金。"}, {"text": "插进", "is_correct": false, "explanation": "chā 与 shā 声母不同（ch 与 sh），意思是插进，指插入。"}], "explanations": {"杀进": "正确答案。杀进（shā jìn）指比赛中强势打入某个名次或轮次。", "傻劲": "shǎ（第三声）与 shā（第一声）声调不同，意思是傻劲，指傻乎乎的劲头。", "沙金": "jīn（第一声）与 jìn（第四声）声调不同，意思是沙金，指沙子里的金。", "插进": "chā 与 shā 声母不同（ch 与 sh），意思是插进，指插入。"}, "sentence_index": null, "correct_answer": "杀进"}, "level_3": {"options": [{"text": "杀进", "is_correct": true, "explanation": "正确。“谁能___下一轮比赛”要用表示晋级的“杀进”。"}, {"text": "逃出", "is_correct": false, "explanation": "语义：“逃出”是逃跑离开，与下一轮比赛的晋级无关，句意不通。"}, {"text": "掉落", "is_correct": false, "explanation": "语义：“掉落”是下落，不能和“下一轮比赛”搭配，句意荒谬。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮料，不能说“喝下一轮比赛”。"}], "explanations": {"杀进": "正确。“谁能___下一轮比赛”要用表示晋级的“杀进”。", "逃出": "语义：“逃出”是逃跑离开，与下一轮比赛的晋级无关，句意不通。", "掉落": "语义：“掉落”是下落，不能和“下一轮比赛”搭配，句意荒谬。", "喝": "搭配：“喝”的对象是饮料，不能说“喝下一轮比赛”。"}, "sentence_index": 6, "correct_answer": "杀进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在关键时刻杀进了一场大胜。", "explanation": "这里应该用〈拿下〉。杀进表示进入名次或轮次，拿下一场大胜应说拿下。"}, {"text": "她杀进了一枚金牌。", "explanation": "这里应该用〈获得〉。杀进不能带奖牌作宾语，获得金牌要说获得。"}, {"text": "我们杀进了好成绩。", "explanation": "这里应该用〈取得〉。杀进表示进入名次，取得成绩要说取得。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors 