INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "中国队最终杀进去了决赛。", "corrected_sentence": "中国队最终杀进了决赛。", "error_description": "趋向补语错误：晋级义的“杀进”后不接趋向补语“去”；“杀进去了决赛”不成立，应说“杀进了决赛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们队一路赢下来，终于杀进着八强。", "corrected_sentence": "我们队一路赢下来，终于杀进了八强。", "error_description": "体标错误：“杀进八强”是已经完成的晋级，应接完成标记“了”，说“杀进了八强”；用“着”表示持续，与已经晋级的结果不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
