INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87323, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "卡片是又小又薄的硬纸片。上面可以写字，也可以画画。", "primary_collocate": null, "pronunciation": "kǎ piàn", "ipa": "kʰa˨˩ pʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "孩子在卡片上画了一只小猫。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用彩笔在卡片上写了名字。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张卡片很薄，也很硬。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每个学生发了一张白卡片。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把卡片剪成了小小的星星。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上有一盒彩色卡片，孩子们都爱画画。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在卡片的背面写了几个字。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在卡片上画一朵花。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些卡片是用硬纸做的，不容易坏。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹正在给卡片涂上红色。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "套", "label": "量词"}], "register": "中性", "sense_fingerprint": "又小又薄的硬纸片，可写字画画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b66f903-6f7d-4f96-9cc8-707587246b0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87323, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "卡片", "is_correct": true, "explanation": "卡片是又小又薄的硬纸片，可以画画，“在…上画”的对象是它，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是看不见的气体，不能作为画画的载体。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光线形成的暗影，不能被画上一只小猫。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“在…上画”的对象应是能承载画面的物体，“天气”不能作画面。"}], "explanations": {"卡片": "卡片是又小又薄的硬纸片，可以画画，“在…上画”的对象是它，符合句意。", "空气": "语义：空气是看不见的气体，不能作为画画的载体。", "影子": "语义：影子是光线形成的暗影，不能被画上一只小猫。", "天气": "搭配：“在…上画”的对象应是能承载画面的物体，“天气”不能作画面。"}, "sentence_index": 0, "correct_answer": "卡片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在卡片上写了三页长信。", "explanation": "这里应该用〈信纸〉。卡片又小又薄，写不下三页长信；长信要用信纸。"}, {"text": "天冷了，他把卡片盖在身上睡觉。", "explanation": "这里应该用〈被子〉。卡片又小又薄，只用来写字画画，不能盖在身上保暖；盖着睡觉要用被子。"}, {"text": "这张卡片有一米多宽，能盖住整张桌子。", "explanation": "这里应该用〈卡纸〉。卡片又小又薄，不可能有一米多宽；大幅的硬纸要用卡纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87323, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "卡片", "is_correct": true, "explanation": "卡片可以写字，“在…的背面写字”说的正是这种纸片，符合句意。"}, {"text": "火焰", "is_correct": false, "explanation": "语义：火焰没有背面，不能在上面写字。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是声音作品，不是能写字的载体，句子说不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“的背面”接的应是实物，“时间”不能这样用。"}], "explanations": {"卡片": "卡片可以写字，“在…的背面写字”说的正是这种纸片，符合句意。", "火焰": "语义：火焰没有背面，不能在上面写字。", "歌曲": "语义：歌曲是声音作品，不是能写字的载体，句子说不通。", "时间": "搭配：“的背面”接的应是实物，“时间”不能这样用。"}, "sentence_index": 6, "correct_answer": "卡片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用卡片把水烧开了。", "explanation": "这里应该用〈锅〉。卡片是薄纸片，不耐火，烧水要用锅。"}, {"text": "他把一沓厚厚的书稿装进了卡片里。", "explanation": "这里应该用〈纸箱〉。卡片又小又薄，装不下一沓厚书稿；装这样的大件要用纸箱。"}, {"text": "他用卡片擦了擦桌子。", "explanation": "这里应该用〈纸巾〉。卡片用来写字画画，不能用来擦桌子，擦桌子要用纸巾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87323, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在一本卡片上写下了生日祝福。", "corrected_sentence": "她在一张卡片上写下了生日祝福。", "error_description": "错误：“一本卡片”。正确：“一张卡片”。“本”用于书籍等，卡片是纸片，量词应用“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87323, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她送给我一把生日卡片。", "corrected_sentence": "她送给我一张生日卡片。", "error_description": "错误：“一把生日卡片”。正确：“一张生日卡片”。“把”用于有柄的东西，卡片是扁平的纸片，量词应用“张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
