INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87324, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用硬纸等制成的小片，用来记录资料或传达信息。", "primary_collocate": null, "pronunciation": "kǎ piàn", "ipa": "kʰa˨˩ pʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "图书馆的卡片上写着书的名字和编号。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用卡片记下了每个学生的电话。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友生日时，我寄了一张祝福卡片。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生在卡片上记录了病人的情况。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的姓名写在这张卡片上。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在卡片上写了地址，放进信封里。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里夹着一张卡片，上面写着谢谢。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把新学的词记在小卡片上。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花店的卡片上写着送花人的话。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议桌上放着每个人的名字卡片。", "target_word": "卡片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "套", "label": "量词"}], "register": "中性", "sense_fingerprint": "用来记录资料或传达信息的小纸片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b66f903-6f7d-4f96-9cc8-707587246b0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87324, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "卡片", "is_correct": true, "explanation": "卡片是写有信息的小纸片，图书馆的卡片上写书名和编号，符合句意。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“上写着”要接纸张或标签类的物件，饮料不能写字。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不能用来记录书的名字和编号。"}, {"text": "地板", "is_correct": false, "explanation": "语义：地板是建筑部件，不能像卡片那样记录书目信息。"}], "explanations": {"卡片": "卡片是写有信息的小纸片，图书馆的卡片上写书名和编号，符合句意。", "饮料": "搭配：“上写着”要接纸张或标签类的物件，饮料不能写字。", "饼干": "语义：饼干是食品，不能用来记录书的名字和编号。", "地板": "语义：地板是建筑部件，不能像卡片那样记录书目信息。"}, "sentence_index": 0, "correct_answer": "卡片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生在卡片上记录了整整五十页的内容。", "explanation": "这里应该用〈病历本〉。卡片只能记录简单信息，记几十页的内容要用病历本。"}, {"text": "店主在卡片上记了厚厚的一百页账。", "explanation": "这里应该用〈账本〉。卡片只能记录简单信息，记一百页的账要用账本。"}, {"text": "护士用卡片量了病人的体温。", "explanation": "这里应该用〈体温计〉。量体温要用体温计，卡片只用来记录信息，不能用来量体温。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "卡片", "is_correct": true, "explanation": "卡片是可以夹在书里、写有字的小纸片，“夹着一张…上面写着谢谢”说的正是它，符合句意。"}, {"text": "桌布", "is_correct": false, "explanation": "语义：桌布是铺在桌上的布，不能夹在书里还写上字句。"}, {"text": "地毯", "is_correct": false, "explanation": "搭配：“书里夹着”接的应是薄小的纸片类物件，“地毯”太大，不能这样用。"}, {"text": "床单", "is_correct": false, "explanation": "语义：床单是寝具，不能夹在书里，句子说不通。"}], "explanations": {"卡片": "卡片是可以夹在书里、写有字的小纸片，“夹着一张…上面写着谢谢”说的正是它，符合句意。", "桌布": "语义：桌布是铺在桌上的布，不能夹在书里还写上字句。", "地毯": "搭配：“书里夹着”接的应是薄小的纸片类物件，“地毯”太大，不能这样用。", "床单": "语义：床单是寝具，不能夹在书里，句子说不通。"}, "sentence_index": 6, "correct_answer": "卡片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用卡片把窗户挡住了。", "explanation": "这里应该用〈硬纸板〉。卡片又小又薄，挡窗户要用硬纸板，卡片太小，不能用来挡窗户。"}, {"text": "这份报告有二十页，我全部写在一张卡片上。", "explanation": "这里应该用〈稿纸〉。卡片太小，写不下二十页的报告；长文要用稿纸。"}, {"text": "他把重要的话刻在卡片上。", "explanation": "这里应该用〈石碑〉。卡片是薄纸片，刻字要用石碑等硬物，卡片不能用来刻字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在一把卡片上记下了地址。", "corrected_sentence": "我在一张卡片上记下了地址。", "error_description": "错误：“一把卡片”。正确：“一张卡片”。“把”用于有柄的东西，卡片是扁平的纸片，量词应用“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把新地址写在一根卡片上，寄给了朋友。", "corrected_sentence": "我把新地址写在一张卡片上，寄给了朋友。", "error_description": "错误：“一根卡片”。正确：“一张卡片”。“根”用于细长的东西，卡片是扁平的纸片，量词应用“张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebc78897-d392-4d11-a1fd-dfee0fd58541') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87325, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
