INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87325, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "了事是很快做完一件事，做得不太认真，只求不再有事。", "primary_collocate": null, "pronunciation": "liǎo shì", "ipa": "ljɑʊ˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他随便擦了擦桌子就了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业太多，她写几个字就了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板让他重做，不能随便了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打扫房间不要草草了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他洗了洗脸就了事，没有洗澡。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做事要认真，不能只想快点了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了几句对不起，想就这样了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事太重要，不能马马虎虎了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟收拾玩具，把它们放进箱子里就了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她画画很认真，从来不会随便了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "草草了事", "label": "复合"}, {"form": "敷衍了事", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：随便很快做完，只求没事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96df1d2b-98d4-4058-aa95-b548c2ba3b98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87325, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "了事", "is_correct": true, "explanation": "正确：了事（liǎo shì）指随便做完、只求了结，是本题的目标词。"}, {"text": "小事", "is_correct": false, "explanation": "xiǎo（第三声）与 liǎo 声母不同（x 与 l），意思是小的事情，不是了事。"}, {"text": "料事", "is_correct": false, "explanation": "liào（第四声）与 liǎo（第三声）声调不同，意思是预先估计事情。"}, {"text": "老是", "is_correct": false, "explanation": "lǎo 与 liǎo 只差中间的 i 音，意思是总是、一直，听感接近但意思不同。"}], "explanations": {"了事": "正确：了事（liǎo shì）指随便做完、只求了结，是本题的目标词。", "小事": "xiǎo（第三声）与 liǎo 声母不同（x 与 l），意思是小的事情，不是了事。", "料事": "liào（第四声）与 liǎo（第三声）声调不同，意思是预先估计事情。", "老是": "lǎo 与 liǎo 只差中间的 i 音，意思是总是、一直，听感接近但意思不同。"}, "sentence_index": null, "correct_answer": "了事"}, "level_3": {"options": [{"text": "了事", "is_correct": true, "explanation": "正确：了事指随便做完、不求好，与“随便擦了擦桌子”的语境一致。"}, {"text": "生病", "is_correct": false, "explanation": "语义：擦桌子与生病没有因果关系，句意不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：擦完桌子就结婚，与句中“随便擦了擦”的语境毫无关联。"}, {"text": "认真", "is_correct": false, "explanation": "语法：“认真”是形容词，不能这样放在“就”后面作结尾，而且与“随便”的意思相反。"}], "explanations": {"了事": "正确：了事指随便做完、不求好，与“随便擦了擦桌子”的语境一致。", "生病": "语义：擦桌子与生病没有因果关系，句意不通。", "结婚": "语义：擦完桌子就结婚，与句中“随便擦了擦”的语境毫无关联。", "认真": "语法：“认真”是形容词，不能这样放在“就”后面作结尾，而且与“随便”的意思相反。"}, "sentence_index": 0, "correct_answer": "了事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对每个细节都反复检查，一丝不苟地了事。", "explanation": "这里应该用〈完成〉。了事指草草做完、只求不再有事，与“一丝不苟”的态度相矛盾。"}, {"text": "他对这份工作尽心尽力，认真地了事，不肯有半点马虎。", "explanation": "这里应该用〈完成〉。了事指草草做完、只求不再有事，与“尽心尽力”的态度相矛盾。"}, {"text": "他把每一个细节都反复推敲，精益求精地了事。", "explanation": "这里应该用〈完成〉。了事指草草做完，与“精益求精”的要求正相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87325, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "了事", "is_correct": true, "explanation": "正确：了事指草草了结，与“想就这样”的意图相符。"}, {"text": "出发", "is_correct": false, "explanation": "语义：出发是离开某地，与“想就这样了事”的意思不符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：说了几句对不起就去睡觉，与句中的意图不通。"}, {"text": "冷战", "is_correct": false, "explanation": "语义：冷战指互不理睬，与“想就这样了事”的结局不一致。"}], "explanations": {"了事": "正确：了事指草草了结，与“想就这样”的意图相符。", "出发": "语义：出发是离开某地，与“想就这样了事”的意思不符。", "睡觉": "语义：说了几句对不起就去睡觉，与句中的意图不通。", "冷战": "语义：冷战指互不理睬，与“想就这样了事”的结局不一致。"}, "sentence_index": 6, "correct_answer": "了事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的零件已经全部了事。", "explanation": "这里应该用〈装好〉。了事指事情草草结束，不能用于机器零件。"}, {"text": "他对每位顾客都很认真，每次服务都全心全意地了事。", "explanation": "这里应该用〈完成〉。了事指草草做完，与“全心全意”的态度相矛盾。"}, {"text": "他对这份工作非常热爱，每天都精心打磨，每一处细节都力求完美地了事。", "explanation": "这里应该用〈完成〉。了事指草草做完，与“力求完美”的要求相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87325, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他随便整理了一下就了事了事。", "corrected_sentence": "他随便整理了一下就了事。", "error_description": "错误：“了事”重复出现了两次；正确：只说“就了事”。“了事”本身已是完整的动词，不能再接一个“了事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87325, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做作业一向很认真，从来不草草了事了。", "corrected_sentence": "他做作业一向很认真，从来不草草了事。", "error_description": "错误：句末多加了“了”；正确：去掉句末“了”，说“从来不草草了事”。“从来”表示习惯，否定的习惯性动作后不能再加句末“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
