INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87326, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把事情结束；多指敷衍着办完。", "primary_collocate": null, "pronunciation": "liǎo shì", "ipa": "ljɑʊ˨˩˦ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "经理想给客人一点钱了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用一句道歉了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说，不能只罚点钱了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校不能只开个会就了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他赔了点钱，想这样了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师只批评了几句，就了事了。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司对这次错误只说了声抱歉就了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说：别想随便道个歉就了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想花钱了事，可是邻居不同意。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的问题，不能只靠几句话了事。", "target_word": "了事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "敷衍了事", "label": "复合"}, {"form": "草草了事", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：把事情敷衍着办完结束", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96df1d2b-98d4-4058-aa95-b548c2ba3b98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87326, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "了事", "is_correct": true, "explanation": "正确：了事（liǎo shì）指敷衍着了结事情，是本题的目标词。"}, {"text": "小事", "is_correct": false, "explanation": "xiǎo（第三声）与 liǎo 声母不同（x 与 l），意思是小的事情，不是了事。"}, {"text": "料事", "is_correct": false, "explanation": "liào（第四声）与 liǎo（第三声）声调不同，意思是预先估计事情。"}, {"text": "老是", "is_correct": false, "explanation": "lǎo 与 liǎo 只差中间的 i 音，意思是总是、一直，听感接近但意思不同。"}], "explanations": {"了事": "正确：了事（liǎo shì）指敷衍着了结事情，是本题的目标词。", "小事": "xiǎo（第三声）与 liǎo 声母不同（x 与 l），意思是小的事情，不是了事。", "料事": "liào（第四声）与 liǎo（第三声）声调不同，意思是预先估计事情。", "老是": "lǎo 与 liǎo 只差中间的 i 音，意思是总是、一直，听感接近但意思不同。"}, "sentence_index": null, "correct_answer": "了事"}, "level_3": {"options": [{"text": "了事", "is_correct": true, "explanation": "正确：了事指用钱或几句话把事情了结，与句中“想给一点钱”的语境相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：给客人一点钱与唱歌没有关系，句意不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：给钱和散步不能组成合理的因果，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：给客人一点钱之后去睡觉，与“经理想给客人一点钱”的处理方式无关，句意不通。"}], "explanations": {"了事": "正确：了事指用钱或几句话把事情了结，与句中“想给一点钱”的语境相符。", "唱歌": "语义：给客人一点钱与唱歌没有关系，句意不通。", "散步": "语义：给钱和散步不能组成合理的因果，句意不通。", "睡觉": "语义：给客人一点钱之后去睡觉，与“经理想给客人一点钱”的处理方式无关，句意不通。"}, "sentence_index": 0, "correct_answer": "了事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他真诚地了事，希望得到原谅。", "explanation": "这里应该用〈道歉〉。了事指敷衍着了结，与“真诚”矛盾，不能用在这里。"}, {"text": "这台机器要认真了事，不能马虎。", "explanation": "这里应该用〈修理〉。了事指草草结束，不能用于认真地修理机器。"}, {"text": "他满怀热情地了事，希望把这件事做到最好。", "explanation": "这里应该用〈完成〉。了事指敷衍着办完，与“满怀热情”和“做到最好”的要求相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87326, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "了事", "is_correct": true, "explanation": "正确：了事指敷衍着了结，与“只说了声抱歉”的做法相符。"}, {"text": "出差", "is_correct": false, "explanation": "语义：说了声抱歉就出差，与句中的处理方式无关，句意不通。"}, {"text": "画画", "is_correct": false, "explanation": "语义：道歉之后画画，与公司对错误的处理毫无关联。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：说了声抱歉就跑步，与句子讲的处理错误的方式不符。"}], "explanations": {"了事": "正确：了事指敷衍着了结，与“只说了声抱歉”的做法相符。", "出差": "语义：说了声抱歉就出差，与句中的处理方式无关，句意不通。", "画画": "语义：道歉之后画画，与公司对错误的处理毫无关联。", "跑步": "语义：说了声抱歉就跑步，与句子讲的处理错误的方式不符。"}, "sentence_index": 6, "correct_answer": "了事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们工作很认真，每天都在了事。", "explanation": "这里应该用〈干活〉。了事指敷衍着结束，与“认真”的工作态度相矛盾，不能用来描述日常干活。"}, {"text": "他每天都在办公室学习，认真了事。", "explanation": "这里应该用〈用功〉。了事表示敷衍着完事，与“认真”的学习态度相矛盾。"}, {"text": "我们吃完饭去公园了事。", "explanation": "这里应该用〈散步〉。了事指草草做完事情，不能用于休闲活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他赔了点钱就了事了事，没有负责到底。", "corrected_sentence": "他赔了点钱就了事，没有负责到底。", "error_description": "错误：“了事”重复出现了两次；正确：只说“就了事”。“了事”本身已是完整的动词，不能再接一个“了事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司只说了声抱歉就了事着。", "corrected_sentence": "公司只说了声抱歉就了事了。", "error_description": "错误：“了事着”；正确：“了事了”。“了事”表示事情结束，是完成的动作，不能用表示持续的“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
