INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87331, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "去重是把一样的东西只留下一个，别的拿走。", "primary_collocate": null, "pronunciation": "qù chóng", "ipa": "tɕʰy˥˩ ʈʂʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "表格里有两行一样的名字，请先去重。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机里有很多一样的照片，我想用软件去重。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名单做完后，老师让我们先去重再打印。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把客户的电话号码全部去重了。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据不去重，统计出来的人数就不对。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去重以后，一共还剩五十个名字。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先给这些邮箱地址去重，再发邮件。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不去重的话，同一个人会收到三封信。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正在给书单去重，一样的书只留一本。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件可以帮你快速去重。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "去重了", "label": "体标：完成"}, {"form": "去重过", "label": "体标：经历"}], "register": "中性", "sense_fingerprint": "把相同的项目只留一个，其余删除", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f650a73-b56c-4b35-a5aa-fa33d63c4ebd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87331, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "去重", "is_correct": true, "explanation": "正确：去重就是把相同的名字只留一个，正好对应“两行一样的名字”。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做菜，与表格和名字无关，句子说不通。"}, {"text": "煎", "is_correct": false, "explanation": "搭配：“煎”只用于食物，名字不能煎。"}, {"text": "缝补", "is_correct": false, "explanation": "语义：“缝补”指修补衣物，表格里的名字不能缝补。"}], "explanations": {"去重": "正确：去重就是把相同的名字只留一个，正好对应“两行一样的名字”。", "烹饪": "语义：“烹饪”指做菜，与表格和名字无关，句子说不通。", "煎": "搭配：“煎”只用于食物，名字不能煎。", "缝补": "语义：“缝补”指修补衣物，表格里的名字不能缝补。"}, "sentence_index": 0, "correct_answer": "去重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把手机里的旧短信全都去重了，一条不剩。", "explanation": "这里应该用〈删除〉。去重要留下一份，全都清掉、一条不剩要说删除。"}, {"text": "妈妈把衣柜去重得干干净净。", "explanation": "这里应该用〈整理〉。去重只指去掉重复的东西，收拾衣柜要说整理。"}, {"text": "这次谈话去重了我们的误会。", "explanation": "这里应该用〈消除〉。去重的对象必须是重复的东西，误会不能去重，要说消除。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87331, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "去重", "is_correct": true, "explanation": "正确：去重指去掉重复的地址，只保留一个，正好符合发邮件前的整理步骤。"}, {"text": "烘烤", "is_correct": false, "explanation": "语义：“烘烤”指用火加热食物，邮箱地址不能烘烤。"}, {"text": "熨烫", "is_correct": false, "explanation": "搭配：“熨烫”用于衣物、布料，不能用于地址。"}, {"text": "晾晒", "is_correct": false, "explanation": "语义：“晾晒”指把衣物等放在太阳下晒干，与邮箱地址无关。"}], "explanations": {"去重": "正确：去重指去掉重复的地址，只保留一个，正好符合发邮件前的整理步骤。", "烘烤": "语义：“烘烤”指用火加热食物，邮箱地址不能烘烤。", "熨烫": "搭配：“熨烫”用于衣物、布料，不能用于地址。", "晾晒": "语义：“晾晒”指把衣物等放在太阳下晒干，与邮箱地址无关。"}, "sentence_index": 6, "correct_answer": "去重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把重要的文件去重到了U盘里。", "explanation": "这里应该用〈备份〉。去重是去掉重复的内容、只留一份，把文件复制到别处保存要说备份。"}, {"text": "学校把这篇稿子的字数去重了一半。", "explanation": "这里应该用〈减少〉。去重只去掉重复的部分，不能按一半来减少字数，要说减少。"}, {"text": "编辑从这些文章里去重了三篇最好的。", "explanation": "这里应该用〈挑出〉。去重是去掉重复的内容、只留一份，从中挑出最好的几篇要说挑出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87331, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份名单我们先很去重，再打印。", "corrected_sentence": "这份名单我们先去重，再打印。", "error_description": "副词“很”不能修饰动作动词“去重”，应去掉“很”，说“先去重”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87331, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经把通讯录去重着。", "corrected_sentence": "他已经把通讯录去重了。", "error_description": "“已经”表示动作已经完成，应与“了”搭配，说“去重了”；“去重着”表示动作仍在持续，与“已经”矛盾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
