INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87332, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "去掉重复的内容，只保留一份。", "primary_collocate": null, "pronunciation": "qù chóng", "ipa": "tɕʰy˥˩ ʈʂʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这篇文章有些句子重复了，你要去重。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写报告前要先给参考文件去重。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业里相同的段落很多，老师用系统去重。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份名单去重以后，重复的名字只保留了一份。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用电脑给资料去重了，文件小了很多。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段话写了两遍，请你去重，只留一份。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "查资料时，网页上的内容常常要先去重。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "论文里的重复部分已经去重，只保留一份。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇稿子先去重，再交给编辑。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些文档去重后发给我。", "target_word": "去重", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "去重了", "label": "体标：完成"}, {"form": "去重过", "label": "体标：经历"}], "register": "中性", "sense_fingerprint": "删掉文字或资料中的重复部分，只留一份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f650a73-b56c-4b35-a5aa-fa33d63c4ebd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87332, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "去重", "is_correct": true, "explanation": "正确：去重就是去掉重复的句子，只留一份，正好对应“句子重复了”。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：“烘干”指用热力把湿的东西弄干，文章不能烘干。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：“缝补”用于衣物等，不能用于句子。"}, {"text": "煎", "is_correct": false, "explanation": "语义：“煎”指用油加热食物，文章不能煎。"}], "explanations": {"去重": "正确：去重就是去掉重复的句子，只留一份，正好对应“句子重复了”。", "烘干": "语义：“烘干”指用热力把湿的东西弄干，文章不能烘干。", "缝补": "搭配：“缝补”用于衣物等，不能用于句子。", "煎": "语义：“煎”指用油加热食物，文章不能煎。"}, "sentence_index": 0, "correct_answer": "去重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把文章里的错别字去重了。", "explanation": "这里应该用〈删去〉。去重只针对重复的内容，错别字不是重复的部分，要说删去。"}, {"text": "老师把作文里的语病去重了。", "explanation": "这里应该用〈修改〉。去重不改写内容，只去掉重复的部分，语病要说修改。"}, {"text": "他把这篇文章去重成了英文。", "explanation": "这里应该用〈翻译〉。去重是去掉重复的内容，把文章换成另一种语言要说翻译。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87332, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "去重", "is_correct": true, "explanation": "正确：去重指去掉网页里重复的内容，正好符合查资料时先整理的说法。"}, {"text": "烘烤", "is_correct": false, "explanation": "语义：“烘烤”指用火加热食物，网页内容不能烘烤。"}, {"text": "熨烫", "is_correct": false, "explanation": "搭配：“熨烫”用于衣物、布料，网页内容不能熨烫。"}, {"text": "晾晒", "is_correct": false, "explanation": "语义：“晾晒”指把东西放在太阳下晒干，与网页内容无关。"}], "explanations": {"去重": "正确：去重指去掉网页里重复的内容，正好符合查资料时先整理的说法。", "烘烤": "语义：“烘烤”指用火加热食物，网页内容不能烘烤。", "熨烫": "搭配：“熨烫”用于衣物、布料，网页内容不能熨烫。", "晾晒": "语义：“晾晒”指把东西放在太阳下晒干，与网页内容无关。"}, "sentence_index": 6, "correct_answer": "去重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些重复内容全部去重，一句都不留。", "explanation": "这里应该用〈全部删除〉。去重要留下一份，不能把重复的内容一句都不留。"}, {"text": "这篇稿子字数去重了一半。", "explanation": "这里应该用〈减少〉。去重只去掉重复的部分，不能按一半来减少字数。"}, {"text": "老师从这些作文里去重了两篇最长的。", "explanation": "这里应该用〈挑出〉。去重是去掉重复的内容、只留一份，从中挑出最长的几篇要说挑出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇稿子我们已经去重着。", "corrected_sentence": "这篇稿子我们已经去重了。", "error_description": "“已经”表示动作已经完成，应与“了”搭配，说“去重了”；“去重着”表示动作仍在持续，与“已经”矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些照片我还没去重了。", "corrected_sentence": "这些照片我还没去重。", "error_description": "“还没”否定动作已经发生，动词后不能再加“了”，应说“还没去重”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
