INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87333, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "全体是一个团体里所有的人。", "primary_collocate": null, "pronunciation": "quán tǐ", "ipa": "tɕʰyɛn˧˥ tʰi˨˩", "syllable_count": 2, "sentences": [{"text": "全体同学都参加了这次活动。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请全体员工明天八点到会议室。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师向全体学生问好。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全体队员在球场上热身。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议开始前，全体起立。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给全体职工发了新年礼物。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长要求全体老师参加培训。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全体村民一起修好了那座桥。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，全体队员向观众鞠躬。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我代表全体同学谢谢您。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全體", "label": "繁体"}], "register": "通用", "sense_fingerprint": "全体：一个团体里所有的人，常放在人员名词前，如“全体同学”“全体员工”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0966929-86ca-4ac4-8d16-7e9b2ba39e93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87333, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全体", "is_correct": true, "explanation": "“全体”指团体里所有的人，正好修饰“同学”，并与句中的“都”相呼应。"}, {"text": "个体", "is_correct": false, "explanation": "语义：“个体”指单独的一个人，与“都”所表示的全部相矛盾。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”是自然景物，不能修饰“同学”，也不能参加活动。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是物品，不能修饰“同学”，“桌子同学”不成话。"}], "explanations": {"全体": "“全体”指团体里所有的人，正好修饰“同学”，并与句中的“都”相呼应。", "个体": "语义：“个体”指单独的一个人，与“都”所表示的全部相矛盾。", "天空": "语义：“天空”是自然景物，不能修饰“同学”，也不能参加活动。", "桌子": "语义：“桌子”是物品，不能修饰“同学”，“桌子同学”不成话。"}, "sentence_index": 0, "correct_answer": "全体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把全体的钱都捐了。", "explanation": "这里应该用〈全部〉。“全体”只指一个团体里所有的人，钱不是人，修饰物品要用“全部”。"}, {"text": "全体的花都开了。", "explanation": "这里应该用〈所有〉。“全体”只指人的群体，花不能说“全体”，修饰物品要用“所有”。"}, {"text": "这座城市的全体规划很合理。", "explanation": "这里应该用〈整体〉。“全体”指成员的总和，规划是事物，不能用“全体”，要用“整体”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87333, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全体", "is_correct": true, "explanation": "“全体”指所有的老师，与“老师”搭配，符合“要求”的对象是一群人。"}, {"text": "教室", "is_correct": false, "explanation": "配价：“要求”的对象应是人，“教室”是场所，不能被要求参加培训。"}, {"text": "机器", "is_correct": false, "explanation": "语义：机器不能参加培训，与“老师”这类人员相矛盾。"}, {"text": "盆栽", "is_correct": false, "explanation": "语义：盆栽是植物，不能被要求参加培训，与“老师”不相符。"}], "explanations": {"全体": "“全体”指所有的老师，与“老师”搭配，符合“要求”的对象是一群人。", "教室": "配价：“要求”的对象应是人，“教室”是场所，不能被要求参加培训。", "机器": "语义：机器不能参加培训，与“老师”这类人员相矛盾。", "盆栽": "语义：盆栽是植物，不能被要求参加培训，与“老师”不相符。"}, "sentence_index": 6, "correct_answer": "全体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "全体房间都打扫干净了。", "explanation": "这里应该用〈整个〉。“全体”指一群人，房间不是人，修饰场所要用“整个”。"}, {"text": "这些苹果全体熟了。", "explanation": "这里应该用〈全都〉。“全体”是名词，指一群人，不能描述苹果成熟，要用副词“全都”。"}, {"text": "这些书全体都是他的。", "explanation": "这里应该用〈统统〉。“全体”只指一群人，书不是人，修饰物品要用“统统”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87333, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三个全体同学都去了操场。", "corrected_sentence": "全体同学都去了操场。", "error_description": "“全体”是指人群的名词，前面不能直接加数量词修饰，应说“全体同学”，不能说“三个全体同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87333, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "全体们员工都很努力工作。", "corrected_sentence": "全体员工都很努力工作。", "error_description": "“全体”本身已表示整体，后面不能再加“们”，应说“全体员工”，不能说“全体们员工”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87334, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "个人", "is_correct": true, "explanation": "“个人”与“全体”相对，指单独的一个人，是这一义项的反义词。"}, {"text": "季节", "is_correct": false, "explanation": "“季节”指一年中的时段，与“全体”的整体义没有对立关系。"}, {"text": "花园", "is_correct": false, "explanation": "“花园”是场所，与“全体”的整体义不构成对立，不是反义词。"}, {"text": "窗户", "is_correct": false, "explanation": "“窗户”是建筑部件，与“全体”的整体义不构成对立，不是反义词。"}], "correct_answer": "个人", "explanations": {"个人": "“个人”与“全体”相对，指单独的一个人，是这一义项的反义词。", "季节": "“季节”指一年中的时段，与“全体”的整体义没有对立关系。", "花园": "“花园”是场所，与“全体”的整体义不构成对立，不是反义词。", "窗户": "“窗户”是建筑部件，与“全体”的整体义不构成对立，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87334, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "部分", "is_correct": true, "explanation": "“部分”与“全体”相对，指整体中的一部分，是这一义项的反义词。"}, {"text": "文件", "is_correct": false, "explanation": "“文件”是纸质材料，与“全体”的整体义不构成对立，不是反义词。"}, {"text": "书包", "is_correct": false, "explanation": "“书包”是随身用品，与“全体”的整体义不构成对立，不是反义词。"}, {"text": "走廊", "is_correct": false, "explanation": "“走廊”是建筑空间，与“全体”的整体义不构成对立，不是反义词。"}], "correct_answer": "部分", "explanations": {"部分": "“部分”与“全体”相对，指整体中的一部分，是这一义项的反义词。", "文件": "“文件”是纸质材料，与“全体”的整体义不构成对立，不是反义词。", "书包": "“书包”是随身用品，与“全体”的整体义不构成对立，不是反义词。", "走廊": "“走廊”是建筑空间，与“全体”的整体义不构成对立，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87334, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "各个部分或所有成员的总和。", "primary_collocate": null, "pronunciation": "quán tǐ", "ipa": "tɕʰyɛn˧˥ tʰi˨˩", "syllable_count": 2, "sentences": [{"text": "个人要服从全体的利益。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次改革考虑的是全体的长远发展。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全体的力量比个人大得多。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个人离不开全体，全体也离不开个人。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部分和全体是分不开的。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们评价一个制度，要看它对全体的影响。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划兼顾了个人与全体的利益。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不只想着自己，也想着全体。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个人的进步离不开全体的帮助。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只看一个人不够，还要看全体的情况。", "target_word": "全体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全體", "label": "繁体"}], "register": "通用", "sense_fingerprint": "全体：由各个部分或所有成员合起来的整体，与个人、部分相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0966929-86ca-4ac4-8d16-7e9b2ba39e93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87334, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全体", "is_correct": true, "explanation": "“全体”指各成员的总和，与“个人”相对，正好作为“服从”的对象。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“利益”指人或组织的好处，不能与“时间”搭配。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人或群体，无法谈“服从”和“利益”。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是物品，不能成为“服从”的对象，也没有利益可言。"}], "explanations": {"全体": "“全体”指各成员的总和，与“个人”相对，正好作为“服从”的对象。", "时间": "搭配：“利益”指人或组织的好处，不能与“时间”搭配。", "天气": "语义：天气不是人或群体，无法谈“服从”和“利益”。", "沙发": "语义：沙发是物品，不能成为“服从”的对象，也没有利益可言。"}, "sentence_index": 0, "correct_answer": "全体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个系统的全体运行很稳定。", "explanation": "这里应该用〈整体〉。“全体”偏重各部分或成员的总和，描述“运行”这种整体过程要用“整体”。"}, {"text": "他的全体很健康。", "explanation": "这里应该用〈全身〉。“全体”指各部分的总和，指人的身体要用“全身”。"}, {"text": "这首歌我全体会唱。", "explanation": "这里应该用〈全都〉。“全体”是名词，指各成员的总和，不能作副词修饰“会唱”，要用“全都”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87334, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全体", "is_correct": true, "explanation": "“全体”与“个人”相对，正好与“兼顾”所涉及的两方面相配。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是物品，没有利益可言，与“个人与……的利益”不相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是人或群体，无法与“个人”相对并谈及利益。"}, {"text": "方向", "is_correct": false, "explanation": "搭配：“利益”指人或群体的好处，不能与“方向”搭配。"}], "explanations": {"全体": "“全体”与“个人”相对，正好与“兼顾”所涉及的两方面相配。", "手机": "语义：手机是物品，没有利益可言，与“个人与……的利益”不相符。", "颜色": "语义：颜色不是人或群体，无法与“个人”相对并谈及利益。", "方向": "搭配：“利益”指人或群体的好处，不能与“方向”搭配。"}, "sentence_index": 6, "correct_answer": "全体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份计划很全体。", "explanation": "这里应该用〈完整〉。“全体”是名词，不能直接用“很”修饰，应说“这份计划很完整”。"}, {"text": "我把作业全体做完了。", "explanation": "这里应该用〈全部〉。“全体”指成员的总和，不能修饰作业这类事情，要用“全部”。"}, {"text": "这本书的全体内容我都看了。", "explanation": "这里应该用〈全部〉。书的内容不是成员，不能说“全体内容”，要用“全部内容”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要关注全体全体的成长。", "corrected_sentence": "我们要关注全体的成长。", "error_description": "“全体”不能重复使用，应说“全体的成长”，不能说“全体全体的成长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个决定维护了全体们的利益。", "corrected_sentence": "这个决定维护了全体的利益。", "error_description": "“全体”后面不能再加“们”，应说“全体的利益”，不能说“全体们的利益”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '452e5ed5-3427-4f1f-a8ee-2474deeffc06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
