INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87335, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "反杀是被打的人反过来把对方打倒。", "primary_collocate": null, "pronunciation": "fǎn shā", "ipa": "fan˨˩˦ ʂa˥˥", "syllable_count": 2, "sentences": [{"text": "小偷先动手，没想到他反杀了。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏里敌人追着他打，他最后反杀了。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大孩子总打他，今天他终于反杀了。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里，弱小的主人公突然反杀坏人。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对手打了他三拳，他一拳就反杀了。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别以为我好欺负，我会反杀你的。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他挨了几拳后，突然反杀了对方。", "target_word": "反杀", "complexity_tier": "T3", "furigana": "tā āi le jǐ quán hòu, tū rán fǎn shā le duì fāng.", "sentence_source": "generated"}, {"text": "老虎扑向猎人，猎人却反杀了老虎。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是他们先动手，我才反杀的。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看他一直挨打，谁想到他能反杀。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反杀了", "label": "完成体"}, {"form": "反杀过", "label": "经验体"}], "register": "口语", "sense_fingerprint": "反杀：挨打的一方反过来打倒对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cfcb1-6d77-42d7-8839-f55207ff99d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87335, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反杀", "is_correct": true, "explanation": "正确答案：反杀，挨打的一方反过来把对方打倒。"}, {"text": "犯傻", "is_correct": false, "explanation": "犯傻读 fàn shǎ，两个字都与 fǎn shā 声调不同，意思是做蠢事。"}, {"text": "反伤", "is_correct": false, "explanation": "shāng 与 shā 韵母不同（ang 与 a），反伤意思是反过来造成伤害。"}, {"text": "砍杀", "is_correct": false, "explanation": "kǎn 与 fǎn 声母不同（k 与 f），砍杀意思是用刀砍死。"}], "explanations": {"反杀": "正确答案：反杀，挨打的一方反过来把对方打倒。", "犯傻": "犯傻读 fàn shǎ，两个字都与 fǎn shā 声调不同，意思是做蠢事。", "反伤": "shāng 与 shā 韵母不同（ang 与 a），反伤意思是反过来造成伤害。", "砍杀": "kǎn 与 fǎn 声母不同（k 与 f），砍杀意思是用刀砍死。"}, "sentence_index": null, "correct_answer": "反杀"}, "level_3": {"options": [{"text": "反杀", "is_correct": true, "explanation": "正确答案：反杀，“没想到他___了”表示被先动手的人反过来打倒了对方。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与“先动手”的情节无关，句子读起来不通。"}, {"text": "颁布", "is_correct": false, "explanation": "搭配：“颁布”只用于法令、命令，不能用于人。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与小偷先动手的打斗情节无关，句子读起来不通。"}], "explanations": {"反杀": "正确答案：反杀，“没想到他___了”表示被先动手的人反过来打倒了对方。", "吃饭": "语义：“吃饭”与“先动手”的情节无关，句子读起来不通。", "颁布": "搭配：“颁布”只用于法令、命令，不能用于人。", "唱歌": "语义：“唱歌”与小偷先动手的打斗情节无关，句子读起来不通。"}, "sentence_index": 0, "correct_answer": "反杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被骂了几句，就反杀了两句。", "explanation": "这里应该用〈反击〉。反杀指把对方打倒，不能用来说回嘴。"}, {"text": "对方的观点有漏洞，我马上反杀了他的观点。", "explanation": "这里应该用〈反驳〉。反驳用于观点、说法；反杀是动手打倒对方，不能用于辩论。"}, {"text": "他主动挑起了争端，然后反杀了对方。", "explanation": "这里应该用〈攻击〉。反杀的“反”表示被攻击后反过来击败，他是先挑起争端的一方，应该用〈攻击〉，不能说反杀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df95e100-f8a6-4de5-a7f9-cc8b779e0c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87335, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反杀", "is_correct": true, "explanation": "正确答案：反杀，挨了几拳后反过来打倒对方。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：挨了打之后“感谢”对方不合情理。"}, {"text": "嘉奖", "is_correct": false, "explanation": "语域：“嘉奖”是书面用语，且含表扬之意，与挨打的叙述相悖。"}, {"text": "招待", "is_correct": false, "explanation": "语义：挨了打后“招待”对方与情节不合。"}], "explanations": {"反杀": "正确答案：反杀，挨了几拳后反过来打倒对方。", "感谢": "语义：挨了打之后“感谢”对方不合情理。", "嘉奖": "语域：“嘉奖”是书面用语，且含表扬之意，与挨打的叙述相悖。", "招待": "语义：挨了打后“招待”对方与情节不合。"}, "sentence_index": 6, "correct_answer": "反杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那块石头突然反杀了他。", "explanation": "这里应该用〈砸〉。反杀的施事必须是有意识、能反击的人；石头是无生命的，只能说砸，不能说反杀。"}, {"text": "他把那张旧桌子反杀了。", "explanation": "这里应该用〈砸坏〉。反杀的对象必须是攻击他的人，桌子不能成为对手；把桌子弄坏应说〈砸坏〉。"}, {"text": "他把那碗饭反杀了。", "explanation": "这里应该用〈吃〉。反杀的对象必须是攻击他的人，饭不能成为对手；把饭吃掉应说〈吃〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df95e100-f8a6-4de5-a7f9-cc8b779e0c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87335, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他只用了一拳，就反杀着对手。", "corrected_sentence": "他只用了一拳，就反杀了对手。", "error_description": "错误：“反杀”后用“着”表示动作持续，与“只用了一拳就”的一次完成矛盾。正确应用“了”：反杀了对手。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df95e100-f8a6-4de5-a7f9-cc8b779e0c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87335, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他忍了很久，最后把对方反杀。", "corrected_sentence": "他忍了很久，最后把对方反杀了。", "error_description": "错误：“把”字句中动词“反杀”后缺少“了”，句子不完整。正确应为：他忍了很久，最后把对方反杀了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df95e100-f8a6-4de5-a7f9-cc8b779e0c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87336, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df95e100-f8a6-4de5-a7f9-cc8b779e0c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87336, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df95e100-f8a6-4de5-a7f9-cc8b779e0c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87336, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在被攻击时逆转局势，反过来击败或消灭对方。", "primary_collocate": null, "pronunciation": "fǎn shā", "ipa": "fan˨˩˦ ʂa˥˥", "syllable_count": 2, "sentences": [{"text": "我们队落后很多，最后反杀了对手。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个人围住了玩家，他却反杀了两人。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛇想吃小鸟，小鸟竟然反杀了蛇。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人以为他输定了，他却突然反杀。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛太精彩，红队最后一分钟反杀了对手。", "target_word": "反杀", "complexity_tier": "T3", "furigana": "zhè chǎng bǐ sài tài jīng cǎi, hóng duì zuì hòu yì fēn zhōng fǎn shā le duì shǒu.", "sentence_source": "generated"}, {"text": "这个游戏里，新手也有机会反杀高手。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直忍着，等到机会才反杀。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人拿刀冲过来，警察及时反杀了他。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对手攻得很猛，我们守住后立刻反杀。", "target_word": "反杀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们人多，可是我们还是反杀了他们。", "target_word": "反杀", "complexity_tier": "T3", "furigana": "tā men rén duō, kě shì wǒ men hái shi fǎn shā le tā men.", "sentence_source": "generated"}], "morphological_forms": [{"form": "反杀了", "label": "完成体"}, {"form": "反杀过", "label": "经验体"}], "register": "口语", "sense_fingerprint": "反杀：受攻击时逆转局势，击败对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cfcb1-6d77-42d7-8839-f55207ff99d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87336, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反杀", "is_correct": true, "explanation": "正确答案：反杀，受攻击时逆转局势，击败对方。"}, {"text": "犯傻", "is_correct": false, "explanation": "犯傻读 fàn shǎ，两个字都与 fǎn shā 声调不同，意思是做蠢事。"}, {"text": "反伤", "is_correct": false, "explanation": "shāng 与 shā 韵母不同（ang 与 a），反伤意思是反过来造成伤害。"}, {"text": "砍杀", "is_correct": false, "explanation": "kǎn 与 fǎn 声母不同（k 与 f），砍杀意思是用刀砍死。"}], "explanations": {"反杀": "正确答案：反杀，受攻击时逆转局势，击败对方。", "犯傻": "犯傻读 fàn shǎ，两个字都与 fǎn shā 声调不同，意思是做蠢事。", "反伤": "shāng 与 shā 韵母不同（ang 与 a），反伤意思是反过来造成伤害。", "砍杀": "kǎn 与 fǎn 声母不同（k 与 f），砍杀意思是用刀砍死。"}, "sentence_index": null, "correct_answer": "反杀"}, "level_3": {"options": [{"text": "反杀", "is_correct": true, "explanation": "正确答案：反杀，落后很多时反过来击败了对手。"}, {"text": "原谅", "is_correct": false, "explanation": "语义：比赛中落后时，“原谅”对手与反超的情节无关。"}, {"text": "宴请", "is_correct": false, "explanation": "语义：比赛落后时“宴请”对手不合逻辑。"}, {"text": "赢得", "is_correct": false, "explanation": "搭配：“赢得”的宾语是比赛、胜利，不能是“对手”。"}], "explanations": {"反杀": "正确答案：反杀，落后很多时反过来击败了对手。", "原谅": "语义：比赛中落后时，“原谅”对手与反超的情节无关。", "宴请": "语义：比赛落后时“宴请”对手不合逻辑。", "赢得": "搭配：“赢得”的宾语是比赛、胜利，不能是“对手”。"}, "sentence_index": 0, "correct_answer": "反杀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们落后三分，最后反杀了比分。", "explanation": "这里应该用〈逆转〉。逆转可以指扭转比分；反杀的对象只能是先攻击自己的对手，不能用于比分。"}, {"text": "他们一直在进攻，结果突然反杀了对方。", "explanation": "这里应该用〈攻击〉。反杀的“反”要求对方先动手；这里是他们主动发起攻击，应说〈攻击〉，不能说反杀。"}, {"text": "这场雨突然反杀了我们队。", "explanation": "这里应该用〈打乱〉。雨不能主动反击，它只能打乱比赛的节奏，不能说反杀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df95e100-f8a6-4de5-a7f9-cc8b779e0c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87336, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反杀", "is_correct": true, "explanation": "正确答案：反杀，忍到机会来了才反过来打倒对方。"}, {"text": "投降", "is_correct": false, "explanation": "语义：“投降”与“等到机会”的意图矛盾。"}, {"text": "求饶", "is_correct": false, "explanation": "语义：“求饶”与“忍着、等机会”的情节矛盾。"}, {"text": "拍照", "is_correct": false, "explanation": "语义：“拍照”与挨打、忍着等机会的情节无关，句子读起来不通。"}], "explanations": {"反杀": "正确答案：反杀，忍到机会来了才反过来打倒对方。", "投降": "语义：“投降”与“等到机会”的意图矛盾。", "求饶": "语义：“求饶”与“忍着、等机会”的情节矛盾。", "拍照": "语义：“拍照”与挨打、忍着等机会的情节无关，句子读起来不通。"}, "sentence_index": 6, "correct_answer": "反杀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一路冲锋，终于反杀了对方的阵地。", "explanation": "这里应该用〈攻占〉。攻占指夺取阵地；反杀的对象只能是打他的人，不能指阵地。"}, {"text": "他一脚把那扇门反杀了。", "explanation": "这里应该用〈踢〉。反杀的对象必须是攻击他的人，门不是对手；一脚踢门应说〈踢〉，不能说反杀。"}, {"text": "那块石头突然反杀了路人。", "explanation": "这里应该用〈砸伤〉。反杀的施事必须是有意识、能动手的人，石头是无生命的，只能砸伤路人，不能说反杀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df95e100-f8a6-4de5-a7f9-cc8b779e0c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们守住后，把对手反杀。", "corrected_sentence": "我们守住后，把对手反杀了。", "error_description": "错误：“把”字句中“反杀”后缺少“了”，句子不完整。正确应为：我们守住后，把对手反杀了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df95e100-f8a6-4de5-a7f9-cc8b779e0c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被围住后，终于反杀着三个人。", "corrected_sentence": "他被围住后，终于反杀了三个人。", "error_description": "错误：“终于”表示一次完成的结果，要用“了”；“着”表示动作持续，不能与“终于反杀”搭配。正确应为：终于反杀了三个人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df95e100-f8a6-4de5-a7f9-cc8b779e0c80') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
