INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87337, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "沿着是顺着路或河的边，一直往前走。", "primary_collocate": null, "pronunciation": "yán zhe", "ipa": "ian˧˥ ʈʂə", "syllable_count": 2, "sentences": [{"text": "我们沿着河慢慢走。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿着这条路一直走，就能看到车站。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们沿着小路跑回家。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他沿着河边走了很久。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿着大街往前走，前面有一家银行。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天早上沿着湖边跑步。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿着铁路走，你会看到一座小桥。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她沿着山路走上去了。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿着海边走，风很大。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请沿着这条线往前走。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "沿着路、河、海边等一直往前走或跑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed69058d-24aa-4c07-bc40-36884250d128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87337, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "沿着", "is_correct": true, "explanation": "沿着 yán zhe，表示顺着路、河或边线一直走，是正确答案。"}, {"text": "研制", "is_correct": false, "explanation": "研制 yánzhì：zhì（第四声）与 zhe（轻声）韵母和声调都不同，意思是研制新产品。"}, {"text": "严重", "is_correct": false, "explanation": "严重 yánzhòng：zhòng（第四声）与 zhe（轻声）韵母和声调不同，意思是情况厉害。"}, {"text": "炎症", "is_correct": false, "explanation": "炎症 yánzhèng：zhèng 与 zhe 韵母不同，意思是身体发炎。"}, {"text": "言者", "is_correct": false, "explanation": "言者 yánzhě：zhě（第三声）与 zhe（轻声）声调不同，意思是讲话的人。"}], "explanations": {"沿着": "沿着 yán zhe，表示顺着路、河或边线一直走，是正确答案。", "研制": "研制 yánzhì：zhì（第四声）与 zhe（轻声）韵母和声调都不同，意思是研制新产品。", "严重": "严重 yánzhòng：zhòng（第四声）与 zhe（轻声）韵母和声调不同，意思是情况厉害。", "炎症": "炎症 yánzhèng：zhèng 与 zhe 韵母不同，意思是身体发炎。", "言者": "言者 yánzhě：zhě（第三声）与 zhe（轻声）声调不同，意思是讲话的人。"}, "sentence_index": null, "correct_answer": "沿着"}, "level_3": {"options": [{"text": "沿着", "is_correct": true, "explanation": "沿着表示顺着河边移动，与“河”和“慢慢走”相配。"}, {"text": "按照", "is_correct": false, "explanation": "语义：按照表示依据或标准，河不是依据，这里说不通。"}, {"text": "随着", "is_correct": false, "explanation": "配价：随着引出伴随某种变化的过程，不能直接接“河慢慢走”。"}, {"text": "关于", "is_correct": false, "explanation": "语义：关于引出话题，不能表示沿河移动。"}], "explanations": {"沿着": "沿着表示顺着河边移动，与“河”和“慢慢走”相配。", "按照": "语义：按照表示依据或标准，河不是依据，这里说不通。", "随着": "配价：随着引出伴随某种变化的过程，不能直接接“河慢慢走”。", "关于": "语义：关于引出话题，不能表示沿河移动。"}, "sentence_index": 0, "correct_answer": "沿着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们沿着老师的要求写作业。", "explanation": "这里应该用〈按照〉。沿着只表示顺着路、河或边线移动，依照要求做事要用按照。"}, {"text": "沿着天气变暖，花开了。", "explanation": "这里应该用〈随着〉。沿着表示空间上顺线移动，表示随某种变化而变化要用随着。"}, {"text": "沿着三点，他到了学校。", "explanation": "这里应该用〈在〉。沿着只表示顺着线路或边缘移动，表示时间点要用在。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87337, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "沿着", "is_correct": true, "explanation": "沿着 yán zhe，表示顺着路、河或边线一直走，是正确答案。"}, {"text": "研究", "is_correct": false, "explanation": "研究 yánjiū：jiū（第一声）与 zhe（轻声）韵母和声调都不同，意思是探讨、钻研。"}, {"text": "颜值", "is_correct": false, "explanation": "颜值 yánzhí：zhí（第二声）与 zhe 韵母和声调不同，意思是外貌好看的程度。"}, {"text": "炎热", "is_correct": false, "explanation": "炎热 yánrè：rè（第四声）与 zhe（轻声）韵母和声调不同，意思是天气很热。"}, {"text": "延误", "is_correct": false, "explanation": "延误 yánwù：wù（第四声）与 zhe（轻声）韵母和声调不同，意思是耽搁、误了时间。"}], "explanations": {"沿着": "沿着 yán zhe，表示顺着路、河或边线一直走，是正确答案。", "研究": "研究 yánjiū：jiū（第一声）与 zhe（轻声）韵母和声调都不同，意思是探讨、钻研。", "颜值": "颜值 yánzhí：zhí（第二声）与 zhe 韵母和声调不同，意思是外貌好看的程度。", "炎热": "炎热 yánrè：rè（第四声）与 zhe（轻声）韵母和声调不同，意思是天气很热。", "延误": "延误 yánwù：wù（第四声）与 zhe（轻声）韵母和声调不同，意思是耽搁、误了时间。"}, "sentence_index": null, "correct_answer": "沿着"}, "level_3": {"options": [{"text": "沿着", "is_correct": true, "explanation": "沿着表示顺着铁路移动，与“走”和后面的“看到小桥”相配。"}, {"text": "为了", "is_correct": false, "explanation": "语义：为了表示目的，铁路不是目的，句子说不通。"}, {"text": "凭借", "is_correct": false, "explanation": "搭配：凭借后面接依靠的手段或条件，不能接“铁路走”。"}, {"text": "由于", "is_correct": false, "explanation": "配价：由于要引出原因，后面需接原因小句，不能直接接“铁路走”。"}], "explanations": {"沿着": "沿着表示顺着铁路移动，与“走”和后面的“看到小桥”相配。", "为了": "语义：为了表示目的，铁路不是目的，句子说不通。", "凭借": "搭配：凭借后面接依靠的手段或条件，不能接“铁路走”。", "由于": "配价：由于要引出原因，后面需接原因小句，不能直接接“铁路走”。"}, "sentence_index": 6, "correct_answer": "沿着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他沿着镜子笑了一下。", "explanation": "这里应该用〈对着〉。沿着指顺着线路或边缘移动，面对镜子笑要用对着。"}, {"text": "他沿着朋友写作业。", "explanation": "这里应该用〈替〉。沿着不能表示为某人代做事情，替人做事要用替。"}, {"text": "我沿着老师请教问题。", "explanation": "这里应该用〈向〉。沿着不能表示向某人发出请教的动作，向人请教要用向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87337, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们沿着慢慢散步。", "corrected_sentence": "我们沿着湖边慢慢散步。", "error_description": "错误：“沿着”后面必须带处所宾语，应说“沿着湖边”，这里漏了宾语“湖边”，句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87337, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们沿着了海岸慢慢走。", "corrected_sentence": "他们沿着海岸慢慢走。", "error_description": "错误：“沿着”是固定的介词结构，中间不能插入“了”。“沿着了海岸”不成立，应说“沿着海岸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
