INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87338, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，顺着（某物的边或方向）。", "primary_collocate": null, "pronunciation": "yán zhe", "ipa": "ian˧˥ ʈʂə", "syllable_count": 2, "sentences": [{"text": "小猫沿着墙走过去。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请沿着线剪开这张纸。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水沿着屋顶流下来。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他沿着桌子的边放了一排书。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汗沿着他的脸流下来。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们沿着操场的边站好。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沿着这个方向走，你会找到出口。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨水沿着窗户流下来。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚂蚁沿着树干往上爬。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她沿着书架一本一本地找书。", "target_word": "沿着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "顺着某物的边、线或方向移动、流动或排列", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed69058d-24aa-4c07-bc40-36884250d128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87338, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "沿着", "is_correct": true, "explanation": "沿着 yán zhe，表示顺着某物的边、线或方向移动，是正确答案。"}, {"text": "研制", "is_correct": false, "explanation": "研制 yánzhì：zhì（第四声）与 zhe（轻声）韵母和声调都不同，意思是研制新产品。"}, {"text": "严重", "is_correct": false, "explanation": "严重 yánzhòng：zhòng（第四声）与 zhe（轻声）韵母和声调不同，意思是情况厉害。"}, {"text": "炎症", "is_correct": false, "explanation": "炎症 yánzhèng：zhèng 与 zhe 韵母不同，意思是身体发炎。"}, {"text": "言者", "is_correct": false, "explanation": "言者 yánzhě：zhě（第三声）与 zhe（轻声）声调不同，意思是讲话的人。"}], "explanations": {"沿着": "沿着 yán zhe，表示顺着某物的边、线或方向移动，是正确答案。", "研制": "研制 yánzhì：zhì（第四声）与 zhe（轻声）韵母和声调都不同，意思是研制新产品。", "严重": "严重 yánzhòng：zhòng（第四声）与 zhe（轻声）韵母和声调不同，意思是情况厉害。", "炎症": "炎症 yánzhèng：zhèng 与 zhe 韵母不同，意思是身体发炎。", "言者": "言者 yánzhě：zhě（第三声）与 zhe（轻声）声调不同，意思是讲话的人。"}, "sentence_index": null, "correct_answer": "沿着"}, "level_3": {"options": [{"text": "沿着", "is_correct": true, "explanation": "沿着表示小猫顺着墙走，与“墙”和“走过去”相配。"}, {"text": "按照", "is_correct": false, "explanation": "语义：按照表示依据或标准，墙不是依据，句子说不通。"}, {"text": "随着", "is_correct": false, "explanation": "配价：随着需要接随某种变化的过程，不能接“墙走过去”。"}, {"text": "关于", "is_correct": false, "explanation": "语义：关于引出话题，不能表示小猫沿墙走。"}], "explanations": {"沿着": "沿着表示小猫顺着墙走，与“墙”和“走过去”相配。", "按照": "语义：按照表示依据或标准，墙不是依据，句子说不通。", "随着": "配价：随着需要接随某种变化的过程，不能接“墙走过去”。", "关于": "语义：关于引出话题，不能表示小猫沿墙走。"}, "sentence_index": 0, "correct_answer": "沿着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "沿着这个计划，我们明天出发。", "explanation": "这里应该用〈根据〉。沿着只表示顺着线路移动，依照计划行事要用根据。"}, {"text": "沿着年龄增长，他变得成熟了。", "explanation": "这里应该用〈随着〉。沿着指顺着空间的线，不能表示随某种变化而变化。"}, {"text": "沿着这件事，大家意见不一。", "explanation": "这里应该用〈关于〉。沿着不能引出讨论的话题，引出话题要用关于。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87338, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "沿着", "is_correct": true, "explanation": "沿着 yán zhe，表示顺着某物的边、线或方向移动，是正确答案。"}, {"text": "研讨", "is_correct": false, "explanation": "研讨 yántǎo：tǎo（第三声）与 zhe（轻声）韵母和声调都不同，意思是讨论研究。"}, {"text": "颜值", "is_correct": false, "explanation": "颜值 yánzhí：zhí（第二声）与 zhe 韵母和声调不同，意思是外貌好看的程度。"}, {"text": "岩石", "is_correct": false, "explanation": "岩石 yánshí：shí（第二声）与 zhe（轻声）韵母和声调不同，意思是岩石、山石。"}, {"text": "颜色", "is_correct": false, "explanation": "颜色 yánsè：sè（第四声）与 zhe（轻声）韵母和声调不同，意思是颜色。"}], "explanations": {"沿着": "沿着 yán zhe，表示顺着某物的边、线或方向移动，是正确答案。", "研讨": "研讨 yántǎo：tǎo（第三声）与 zhe（轻声）韵母和声调都不同，意思是讨论研究。", "颜值": "颜值 yánzhí：zhí（第二声）与 zhe 韵母和声调不同，意思是外貌好看的程度。", "岩石": "岩石 yánshí：shí（第二声）与 zhe（轻声）韵母和声调不同，意思是岩石、山石。", "颜色": "颜色 yánsè：sè（第四声）与 zhe（轻声）韵母和声调不同，意思是颜色。"}, "sentence_index": null, "correct_answer": "沿着"}, "level_3": {"options": [{"text": "沿着", "is_correct": true, "explanation": "沿着表示顺着这个方向走，与“方向”和“找到出口”相配。"}, {"text": "为了", "is_correct": false, "explanation": "语义：为了表示目的，“方向”不能作为走的目的，句子说不通。"}, {"text": "凭借", "is_correct": false, "explanation": "搭配：凭借后面接依靠的手段或条件，不能接“这个方向走”。"}, {"text": "由于", "is_correct": false, "explanation": "配价：由于需要引出原因小句，不能直接接“这个方向走”。"}], "explanations": {"沿着": "沿着表示顺着这个方向走，与“方向”和“找到出口”相配。", "为了": "语义：为了表示目的，“方向”不能作为走的目的，句子说不通。", "凭借": "搭配：凭借后面接依靠的手段或条件，不能接“这个方向走”。", "由于": "配价：由于需要引出原因小句，不能直接接“这个方向走”。"}, "sentence_index": 6, "correct_answer": "沿着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "沿着努力，我们成功了。", "explanation": "这里应该用〈通过〉。沿着表示顺着线路或边缘，不能表示凭借某种方式。"}, {"text": "沿着我来说，这很重要。", "explanation": "这里应该用〈对〉。沿着不能引出看法的角度，从某人的角度说要用对。"}, {"text": "他沿着我讲了一个故事。", "explanation": "这里应该用〈给〉。沿着不能引出动作的接受者，对谁做某事要用给。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') 