INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨水沿着慢慢流下来。", "corrected_sentence": "雨水沿着玻璃慢慢流下来。", "error_description": "错误：“沿着”后面必须带处所宾语，应说“沿着玻璃慢慢流下来”，这里漏了宾语“玻璃”，句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他沿着了墙边慢慢摸过去。", "corrected_sentence": "他沿着墙边慢慢摸过去。", "error_description": "错误：“沿着”是固定的介词结构，中间不能插入“了”。“沿着了墙边”不成立，应说“沿着墙边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
