INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87342, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "吃饭的过程结束，吃毕（不要求全部吃光）。", "primary_collocate": null, "pronunciation": "chī wán", "ipa": "ʈʂʰɨ˥ wan˧˥", "syllable_count": 2, "sentences": [{"text": "吃完饭以后，我们一起去公园散步。", "target_word": "吃完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子吃完早饭，就背着书包上学去了。", "target_word": "吃完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你吃完了吗？我们要走了。", "target_word": "吃完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完晚饭，爸爸在客厅看新闻。", "target_word": "吃完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃完午饭，在办公室休息了一会儿。", "target_word": "吃完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等你吃完饭，我们再说这件事。", "target_word": "吃完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完火锅，大家都说今天太开心了。", "target_word": "吃完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她吃完水果，把盘子拿去洗了。", "target_word": "吃完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人还没吃完，服务员不会收盘子。", "target_word": "吃完", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我吃完早饭才发现，今天是星期天。", "target_word": "吃完", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吃完了", "label": "体标：完成"}, {"form": "没吃完", "label": "否定"}], "register": "口语", "sense_fingerprint": "吃饭结束，吃毕后接着做别的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f650a73-b56c-4b35-a5aa-fa33d63c4ebd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87342, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃完", "is_correct": true, "explanation": "正确：“吃完饭”表示吃饭结束，之后再去散步，符合句意。"}, {"text": "刷完", "is_correct": false, "explanation": "搭配：“刷”的对象是牙齿、碗具等，不能刷饭。"}, {"text": "唱完", "is_correct": false, "explanation": "语义：“唱完”指唱歌结束，饭不能唱。"}, {"text": "穿好", "is_correct": false, "explanation": "配价：“穿”要求衣物作宾语，饭不能穿。"}], "explanations": {"吃完": "正确：“吃完饭”表示吃饭结束，之后再去散步，符合句意。", "刷完": "搭配：“刷”的对象是牙齿、碗具等，不能刷饭。", "唱完": "语义：“唱完”指唱歌结束，饭不能唱。", "穿好": "配价：“穿”要求衣物作宾语，饭不能穿。"}, "sentence_index": 0, "correct_answer": "吃完"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃完电影以后，他们去吃了夜宵。", "explanation": "这里应该用〈看完〉。“吃完”表示吃饭结束，电影不能吃，要说看完。"}, {"text": "吃完作业以后，她就去睡觉了。", "explanation": "这里应该用〈做完〉。“吃完”的对象只能是饭菜，作业不能吃，要说做完。"}, {"text": "吃完咖啡以后，他精神好多了。", "explanation": "这里应该用〈喝完〉。咖啡是饮料，“吃完”只用于饭菜，要说喝完。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87342, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃完", "is_correct": true, "explanation": "正确：“吃完火锅”指吃饭结束，之后大家都觉得开心，符合句意。"}, {"text": "逛完", "is_correct": false, "explanation": "语义：“逛完”指逛街或逛景点，火锅不能逛。"}, {"text": "录完", "is_correct": false, "explanation": "搭配：“录”的对象是声音、视频，火锅不能录。"}, {"text": "修完", "is_correct": false, "explanation": "搭配：“修”的对象是需要修理的器物，火锅不能修。"}], "explanations": {"吃完": "正确：“吃完火锅”指吃饭结束，之后大家都觉得开心，符合句意。", "逛完": "语义：“逛完”指逛街或逛景点，火锅不能逛。", "录完": "搭配：“录”的对象是声音、视频，火锅不能录。", "修完": "搭配：“修”的对象是需要修理的器物，火锅不能修。"}, "sentence_index": 6, "correct_answer": "吃完"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天晚上吃完了一本小说。", "explanation": "这里应该用〈读完〉。“吃完”表示吃饭结束，小说不能吃，要说读完。"}, {"text": "我们在海边吃完了整个暑假。", "explanation": "这里应该用〈度过〉。“吃完”只能用于食物，暑假不能被吃完，要说度过。"}, {"text": "他终于吃完了那份报告。", "explanation": "这里应该用〈完成〉。“吃完”只用于饭菜等食物，报告要说完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子还没吃完了饭呢，你先等等。", "corrected_sentence": "孩子还没吃完饭呢，你先等等。", "error_description": "“没”否定时动词后不能加“了”，应说“还没吃完饭”，“还没吃完了饭”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子已经把早饭吃完着。", "corrected_sentence": "孩子已经把早饭吃完了。", "error_description": "“已经”表示动作已经完成，应与“了”搭配，说“吃完了”；“吃完着”表示动作仍在持续，与“已经”矛盾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
