INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87343, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "流氓是不讲道理，爱欺负人的坏人。", "primary_collocate": null, "pronunciation": "liú máng", "ipa": "liou˧˥ mɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "那个流氓总是欺负比他小的孩子。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不讲道理，大家都说他是流氓。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "流氓在路上拦住了一个女孩。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察把那个流氓带走了。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最怕遇到爱打人的流氓。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影里的流氓又坏又不讲理。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看起来像好人，其实是个流氓。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店老板不敢得罪那些流氓。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别学那个流氓，他老是骂人。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人都讨厌这个爱欺负人的流氓。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "伙", "label": "量词"}, {"form": "群", "label": "量词"}], "register": "中性", "sense_fingerprint": "流氓：不讲道理、爱欺负人的坏人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dac0efc-fc80-403b-ae86-f40de6bf3e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87343, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流氓", "is_correct": true, "explanation": "正确：“流氓”指爱欺负人的坏人，与“总是欺负比他小的孩子”相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有行动能力，不会欺负孩子。"}, {"text": "植物", "is_correct": false, "explanation": "语义：植物不能主动欺负人，与句中的行为主体不符。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“欺负”的主语应是人，不能说“天空”欺负孩子。"}], "explanations": {"流氓": "正确：“流氓”指爱欺负人的坏人，与“总是欺负比他小的孩子”相符。", "石头": "语义：石头没有行动能力，不会欺负孩子。", "植物": "语义：植物不能主动欺负人，与句中的行为主体不符。", "天空": "搭配：“欺负”的主语应是人，不能说“天空”欺负孩子。"}, "sentence_index": 0, "correct_answer": "流氓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在外地流氓了好几年，才回到家乡。", "explanation": "这里应该用〈流浪〉。“流氓”指人，不表示到处漂泊；句中“流氓了”只能理解为“耍流氓”，与“在外地漂泊”的意思不符，表示漂泊要用“流浪”。"}, {"text": "昨天我在马路上看见一张流氓。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，不能用来数人。"}, {"text": "门口停着一辆流氓，谁也不敢靠近。", "explanation": "这里应该用〈个〉。“辆”用于车辆，不能用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87343, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流氓", "is_correct": true, "explanation": "正确：“其实是个流氓”与前文“看起来像好人”形成转折，指表面像好人、实际是坏人的人。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会“看起来像好人”，也不能是坏人的身份。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，与“看起来像好人”的人无关，不能作为其实的身份。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”是不可数名词，不能说“是个空气”。"}], "explanations": {"流氓": "正确：“其实是个流氓”与前文“看起来像好人”形成转折，指表面像好人、实际是坏人的人。", "桌子": "语义：桌子是家具，不会“看起来像好人”，也不能是坏人的身份。", "月亮": "语义：月亮是天体，与“看起来像好人”的人无关，不能作为其实的身份。", "空气": "搭配：“空气”是不可数名词，不能说“是个空气”。"}, "sentence_index": 6, "correct_answer": "流氓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校门口有一座流氓，总是欺负小学生。", "explanation": "这里应该用〈个〉。“座”用于山、房屋等大型固定的东西，不能用来数人。"}, {"text": "河边停着一条流氓，大家都绕着走。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，不能用来数人。"}, {"text": "村口站着一头流氓，谁都不愿意搭理。", "explanation": "这里应该用〈个〉。“头”用于牲畜，指人不能用“头”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87343, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里来了一台流氓，大家都很害怕。", "corrected_sentence": "村里来了一个流氓，大家都很害怕。", "error_description": "量词错误：“流氓”指人，应用量词“个”，不能用“台”（“台”用于机器等器械）。应说“一个流氓”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87343, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不想再当一头流氓了，决定去工厂上班。", "corrected_sentence": "他不想再当流氓了，决定去工厂上班。", "error_description": "量词错误：“流氓”指人，不能用量词“头”（“头”用于牲畜）。应去掉“一头”，说“不想再当流氓了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
