INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87344, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87344, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "不务正业、专做坏事、欺压他人的人。", "primary_collocate": null, "pronunciation": "liú máng", "ipa": "liou˧˥ mɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他不工作，整天做坏事，是个流氓。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几个流氓天天在街上收别人的钱。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻时不学好，成了村里的流氓。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "流氓不做正经事，只会欺压老百姓。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，那个流氓偷过很多东西。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些流氓在车站里打人，大家都很害怕。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想当流氓，想找一份正当工作。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，警察已经抓住了这伙流氓。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "流氓整天在外面玩，不好好工作。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人走夜路，遇到了几个流氓。", "target_word": "流氓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "伙", "label": "量词"}, {"form": "群", "label": "量词"}], "register": "中性", "sense_fingerprint": "流氓：不务正业、专做坏事、欺压他人的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dac0efc-fc80-403b-ae86-f40de6bf3e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87344, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "流氓", "is_correct": true, "explanation": "正确：“流氓”指不工作、专做坏事的人，与“整天做坏事”相符。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生的职业是救人治病，与“整天做坏事”相反，不能这样描述。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的东西，不会做坏事。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”是不可数名词，不能说“是个空气”。"}], "explanations": {"流氓": "正确：“流氓”指不工作、专做坏事的人，与“整天做坏事”相符。", "医生": "语义：医生的职业是救人治病，与“整天做坏事”相反，不能这样描述。", "石头": "语义：石头是无生命的东西，不会做坏事。", "空气": "搭配：“空气”是不可数名词，不能说“是个空气”。"}, "sentence_index": 0, "correct_answer": "流氓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他年轻时到处流氓，没有固定的家。", "explanation": "这里应该用〈流浪〉。“流氓”指人，不表示到处漂泊；句中只能理解为“耍流氓”，与“没有固定的家”的漂泊之意不符。"}, {"text": "我在车站看见一张流氓。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，不能用来数人。"}, {"text": "街角站着一座流氓，大家都躲着他。", "explanation": "这里应该用〈个〉。“座”用于山、房屋等大型固定的东西，不能用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "流氓", "is_correct": true, "explanation": "正确：“不想当流氓”与“想找一份正当工作”形成对比，指做坏事的人。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑部件，不是人，“不想当窗户”没有意义。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能选择“当”什么身份，句意不通。"}, {"text": "空调", "is_correct": false, "explanation": "搭配：“当”后面接的应是人的身份，“空调”不能这样搭配。"}], "explanations": {"流氓": "正确：“不想当流氓”与“想找一份正当工作”形成对比，指做坏事的人。", "窗户": "语义：窗户是建筑部件，不是人，“不想当窗户”没有意义。", "桌子": "语义：桌子是家具，不能选择“当”什么身份，句意不通。", "空调": "搭配：“当”后面接的应是人的身份，“空调”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "流氓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市场里有一台流氓，天天收别人的钱。", "explanation": "这里应该用〈个〉。“台”用于机器等器械，不能用来数人。"}, {"text": "河边停着一条流氓，谁也不敢靠近。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，不能用来数人。"}, {"text": "村口站着一头流氓，大家都绕着走。", "explanation": "这里应该用〈个〉。“头”用于牲畜，指人不能用“头”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里有几辆流氓常常欺负外地人，大家都很害怕。", "corrected_sentence": "村里有几个流氓常常欺负外地人，大家都很害怕。", "error_description": "量词错误：“流氓”指人，应用量词“个”，不能用“辆”（“辆”用于车辆）。应说“几个流氓”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他后来决定不当一流氓了，到工厂去上班。", "corrected_sentence": "他后来决定不当流氓了，到工厂去上班。", "error_description": "量词缺失：“一”后接人的名词“流氓”须加量词“个”，应说“一个流氓”，或去掉“一”，说“不当流氓了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
