INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87345, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "哪些是问有几样东西、是哪几个。", "primary_collocate": null, "pronunciation": "nǎ xiē", "ipa": "na˨˩˦ ɕjɛ˥", "syllable_count": 2, "sentences": [{"text": "这些书里，哪些是你的？", "target_word": "哪些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上的东西，哪些你要带走？", "target_word": "哪些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我，哪些是今天的作业。", "target_word": "哪些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道哪些是新来的同学吗？", "target_word": "哪些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些菜里，哪些不辣？", "target_word": "哪些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的水果，哪些最便宜？", "target_word": "哪些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几件衣服，哪些要洗？", "target_word": "哪些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪些是你喜欢的歌？告诉我吧。", "target_word": "哪些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不清楚哪些是老师给的。", "target_word": "哪些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片里的人，哪些是你家人？", "target_word": "哪些", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "疑问代词，在一组东西里问是哪几样，单独作主语或宾语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf41015-8ec0-4664-ad3d-be3fa4f8add0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87345, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哪些", "is_correct": true, "explanation": "哪些：疑问代词，在“这些书里”这一组中问是哪几本是你的，作主语，句意完整。"}, {"text": "哪里", "is_correct": false, "explanation": "语义：“哪里”问地点，书不是地点，“哪里是你的”句意不通。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”问人，这里问的是书，不能用“谁”指代物品。"}, {"text": "自己", "is_correct": false, "explanation": "搭配：“自己”指人本身，不能用来指代一组书，与“这些书里”搭配不当。"}], "explanations": {"哪些": "哪些：疑问代词，在“这些书里”这一组中问是哪几本是你的，作主语，句意完整。", "哪里": "语义：“哪里”问地点，书不是地点，“哪里是你的”句意不通。", "谁": "语义：“谁”问人，这里问的是书，不能用“谁”指代物品。", "自己": "搭配：“自己”指人本身，不能用来指代一组书，与“这些书里”搭配不当。"}, "sentence_index": 0, "correct_answer": "哪些"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你的书包是哪些？", "explanation": "这里应该用〈哪个〉。书包只有一件，问单个东西要用“哪个”，“哪些”只用于问几样东西。"}, {"text": "你们班的班主任是哪些？", "explanation": "这里应该用〈哪位〉。班主任只有一位，问一位人员要用“哪位”，不用“哪些”。"}, {"text": "你家的洗衣机是哪些？", "explanation": "这里应该用〈哪台〉。洗衣机是一台机器，量词“台”搭配“哪”，问单台时不用“哪些”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87345, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哪些", "is_correct": true, "explanation": "哪些：疑问代词，问“这几件衣服”中哪几件要洗，与前面的“这几件衣服”呼应。"}, {"text": "哪儿", "is_correct": false, "explanation": "语义：“哪儿”问地点，衣服不是地点，“哪儿要洗”句意不通。"}, {"text": "多远", "is_correct": false, "explanation": "语义：“多远”问距离，衣服不是距离，“多远要洗”句意不通。"}, {"text": "多高", "is_correct": false, "explanation": "语义：“多高”问高度，不能指代衣服，“多高要洗”句意不通。"}], "explanations": {"哪些": "哪些：疑问代词，问“这几件衣服”中哪几件要洗，与前面的“这几件衣服”呼应。", "哪儿": "语义：“哪儿”问地点，衣服不是地点，“哪儿要洗”句意不通。", "多远": "语义：“多远”问距离，衣服不是距离，“多远要洗”句意不通。", "多高": "语义：“多高”问高度，不能指代衣服，“多高要洗”句意不通。"}, "sentence_index": 6, "correct_answer": "哪些"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛的冠军是哪些？", "explanation": "这里应该用〈哪个〉。冠军只有一个，问单个结果要用“哪个”，“哪些”只用于问几样东西。"}, {"text": "地球的卫星是哪些？", "explanation": "这里应该用〈哪颗〉。地球只有一颗卫星，问单颗要用“哪颗”，“哪些”只用于问几样东西。"}, {"text": "学校的校长是哪些？", "explanation": "这里应该用〈哪位〉。校长只有一位，问一位人员要用“哪位”，不能用“哪些”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87345, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "哪些本书是你的？", "corrected_sentence": "哪些书是你的？", "error_description": "“哪些”后面不能直接带数量词“本”。问几样东西时直接说“哪些书”，问单个时用“哪本书”。错误形式是“哪些本书”，正确形式是“哪些书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87345, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哪些们是你的朋友？", "corrected_sentence": "哪些是你的朋友？", "error_description": "“哪些”是疑问代词，后面不能加复数后缀“们”。“们”只能加在人称代词或表示人的名词后面。正确形式是“哪些是你的朋友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
