INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87350, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "饮食和衣着，泛指基本的生活所需。", "primary_collocate": null, "pronunciation": "chī chuān", "ipa": "ʈʂʰɨ˥ ʈʂʰwan˥", "syllable_count": 2, "sentences": [{"text": "他工作很努力，一家人的吃穿不用担心。", "target_word": "吃穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的吃穿，爸爸妈妈都会安排好。", "target_word": "吃穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些年家里很穷，吃穿都成问题。", "target_word": "吃穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不在乎吃穿，只想多读点书。", "target_word": "吃穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司给员工解决了吃穿问题。", "target_word": "吃穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在山区，人们的吃穿很简单。", "target_word": "吃穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠自己挣钱，吃穿不靠父母。", "target_word": "吃穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要有工作，吃穿就有办法了。", "target_word": "吃穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说过，吃穿不愁就是幸福。", "target_word": "吃穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在学校里，吃穿都由家里负责。", "target_word": "吃穿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "饮食和衣着，泛指基本的生活所需", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4cf27cd-43b5-427b-9ffd-1e148fc0d9bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87350, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃穿", "is_correct": true, "explanation": "吃穿指饮食和衣着，泛指基本的生活所需，与“一家人的……不用担心”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是一家人需要担心的生活所需，句子说的是生活保障。"}, {"text": "相貌", "is_correct": false, "explanation": "语义：相貌是人的外形，不属于基本生活所需，“一家人的相貌不用担心”与努力工作的上下文不符。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，与一家人的基本生活保障无关。"}], "explanations": {"吃穿": "吃穿指饮食和衣着，泛指基本的生活所需，与“一家人的……不用担心”相符。", "天气": "语义：天气是自然现象，不是一家人需要担心的生活所需，句子说的是生活保障。", "相貌": "语义：相貌是人的外形，不属于基本生活所需，“一家人的相貌不用担心”与努力工作的上下文不符。", "作业": "语义：作业是学习任务，与一家人的基本生活保障无关。"}, "sentence_index": 0, "correct_answer": "吃穿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们家一只吃穿都不缺。", "explanation": "这里不应使用“只”计量。吃穿是泛指生活所需的饮食和衣着，不是一个个可以数的东西，不能说“一只吃穿”。"}, {"text": "我买了一份吃穿，放在桌上。", "explanation": "这里指的是某一份食物，但吃穿是饮食和衣着的总称，不指单独的一份食物，不能说“一份吃穿”。"}, {"text": "他买的吃穿会唱歌。", "explanation": "吃穿指饮食和衣着，不会唱歌，这里把它当成了能唱歌的人或物，用法不当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87350, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吃穿", "is_correct": true, "explanation": "吃穿指饮食和衣着，与“靠自己挣钱”所支付的生活开支相符，句中是“不靠父母”的对象。"}, {"text": "路程", "is_correct": false, "explanation": "语义：路程指距离，与靠自己挣钱、不靠父母的生活开支无关。"}, {"text": "时钟", "is_correct": false, "explanation": "语义：时钟是计时工具，不能作为“靠”或“不靠”的对象。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景物，不能作为“靠”或“不靠”的对象，句子不通。"}], "explanations": {"吃穿": "吃穿指饮食和衣着，与“靠自己挣钱”所支付的生活开支相符，句中是“不靠父母”的对象。", "路程": "语义：路程指距离，与靠自己挣钱、不靠父母的生活开支无关。", "时钟": "语义：时钟是计时工具，不能作为“靠”或“不靠”的对象。", "天空": "语义：天空是自然景物，不能作为“靠”或“不靠”的对象，句子不通。"}, "sentence_index": 6, "correct_answer": "吃穿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班新来的吃穿是一位同学。", "explanation": "这里把吃穿当成了人。吃穿指饮食和衣着，不能指人，不能说“是一位同学”。"}, {"text": "他想把吃穿写成一篇小说。", "explanation": "吃穿是泛指生活所需的饮食和衣着，不是可以创作的作品，这里不能说“写成一篇小说”。"}, {"text": "这场考试的吃穿很难。", "explanation": "吃穿不是考试或任务，不能用“难”来评价，这里误把它当成了事件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家的一件吃穿都很好。", "corrected_sentence": "他家的吃穿都很好。", "error_description": "量词错：“吃穿”泛指饮食和衣着，不是一件件可数的物品，不能用“件”计量，应说“他家的吃穿都很好”，不说“一件吃穿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
